INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37730, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パターン", "is_correct": true, "explanation": "敵の動きの決まった型を指し、「三つの〜があり」に入る語なので正しい。"}, {"text": "天井", "is_correct": false, "explanation": "建物の上の面を表す語で、敵の動きの種類を表せない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を表す語で、動きの種類は表さないので合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "書いた文書を表す語で、敵の動きには当てはまらない。"}], "explanations": {"パターン": "敵の動きの決まった型を指し、「三つの〜があり」に入る語なので正しい。", "天井": "建物の上の面を表す語で、敵の動きの種類を表せない。", "気温": "空気の温度を表す語で、動きの種類は表さないので合わない。", "手紙": "書いた文書を表す語で、敵の動きには当てはまらない。"}, "sentence_index": 0, "correct_answer": "パターン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪のパターンを飲んだ。", "explanation": "ここは〈薬〉の意味。飲んで服用するものを表す語で、形や動き方の種類は飲めないので合わない。"}, {"text": "次の大会では、三つのパターンで金メダルが決まった。", "explanation": "ここは〈種目〉の意味。競技の分類を指す語で、形や動き方の種類とは意味が違うので、メダルが決まる文には合わない。"}, {"text": "今日のパターンは十月二十九日だ。", "explanation": "ここは〈日付〉の意味。日にちを表す語で、形や動き方の種類は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37730, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パターン", "is_correct": true, "explanation": "書道で筆の運びの決まった型を指し、「〜を何度も練習して」に合う語なので正しい。"}, {"text": "雷鳴", "is_correct": false, "explanation": "雷の音を表す語で、練習の対象にならないので合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "食べ物を欲する状態で、練習の対象にならないので合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵送のことを表し、筆の運び方とは結びつかない。"}], "explanations": {"パターン": "書道で筆の運びの決まった型を指し、「〜を何度も練習して」に合う語なので正しい。", "雷鳴": "雷の音を表す語で、練習の対象にならないので合わない。", "空腹": "食べ物を欲する状態で、練習の対象にならないので合わない。", "郵便": "郵送のことを表し、筆の運び方とは結びつかない。"}, "sentence_index": 6, "correct_answer": "パターン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼のパターンは、六十代に入ったところだ。", "explanation": "ここは〈年齢〉の意味。人の年数を表す語で、形や動き方の種類は表さないので合わない。"}, {"text": "次のパターンは、中央駅です。", "explanation": "ここは〈駅名〉の意味。場所の呼び名を表す語で、形や動き方の種類とは合わない。"}, {"text": "この財布には、三つのパターンの小銭が入っている。", "explanation": "ここは〈硬貨〉の意味。お金の一種を指す語で、形や動き方の種類を表すパターンとは意味が違うので、小銭の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37730, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "相手チームは守り方のパターンを焼いてきた。", "corrected_sentence": "相手チームは守り方のパターンを変えてきた。", "error_description": "「パターン」に続く動詞が誤り。「変える」が正しく、「焼く」はパターンと結びつかないので不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37730, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは、同じ手遊びのパターンに何度も繰り返す。", "corrected_sentence": "子どもは、同じ手遊びのパターンを何度も繰り返す。", "error_description": "「パターン」に付く助詞が誤り。「繰り返す」は対象を「を」で取るため、「に」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37731, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「見られる」は見られる対象を「が」で示すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「見られる」は受身の自動詞的な用法で「を」は取らないので不可。"}, {"text": "と", "is_correct": false, "explanation": "「パターンと見られる」は並列になり、見られる対象を示せないので不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の見られる」は文の構造が崩れ、続かない。"}], "correct_answer": "が", "explanations": {"が": "「見られる」は見られる対象を「が」で示すので正しい。", "を": "「見られる」は受身の自動詞的な用法で「を」は取らないので不可。", "と": "「パターンと見られる」は並列になり、見られる対象を示せないので不自然。", "の": "「の見られる」は文の構造が崩れ、続かない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37731, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見つけ出す」は見つける対象を目的語として「を」で取るので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「パターンが見つけ出す」は主語になり、目的語を欠いて意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「パターンに見つけ出す」は方向や対象になり、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「パターンと見つけ出す」は並列を表し、成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「見つけ出す」は見つける対象を目的語として「を」で取るので正しい。", "が": "「パターンが見つけ出す」は主語になり、目的語を欠いて意味が通らない。", "に": "「パターンに見つけ出す」は方向や対象になり、不自然。", "と": "「パターンと見つけ出す」は並列を表し、成り立たない。"}, "error_tags": {"が": "主語", "に": "方向・対象", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37731, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "繰り返し現れる、ある特徴を持った形や仕組みのこと。", "primary_collocate": null, "pronunciation": "ぱたーん", "ipa": "pataːɴ", "syllable_count": 4, "sentences": [{"text": "それは、同じ人の隆線パターンが何度読み取っても同じ形で現れるという生体認証の絶対性に拠る。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "それは、同[おな]じ人[ひと]の隆線[りゅうせん]パターンが何度[なんど]読[よ]み取[と]っても同[おな]じ形[かたち]で現[あらわ]れるという生体[せいたい]認証[にんしょう]の絶対性[ぜったいせい]に拠[よ]る。", "sentence_source": "generated"}, {"text": "この会社の顧客は、月末に買い物をするというパターンが見られる。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の顧客[こきゃく]は、月末[げつまつ]に買[か]い物[もの]をするというパターンが見[み]られる。", "sentence_source": "generated"}, {"text": "失敗のパターンを分析すれば、同じミスを防ぐことができる。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "失敗[しっぱい]のパターンを分析[ぶんせき]すれば、同[おな]じミスを防[ふせ]ぐことができる。", "sentence_source": "generated"}, {"text": "天気が崩れる前には、雲が増えるパターンがよくある。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "天気[てんき]が崩[くず]れる前[まえ]には、雲[くも]が増[ふ]えるパターンがよくある。", "sentence_source": "generated"}, {"text": "彼の話し方にはいつも同じパターンがあって、次の言葉が予想できる。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はな]し方[かた]にはいつも同[おな]じパターンがあって、次[つぎ]の言葉[ことば]が予想[よそう]できる。", "sentence_source": "generated"}, {"text": "睡眠のパターンが乱れると、体調を崩しやすくなる。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "睡眠[すいみん]のパターンが乱[みだ]れると、体調[たいちょう]を崩[くず]しやすくなる。", "sentence_source": "generated"}, {"text": "詐欺の手口には一定のパターンがあるので、事前に知っておくと安心だ。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "詐欺[さぎ]の手口[てぐち]には一定[いってい]のパターンがあるので、事前[じぜん]に知[し]っておくと安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "データから一定のパターンを見つけ出すのが、この研究の目的だ。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "データから一定[いってい]のパターンを見[み]つけ出[だ]すのが、この研究[けんきゅう]の目的[もくてき]だ。", "sentence_source": "generated"}, {"text": "この壁紙は同じパターンが続くため、つなぎ目がわかりにくい。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "この壁紙[かべがみ]は同[おな]じパターンが続[つづ]くため、つなぎ目[め]がわかりにくい。", "sentence_source": "generated"}, {"text": "子どもの行動にはパターンがあり、昼寝のあとは必ず機嫌が悪い。", "target_word": "パターン", "complexity_tier": "T3", "furigana": "子[こ]どもの行動[こうどう]にはパターンがあり、昼寝[ひるね]のあとは必[かなら]ず機嫌[きげん]が悪[わる]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パターン", "label": "基本形"}], "register": "中立", "sense_fingerprint": "繰り返し現れる、特徴のある形や仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 拠る (Zipf 2.41)','sentence 8 above tier T2: contains vocabulary far above tier T2: つなぎ目 (Zipf 2.24)']::text[], '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37731, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パターン", "is_correct": true, "explanation": "同じ人の隆線が何度読み取っても同じ形で現れる型を指し、「隆線の〜」に入る語なので正しい。"}, {"text": "手順", "is_correct": false, "explanation": "作業の順序を表す語で、同じ人の隆線が現れる型を表せないので合わない。"}, {"text": "制度", "is_correct": false, "explanation": "決まりの仕組みを表す語で、隆線が何度も現れる型とは結びつかない。"}, {"text": "比率", "is_correct": false, "explanation": "割合を表す語で、隆線の型を示す語としては合わない。"}], "explanations": {"パターン": "同じ人の隆線が何度読み取っても同じ形で現れる型を指し、「隆線の〜」に入る語なので正しい。", "手順": "作業の順序を表す語で、同じ人の隆線が現れる型を表せないので合わない。", "制度": "決まりの仕組みを表す語で、隆線が何度も現れる型とは結びつかない。", "比率": "割合を表す語で、隆線の型を示す語としては合わない。"}, "sentence_index": 0, "correct_answer": "パターン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パターンを割って、ガラスの破片を集めた。", "explanation": "ここは〈器〉の意味。割れる物を指す語で、繰り返し現れる形や仕組みは割れないので合わない。"}, {"text": "来週のパターンはまだ決まっていない。", "explanation": "ここは〈予定〉の意味。未来の計画を指し、繰り返し現れる形や仕組みは表さないので合わない。"}, {"text": "この製品のパターンは、防水性が弱いことだ。", "explanation": "ここは〈欠陥〉の意味。製品の欠けた点を指すので、繰り返し現れる形や仕組みとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37731, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パターン", "is_correct": true, "explanation": "「一定の〜がある」で、詐欺の決まった型を指すので正しい。"}, {"text": "天候", "is_correct": false, "explanation": "空模様を表す語で、「一定の天候がある」は手口の型を示す文に合わない。"}, {"text": "隣人", "is_correct": false, "explanation": "近所に住む人を表す語で、手口の型とは結びつかない。"}, {"text": "植物", "is_correct": false, "explanation": "生き物の一種で、詐欺の手口を表す文に合わない。"}], "explanations": {"パターン": "「一定の〜がある」で、詐欺の決まった型を指すので正しい。", "天候": "空模様を表す語で、「一定の天候がある」は手口の型を示す文に合わない。", "隣人": "近所に住む人を表す語で、手口の型とは結びつかない。", "植物": "生き物の一種で、詐欺の手口を表す文に合わない。"}, "sentence_index": 6, "correct_answer": "パターン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中にパターンが大声で泣いていた。", "explanation": "ここは〈悲鳴〉の意味。人が上げる叫び声を指す語で、繰り返し現れる形や仕組みは泣かないので合わない。"}, {"text": "明日は一日中、パターンが降るらしい。", "explanation": "ここは〈雨〉の意味。降る対象を表す語で、形や仕組みは降らないので合わない。"}, {"text": "この地図のパターンは五万分の一だ。", "explanation": "ここは〈縮尺〉の意味。地図の大きさの比率を表す語で、繰り返し現れる形は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37731, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この分析では、売上の推移から一定のパターンを打った。", "corrected_sentence": "この分析では、売上の推移から一定のパターンを見つけた。", "error_description": "「パターン」に続く動詞が誤り。「パターンを見つける」が正しく、「打つ」はパターンと結びつかないので不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37731, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店では、雨の日に客が減るパターンを見られる。", "corrected_sentence": "この店では、雨の日に客が減るパターンが見られる。", "error_description": "「見られる」は「〜が見られる」と主語に「が」を取るので、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
