INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37732, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものをくわしくしらべること。", "primary_collocate": null, "pronunciation": "かいせき", "ipa": "kaiseki", "syllable_count": 4, "sentences": [{"text": "この石の成分を解析してもらうために、研究所に送った。", "target_word": "解析", "complexity_tier": "T3", "furigana": "この石[いし]の成分[せいぶん]を解析[かいせき]してもらうために、研究所[けんきゅうじょ]に送[おく]った。", "sentence_source": "generated"}, {"text": "警察は残された足あとを解析して、犯人を探している。", "target_word": "解析", "complexity_tier": "T3", "furigana": "警察[けいさつ]は残[のこ]された足[あし]あとを解析[かいせき]して、犯人[はんにん]を探[さが]している。", "sentence_source": "generated"}, {"text": "博物館では、古い絵の絵の具を解析しています。", "target_word": "解析", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、古[ふる]い絵[え]の絵[え]の具[ぐ]を解析[かいせき]しています。", "sentence_source": "generated"}, {"text": "解析の結果が出るまで、一週間待ってください。", "target_word": "解析", "complexity_tier": "T3", "furigana": "解析[かいせき]の結果[けっか]が出[で]るまで、一週間[いっしゅうかん]待[ま]ってください。", "sentence_source": "generated"}, {"text": "彼は試合の動画を解析して、自分の癖を直した。", "target_word": "解析", "complexity_tier": "T3", "furigana": "彼[かれ]は試合[しあい]の動画[どうが]を解析[かいせき]して、自分[じぶん]の癖[くせ]を直[なお]した。", "sentence_source": "generated"}, {"text": "水の汚れの解析は、川の生き物を守るために大切だ。", "target_word": "解析", "complexity_tier": "T3", "furigana": "水[みず]の汚[よご]れの解析[かいせき]は、川[かわ]の生[い]き物[もの]を守[まも]るために大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "声の高さを解析すると、その人の気持ちが分かることがある。", "target_word": "解析", "complexity_tier": "T3", "furigana": "声[こえ]の高[たか]さを解析[かいせき]すると、その人[ひと]の気持[きも]ちが分[わ]かることがある。", "sentence_source": "generated"}, {"text": "この機械は、食べ物にふくまれる塩の量を解析できます。", "target_word": "解析", "complexity_tier": "T3", "furigana": "この機械[きかい]は、食[た]べ物[もの]にふくまれる塩[しお]の量[りょう]を解析[かいせき]できます。", "sentence_source": "generated"}, {"text": "ノートの文字を解析しても、誰が書いたかは分からなかった。", "target_word": "解析", "complexity_tier": "T3", "furigana": "ノートの文字[もじ]を解析[かいせき]しても、誰[だれ]が書[か]いたかは分[わ]からなかった。", "sentence_source": "generated"}, {"text": "友だちと理科の実験の結果を解析して、発表のしたくをした。", "target_word": "解析", "complexity_tier": "T3", "furigana": "友[とも]だちと理科[りか]の実験[じっけん]の結果[けっか]を解析[かいせき]して、発表[はっぴょう]のしたくをした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解析", "label": "名詞(基本形)"}, {"form": "解析する", "label": "サ変動詞・終止形"}, {"form": "解析して", "label": "て形"}, {"form": "解析した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "ものの成分や中身をくわしく調べる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37732, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焙煎", "is_correct": false, "explanation": "石の成分に対して焙煎は行わない。焙煎は豆などを炒る作業で、この文脈には合わない。"}, {"text": "解凍", "is_correct": false, "explanation": "凍った物を元に戻す作業で、石の成分を調べる文脈には合わない。"}, {"text": "解析", "is_correct": true, "explanation": "成分を詳しく調べてもらうために研究所へ送る流れに合うのは「解析」。"}, {"text": "研磨", "is_correct": false, "explanation": "石を磨く作業で、成分を調べるという文脈には合わない。"}], "explanations": {"焙煎": "石の成分に対して焙煎は行わない。焙煎は豆などを炒る作業で、この文脈には合わない。", "解凍": "凍った物を元に戻す作業で、石の成分を調べる文脈には合わない。", "解析": "成分を詳しく調べてもらうために研究所へ送る流れに合うのは「解析」。", "研磨": "石を磨く作業で、成分を調べるという文脈には合わない。"}, "sentence_index": 0, "correct_answer": "解析"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅行の予約を解析して、ホテルを取った。", "explanation": "ここは〈予約〉の意味。解析は中身を細かく調べることで、部屋を押さえる意味では使わない。"}, {"text": "店で代金の解析を支払った。", "explanation": "ここは〈会計〉の意味。解析は中身を細かく調べることで、お金を精算する意味では使わない。"}, {"text": "週末は、新しい家具を解析して、部屋に並べた。", "explanation": "ここは〈配置〉の意味。解析は中身を細かく調べることで、物を並べる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37732, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗浄", "is_correct": false, "explanation": "声の高さを洗浄するとは言わない。洗浄は汚れを落とす作業で、この文脈には合わない。"}, {"text": "冷却", "is_correct": false, "explanation": "声の高さを冷やすという意味になり、この文脈では不自然。"}, {"text": "焼却", "is_correct": false, "explanation": "燃やして処分する意味で、声の特徴を調べる文脈には合わない。"}, {"text": "解析", "is_correct": true, "explanation": "声の特徴を細かく調べて気持ちを読み取る流れに合うのは「解析」。"}], "explanations": {"洗浄": "声の高さを洗浄するとは言わない。洗浄は汚れを落とす作業で、この文脈には合わない。", "冷却": "声の高さを冷やすという意味になり、この文脈では不自然。", "焼却": "燃やして処分する意味で、声の特徴を調べる文脈には合わない。", "解析": "声の特徴を細かく調べて気持ちを読み取る流れに合うのは「解析」。"}, "sentence_index": 6, "correct_answer": "解析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "放課後、教室の解析をした。", "explanation": "ここは〈清掃〉の意味。解析は物の中身を調べることで、きれいにする意味では使わない。"}, {"text": "先生は、黒板の字を解析して消した。", "explanation": "ここは〈消去〉の意味。解析は中身を細かく調べることで、字を消す意味では使わない。"}, {"text": "会議の資料を英語に解析して配った。", "explanation": "ここは〈翻訳〉の意味。翻訳は文章を別の言語に置き換えることで、中身を細かく調べる解析とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37732, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大学の研究室で、土の成分の解析に依頼した。", "corrected_sentence": "大学の研究室で、土の成分の解析を依頼した。", "error_description": "「依頼する」は頼む対象を「を」で示す。「解析に」では依頼の対象が示されず、文が成り立たない。「解析を依頼した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37732, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "録音した自分の声を解析れると、話し方の癖が分かった。", "corrected_sentence": "録音した自分の声を解析すると、話し方の癖が分かった。", "error_description": "サ変動詞「解析する」の活用を誤っている。「す」を「れ」に変えたのが誤りで、「解析すると」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37733, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「解析に一か月かけた」は、作業に時間を使う意味で「に」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「解析が一か月かけた」では主語と動詞が合わず、時間を使う文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「解析の一か月かけた」は連体修飾のままで文が完結せず、文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は行き先の方向を表すため、時間をかける対象の「解析」とは結びつかず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「解析に一か月かけた」は、作業に時間を使う意味で「に」が正しい。", "が": "「解析が一か月かけた」では主語と動詞が合わず、時間を使う文として成り立たない。", "の": "「解析の一か月かけた」は連体修飾のままで文が完結せず、文にならない。", "へ": "「へ」は行き先の方向を表すため、時間をかける対象の「解析」とは結びつかず、文が成り立たない。"}, "error_tags": {"が": "主格", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37733, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「解析が進み」は、作業が進行する主語を示す「が」で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「解析を進み」は「進む」が自動詞なので、目的語の「を」とは合わない。"}, {"text": "と", "is_correct": false, "explanation": "「解析と進み」は並列や引用の「と」で、文の意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「解析より進み」は比較の「より」で、文の意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「解析が進み」は、作業が進行する主語を示す「が」で正しい。", "を": "「解析を進み」は「進む」が自動詞なので、目的語の「を」とは合わない。", "と": "「解析と進み」は並列や引用の「と」で、文の意味が通らない。", "より": "「解析より進み」は比較の「より」で、文の意味が通らない。"}, "error_tags": {"を": "目的語（自動詞と不一致）", "と": "並列・引用", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37733, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複雑な事柄を細かく調べて、その仕組みや意味を明らかにすること。", "primary_collocate": null, "pronunciation": "かいせき", "ipa": "kaiseki", "syllable_count": 4, "sentences": [{"text": "近年、センサーやデータ解析技術を活用した「精密農業」が注目されています。", "target_word": "解析", "complexity_tier": "T3", "furigana": "近年[きんねん]、センサーやデータ解析[かいせき]技術[ぎじゅつ]を活用[かつよう]した「精密農業[せいみつのうぎょう]」が注目[ちゅうもく]されています。", "sentence_source": "mined"}, {"text": "研究者は、集めた大量のデータの解析に一か月かけた。", "target_word": "解析", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、集[あつ]めた大量[たいりょう]のデータの解析[かいせき]に一[いっ]か月[げつ]かけた。", "sentence_source": "generated"}, {"text": "事故の原因を解析した結果、部品の不具合だと分かった。", "target_word": "解析", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]を解析[かいせき]した結果[けっか]、部品[ぶひん]の不具合[ふぐあい]だと分[わ]かった。", "sentence_source": "generated"}, {"text": "この装置は、血液の成分を短時間で解析できます。", "target_word": "解析", "complexity_tier": "T3", "furigana": "この装置[そうち]は、血液[けつえき]の成分[せいぶん]を短時間[たんじかん]で解析[かいせき]できます。", "sentence_source": "generated"}, {"text": "専門家が遺伝子を解析すると、病気のなりやすさが分かる場合がある。", "target_word": "解析", "complexity_tier": "T3", "furigana": "専門家[せんもんか]が遺伝子[いでんし]を解析[かいせき]すると、病気[びょうき]のなりやすさが分[わ]かる場合[ばあい]がある。", "sentence_source": "generated"}, {"text": "アンケートの結果を解析して、客の好みの変化を調べました。", "target_word": "解析", "complexity_tier": "T3", "furigana": "アンケートの結果[けっか]を解析[かいせき]して、客[きゃく]の好[この]みの変化[へんか]を調[しら]べました。", "sentence_source": "generated"}, {"text": "彼は敵の戦い方を解析し、弱点を見つけた。", "target_word": "解析", "complexity_tier": "T3", "furigana": "彼[かれ]は敵[てき]の戦[たたか]い方[かた]を解析[かいせき]し、弱点[じゃくてん]を見[み]つけた。", "sentence_source": "generated"}, {"text": "地震の揺れの解析が進み、建物の設計に生かされている。", "target_word": "解析", "complexity_tier": "T3", "furigana": "地震[じしん]の揺[ゆ]れの解析[かいせき]が進[すす]み、建物[たてもの]の設計[せっけい]に生[い]かされている。", "sentence_source": "generated"}, {"text": "複雑な文章の構造を解析するソフトが、翻訳に使われています。", "target_word": "解析", "complexity_tier": "T3", "furigana": "複雑[ふくざつ]な文章[ぶんしょう]の構造[こうぞう]を解析[かいせき]するソフトが、翻訳[ほんやく]に使[つか]われています。", "sentence_source": "generated"}, {"text": "天気の変化は複雑なので、コンピューターによる解析が欠かせない。", "target_word": "解析", "complexity_tier": "T3", "furigana": "天気[てんき]の変化[へんか]は複雑[ふくざつ]なので、コンピューターによる解析[かいせき]が欠[か]かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解析", "label": "名詞(基本形)"}, {"form": "解析する", "label": "サ変動詞・終止形"}, {"form": "解析して", "label": "て形"}, {"form": "解析した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "複雑な事柄やデータを細かく調べ、仕組みや意味を明らかにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37733, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発酵", "is_correct": false, "explanation": "「データ発酵技術」は意味が通らない。発酵は微生物が物質を変える現象で、データを調べる文脈には合わない。"}, {"text": "解析", "is_correct": true, "explanation": "「データ〜技術」には、データを細かく調べて仕組みを明らかにする技術を表すこの語が入る。"}, {"text": "防水", "is_correct": false, "explanation": "「データ防水技術」は不自然。防水は水を通さないようにすることで、データの処理には使わない。"}, {"text": "溶接", "is_correct": false, "explanation": "「データ溶接技術」は意味をなさない。溶接は金属をつなぎ合わせる作業で、データには使わない。"}], "explanations": {"発酵": "「データ発酵技術」は意味が通らない。発酵は微生物が物質を変える現象で、データを調べる文脈には合わない。", "解析": "「データ〜技術」には、データを細かく調べて仕組みを明らかにする技術を表すこの語が入る。", "防水": "「データ防水技術」は不自然。防水は水を通さないようにすることで、データの処理には使わない。", "溶接": "「データ溶接技術」は意味をなさない。溶接は金属をつなぎ合わせる作業で、データには使わない。"}, "sentence_index": 0, "correct_answer": "解析"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食のスープを解析して、味を整えた。", "explanation": "ここは〈味付け〉の意味。解析は中身を細かく調べることで、料理の味を整える意味では使わない。"}, {"text": "散らかった机を解析して、きれいに並べた。", "explanation": "ここは〈整理〉の意味。解析は中身を細かく調べることで、物を片づける意味では使わない。"}, {"text": "図書館の本を解析して、ジャンルごとに分けた。", "explanation": "ここは〈分類〉の意味。分類は同じ種類ごとに分けることで、中身を調べる解析とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37733, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酸化", "is_correct": false, "explanation": "「戦い方を酸化」は意味をなさない。酸化は物質が酸素と結びつく変化で、戦い方には使わない。"}, {"text": "解凍", "is_correct": false, "explanation": "「戦い方を解凍」は冷凍したものを戻す意味で、この文脈に合わない。"}, {"text": "解析", "is_correct": true, "explanation": "「敵の戦い方を〜し、弱点を見つけた」は、詳しく調べて弱点を見つける流れに合う。"}, {"text": "乾燥", "is_correct": false, "explanation": "「戦い方を乾燥」は水分をとばす意味で、この文脈では成り立たない。"}], "explanations": {"酸化": "「戦い方を酸化」は意味をなさない。酸化は物質が酸素と結びつく変化で、戦い方には使わない。", "解凍": "「戦い方を解凍」は冷凍したものを戻す意味で、この文脈に合わない。", "解析": "「敵の戦い方を〜し、弱点を見つけた」は、詳しく調べて弱点を見つける流れに合う。", "乾燥": "「戦い方を乾燥」は水分をとばす意味で、この文脈では成り立たない。"}, "sentence_index": 6, "correct_answer": "解析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕食のあと、家族で皿の解析をした。", "explanation": "ここは〈洗う〉の意味。解析は物の仕組みや中身を調べることで、汚れを落とす意味では使わない。"}, {"text": "健康診断で視力の解析をした。", "explanation": "ここは〈検査〉の意味。検査は基準と比べて確かめることで、詳しく仕組みを調べる解析とは違う。"}, {"text": "店で買った服を解析して、丈を詰めた。", "explanation": "ここは〈仕立て直し〉の意味。解析は中身を細かく調べることで、布の長さを変える作業とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37733, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察は事件の手がかりを解析が、犯人を見つけた。", "corrected_sentence": "警察は事件の手がかりを解析して、犯人を見つけた。", "error_description": "「解析」は動作を表すサ変名詞で、直後に「が」を付けると文が続かない。「解析して」と接続して「見つけた」につなげるのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37733, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は敵の戦い方を解析する、弱点を見つけた。", "corrected_sentence": "彼は敵の戦い方を解析して、弱点を見つけた。", "error_description": "「解析する」の終止形で文を切って「、」で続けると文が成り立たない。並列を表す「解析して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37734, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小", "is_correct": true, "explanation": "「最大」の対義語。仲間の中で最も小さいことを指す。"}, {"text": "平均", "is_correct": false, "explanation": "全体をならした中間の値で、対義語ではない。"}, {"text": "中央", "is_correct": false, "explanation": "中心の位置を指すもので、反対の意味にはならない。"}, {"text": "基準", "is_correct": false, "explanation": "比べる目安のことで、「最も大きい」の反対語ではない。"}], "correct_answer": "最小", "explanations": {"最小": "「最大」の対義語。仲間の中で最も小さいことを指す。", "平均": "全体をならした中間の値で、対義語ではない。", "中央": "中心の位置を指すもので、反対の意味にはならない。", "基準": "比べる目安のことで、「最も大きい」の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37734, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小", "is_correct": true, "explanation": "「最大」の対義語。仲間の中で最も小さいことを指す。"}, {"text": "標準", "is_correct": false, "explanation": "基準となる水準のことで、反対の意味にはならない。"}, {"text": "中間", "is_correct": false, "explanation": "両端の間の位置を表すもので、対義語ではない。"}, {"text": "平常", "is_correct": false, "explanation": "ふだんの状態を指し、「最も大きい」の反対語ではない。"}], "correct_answer": "最小", "explanations": {"最小": "「最大」の対義語。仲間の中で最も小さいことを指す。", "標準": "基準となる水準のことで、反対の意味にはならない。", "中間": "両端の間の位置を表すもので、対義語ではない。", "平常": "ふだんの状態を指し、「最も大きい」の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37734, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "いちばんおおきいこと。", "primary_collocate": null, "pronunciation": "さいだい", "ipa": "saidai", "syllable_count": 4, "sentences": [{"text": "動物園で最大の動物は、アフリカゾウです。", "target_word": "最大", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]で最大[さいだい]の動物[どうぶつ]は、アフリカゾウです。", "sentence_source": "generated"}, {"text": "世界最大の海は太平洋だ。", "target_word": "最大", "complexity_tier": "T3", "furigana": "世界[せかい]最大[さいだい]の海[うみ]は太平洋[たいへいよう]だ。", "sentence_source": "generated"}, {"text": "このクラスで最大のかぼちゃを、花子さんが育てた。", "target_word": "最大", "complexity_tier": "T3", "furigana": "このクラスで最大[さいだい]のかぼちゃを、花子[はなこ]さんが育[そだ]てた。", "sentence_source": "generated"}, {"text": "最大のケーキを作るために、みんなで材料を集めた。", "target_word": "最大", "complexity_tier": "T3", "furigana": "最大[さいだい]のケーキを作[つく]るために、みんなで材料[ざいりょう]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "彼の最大の夢は、宇宙飛行士になることだ。", "target_word": "最大", "complexity_tier": "T3", "furigana": "彼[かれ]の最大[さいだい]の夢[ゆめ]は、宇宙[うちゅう]飛行士[ひこうし]になることだ。", "sentence_source": "generated"}, {"text": "この町の最大の祭りは、夏の花火大会だ。", "target_word": "最大", "complexity_tier": "T3", "furigana": "この町[まち]の最大[さいだい]の祭[まつ]りは、夏[なつ]の花火[はなび]大会[たいかい]だ。", "sentence_source": "generated"}, {"text": "私の家族で最大の問題は、朝起きられないことだ。", "target_word": "最大", "complexity_tier": "T3", "furigana": "私[わたし]の家族[かぞく]で最大[さいだい]の問題[もんだい]は、朝[あさ]起[お]きられないことだ。", "sentence_source": "generated"}, {"text": "最大のスーツケースでも、お土産が入りきらなかった。", "target_word": "最大", "complexity_tier": "T3", "furigana": "最大[さいだい]のスーツケースでも、お土産[みやげ]が入[はい]りきらなかった。", "sentence_source": "generated"}, {"text": "日本最大の湖は琵琶湖で、滋賀県にある。", "target_word": "最大", "complexity_tier": "T3", "furigana": "日本[にほん]最大[さいだい]の湖[みずうみ]は琵琶湖[びわこ]で、滋賀県[しがけん]にある。", "sentence_source": "generated"}, {"text": "今日の釣りで、最大の魚は三十センチだった。", "target_word": "最大", "complexity_tier": "T3", "furigana": "今日[きょう]の釣[つ]りで、最大[さいだい]の魚[さかな]は三十[さんじゅう]センチだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "最大", "label": "基本形"}, {"form": "最大の", "label": "連体形"}, {"form": "最大で", "label": "で形"}], "register": "neutral", "sense_fingerprint": "仲間の中でいちばん大きいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37734, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最大", "is_correct": true, "explanation": "「動物園で最大の動物」で、仲間の中で一番大きいものを表す名詞の形。"}, {"text": "最大で", "is_correct": false, "explanation": "「動物園で最大で」となり、後の「の動物」に続かない。"}, {"text": "最大に", "is_correct": false, "explanation": "「に」は副詞用法なので、名詞「動物」を修飾できない。"}, {"text": "最大を", "is_correct": false, "explanation": "「を」は目的語を示すため、場所を示す「動物園で」の後には続かない。"}], "explanations": {"最大": "「動物園で最大の動物」で、仲間の中で一番大きいものを表す名詞の形。", "最大で": "「動物園で最大で」となり、後の「の動物」に続かない。", "最大に": "「に」は副詞用法なので、名詞「動物」を修飾できない。", "最大を": "「を」は目的語を示すため、場所を示す「動物園で」の後には続かない。"}, "sentence_index": 0, "correct_answer": "最大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの店の料理は、味が最大だと評判だ。", "explanation": "ここは〈最高〉の意味（味が一番よい）。「最大」は大きさの一番を表すので、味の良し悪しには合わない。"}, {"text": "彼女は最大のやり方で仕事を片付けた。", "explanation": "ここは〈最善〉の意味（いちばん良い方法）。「最大」は大きさを表すので、やり方の良し悪しには合わない。"}, {"text": "この薬は子どもに最大だ。", "explanation": "ここは〈最適〉の意味（条件に一番合う）。「最大」は大きさや程度を表し、薬の合い具合は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37734, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最大", "is_correct": true, "explanation": "「私の家族で最大の問題」で、家族の中で一番大きい問題を表す名詞の形。"}, {"text": "最大の", "is_correct": false, "explanation": "「家族で」の直後に「最大の」を入れると、後の「の問題」の「の」と重なり成り立たない。"}, {"text": "最大だ", "is_correct": false, "explanation": "「だ」は述語の形で、名詞「問題」を修飾する位置には入らない。"}, {"text": "最大へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「家族で」の後の名詞修飾には合わない。"}], "explanations": {"最大": "「私の家族で最大の問題」で、家族の中で一番大きい問題を表す名詞の形。", "最大の": "「家族で」の直後に「最大の」を入れると、後の「の問題」の「の」と重なり成り立たない。", "最大だ": "「だ」は述語の形で、名詞「問題」を修飾する位置には入らない。", "最大へ": "「へ」は方向を示すので、「家族で」の後の名詞修飾には合わない。"}, "sentence_index": 6, "correct_answer": "最大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このホテルの朝食は、最大の味わいだった。", "explanation": "ここは〈最上〉の意味（いちばん優れた）。「最大」は大きさを表すので、味わいの優劣は表せない。"}, {"text": "今朝は最大の空模様だった。", "explanation": "ここは〈最悪〉の意味（いちばん悪い）。「最大」は大きさの一番を指すので、空模様の悪さには使えない。"}, {"text": "この靴は、長く歩くのに最大の履き心地だ。", "explanation": "ここは〈最良〉の意味（いちばん良い）。「最大」は大きさを表し、履き心地の良さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37734, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "世界最大に島はグリーンランドだ。", "corrected_sentence": "世界最大の島はグリーンランドだ。", "error_description": "誤：「最大に」（助詞「に」）→正：「最大の」（「の」）。「最大」は名詞で、後の「島」を修飾するには「の」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37734, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私の町で最大へ祭りは夏に開かれる。", "corrected_sentence": "私の町で最大の祭りは夏に開かれる。", "error_description": "誤：「最大へ」（助詞「へ」）→正：「最大の」（「の」）。「最大」は名詞で、後の「祭り」を修飾するには「の」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37735, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小", "is_correct": true, "explanation": "「最大」の対義語。範囲の中で最も小さいことを指し、「最も大きい」の反対になる。"}, {"text": "平均", "is_correct": false, "explanation": "全体をならした中間の値で、「最も大きい」の反対語ではない。"}, {"text": "中間", "is_correct": false, "explanation": "両端の間の位置を表すもので、「最も大きい」の反対語ではない。"}, {"text": "標準", "is_correct": false, "explanation": "基準となる水準のことで、反対の意味にはならない。"}], "correct_answer": "最小", "explanations": {"最小": "「最大」の対義語。範囲の中で最も小さいことを指し、「最も大きい」の反対になる。", "平均": "全体をならした中間の値で、「最も大きい」の反対語ではない。", "中間": "両端の間の位置を表すもので、「最も大きい」の反対語ではない。", "標準": "基準となる水準のことで、反対の意味にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37735, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小", "is_correct": true, "explanation": "「最大」の対義語。範囲の中で最も小さいことを指す。"}, {"text": "中央", "is_correct": false, "explanation": "中心の位置を指すもので、「最も大きい」の反対語ではない。"}, {"text": "基準", "is_correct": false, "explanation": "比べる目安のことで、反対の意味にはならない。"}, {"text": "平常", "is_correct": false, "explanation": "ふだんの状態を指し、「最も大きい」の反対語ではない。"}], "correct_answer": "最小", "explanations": {"最小": "「最大」の対義語。範囲の中で最も小さいことを指す。", "中央": "中心の位置を指すもので、「最も大きい」の反対語ではない。", "基準": "比べる目安のことで、反対の意味にはならない。", "平常": "ふだんの状態を指し、「最も大きい」の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37735, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ある範囲の中で、最も大きいこと。", "primary_collocate": null, "pronunciation": "さいだい", "ipa": "saidai", "syllable_count": 4, "sentences": [{"text": "この町で最大の寺は、千年以上の歴史がある。", "target_word": "最大", "complexity_tier": "T3", "furigana": "この町[まち]で最大[さいだい]の寺[てら]は、千年[せんねん]以上[いじょう]の歴史[れきし]がある。", "sentence_source": "generated"}, {"text": "県内最大の湖で、多くの観光客が訪れる。", "target_word": "最大", "complexity_tier": "T3", "furigana": "県内[けんない]最大[さいだい]の湖[みずうみ]で、多[おお]くの観光客[かんこうきゃく]が訪[おとず]れる。", "sentence_source": "generated"}, {"text": "今日の最大の課題は、時間が足りないことだ。", "target_word": "最大", "complexity_tier": "T3", "furigana": "今日[きょう]の最大[さいだい]の課題[かだい]は、時間[じかん]が足[た]りないことだ。", "sentence_source": "generated"}, {"text": "この台風の最大の被害は、川の氾濫だった。", "target_word": "最大", "complexity_tier": "T3", "furigana": "この台風[たいふう]の最大[さいだい]の被害[ひがい]は、川[かわ]の氾濫[はんらん]だった。", "sentence_source": "generated"}, {"text": "このホールには最大で五百人が入れる。", "target_word": "最大", "complexity_tier": "T3", "furigana": "このホールには最大[さいだい]で五百[ごひゃく]人[にん]が入[はい]れる。", "sentence_source": "generated"}, {"text": "彼は最大の力を出して、重い荷物を持ち上げた。", "target_word": "最大", "complexity_tier": "T3", "furigana": "彼[かれ]は最大[さいだい]の力[ちから]を出[だ]して、重[おも]い荷物[にもつ]を持[も]ち上[あ]げた。", "sentence_source": "generated"}, {"text": "東京は日本で最大の人口を持つ都市だ。", "target_word": "最大", "complexity_tier": "T3", "furigana": "東京[とうきょう]は日本[にほん]で最大[さいだい]の人口[じんこう]を持[も]つ都市[とし]だ。", "sentence_source": "generated"}, {"text": "今回の試合で最大の山場は、最後の五分間だった。", "target_word": "最大", "complexity_tier": "T3", "furigana": "今回[こんかい]の試合[しあい]で最大[さいだい]の山場[やまば]は、最後[さいご]の五分間[ごふんかん]だった。", "sentence_source": "generated"}, {"text": "小さな店だが、最大の魅力は手作りのパンだ。", "target_word": "最大", "complexity_tier": "T3", "furigana": "小[ちい]さな店[みせ]だが、最大[さいだい]の魅力[みりょく]は手作[てづく]りのパンだ。", "sentence_source": "generated"}, {"text": "地震の最大の揺れは、午後三時に観測された。", "target_word": "最大", "complexity_tier": "T3", "furigana": "地震[じしん]の最大[さいだい]の揺[ゆ]れは、午後[ごご]三時[さんじ]に観測[かんそく]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "最大", "label": "基本形"}, {"form": "最大の", "label": "連体形"}, {"form": "最大で", "label": "で形"}], "register": "neutral", "sense_fingerprint": "ある範囲や条件の中で、大きさや程度が最も大きいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37735, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最大", "is_correct": true, "explanation": "「この町で最大の寺」で、範囲の中で一番大きいものを表す名詞の形。"}, {"text": "最大で", "is_correct": false, "explanation": "「で」は範囲や場所を示すため、後の「の寺」に続かない。"}, {"text": "最大に", "is_correct": false, "explanation": "「に」は副詞用法なので、名詞「寺」を修飾できない。"}, {"text": "最大を", "is_correct": false, "explanation": "「を」は目的語を示すため、「最大を」の後に「の寺」は続かない。"}], "explanations": {"最大": "「この町で最大の寺」で、範囲の中で一番大きいものを表す名詞の形。", "最大で": "「で」は範囲や場所を示すため、後の「の寺」に続かない。", "最大に": "「に」は副詞用法なので、名詞「寺」を修飾できない。", "最大を": "「を」は目的語を示すため、「最大を」の後に「の寺」は続かない。"}, "sentence_index": 0, "correct_answer": "最大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店のラーメンは、町で最大の味だ。", "explanation": "ここは〈最高〉の意味（いちばん良い味）。「最大」は大きさを表すので、味の良し悪しは表せない。"}, {"text": "問題を解決するため、最大の方法を選んだ。", "explanation": "ここは〈最善〉の意味（いちばん良い方法）。「最大」は大きさを表し、方法の良し悪しには合わない。"}, {"text": "この部屋は、勉強するのに最大の環境だ。", "explanation": "ここは〈最適〉の意味（条件に一番合う）。「最大」は大きさを表すので、環境が合っているかは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37735, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最大", "is_correct": true, "explanation": "「日本で最大の人口」で、比べて一番多い人口を表す名詞の形。"}, {"text": "最大の", "is_correct": false, "explanation": "「日本で」の直後に「最大の」を入れると、後の「の人口」と「の」が重なり成り立たない。"}, {"text": "最大だ", "is_correct": false, "explanation": "「だ」は述語の形で、名詞「人口」を修飾する位置には入らない。"}, {"text": "最大へ", "is_correct": false, "explanation": "「へ」は方向を示す助詞で、「日本で」の後の名詞修飾には使えない。"}], "explanations": {"最大": "「日本で最大の人口」で、比べて一番多い人口を表す名詞の形。", "最大の": "「日本で」の直後に「最大の」を入れると、後の「の人口」と「の」が重なり成り立たない。", "最大だ": "「だ」は述語の形で、名詞「人口」を修飾する位置には入らない。", "最大へ": "「へ」は方向を示す助詞で、「日本で」の後の名詞修飾には使えない。"}, "sentence_index": 6, "correct_answer": "最大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この選手は、チームで最大の仕事ぶりを見せた。", "explanation": "ここは〈最上〉の意味（いちばん優れた）。「最大」は大きさを表すので、仕事ぶりの優劣は表せない。"}, {"text": "今日は最大の天気だった。", "explanation": "ここは〈最悪〉の意味（いちばん悪い）。「最大」は大きさの一番を指すので、天気の悪さには使えない。"}, {"text": "この家は、家族にとって最大の住み心地だ。", "explanation": "ここは〈最良〉の意味（いちばん良い）。「最大」は大きさを表すので、住み心地の良さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37735, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町には最大に寺がある。", "corrected_sentence": "この町には最大の寺がある。", "error_description": "誤：「最大に」（助詞「に」）→正：「最大の」（「の」）。「最大」は名詞で、後の名詞「寺」を修飾するには「の」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37735, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この県は日本で最大から米の産地だ。", "corrected_sentence": "この県は日本で最大の米の産地だ。", "error_description": "誤：「最大から」（助詞「から」）→正：「最大の」（「の」）。「最大」は後の名詞「米の産地」を修飾するので「の」が必要。「から」は起点の助詞で合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37736, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「追求をやめない」で、やめる対象を表す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「追求にやめない」では「やめる」と結びつかず誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「追求へやめない」では対象を表せず誤り。"}, {"text": "と", "is_correct": false, "explanation": "「追求とやめない」では意味が通らず誤り。"}], "correct_answer": "を", "explanations": {"を": "「追求をやめない」で、やめる対象を表す「を」。", "に": "「追求にやめない」では「やめる」と結びつかず誤り。", "へ": "「追求へやめない」では対象を表せず誤り。", "と": "「追求とやめない」では意味が通らず誤り。"}, "error_tags": {"に": "target_misuse", "へ": "direction_misuse", "と": "accompaniment_misuse"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "断念", "is_correct": true, "explanation": "あきらめず続ける追求に対し、あきらめる断念は反対の意味。"}, {"text": "努力", "is_correct": false, "explanation": "努力は励むことで、追求に近く反対ではない。"}, {"text": "継続", "is_correct": false, "explanation": "継続は続けることで、追求の反対ではない。"}, {"text": "研究", "is_correct": false, "explanation": "研究は調べ求めることで、追求の反対ではない。"}], "correct_answer": "断念", "explanations": {"断念": "あきらめず続ける追求に対し、あきらめる断念は反対の意味。", "努力": "努力は励むことで、追求に近く反対ではない。", "継続": "継続は続けることで、追求の反対ではない。", "研究": "研究は調べ求めることで、追求の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37736, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「夢を追求する」で、追求の対象を表す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「夢が追求して」では主語が重なり誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「夢へ追求して」では対象を表せず誤り。"}, {"text": "と", "is_correct": false, "explanation": "「夢と追求して」では意味が通らず誤り。"}], "correct_answer": "を", "explanations": {"を": "「夢を追求する」で、追求の対象を表す「を」。", "が": "「夢が追求して」では主語が重なり誤り。", "へ": "「夢へ追求して」では対象を表せず誤り。", "と": "「夢と追求して」では意味が通らず誤り。"}, "error_tags": {"が": "subject_misuse", "へ": "direction_misuse", "と": "accompaniment_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放棄", "is_correct": true, "explanation": "目指し続ける追求に対し、手放す放棄は反対の意味。"}, {"text": "探求", "is_correct": false, "explanation": "探求は追い求める意味で、反対ではなく近い意味。"}, {"text": "挑戦", "is_correct": false, "explanation": "挑戦は取り組むことで、追求の反対ではない。"}, {"text": "実現", "is_correct": false, "explanation": "実現は現実にすることで、追求の反対ではない。"}], "correct_answer": "放棄", "explanations": {"放棄": "目指し続ける追求に対し、手放す放棄は反対の意味。", "探求": "探求は追い求める意味で、反対ではなく近い意味。", "挑戦": "挑戦は取り組むことで、追求の反対ではない。", "実現": "実現は現実にすることで、追求の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37736, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを一生懸命に目指して、あきらめないでやり続けること。", "primary_collocate": null, "pronunciation": "ついきゅう", "ipa": "tsɯikʲɯː", "syllable_count": 4, "sentences": [{"text": "夢を追求します。", "target_word": "追求します", "complexity_tier": "T2", "furigana": "夢(ゆめ)を追求(ついきゅう)します。", "sentence_source": "generated"}, {"text": "彼は夢の追求をやめない。", "target_word": "追求", "complexity_tier": "T2", "furigana": "彼(かれ)は夢(ゆめ)の追求(ついきゅう)をやめない。", "sentence_source": "generated"}, {"text": "兄は音楽を追求している。", "target_word": "追求している", "complexity_tier": "T3", "furigana": "兄(あに)は音楽(おんがく)を追求(ついきゅう)している。", "sentence_source": "generated"}, {"text": "追求は大変ですが、楽しいです。", "target_word": "追求", "complexity_tier": "T2", "furigana": "追求(ついきゅう)は大変(たいへん)ですが、楽(たの)しいです。", "sentence_source": "generated"}, {"text": "最後まであきらめず、理想の音を追求した。", "target_word": "追求した", "complexity_tier": "T3", "furigana": "最後(さいご)まであきらめず、理想(りそう)の音(おと)を追求(ついきゅう)した。", "sentence_source": "generated"}, {"text": "私は健康を追求したい。", "target_word": "追求したい", "complexity_tier": "T3", "furigana": "私(わたし)は健康(けんこう)を追求(ついきゅう)したい。", "sentence_source": "generated"}, {"text": "強さの追求が、彼の目標だ。", "target_word": "追求", "complexity_tier": "T3", "furigana": "強(つよ)さの追求(ついきゅう)が、彼(かれ)の目標(もくひょう)だ。", "sentence_source": "generated"}, {"text": "彼女は夢を追求して、留学した。", "target_word": "追求して", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は夢(ゆめ)を追求(ついきゅう)して、留学(りゅうがく)した。", "sentence_source": "generated"}, {"text": "追求する気持ちが大切です。", "target_word": "追求する", "complexity_tier": "T3", "furigana": "追求(ついきゅう)する気持(きも)ちが大切(たいせつ)です。", "sentence_source": "generated"}, {"text": "一生懸命に追求すれば、道は開ける。", "target_word": "追求すれば", "complexity_tier": "T4", "furigana": "一生懸命(いっしょうけんめい)に追求(ついきゅう)すれば、道(みち)は開(ひら)ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "追求する", "label": "活用"}, {"form": "追求した", "label": "活用"}, {"form": "追求される", "label": "活用"}, {"form": "追求心", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 目指してあきらめずやり続けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37736, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追求します", "is_correct": true, "explanation": "夢をあきらめず目指す、という文意に合う。"}, {"text": "修理します", "is_correct": false, "explanation": "形は合うが、夢を修理するという意味は合わない。"}, {"text": "輸入します", "is_correct": false, "explanation": "形は合うが、夢を輸入するという意味は合わない。"}, {"text": "運転します", "is_correct": false, "explanation": "形は合うが、夢を運転するという意味は合わない。"}], "explanations": {"追求します": "夢をあきらめず目指す、という文意に合う。", "修理します": "形は合うが、夢を修理するという意味は合わない。", "輸入します": "形は合うが、夢を輸入するという意味は合わない。", "運転します": "形は合うが、夢を運転するという意味は合わない。"}, "sentence_index": 0, "correct_answer": "追求します"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "追求を着て、学校へ行った。", "explanation": "追求は服ではないので、「着る」との組み合わせは誤り。"}, {"text": "かばんの中の追求を探して、取り出した。", "explanation": "追求は具体的な物ではなく、物として探す使い方は誤り。"}, {"text": "犬が追求して、私の前を走った。", "explanation": "追求は走るという意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37736, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追求", "is_correct": true, "explanation": "強さを目指し続けることが目標、という文意に合う。"}, {"text": "修理", "is_correct": false, "explanation": "形は合うが、強さの修理が目標という意味は合わない。"}, {"text": "輸入", "is_correct": false, "explanation": "形は合うが、強さの輸入が目標という意味は合わない。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが、強さの運転が目標という意味は合わない。"}], "explanations": {"追求": "強さを目指し続けることが目標、という文意に合う。", "修理": "形は合うが、強さの修理が目標という意味は合わない。", "輸入": "形は合うが、強さの輸入が目標という意味は合わない。", "運転": "形は合うが、強さの運転が目標という意味は合わない。"}, "sentence_index": 6, "correct_answer": "追求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "追求の中で魚を釣って、夕食にした。", "explanation": "追求は場所ではなく、魚を釣る場所としては使えない。"}, {"text": "追求を電車に乗せて、遠くへ運んだ。", "explanation": "追求は運べる物ではなく、「運ぶ」との組み合わせは誤り。"}, {"text": "私の追求は冷たくて、おいしい。", "explanation": "追求は味や温度を持つ物ではないので、描写として誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37736, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟は絵に追求している。", "corrected_sentence": "弟は絵を追求している。", "error_description": "追求する対象を示す助詞は「に」ではなく「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37736, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は医者になる夢が追求している。", "corrected_sentence": "姉は医者になる夢を追求している。", "error_description": "追求の対象を示す助詞は「が」ではなく「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37737, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「味を追求する」で、追求の対象を表す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「味が追求している」では主語が重なり誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「味へ追求している」では対象を表せず誤り。"}, {"text": "と", "is_correct": false, "explanation": "「味と追求している」では意味が通らず誤り。"}], "correct_answer": "を", "explanations": {"を": "「味を追求する」で、追求の対象を表す「を」。", "が": "「味が追求している」では主語が重なり誤り。", "へ": "「味へ追求している」では対象を表せず誤り。", "と": "「味と追求している」では意味が通らず誤り。"}, "error_tags": {"が": "subject_misuse", "へ": "direction_misuse", "と": "accompaniment_misuse"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放棄", "is_correct": true, "explanation": "目標を追い求める追求に対し、手放す放棄は反対の意味。"}, {"text": "探求", "is_correct": false, "explanation": "探求は追い求める意味で、反対ではなく近い意味。"}, {"text": "達成", "is_correct": false, "explanation": "達成は成し遂げることで、追求の反対ではない。"}, {"text": "継続", "is_correct": false, "explanation": "継続は続けることで、追求の反対ではない。"}], "correct_answer": "放棄", "explanations": {"放棄": "目標を追い求める追求に対し、手放す放棄は反対の意味。", "探求": "探求は追い求める意味で、反対ではなく近い意味。", "達成": "達成は成し遂げることで、追求の反対ではない。", "継続": "継続は続けることで、追求の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37737, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「追求に終わりはない」で、事柄の範囲を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「追求を終わりはない」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「追求へ終わりはない」では意味が通らず誤り。"}, {"text": "が", "is_correct": false, "explanation": "「追求が終わりはない」では助詞が重なり誤り。"}], "correct_answer": "に", "explanations": {"に": "「追求に終わりはない」で、事柄の範囲を示す「に」。", "を": "「追求を終わりはない」では文が成り立たない。", "へ": "「追求へ終わりはない」では意味が通らず誤り。", "が": "「追求が終わりはない」では助詞が重なり誤り。"}, "error_tags": {"を": "object_misuse", "へ": "direction_misuse", "が": "subject_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "断念", "is_correct": true, "explanation": "目指し続ける追求に対し、あきらめる断念は反対の意味。"}, {"text": "研究", "is_correct": false, "explanation": "研究は調べ求めることで、追求の反対ではない。"}, {"text": "実現", "is_correct": false, "explanation": "実現は現実にすることで、追求の反対ではない。"}, {"text": "努力", "is_correct": false, "explanation": "努力は励むことで、追求に近く反対ではない。"}], "correct_answer": "断念", "explanations": {"断念": "目指し続ける追求に対し、あきらめる断念は反対の意味。", "研究": "研究は調べ求めることで、追求の反対ではない。", "実現": "実現は現実にすることで、追求の反対ではない。", "努力": "努力は励むことで、追求に近く反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37737, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "目標や理想を達成しようと、積極的に追い求めること。", "primary_collocate": null, "pronunciation": "ついきゅう", "ipa": "tsɯikʲɯː", "syllable_count": 4, "sentences": [{"text": "これらは視覚的な雑音を減らし、心の豊かさを追求する手段となっています。", "target_word": "追求する", "complexity_tier": "T5", "furigana": "これらは視覚的(しかくてき)な雑音(ざつおん)を減(へ)らし、心(こころ)の豊(ゆた)かさを追求(ついきゅう)する手段(しゅだん)となっています。", "sentence_source": "mined"}, {"text": "彼は理想の味を追求している。", "target_word": "追求している", "complexity_tier": "T3", "furigana": "彼(かれ)は理想(りそう)の味(あじ)を追求(ついきゅう)している。", "sentence_source": "generated"}, {"text": "美の追求が彼女の仕事だ。", "target_word": "追求", "complexity_tier": "T3", "furigana": "美(び)の追求(ついきゅう)が彼女(かのじょ)の仕事(しごと)だ。", "sentence_source": "generated"}, {"text": "利益ばかりを追求すると、信用を失う。", "target_word": "追求すると", "complexity_tier": "T4", "furigana": "利益(りえき)ばかりを追求(ついきゅう)すると、信用(しんよう)を失(うしな)う。", "sentence_source": "generated"}, {"text": "彼女は完璧を追求する人だ。", "target_word": "追求する", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は完璧(かんぺき)を追求(ついきゅう)する人(ひと)だ。", "sentence_source": "generated"}, {"text": "理想の追求には、時間がかかる。", "target_word": "追求", "complexity_tier": "T3", "furigana": "理想(りそう)の追求(ついきゅう)には、時間(じかん)がかかる。", "sentence_source": "generated"}, {"text": "幸せを追求することは悪くない。", "target_word": "追求する", "complexity_tier": "T3", "furigana": "幸(しあわ)せを追求(ついきゅう)することは悪(わる)くない。", "sentence_source": "generated"}, {"text": "品質の追求に終わりはない。", "target_word": "追求", "complexity_tier": "T3", "furigana": "品質(ひんしつ)の追求(ついきゅう)に終(お)わりはない。", "sentence_source": "generated"}, {"text": "技術を追求し続けた結果、特許を取った。", "target_word": "追求し", "complexity_tier": "T4", "furigana": "技術(ぎじゅつ)を追求(ついきゅう)し続(つづ)けた結果(けっか)、特許(とっきょ)を取(と)った。", "sentence_source": "generated"}, {"text": "自由を追求した若者たちが、都市に集まった。", "target_word": "追求した", "complexity_tier": "T4", "furigana": "自由(じゆう)を追求(ついきゅう)した若者(わかもの)たちが、都市(とし)に集(あつ)まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "追求する", "label": "活用"}, {"form": "追求した", "label": "活用"}, {"form": "追求される", "label": "活用"}, {"form": "追求心", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 目標や理想を積極的に追い求めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37737, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追求する", "is_correct": true, "explanation": "心の豊かさを積極的に求める手段、という文意に合う。"}, {"text": "計算する", "is_correct": false, "explanation": "形は合うが、心の豊かさを計算する手段という意味は合わない。"}, {"text": "分解する", "is_correct": false, "explanation": "形は合うが、心の豊かさを分解する手段という意味は合わない。"}, {"text": "輸出する", "is_correct": false, "explanation": "形は合うが、心の豊かさを輸出する手段という意味は合わない。"}], "explanations": {"追求する": "心の豊かさを積極的に求める手段、という文意に合う。", "計算する": "形は合うが、心の豊かさを計算する手段という意味は合わない。", "分解する": "形は合うが、心の豊かさを分解する手段という意味は合わない。", "輸出する": "形は合うが、心の豊かさを輸出する手段という意味は合わない。"}, "sentence_index": 0, "correct_answer": "追求する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "道に落ちたごみを追求して、ごみ箱に捨てた。", "explanation": "追求は目標を追い求めることで、物を拾う意味では使えない。"}, {"text": "友達に追求して、駅まで走った。", "explanation": "追求は人を物理的に追いかける意味では使えない。"}, {"text": "朝ごはんに追求を食べた。", "explanation": "追求は食べ物ではないので、「食べる」との組み合わせは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37737, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追求する", "is_correct": true, "explanation": "幸せを目指して求めることは悪くない、という文意に合う。"}, {"text": "修理する", "is_correct": false, "explanation": "形は合うが、幸せを修理するという意味は合わない。"}, {"text": "運転する", "is_correct": false, "explanation": "形は合うが、幸せを運転するという意味は合わない。"}, {"text": "輸入する", "is_correct": false, "explanation": "形は合うが、幸せを輸入するという意味は合わない。"}], "explanations": {"追求する": "幸せを目指して求めることは悪くない、という文意に合う。", "修理する": "形は合うが、幸せを修理するという意味は合わない。", "運転する": "形は合うが、幸せを運転するという意味は合わない。", "輸入する": "形は合うが、幸せを輸入するという意味は合わない。"}, "sentence_index": 6, "correct_answer": "追求する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "犬を追求して、公園を一周した。", "explanation": "追求は動物を追いかける意味では使えない。"}, {"text": "追求が空から降ってきて、傘をさした。", "explanation": "追求は雨のように降る物ではなく、主語として誤り。"}, {"text": "弟は追求を飲んで元気になった。", "explanation": "追求は飲み物ではないので、「飲む」との組み合わせは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
