INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37738, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "空など、ものの上の方までの高さのこと。", "primary_collocate": null, "pronunciation": "こうど", "ipa": "koːdo", "syllable_count": 3, "sentences": [{"text": "飛行機は高度一万メートルまで上がった。", "target_word": "高度", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は高度[こうど]一万[いちまん]メートルまで上[あ]がった。", "sentence_source": "generated"}, {"text": "高度が上がると、空気がうすくなって寒くなる。", "target_word": "高度", "complexity_tier": "T3", "furigana": "高度[こうど]が上[あ]がると、空気[くうき]がうすくなって寒[さむ]くなる。", "sentence_source": "generated"}, {"text": "パイロットは高度を下げて、着陸の準備を始めた。", "target_word": "高度", "complexity_tier": "T3", "furigana": "パイロットは高度[こうど]を下[さ]げて、着陸[ちゃくりく]の準備[じゅんび]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "ドローンは高度百メートルを超えて飛んではいけない決まりがある。", "target_word": "高度", "complexity_tier": "T3", "furigana": "ドローンは高度[こうど]百[ひゃく]メートルを超[こ]えて飛[と]んではいけない決[き]まりがある。", "sentence_source": "generated"}, {"text": "ヘリコプターは低い高度で町の上を飛んでいた。", "target_word": "高度", "complexity_tier": "T3", "furigana": "ヘリコプターは低[ひく]い高度[こうど]で町[まち]の上[うえ]を飛[と]んでいた。", "sentence_source": "generated"}, {"text": "ロケットは高度を上げながら、速く飛んでいった。", "target_word": "高度", "complexity_tier": "T3", "furigana": "ロケットは高度[こうど]を上[あ]げながら、速[はや]く飛[と]んでいった。", "sentence_source": "generated"}, {"text": "飛行機の高度を知るために、パイロットは計器を見た。", "target_word": "高度", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]の高度[こうど]を知[し]るために、パイロットは計器[けいき]を見[み]た。", "sentence_source": "generated"}, {"text": "鳥は高度を保ったまま、ゆっくり海の上を飛んだ。", "target_word": "高度", "complexity_tier": "T3", "furigana": "鳥[とり]は高度[こうど]を保[たも]ったまま、ゆっくり海[うみ]の上[うえ]を飛[と]んだ。", "sentence_source": "generated"}, {"text": "高度が増すにつれて、気圧はだんだん下がっていく。", "target_word": "高度", "complexity_tier": "T3", "furigana": "高度[こうど]が増[ま]すにつれて、気圧[きあつ]はだんだん下[さ]がっていく。", "sentence_source": "generated"}, {"text": "気球は高度を上げすぎて、地上の家が小さく見えた。", "target_word": "高度", "complexity_tier": "T3", "furigana": "気球[ききゅう]は高度[こうど]を上[あ]げすぎて、地上[ちじょう]の家[いえ]が小[ちい]さく見[み]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高度", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "飛行機・鳥・気球などが飛ぶ、空中での地上からの高さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: うすく (Zipf 2.37)']::text[], '0e61789a-9eca-468c-8b66-53ec4aea85ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37738, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高度", "is_correct": true, "explanation": "地面からの空中の高さを表す語で、飛行機が一万メートルまで上がった文に入る。"}, {"text": "速度", "is_correct": false, "explanation": "速度は速さを表す語で、「一万メートルまで」という高さの表現とは合わない。"}, {"text": "重量", "is_correct": false, "explanation": "重量は機体の重さを表す語で、上昇の高さを示す文には入らない。"}, {"text": "燃料", "is_correct": false, "explanation": "燃料は機体の燃料で、「燃料一万メートルまで上がった」は意味をなさない。"}], "explanations": {"高度": "地面からの空中の高さを表す語で、飛行機が一万メートルまで上がった文に入る。", "速度": "速度は速さを表す語で、「一万メートルまで」という高さの表現とは合わない。", "重量": "重量は機体の重さを表す語で、上昇の高さを示す文には入らない。", "燃料": "燃料は機体の燃料で、「燃料一万メートルまで上がった」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "高度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は高度が五階にあって、客が多い。", "explanation": "ここは〈階数〉の意味。店の位置を階で数えるのは階数で、高度は空中の高さを表すので合わない。"}, {"text": "この部屋の高度は三メートルある。", "explanation": "ここは〈高さ〉の意味。天井の高さは高さで表し、空中での高さを表す高度は室内には使わない。"}, {"text": "屋根の高度を三十度にする。", "explanation": "ここは〈傾斜〉の意味。屋根の傾きは傾斜や勾配で表し、高度は空中の高さや天体の角度に使うので、屋根には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37738, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高度", "is_correct": true, "explanation": "飛行機の空中での高さを表す語で、「飛行機の〜を知る」に入る。"}, {"text": "味", "is_correct": false, "explanation": "味は食べ物の性質で、飛行機の味を知るという文は意味をなさない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは匂いの性質で、飛行機の香りを知るという文には合わない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は音楽の一種で、飛行機の歌を知るという文は成り立たない。"}], "explanations": {"高度": "飛行機の空中での高さを表す語で、「飛行機の〜を知る」に入る。", "味": "味は食べ物の性質で、飛行機の味を知るという文は意味をなさない。", "香り": "香りは匂いの性質で、飛行機の香りを知るという文には合わない。", "歌": "歌は音楽の一種で、飛行機の歌を知るという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "高度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪で高度が出て、一日中寝込んだ。", "explanation": "ここは〈高熱〉の意味。体温の高さを指す語で、空中の高さを表す高度は体温には使わない。"}, {"text": "父の高度は百八十センチだ。", "explanation": "ここは〈身長〉の意味。人の背の高さを指す語で、空中の高さを表す高度は人には使わない。"}, {"text": "この部屋は高度が大きくて、眠れない。", "explanation": "ここは〈音量〉の意味。音の大きさは音量で言い、高度は高さを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37738, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ロケットは高度が上げながら、まっすぐ飛んでいった。", "corrected_sentence": "ロケットは高度を上げながら、まっすぐ飛んでいった。", "error_description": "「上げる」の目的語は「高度を」。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37738, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "パイロットは高度を保るために、操縦桿を少し引いた。", "corrected_sentence": "パイロットは高度を保つために、操縦桿を少し引いた。", "error_description": "「保つ」の活用を誤って「保る」とした。「ために」に続く正しい形は「保つ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
