INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37740, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "空気のあたたかさや冷たさの程度。", "primary_collocate": null, "pronunciation": "きおん", "ipa": "kioɴ", "syllable_count": 3, "sentences": [{"text": "冬になって気温が下がると、朝の池に薄い氷が張る。", "target_word": "気温", "complexity_tier": "T3", "furigana": "冬[ふゆ]になって気温[きおん]が下[さ]がると、朝[あさ]の池[いけ]に薄[うす]い氷[こおり]が張[は]る。", "sentence_source": "generated"}, {"text": "気温が高い日は、水を多めに持って散歩に出かける。", "target_word": "気温", "complexity_tier": "T3", "furigana": "気温[きおん]が高[たか]い日[ひ]は、水[みず]を多[おお]めに持[も]って散歩[さんぽ]に出[で]かける。", "sentence_source": "generated"}, {"text": "北の町は、同じ季節でも南の町より気温がずっと低い。", "target_word": "気温", "complexity_tier": "T3", "furigana": "北[きた]の町[まち]は、同[おな]じ季節[きせつ]でも南[みなみ]の町[まち]より気温[きおん]がずっと低[ひく]い。", "sentence_source": "generated"}, {"text": "天気予報によると、明日は気温が二十度まで上がるそうだ。", "target_word": "気温", "complexity_tier": "T3", "furigana": "天気[てんき]予報[よほう]によると、明日[あした]は気温[きおん]が二十度[にじゅうど]まで上[あ]がるそうだ。", "sentence_source": "generated"}, {"text": "気温が急に変わったせいで、弟は風邪をひいてしまった。", "target_word": "気温", "complexity_tier": "T3", "furigana": "気温[きおん]が急[きゅう]に変[か]わったせいで、弟[おとうと]は風邪[かぜ]をひいてしまった。", "sentence_source": "generated"}, {"text": "砂漠では昼と夜の気温の差がとても大きい。", "target_word": "気温", "complexity_tier": "T3", "furigana": "砂漠[さばく]では昼[ひる]と夜[よる]の気温[きおん]の差[さ]がとても大[おお]きい。", "sentence_source": "generated"}, {"text": "気温が低いと、車のバッテリーは力が弱くなる。", "target_word": "気温", "complexity_tier": "T3", "furigana": "気温[きおん]が低[ひく]いと、車[くるま]のバッテリーは力[ちから]が弱[よわ]くなる。", "sentence_source": "generated"}, {"text": "朝の気温を見て、着ていく服を決める人は多い。", "target_word": "気温", "complexity_tier": "T3", "furigana": "朝[あさ]の気温[きおん]を見[み]て、着[き]ていく服[ふく]を決[き]める人[ひと]は多[おお]い。", "sentence_source": "generated"}, {"text": "十月に入っても気温が下がらず、秋らしさを感じない。", "target_word": "気温", "complexity_tier": "T3", "furigana": "十月[じゅうがつ]に入[はい]っても気温[きおん]が下[さ]がらず、秋[あき]らしさを感[かん]じない。", "sentence_source": "generated"}, {"text": "気温が三十度を超えたので、教室のエアコンをつけた。", "target_word": "気温", "complexity_tier": "T3", "furigana": "気温[きおん]が三十度[さんじゅうど]を超[こ]えたので、教室[きょうしつ]のエアコンをつけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気温", "label": "基本形"}], "register": "標準語・中立（普通体）", "sense_fingerprint": "暑い・寒いで感じる空気のあたたかさ冷たさの程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37740, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気温", "is_correct": true, "explanation": "「気温が下がると」の「気温」。冬に下がって池に氷が張るという文脈に合う唯一の語。"}, {"text": "手足", "is_correct": false, "explanation": "体の末端部分。「手足が下がると」は成り立たず、空欄に入らない。"}, {"text": "紙", "is_correct": false, "explanation": "書く材料の紙。「紙が下がると」は成り立たず、空欄に入らない。"}, {"text": "靴", "is_correct": false, "explanation": "足にはく物。「靴が下がると」は成り立たず、空欄に入らない。"}], "explanations": {"気温": "「気温が下がると」の「気温」。冬に下がって池に氷が張るという文脈に合う唯一の語。", "手足": "体の末端部分。「手足が下がると」は成り立たず、空欄に入らない。", "紙": "書く材料の紙。「紙が下がると」は成り立たず、空欄に入らない。", "靴": "足にはく物。「靴が下がると」は成り立たず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "気温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熱が出て、気温が三十七度まで上がった。", "explanation": "ここは〈体温〉の意味。人の体の熱は体温で表す。気温は大気の温度なので、人には使えない。"}, {"text": "彼は気温が荒く、すぐに怒り出す。", "explanation": "ここは〈気性〉の意味。人の性質は気性で表す。気温は大気の温度なので、人の性格には使えない。"}, {"text": "梅雨の朝、気温が崩れて雨が降り出した。", "explanation": "ここは〈天気〉の意味。空のようすが崩れるという言い方は天気で表す。気温は温度なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37740, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気温", "is_correct": true, "explanation": "「気温が低いと」の「気温」。電池の働きに影響する大気の温度を表す唯一の語。"}, {"text": "歩幅", "is_correct": false, "explanation": "歩くときの一歩の長さ。「歩幅が低いと」は成り立たず、空欄に入らない。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさ。「音量が低いと、車のバッテリーは力が弱くなる」は成り立たない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている人の呼吸の音。「寝息が低いと」は成り立たず、空欄に入らない。"}], "explanations": {"気温": "「気温が低いと」の「気温」。電池の働きに影響する大気の温度を表す唯一の語。", "歩幅": "歩くときの一歩の長さ。「歩幅が低いと」は成り立たず、空欄に入らない。", "音量": "音の大きさ。「音量が低いと、車のバッテリーは力が弱くなる」は成り立たない。", "寝息": "眠っている人の呼吸の音。「寝息が低いと」は成り立たず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "気温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "健康診断で気温を測ったら、二キロ増えていた。", "explanation": "ここは〈体重〉の意味。人の重さは体重で表す。気温は大気の温度なので、重さとして使えない。"}, {"text": "梅雨の気温が九十パーセントを超え、洗濯物が乾かなかった。", "explanation": "ここは〈湿度〉の意味。パーセントで表す空気の湿り具合は湿度で、気温は温度なので合わない。"}, {"text": "夕焼けの気温がとても濃くて、目を奪われた。", "explanation": "ここは〈色〉の意味。色の濃さは色で表す。気温は温度なので、濃さの表現には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37740, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨夜は気温が高いて、なかなか寝つけなかった。", "corrected_sentence": "昨夜は気温が高くて、なかなか寝つけなかった。", "error_description": "形容詞「高い」の連用形は「高く」で、「高くて」が正しい。「高いて」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37740, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "気温に十度を下回ったので、朝は霜が降りていた。", "corrected_sentence": "気温が十度を下回ったので、朝は霜が降りていた。", "error_description": "「気温」が「下回る」の主語なので助詞は「が」が正しい。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
