INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37741, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37741, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "大気の温度。空気のあたたかさや冷たさを数値で表したもの。", "primary_collocate": null, "pronunciation": "きおん", "ipa": "kioɴ", "syllable_count": 3, "sentences": [{"text": "毎朝の天気予報を確認し、気温や湿度に合わせて水を調整する。", "target_word": "気温", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]の天気[てんき]予報[よほう]を確認[かくにん]し、気温[きおん]や湿度[しつど]に合[あ]わせて水[みず]を調整[ちょうせい]する。", "sentence_source": "mined"}, {"text": "昨日は朝から気温が急に下がったので、厚手のコートを出した。", "target_word": "気温", "complexity_tier": "T3", "furigana": "昨日[きのう]は朝[あさ]から気温[きおん]が急[きゅう]に下[さ]がったので、厚手[あつで]のコートを出[だ]した。", "sentence_source": "generated"}, {"text": "夏の気温が三十五度を超える日は、無理をせずに室内で過ごす。", "target_word": "気温", "complexity_tier": "T3", "furigana": "夏[なつ]の気温[きおん]が三十五度[さんじゅうごど]を超[こ]える日[ひ]は、無理[むり]をせずに室内[しつない]で過[す]ごす。", "sentence_source": "generated"}, {"text": "山の上は気温が低く、七月でも朝晩は上着が必要だ。", "target_word": "気温", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は気温[きおん]が低[ひく]く、七月[しちがつ]でも朝晩[あさばん]は上着[うわぎ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "気温の変化が大きい季節は、体調をくずしやすい。", "target_word": "気温", "complexity_tier": "T3", "furigana": "気温[きおん]の変化[へんか]が大[おお]きい季節[きせつ]は、体調[たいちょう]をくずしやすい。", "sentence_source": "generated"}, {"text": "今日は風が強く、気温は低くないのに体感はとても寒い。", "target_word": "気温", "complexity_tier": "T3", "furigana": "今日[きょう]は風[かぜ]が強[つよ]く、気温[きおん]は低[ひく]くないのに体感[たいかん]はとても寒[さむ]い。", "sentence_source": "generated"}, {"text": "気温が零度を下回ると、道路の水たまりが凍って危ない。", "target_word": "気温", "complexity_tier": "T3", "furigana": "気温[きおん]が零度[れいど]を下回[したまわ]ると、道路[どうろ]の水[みず]たまりが凍[こお]って危[あぶ]ない。", "sentence_source": "generated"}, {"text": "農家の人たちは、気温に注意しながら野菜の苗を畑に植える。", "target_word": "気温", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]たちは、気温[きおん]に注意[ちゅうい]しながら野菜[やさい]の苗[なえ]を畑[はたけ]に植[う]える。", "sentence_source": "generated"}, {"text": "気温が上がるにつれて、公園で遊ぶ子供たちの声も増えてきた。", "target_word": "気温", "complexity_tier": "T3", "furigana": "気温[きおん]が上[あ]がるにつれて、公園[こうえん]で遊[あそ]ぶ子供[こども]たちの声[こえ]も増[ふ]えてきた。", "sentence_source": "generated"}, {"text": "朝六時に庭で気温を測ると、まだ十度しかなかった。", "target_word": "気温", "complexity_tier": "T3", "furigana": "朝[あさ]六時[ろくじ]に庭[にわ]で気温[きおん]を測[はか]ると、まだ十度[じゅうど]しかなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気温", "label": "基本形"}], "register": "標準語・中立（普通体）", "sense_fingerprint": "天気予報や測定で数値として示される大気の温度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37741, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気温", "is_correct": true, "explanation": "「気温や湿度に合わせて」の「気温」。水の量を決める基準として自然な唯一の語。"}, {"text": "色", "is_correct": false, "explanation": "見た目の色合い。「色や湿度に合わせて水を調整」は基準として成り立たない。"}, {"text": "手触り", "is_correct": false, "explanation": "触れたときの感じ。水の調整の基準としては成り立たず、空欄に入らない。"}, {"text": "歯", "is_correct": false, "explanation": "口の中の器官。「歯や湿度に合わせて水を調整」は成り立たず、空欄に入らない。"}], "explanations": {"気温": "「気温や湿度に合わせて」の「気温」。水の量を決める基準として自然な唯一の語。", "色": "見た目の色合い。「色や湿度に合わせて水を調整」は基準として成り立たない。", "手触り": "触れたときの感じ。水の調整の基準としては成り立たず、空欄に入らない。", "歯": "口の中の器官。「歯や湿度に合わせて水を調整」は成り立たず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "気温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今朝の気温は晴れで、午後から雨が降る見込みだ。", "explanation": "ここは〈天気〉の意味。晴れや雨など空のようすは天気で表すので、温度の数値である気温には合わない。"}, {"text": "熱を測ると、気温が三十八度もあった。", "explanation": "ここは〈体温〉の意味。人の体の熱は体温で表す。気温は大気の温度なので合わない。"}, {"text": "彼女は気温があり、所作がとても美しい。", "explanation": "ここは〈気品〉の意味。人の上品さは気品で表す。気温は大気の温度なので、人には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37741, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気温", "is_correct": true, "explanation": "「気温が零度を下回ると」の「気温」。零度を基準に比べられる大気の温度を表す唯一の語。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の湿り具合を表す。「湿度が零度を下回る」は成り立たず、空欄に入らない。"}, {"text": "距離", "is_correct": false, "explanation": "二点間の隔たりを表す。「距離が零度を下回る」は成り立たず、空欄に入らない。"}, {"text": "血圧", "is_correct": false, "explanation": "血管内の圧力を表す。「血圧が零度を下回る」は成り立たず、空欄に入らない。"}], "explanations": {"気温": "「気温が零度を下回ると」の「気温」。零度を基準に比べられる大気の温度を表す唯一の語。", "湿度": "空気の湿り具合を表す。「湿度が零度を下回る」は成り立たず、空欄に入らない。", "距離": "二点間の隔たりを表す。「距離が零度を下回る」は成り立たず、空欄に入らない。", "血圧": "血管内の圧力を表す。「血圧が零度を下回る」は成り立たず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "気温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この果物は気温が甘くて、子供に人気がある。", "explanation": "ここは〈味〉の意味。食べ物の甘さは味で表す。気温は大気の温度なので、味には使えない。"}, {"text": "この部屋は気温が乾いていて、喉が痛くなる。", "explanation": "ここは〈空気〉の意味。部屋の空気の乾き具合は空気で表す。気温は温度の高低を表す語なので合わない。"}, {"text": "隣の部屋は気温が大きくて、勉強に集中できない。", "explanation": "ここは〈音量〉の意味。音の大きさは音量で表す。気温は温度なので、大きさとして使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37741, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜になって気温を下がったので、暖房をつけた。", "corrected_sentence": "夜になって気温が下がったので、暖房をつけた。", "error_description": "「気温」が「下がる」の主語なので助詞は「が」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37741, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "気温が低いくなって、池の水が凍った。", "corrected_sentence": "気温が低くなって、池の水が凍った。", "error_description": "「低い」の連用形は「低く」で、「低くなって」が正しい。「低いくなって」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
