INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37742, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ものの詰まりぐあいのこと。", "primary_collocate": null, "pronunciation": "みつど", "ipa": "mitsɯdo", "syllable_count": 3, "sentences": [{"text": "このスポンジは、穴が小さくて密度が高い。", "target_word": "密度", "complexity_tier": "T3", "furigana": "このスポンジは、穴[あな]が小[ちい]さくて密度[みつど]が高[たか]い。", "sentence_source": "generated"}, {"text": "木の密度が高いほど、重くてかたい。", "target_word": "密度", "complexity_tier": "T3", "furigana": "木[き]の密度[みつど]が高[たか]いほど、重[おも]くてかたい。", "sentence_source": "generated"}, {"text": "星が集まっている所は、密度が高く見える。", "target_word": "密度", "complexity_tier": "T3", "furigana": "星[ほし]が集[あつ]まっている所[ところ]は、密度[みつど]が高[たか]く見[み]える。", "sentence_source": "generated"}, {"text": "密度の低いパンは、ふわふわで軽い。", "target_word": "密度", "complexity_tier": "T3", "furigana": "密度[みつど]の低[ひく]いパンは、ふわふわで軽[かる]い。", "sentence_source": "generated"}, {"text": "森の木の密度が高くて、光があまり地面に届かない。", "target_word": "密度", "complexity_tier": "T3", "furigana": "森[もり]の木[き]の密度[みつど]が高[たか]くて、光[ひかり]があまり地面[じめん]に届[とど]かない。", "sentence_source": "generated"}, {"text": "電車の中は人の密度が高く、身動きが取れなかった。", "target_word": "密度", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]は人[ひと]の密度[みつど]が高[たか]く、身動[みうご]きが取[と]れなかった。", "sentence_source": "generated"}, {"text": "毛糸の密度を上げて、あたたかいセーターを編んだ。", "target_word": "密度", "complexity_tier": "T3", "furigana": "毛糸[けいと]の密度[みつど]を上[あ]げて、あたたかいセーターを編[あ]んだ。", "sentence_source": "generated"}, {"text": "密度が低いと、すき間が多くて弱くなる。", "target_word": "密度", "complexity_tier": "T3", "furigana": "密度[みつど]が低[ひく]いと、すき間[ま]が多[おお]くて弱[よわ]くなる。", "sentence_source": "generated"}, {"text": "このチョコは中身の密度が高くて、小さくても食べごたえがある。", "target_word": "密度", "complexity_tier": "T3", "furigana": "このチョコは中身[なかみ]の密度[みつど]が高[たか]くて、小[ちい]さくても食[た]べごたえがある。", "sentence_source": "generated"}, {"text": "砂をぎゅっと固めて、密度を上げた。", "target_word": "密度", "complexity_tier": "T3", "furigana": "砂[すな]をぎゅっと固[かた]めて、密度[みつど]を上[あ]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "密度", "label": "基本形"}], "register": "一般", "sense_fingerprint": "ものがどれだけぎっしり詰まっているかの度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37742, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密度", "is_correct": true, "explanation": "穴が小さく、ものが詰まっている度合いを表すので正解。"}, {"text": "面積", "is_correct": false, "explanation": "面積は広さを表す語で、「高い」と組み合わせても意味が通らない。"}, {"text": "色", "is_correct": false, "explanation": "色は「高い」で程度を表さないため、この文には入らない。"}, {"text": "形", "is_correct": false, "explanation": "形は「高い」で詰まりぐあいを表せないため、文が成り立たない。"}], "explanations": {"密度": "穴が小さく、ものが詰まっている度合いを表すので正解。", "面積": "面積は広さを表す語で、「高い」と組み合わせても意味が通らない。", "色": "色は「高い」で程度を表さないため、この文には入らない。", "形": "形は「高い」で詰まりぐあいを表せないため、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "密度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この鍋は密度が強火で、すぐ焦げる。", "explanation": "ここは〈火力〉の意味。火の強さは火力で表すので、密度とは合わない。"}, {"text": "今日は密度が高くて、洗濯物が乾かない。", "explanation": "ここは〈湿度〉の意味。空気中の水分の多さは湿度で表すので、密度とは合わない。"}, {"text": "この車は密度が速くて、高速道路でも一番速い。", "explanation": "ここは〈速度〉の意味。速さは速度で表し、「密度が速い」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37742, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密度", "is_correct": true, "explanation": "毛糸の詰まりぐあいを表し、編み目の細かさに合うので正解。"}, {"text": "種類", "is_correct": false, "explanation": "種類は「上げる」と結びつかず、毛糸の密度を上げる文には合わない。"}, {"text": "手間", "is_correct": false, "explanation": "手間は「かける」ものなので、「上げて」では不自然で合わない。"}, {"text": "柄", "is_correct": false, "explanation": "柄は「上げる」と結びつかず、編み方の説明にならない。"}], "explanations": {"密度": "毛糸の詰まりぐあいを表し、編み目の細かさに合うので正解。", "種類": "種類は「上げる」と結びつかず、毛糸の密度を上げる文には合わない。", "手間": "手間は「かける」ものなので、「上げて」では不自然で合わない。", "柄": "柄は「上げる」と結びつかず、編み方の説明にならない。"}, "sentence_index": 6, "correct_answer": "密度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このゴムは密度が硬くて、なかなか伸びない。", "explanation": "ここは〈硬度〉の意味。かたさは硬度で表すので、密度とは合わない。"}, {"text": "この橋は密度が強くて、大型トラックも渡れる。", "explanation": "ここは〈強度〉の意味。耐える力は強度で表すので、密度とは合わない。"}, {"text": "このペンキは密度が鮮やかで、遠くからも見える。", "explanation": "ここは〈鮮やかさ〉の意味。色の鮮明さを言うので、密度とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37742, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この箱は紙の密度を高くて、丈夫だ。", "corrected_sentence": "この箱は紙の密度が高くて、丈夫だ。", "error_description": "「密度」は「高い」の主語になるので「が」を使う。「を」は誤りで、正しくは「密度が高い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37742, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この布は、目の密度が高いくて丈夫だ。", "corrected_sentence": "この布は、目の密度が高くて丈夫だ。", "error_description": "形容詞「高い」の連用形は「高く」で、「高いくて」は誤り。正しくは「高くて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
