INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37743, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物質や空間にどれだけ物が入っているかを表す量。", "primary_collocate": null, "pronunciation": "みつど", "ipa": "mitsɯdo", "syllable_count": 3, "sentences": [{"text": "水の密度は、一立方センチメートルあたり約一グラムだ。", "target_word": "密度", "complexity_tier": "T3", "furigana": "水[みず]の密度[みつど]は、一立方[いちりっぽう]センチメートルあたり約[やく]一[いち]グラムだ。", "sentence_source": "generated"}, {"text": "鉄は水より密度が大きいので、水に沈む。", "target_word": "密度", "complexity_tier": "T3", "furigana": "鉄[てつ]は水[みず]より密度[みつど]が大[おお]きいので、水[みず]に沈[しず]む。", "sentence_source": "generated"}, {"text": "密度は、質量を体積で割って求める。", "target_word": "密度", "complexity_tier": "T3", "furigana": "密度[みつど]は、質量[しつりょう]を体積[たいせき]で割[わ]って求[もと]める。", "sentence_source": "generated"}, {"text": "氷は水より密度が小さいため、水に浮かぶ。", "target_word": "密度", "complexity_tier": "T3", "furigana": "氷[こおり]は水[みず]より密度[みつど]が小[ちい]さいため、水[みず]に浮[う]かぶ。", "sentence_source": "generated"}, {"text": "空気の密度は、高い山ほど小さくなる。", "target_word": "密度", "complexity_tier": "T3", "furigana": "空気[くうき]の密度[みつど]は、高[たか]い山[やま]ほど小[ちい]さくなる。", "sentence_source": "generated"}, {"text": "同じ体積なら、密度が大きい金属のほうが重い。", "target_word": "密度", "complexity_tier": "T3", "furigana": "同[おな]じ体積[たいせき]なら、密度[みつど]が大[おお]きい金属[きんぞく]のほうが重[おも]い。", "sentence_source": "generated"}, {"text": "この液体の密度を量るために、体積と重さを調べた。", "target_word": "密度", "complexity_tier": "T3", "furigana": "この液体[えきたい]の密度[みつど]を量[はか]るために、体積[たいせき]と重[おも]さを調[しら]べた。", "sentence_source": "generated"}, {"text": "宇宙では、物質の密度がとても低い。", "target_word": "密度", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]では、物質[ぶっしつ]の密度[みつど]がとても低[ひく]い。", "sentence_source": "generated"}, {"text": "温度が上がると、気体の密度は小さくなる。", "target_word": "密度", "complexity_tier": "T3", "furigana": "温度[おんど]が上[あ]がると、気体[きたい]の密度[みつど]は小[ちい]さくなる。", "sentence_source": "generated"}, {"text": "実験で、油と水の密度を比べた。", "target_word": "密度", "complexity_tier": "T3", "furigana": "実験[じっけん]で、油[あぶら]と水[みず]の密度[みつど]を比[くら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "密度", "label": "基本形"}], "register": "一般", "sense_fingerprint": "物質の質量を体積で割った量（物理の密度）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37743, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密度", "is_correct": true, "explanation": "体積あたりの質量を表す物理の密度で、「一立方センチメートルあたり一グラム」に合うので正解。"}, {"text": "温度", "is_correct": false, "explanation": "温度は体積あたりの量ではなく、「一立方センチメートルあたり一グラム」とは合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は重さや体積の数値で表せないため、この文には入らない。"}, {"text": "味", "is_correct": false, "explanation": "味は質量と体積の比で表せないため、文が成り立たない。"}], "explanations": {"密度": "体積あたりの質量を表す物理の密度で、「一立方センチメートルあたり一グラム」に合うので正解。", "温度": "温度は体積あたりの量ではなく、「一立方センチメートルあたり一グラム」とは合わない。", "色": "色は重さや体積の数値で表せないため、この文には入らない。", "味": "味は質量と体積の比で表せないため、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "密度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は密度が三キロもあり、一人では持てない。", "explanation": "ここは〈重さ〉の意味。重さは物の質量を言い、体積あたりの量である密度とは合わない。"}, {"text": "深い海では、上から密度がかかって体が押しつぶされそうになる。", "explanation": "ここは〈圧力〉の意味。上から押す力は圧力で表し、密度がかかるとは言わないので合わない。"}, {"text": "この箱は密度が二リットルもあり、中に水がたっぷり入る。", "explanation": "ここは〈体積〉の意味。容器のかさの大きさは体積で表し、密度が二リットルあるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37743, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密度", "is_correct": true, "explanation": "液体の詰まりぐあいを量る対象で、物理の密度として正解。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は液体の性質ではなく、「量る」の対象にならないため合わない。"}, {"text": "名前", "is_correct": false, "explanation": "名前は量るものではなく、「量るために」と続かないため文が成り立たない。"}, {"text": "人数", "is_correct": false, "explanation": "人数は液体の性質ではなく、この文の「量る」とも合わない。"}], "explanations": {"密度": "液体の詰まりぐあいを量る対象で、物理の密度として正解。", "年齢": "年齢は液体の性質ではなく、「量る」の対象にならないため合わない。", "名前": "名前は量るものではなく、「量るために」と続かないため文が成り立たない。", "人数": "人数は液体の性質ではなく、この文の「量る」とも合わない。"}, "sentence_index": 6, "correct_answer": "密度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この油は密度が強くて、なかなか流れない。", "explanation": "ここは〈粘度〉の意味。流れにくさは粘度で表し、密度とは合わない。"}, {"text": "水は密度が熱をため込み、温まりにくい。", "explanation": "ここは〈比熱〉の意味。温まりにくさは比熱で表すので、密度とは合わない。"}, {"text": "この水は密度が高く、底が見えるほど澄んでいる。", "explanation": "ここは〈透明度〉の意味。澄み具合は透明度で言うので、密度とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37743, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この金属は、密度を大きいので、水に沈む。", "corrected_sentence": "この金属は、密度が大きいので、水に沈む。", "error_description": "「密度」は「大きい」の主語になるので「が」を使う。「を」は誤りで、正しくは「密度が大きい」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37743, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この石は密度が大きいくて、水に沈む。", "corrected_sentence": "この石は密度が大きくて、水に沈む。", "error_description": "形容詞「大きい」の連用形は「大きく」で、「大きいくて」は誤り。正しくは「密度が大きくて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37744, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37744, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「マッハの数字」と続けると、マッハを修飾する連体修飾になり文が成り立つ。"}, {"text": "へ", "is_correct": false, "explanation": "「マッハへ数字が大きい」は方向を示す「へ」で、数字と続けると意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「マッハを数字」では目的語として続く動詞がなく、不自然で意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「マッハに数字」は方向や相手を示す語で、数字と続けると意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「マッハの数字」と続けると、マッハを修飾する連体修飾になり文が成り立つ。", "へ": "「マッハへ数字が大きい」は方向を示す「へ」で、数字と続けると意味が通らない。", "を": "「マッハを数字」では目的語として続く動詞がなく、不自然で意味が通らない。", "に": "「マッハに数字」は方向や相手を示す語で、数字と続けると意味が通らない。"}, "error_tags": {"へ": "方向", "を": "目的語", "に": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37744, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "飛行機の速さを表す数字で、音の速さの何倍かを示すものです。", "primary_collocate": null, "pronunciation": "まっは", "ipa": "mahːa", "syllable_count": 3, "sentences": [{"text": "その戦闘機はマッハ2で飛ぶことができる。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "その戦闘機[せんとうき]はマッハ2で飛[と]ぶことができる。", "sentence_source": "generated"}, {"text": "旅客機の速度はマッハ0.8ほどで、音より遅い。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "旅客機[りょかくき]の速度[そくど]はマッハ0.8ほどで、音[おと]より遅[おそ]い。", "sentence_source": "generated"}, {"text": "新しい飛行機はマッハ3を超えたので、世界で一番速い。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "新[あたら]しい飛行機[ひこうき]はマッハ3を超[こ]えたので、世界[せかい]で一番[いちばん]速[はや]い。", "sentence_source": "generated"}, {"text": "飛行機の速さは、時速ではなくマッハで表すことが多い。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]の速[はや]さは、時速[じそく]ではなくマッハで表[あらわ]すことが多[おお]い。", "sentence_source": "generated"}, {"text": "パイロットは計器を見て、今の速さがマッハ1.5だと確かめた。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "パイロットは計器[けいき]を見[み]て、今[いま]の速[はや]さがマッハ1.5だと確[たし]かめた。", "sentence_source": "generated"}, {"text": "マッハ1は音の速さと同じだから、それより速い飛行機は音を追い越す。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "マッハ1は音[おと]の速[はや]さと同[おな]じだから、それより速[はや]い飛行機[ひこうき]は音[おと]を追[お]い越[こ]す。", "sentence_source": "generated"}, {"text": "この飛行機の最高速度は、マッハ2.2だと発表された。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "この飛行機[ひこうき]の最高速度[さいこうそくど]は、マッハ2.2だと発表[はっぴょう]された。", "sentence_source": "generated"}, {"text": "マッハの数字が大きいほど、飛行機は速く飛んでいる。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "マッハの数字[すうじ]が大[おお]きいほど、飛行機[ひこうき]は速[はや]く飛[と]んでいる。", "sentence_source": "generated"}, {"text": "昔の飛行機はマッハ1に届かなかったが、今は簡単に超える。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "昔[むかし]の飛行機[ひこうき]はマッハ1に届[とど]かなかったが、今[いま]は簡単[かんたん]に超[こ]える。", "sentence_source": "generated"}, {"text": "軍用機がマッハ1を超えると、地上にも大きな音が聞こえる。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "軍用機[ぐんようき]がマッハ1を超[こ]えると、地上[ちじょう]にも大[おお]きな音[おと]が聞[き]こえる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マッハ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "飛行機の速さを、音の速さの何倍かで表す数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37744, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マッハ", "is_correct": true, "explanation": "「マッハ2」は音速の2倍を表し、空欄に入る唯一の語。"}, {"text": "時速", "is_correct": false, "explanation": "時速は「時速○キロ」の形で速さを示す語で、「時速2で」と単位なしの数字に続けられない。"}, {"text": "機体", "is_correct": false, "explanation": "機体は飛行機の本体を指す語で、速さの数字の前には置けない。"}, {"text": "ひとつ", "is_correct": false, "explanation": "「ひとつ」は個数を表す語で、「ひとつ2で飛ぶ」は速さの表現として成り立たない。"}], "explanations": {"マッハ": "「マッハ2」は音速の2倍を表し、空欄に入る唯一の語。", "時速": "時速は「時速○キロ」の形で速さを示す語で、「時速2で」と単位なしの数字に続けられない。", "機体": "機体は飛行機の本体を指す語で、速さの数字の前には置けない。", "ひとつ": "「ひとつ」は個数を表す語で、「ひとつ2で飛ぶ」は速さの表現として成り立たない。"}, "sentence_index": 0, "correct_answer": "マッハ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新幹線はマッハ250キロで走るので、東京から大阪まで約二時間半で着く。", "explanation": "ここは〈時速〉の意味。時速は「時速250キロ」のようにキロを付けて速さを示すが、マッハは音速の倍率を表す数なのでキロとは続かない。"}, {"text": "マッハは、空気中を伝わる音そのものの速さのことだ。", "explanation": "ここは〈音速〉の意味。マッハは音速に対する倍率の数で、音の速さそのものは指さない。"}, {"text": "音の壁を越えたときに地上へ響く大きな爆音を、マッハと呼ぶ。", "explanation": "ここは〈ソニックブーム〉の意味。マッハは速さの倍率を示す数で、超音速機の通過で生じる爆音そのものは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37744, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マッハ", "is_correct": true, "explanation": "「マッハ2.2」は音速の2.2倍を表し、最高速度を示す語として空欄に入る。"}, {"text": "音速", "is_correct": false, "explanation": "音速は速さそのものを表す語で、「音速2.2だと」のように倍率の数字には続かない。"}, {"text": "ノット", "is_correct": false, "explanation": "ノットは船や航空で使う速さの単位だが、「ノット2.2だと」と数値の前に単位として置く形にはならない。"}, {"text": "最高", "is_correct": false, "explanation": "最高は程度を表す語で、「最高2.2だと」と数字の直前に置くと意味が通らない。"}], "explanations": {"マッハ": "「マッハ2.2」は音速の2.2倍を表し、最高速度を示す語として空欄に入る。", "音速": "音速は速さそのものを表す語で、「音速2.2だと」のように倍率の数字には続かない。", "ノット": "ノットは船や航空で使う速さの単位だが、「ノット2.2だと」と数値の前に単位として置く形にはならない。", "最高": "最高は程度を表す語で、「最高2.2だと」と数字の直前に置くと意味が通らない。"}, "sentence_index": 6, "correct_answer": "マッハ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "マッハはいつも音より速く飛ぶ飛行機のことだ。", "explanation": "ここは〈超音速機〉の意味。マッハは速さの倍率を表す数で、飛行機そのものを指す語ではない。"}, {"text": "マッハは、速さがだんだん増えていくことだ。", "explanation": "ここは〈加速〉の意味。マッハは速さを示す数で、速度が増していく動作そのものは表さない。"}, {"text": "この船の速さは、マッハで表すことが多い。", "explanation": "ここは〈ノット〉の意味。船の速さは海里・ノットで表し、マッハは空や宇宙の物体にしか使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37744, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このジェット機はマッハ0.9を飛ぶと、音速に近い速さになる。", "corrected_sentence": "このジェット機はマッハ0.9で飛ぶと、音速に近い速さになる。", "error_description": "助詞の誤り。速さで飛ぶ様子は「で」で示すので、「マッハ0.9を飛ぶ」は誤り。正しくは「マッハ0.9で飛ぶ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37744, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機体はマッハ2.2に超えて飛ぶことができる。", "corrected_sentence": "この機体はマッハ2.2を超えて飛ぶことができる。", "error_description": "助詞の誤り。「超える」は対象を「を」で取るので、「マッハ2.2に超える」は誤り。正しくは「マッハ2.2を超える」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
