INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37745, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体の速度が音速の何倍であるかを示す数値。例えば、マッハ1は音速と同じ速さ。", "primary_collocate": null, "pronunciation": "まっは", "ipa": "mahːa", "syllable_count": 3, "sentences": [{"text": "弾丸はマッハ2以上の速さで飛ぶことがある。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "弾丸[だんがん]はマッハ2以上[いじょう]の速[はや]さで飛[と]ぶことがある。", "sentence_source": "generated"}, {"text": "ロケットはマッハ25で大気圏に戻ってくる。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "ロケットはマッハ25で大気圏[たいきけん]に戻[もど]ってくる。", "sentence_source": "generated"}, {"text": "マッハ1は、物体が音速と同じ速さで動いていることを表す。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "マッハ1は、物体[ぶったい]が音速[おんそく]と同[おな]じ速[はや]さで動[うご]いていることを表[あらわ]す。", "sentence_source": "generated"}, {"text": "隕石は、マッハ30の速さで地球に入ってくることもある。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "隕石[いんせき]は、マッハ30の速[はや]さで地球[ちきゅう]に入[はい]ってくることもある。", "sentence_source": "generated"}, {"text": "新幹線はマッハ0.25ぐらいで、音よりずっと遅い。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "新幹線[しんかんせん]はマッハ0.25ぐらいで、音[おと]よりずっと遅[おそ]い。", "sentence_source": "generated"}, {"text": "風洞実験では、物体をマッハ5まで加速させて調べる。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "風洞実験[ふうどうじっけん]では、物体[ぶったい]をマッハ5まで加速[かそく]させて調[しら]べる。", "sentence_source": "generated"}, {"text": "速さがマッハ1を超えると、物体の周りに衝撃波ができる。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "速[はや]さがマッハ1を超[こ]えると、物体[ぶったい]の周[まわ]りに衝撃波[しょうげきは]ができる。", "sentence_source": "generated"}, {"text": "その鳥は速いが、マッハ1には遠く及ばない。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "その鳥[とり]は速[はや]いが、マッハ1には遠[とお]く及[およ]ばない。", "sentence_source": "generated"}, {"text": "鞭の先はマッハ1を超えるので、あの鋭い音が出る。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "鞭[むち]の先[さき]はマッハ1を超[こ]えるので、あの鋭[するど]い音[おと]が出[で]る。", "sentence_source": "generated"}, {"text": "このロケットは、打ち上げから数分でマッハ10に達した。", "target_word": "マッハ", "complexity_tier": "T3", "furigana": "このロケットは、打[う]ち上[あ]げから数分[すうふん]でマッハ10に達[たっ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マッハ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "弾丸やロケットなど物体の速度が、音速の何倍かを示す数値", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37745, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マッハ", "is_correct": true, "explanation": "「マッハ2以上の速さ」で速さの倍率を示す数として、空欄に入る。"}, {"text": "時速", "is_correct": false, "explanation": "時速は単位を伴う速さの語で、「時速2以上の速さ」のように単位なしの数には続かない。"}, {"text": "距離", "is_correct": false, "explanation": "距離は長さを表す語で、速さの数字の前には置けない。"}, {"text": "ひとつ", "is_correct": false, "explanation": "「ひとつ」は個数を表す語で、「ひとつ2以上の速さ」は意味が通らない。"}], "explanations": {"マッハ": "「マッハ2以上の速さ」で速さの倍率を示す数として、空欄に入る。", "時速": "時速は単位を伴う速さの語で、「時速2以上の速さ」のように単位なしの数には続かない。", "距離": "距離は長さを表す語で、速さの数字の前には置けない。", "ひとつ": "「ひとつ」は個数を表す語で、「ひとつ2以上の速さ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "マッハ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新幹線の速さは、マッハ二百キロほどだ。", "explanation": "ここは〈時速〉の意味。キロを付けて速さを示すのは時速で、マッハには単位のキロは続かない。"}, {"text": "マッハは、物体の周りにできる圧力の波のことだ。", "explanation": "ここは〈衝撃波〉の意味。マッハは速さの倍率を示す数で、波や現象そのものを指さない。"}, {"text": "マッハは、物体が一秒間に進む距離で示す速さのことだ。", "explanation": "ここは〈速度〉の意味。マッハは音速に対する倍率の数で、一秒に進む距離そのものは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37745, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マッハ", "is_correct": true, "explanation": "「速さがマッハ1を超える」と、音速の倍率で表す語として空欄に入る。"}, {"text": "音速", "is_correct": false, "explanation": "音速は速さそのものを表す語で、「音速1を超える」と倍率の数字には続かない。"}, {"text": "ノット", "is_correct": false, "explanation": "ノットは船や航空で使う速さの単位で、マッハ1の位置には入らない。"}, {"text": "最高", "is_correct": false, "explanation": "最高は程度を表す語で、「最高1を超える」と数字に続けると意味が通らない。"}], "explanations": {"マッハ": "「速さがマッハ1を超える」と、音速の倍率で表す語として空欄に入る。", "音速": "音速は速さそのものを表す語で、「音速1を超える」と倍率の数字には続かない。", "ノット": "ノットは船や航空で使う速さの単位で、マッハ1の位置には入らない。", "最高": "最高は程度を表す語で、「最高1を超える」と数字に続けると意味が通らない。"}, "sentence_index": 6, "correct_answer": "マッハ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "マッハは、物体の速さがだんだん増していくことだ。", "explanation": "ここは〈加速〉の意味。マッハは速さを示す倍率の数で、速さが増していく動作そのものは表さない。"}, {"text": "マッハは、超音速機が通った後に響く大きな音だ。", "explanation": "ここは〈ソニックブーム〉の意味。マッハは速さを示す数で、音や現象そのものを指さない。"}, {"text": "アメリカでは車の速さをマッハで表すことが多い。", "explanation": "ここは〈マイル〉の意味。車の速さはマイル毎時で表し、マッハは音速の倍率なので車には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37745, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "探査機はマッハ20を大気圏に突入した。", "corrected_sentence": "探査機はマッハ20で大気圏に突入した。", "error_description": "助詞の誤り。速さで移動する様子は「で」で示すので、「マッハ20を」は誤り。正しくは「マッハ20で大気圏に突入した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37745, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機体は打ち上げ後、マッハ5を達した。", "corrected_sentence": "この機体は打ち上げ後、マッハ5に達した。", "error_description": "助詞の誤り。「達する」は到達点を「に」で示すので、「マッハ5を達した」は誤り。正しくは「マッハ5に達した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
