INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37746, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物が重なって何枚もの層になること。", "primary_collocate": null, "pronunciation": "せいそう", "ipa": "seːsoː", "syllable_count": 4, "sentences": [{"text": "湖底の泥は毎年少しずつ成層し、その様子から過去の環境が分かる。", "target_word": "成層", "complexity_tier": "T3", "furigana": "湖底[こてい]の泥[どろ]は毎年[まいとし]少[すこ]しずつ成層[せいそう]し、その様子[ようす]から過去[かこ]の環境[かんきょう]が分[わ]かる。", "sentence_source": "generated"}, {"text": "砂と泥が交互に積もって成層し、縞模様ができた。", "target_word": "成層", "complexity_tier": "T3", "furigana": "砂[すな]と泥[どろ]が交互[こうご]に積[つ]もって成層[せいそう]し、縞模様[しまもよう]ができた。", "sentence_source": "generated"}, {"text": "河口の三角州は、川が運んだ土砂が成層してできたものだ。", "target_word": "成層", "complexity_tier": "T3", "furigana": "河口[かこう]の三角州[さんかくす]は、川[かわ]が運[はこ]んだ土砂[どしゃ]が成層[せいそう]してできたものだ。", "sentence_source": "generated"}, {"text": "成層した岩の断面には、細い線が何本も見える。", "target_word": "成層", "complexity_tier": "T3", "furigana": "成層[せいそう]した岩[いわ]の断面[だんめん]には、細[ほそ]い線[せん]が何本[なんぼん]も見[み]える。", "sentence_source": "generated"}, {"text": "火山灰が降るたびに成層して、斜面に厚い層ができた。", "target_word": "成層", "complexity_tier": "T3", "furigana": "火山灰[かざんばい]が降[ふ]るたびに成層[せいそう]して、斜面[しゃめん]に厚[あつ]い層[そう]ができた。", "sentence_source": "generated"}, {"text": "この石灰岩は、貝殻が何百年もかけて成層したものだ。", "target_word": "成層", "complexity_tier": "T3", "furigana": "この石灰岩[せっかいがん]は、貝殻[かいがら]が何百年[なんびゃくねん]もかけて成層[せいそう]したものだ。", "sentence_source": "generated"}, {"text": "雪は降るたびに成層して、春には何枚もの層になっていた。", "target_word": "成層", "complexity_tier": "T3", "furigana": "雪[ゆき]は降[ふ]るたびに成層[せいそう]して、春[はる]には何枚[なんまい]もの層[そう]になっていた。", "sentence_source": "generated"}, {"text": "南極の氷床は、何万年もの雪が成層して厚くなった。", "target_word": "成層", "complexity_tier": "T3", "furigana": "南極[なんきょく]の氷床[ひょうしょう]は、何万年[なんまんねん]もの雪[ゆき]が成層[せいそう]して厚[あつ]くなった。", "sentence_source": "generated"}, {"text": "氷河の氷は成層しているので、断面を見ると年ごとの違いが分かる。", "target_word": "成層", "complexity_tier": "T3", "furigana": "氷河[ひょうが]の氷[こおり]は成層[せいそう]しているので、断面[だんめん]を見[み]ると年[とし]ごとの違[ちが]いが分[わ]かる。", "sentence_source": "generated"}, {"text": "土砂が海底に成層すると、長い時間をかけて硬い岩になる。", "target_word": "成層", "complexity_tier": "T3", "furigana": "土砂[どしゃ]が海底[かいてい]に成層[せいそう]すると、長い時間[じかん]をかけて硬[かた]い岩[いわ]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成層する", "label": "基本形"}, {"form": "成層した", "label": "過去形"}, {"form": "成層して", "label": "て形"}, {"form": "成層させる", "label": "使役形"}], "register": "technical", "sense_fingerprint": "物が何枚も重なって層を作ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37746, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成層", "is_correct": true, "explanation": "泥が少しずつ層になって重なる様子を表す動詞で、空欄に入る。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつける動作で、泥が層になる意味とは合わない。"}, {"text": "感電", "is_correct": false, "explanation": "感電は電流に触れることで、泥の堆積の様子には続かない。"}, {"text": "解凍", "is_correct": false, "explanation": "解凍は凍ったものを溶かす動作で、泥が層を作る意味を表さない。"}], "explanations": {"成層": "泥が少しずつ層になって重なる様子を表す動詞で、空欄に入る。", "点火": "点火は火をつける動作で、泥が層になる意味とは合わない。", "感電": "感電は電流に触れることで、泥の堆積の様子には続かない。", "解凍": "解凍は凍ったものを溶かす動作で、泥が層を作る意味を表さない。"}, "sentence_index": 0, "correct_answer": "成層"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "成層は、岩が風や雨で少しずつ崩れることだ。", "explanation": "ここは〈風化〉の意味。成層は層が重なることで、岩が崩れていく変化を表さない。"}, {"text": "成層は、流れが土地を削る働きだ。", "explanation": "ここは〈浸食〉の意味。成層は層が重なる現象で、土地を削る働きは指さない。"}, {"text": "旅客機は成層を飛ぶことが多い。", "explanation": "ここは〈成層圏〉の意味。成層は場所を表さないので、「成層を飛ぶ」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37746, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成層", "is_correct": true, "explanation": "雪が降るたびに層を重ねる様子を表す動詞で、空欄に入る。"}, {"text": "点滅", "is_correct": false, "explanation": "点滅は光がついたり消えたりすることで、雪が重なる意味には合わない。"}, {"text": "切断", "is_correct": false, "explanation": "切断は断ち切る動作で、雪が層になる意味とは合わない。"}, {"text": "漂白", "is_correct": false, "explanation": "漂白は色を抜く動作で、雪の層を表す語ではない。"}], "explanations": {"成層": "雪が降るたびに層を重ねる様子を表す動詞で、空欄に入る。", "点滅": "点滅は光がついたり消えたりすることで、雪が重なる意味には合わない。", "切断": "切断は断ち切る動作で、雪が層になる意味とは合わない。", "漂白": "漂白は色を抜く動作で、雪の層を表す語ではない。"}, "sentence_index": 6, "correct_answer": "成層"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日の練習が成層して、彼の実力を伸ばした。", "explanation": "ここは〈積み重ね〉の意味。成層は物が重なって層になることで、練習を繰り返す意味には使わない。"}, {"text": "溶けた樹脂を金型に流し込んで、部品を成層した。", "explanation": "ここは〈成型〉の意味。成層は物が重なって層になることで、型に入れて形を作る働きは表さない。"}, {"text": "果物は成層すると、甘くなる。", "explanation": "ここは〈成熟〉の意味。成層は層が重なる現象で、果物が熟すことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37746, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "土砂は、年ごとに成層しる、縞模様を作る。", "corrected_sentence": "土砂は、年ごとに成層して、縞模様を作る。", "error_description": "活用形の誤り。「成層する」の連用形は「成層し」「成層して」で、「成層しる」は活用として成り立たない。正しくは「成層して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37746, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "砂と泥が重なって成層を岩が、川の底にできた。", "corrected_sentence": "砂と泥が重なって成層した岩が、川の底にできた。", "error_description": "活用形の誤り。名詞「岩」を修飾するには「成層した岩」の形が必要で、「成層を」と続けると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
