INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37747, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "大気や地層などで、性質の異なる層が積み重なっている状態。また、そのような層を作ること。", "primary_collocate": null, "pronunciation": "せいそう", "ipa": "seːsoː", "syllable_count": 4, "sentences": [{"text": "夏の湖は、水温の差で水が成層する。", "target_word": "成層", "complexity_tier": "T3", "furigana": "夏[なつ]の湖[みずうみ]は、水温[すいおん]の差[さ]で水[みず]が成層[せいそう]する。", "sentence_source": "generated"}, {"text": "大気が成層していると、上下に空気が混ざりにくい。", "target_word": "成層", "complexity_tier": "T3", "furigana": "大気[たいき]が成層[せいそう]していると、上下[じょうげ]に空気[くうき]が混[ま]ざりにくい。", "sentence_source": "generated"}, {"text": "海水は塩分の違いで成層し、上と下で性質が異なる。", "target_word": "成層", "complexity_tier": "T3", "furigana": "海水[かいすい]は塩分[えんぶん]の違[ちが]いで成層[せいそう]し、上[うえ]と下[した]で性質[せいしつ]が異[こと]なる。", "sentence_source": "generated"}, {"text": "風が弱い夜は、冷たい空気が下にたまって成層しやすい。", "target_word": "成層", "complexity_tier": "T3", "furigana": "風[かぜ]が弱[よわ]い夜[よる]は、冷[つめ]たい空気[くうき]が下[した]にたまって成層[せいそう]しやすい。", "sentence_source": "generated"}, {"text": "地層は、時代ごとに成層した堆積物でできている。", "target_word": "成層", "complexity_tier": "T3", "furigana": "地層[ちそう]は、時代[じだい]ごとに成層[せいそう]した堆積物[たいせきぶつ]でできている。", "sentence_source": "generated"}, {"text": "川の水が海に入ると、軽い淡水が上に乗って成層する。", "target_word": "成層", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が海[うみ]に入[はい]ると、軽[かる]い淡水[たんすい]が上[うえ]に乗[の]って成層[せいそう]する。", "sentence_source": "generated"}, {"text": "湖が成層している間は、底の水に酸素が届きにくい。", "target_word": "成層", "complexity_tier": "T3", "furigana": "湖[みずうみ]が成層[せいそう]している間[あいだ]は、底[そこ]の水[みず]に酸素[さんそ]が届[とど]きにくい。", "sentence_source": "generated"}, {"text": "冬になって水温が下がると、湖の成層はなくなる。", "target_word": "成層", "complexity_tier": "T3", "furigana": "冬[ふゆ]になって水温[すいおん]が下[さ]がると、湖[みずうみ]の成層[せいそう]はなくなる。", "sentence_source": "generated"}, {"text": "成層した地層を調べると、昔の気候が分かる。", "target_word": "成層", "complexity_tier": "T3", "furigana": "成層[せいそう]した地層[ちそう]を調[しら]べると、昔[むかし]の気候[きこう]が分[わ]かる。", "sentence_source": "generated"}, {"text": "空気が成層している日は、スモッグが町にたまりやすい。", "target_word": "成層", "complexity_tier": "T3", "furigana": "空気[くうき]が成層[せいそう]している日[ひ]は、スモッグが町[まち]にたまりやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成層する", "label": "基本形"}, {"form": "成層した", "label": "過去形"}, {"form": "成層して", "label": "て形"}, {"form": "成層している", "label": "状態形"}], "register": "technical", "sense_fingerprint": "大気・水・地層などで、性質の異なる層が重なっている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37747, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成層", "is_correct": true, "explanation": "水が水温の差で層に分かれる現象を表す動詞で、空欄に入る。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつける動作で、水の層の現象には使えない。"}, {"text": "感電", "is_correct": false, "explanation": "感電は電流が体に流れることで、水温による層の現象とは合わない。"}, {"text": "解凍", "is_correct": false, "explanation": "解凍は凍ったものを溶かす動作で、水温の差による層を表さない。"}], "explanations": {"成層": "水が水温の差で層に分かれる現象を表す動詞で、空欄に入る。", "点火": "点火は火をつける動作で、水の層の現象には使えない。", "感電": "感電は電流が体に流れることで、水温による層の現象とは合わない。", "解凍": "解凍は凍ったものを溶かす動作で、水温の差による層を表さない。"}, "sentence_index": 0, "correct_answer": "成層"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "成層は、いくつかの物を混ぜ合わせることだ。", "explanation": "ここは〈混合〉の意味。成層は層が分かれて重なる状態で、混ぜ合わせることではない。"}, {"text": "成層は、温められた空気が上昇して循環する流れだ。", "explanation": "ここは〈対流〉の意味。成層は層の重なりを表し、循環する流れは指さない。"}, {"text": "電気を大量に成層して、ブレーカーが落ちた。", "explanation": "ここは〈消費〉の意味。成層は層が重なる状態を表し、電気を使い切ることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37747, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成層", "is_correct": true, "explanation": "湖の水が層に分かれている状態を表し、「成層している」で空欄に入る。"}, {"text": "点滅", "is_correct": false, "explanation": "点滅は光がついたり消えたりすることで、湖の層の状態には使えない。"}, {"text": "切断", "is_correct": false, "explanation": "切断は断ち切る動作で、湖の状態には続かない。"}, {"text": "漂白", "is_correct": false, "explanation": "漂白は色を抜く動作で、水の層の状態を表さない。"}], "explanations": {"成層": "湖の水が層に分かれている状態を表し、「成層している」で空欄に入る。", "点滅": "点滅は光がついたり消えたりすることで、湖の層の状態には使えない。", "切断": "切断は断ち切る動作で、湖の状態には続かない。", "漂白": "漂白は色を抜く動作で、水の層の状態を表さない。"}, "sentence_index": 6, "correct_answer": "成層"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の朝、湖の水が成層して霧になった。", "explanation": "ここは〈蒸発〉の意味。成層は物が層になって重なることで、水が気体になって空へ上がる変化は表さない。"}, {"text": "汚れた池の水を、薬で成層して、魚が戻ってきた。", "explanation": "ここは〈浄化〉の意味。成層は層が重なる現象で、汚れを取り除いてきれいにする働きは表さない。"}, {"text": "香水のにおいが部屋に成層して、だんだん薄まった。", "explanation": "ここは〈拡散〉の意味。成層は物が層になって重なることで、においが広がって薄まる現象は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37747, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の湖では成層を起きる。", "corrected_sentence": "夏の湖では成層が起きる。", "error_description": "助詞の誤り。「起きる」は主語を「が」で受けるので、「成層が起きる」が正しい。「成層を起きる」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37747, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の湖は冷えて成層に、底の酸素が減る。", "corrected_sentence": "夜の湖は冷えて成層し、底の酸素が減る。", "error_description": "活用形の誤り。「成層」は「する」の動詞なので、中止形「成層し」で続ける。「成層に」では動詞が欠け、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
