INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37748, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "音の速さのこと。とても速い。", "primary_collocate": null, "pronunciation": "おんそく", "ipa": "onsokɯ", "syllable_count": 4, "sentences": [{"text": "飛行機が音速を超えると、大きな音が出ることがある。", "target_word": "音速", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が音速[おんそく]を超[こ]えると、大[おお]きな音[おと]が出[で]ることがある。", "sentence_source": "generated"}, {"text": "光は音速よりずっと速いので、雷は先に光って見える。", "target_word": "音速", "complexity_tier": "T3", "furigana": "光[ひかり]は音速[おんそく]よりずっと速[はや]いので、雷[かみなり]は先[さき]に光[ひか]って見[み]える。", "sentence_source": "generated"}, {"text": "この飛行機は音速で飛べるから、遠い国へすぐ行ける。", "target_word": "音速", "complexity_tier": "T3", "furigana": "この飛行機[ひこうき]は音速[おんそく]で飛[と]べるから、遠[とお]い国[くに]へすぐ行[い]ける。", "sentence_source": "generated"}, {"text": "音速を超える飛行機は、普通の旅客機よりずっと速い。", "target_word": "音速", "complexity_tier": "T3", "furigana": "音速[おんそく]を超[こ]える飛行機[ひこうき]は、普通[ふつう]の旅客機[りょかくき]よりずっと速[はや]い。", "sentence_source": "generated"}, {"text": "遠くの花火は、音速より光が速いので、光ってから音が聞こえる。", "target_word": "音速", "complexity_tier": "T3", "furigana": "遠[とお]くの花火[はなび]は、音速[おんそく]より光[ひかり]が速[はや]いので、光[ひか]ってから音[おと]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "音速の何倍もの速さで飛ぶ弾がある。", "target_word": "音速", "complexity_tier": "T3", "furigana": "音速[おんそく]の何倍[なんばい]もの速[はや]さで飛[と]ぶ弾[たま]がある。", "sentence_source": "generated"}, {"text": "戦闘機が音速を超えた瞬間、窓がびりびりと震えた。", "target_word": "音速", "complexity_tier": "T3", "furigana": "戦闘機[せんとうき]が音速[おんそく]を超[こ]えた瞬間[しゅんかん]、窓[まど]がびりびりと震[ふる]えた。", "sentence_source": "generated"}, {"text": "音速に近づくと、飛行機は大きく揺れることがある。", "target_word": "音速", "complexity_tier": "T3", "furigana": "音速[おんそく]に近[ちか]づくと、飛行機[ひこうき]は大[おお]きく揺[ゆ]れることがある。", "sentence_source": "generated"}, {"text": "音速より速く走れる人間は、世界にいない。", "target_word": "音速", "complexity_tier": "T3", "furigana": "音速[おんそく]より速[はや]く走[はし]れる人間[にんげん]は、世界[せかい]にいない。", "sentence_source": "generated"}, {"text": "彼女は音速で返事をしたので、みんなが驚いた。", "target_word": "音速", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は音速[おんそく]で返事[へんじ]をしたので、みんなが驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "音速", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "音の速さ。比べるとき基準になる、とても速い速度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37748, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音速", "is_correct": true, "explanation": "超えるのは速さで、速さの基準となる音速が入る。これが正解。"}, {"text": "音波", "is_correct": false, "explanation": "音波は伝わる波のことで、速さの値ではない。「音波を超える」とは言わない。"}, {"text": "音階", "is_correct": false, "explanation": "音の高さの並びのことで、飛行機の速さには関係しない。超える対象にならない。"}, {"text": "水深", "is_correct": false, "explanation": "水の深さを表す語で、飛行機の速さには当てはまらない。"}], "explanations": {"音速": "超えるのは速さで、速さの基準となる音速が入る。これが正解。", "音波": "音波は伝わる波のことで、速さの値ではない。「音波を超える」とは言わない。", "音階": "音の高さの並びのことで、飛行機の速さには関係しない。超える対象にならない。", "水深": "水の深さを表す語で、飛行機の速さには当てはまらない。"}, "sentence_index": 0, "correct_answer": "音速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この自動車の音速は時速百キロだ。", "explanation": "ここは〈速度〉の意味。音速は音の速さを指すので、車の速さには使わない。"}, {"text": "あの歌手は音速がとても美しい。", "explanation": "ここは〈音声〉の意味。音速は音が伝わる速さなので、声の質には使わない。"}, {"text": "音速は空気中を伝わり、鼓膜を揺らす。", "explanation": "ここは〈音波〉の意味。音速は音が伝わる速さで、伝わって鼓膜を揺らす波そのものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37748, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音速", "is_correct": true, "explanation": "超えたのは速さで、音速が入る。これが正解。"}, {"text": "色彩", "is_correct": false, "explanation": "色合いのことで、速さの基準にならない。「色彩を超える」とは言わない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の齢を表す語で、戦闘機の速さには当てはまらない。"}, {"text": "体重", "is_correct": false, "explanation": "重さの量で、「戦闘機が体重を超える」は意味が成り立たない。"}], "explanations": {"音速": "超えたのは速さで、音速が入る。これが正解。", "色彩": "色合いのことで、速さの基準にならない。「色彩を超える」とは言わない。", "年齢": "人の齢を表す語で、戦闘機の速さには当てはまらない。", "体重": "重さの量で、「戦闘機が体重を超える」は意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "音速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電話の向こうの彼は、音速がこもっていて聞き取りにくい。", "explanation": "ここは〈音声〉の意味。音速は速さを表すので、話し声の明瞭さには使わない。"}, {"text": "このアンプは音速がとても大きい。", "explanation": "ここは〈音量〉の意味。音速は速さで、音の大きさには使わない。"}, {"text": "この歌手は音速がずれている。", "explanation": "ここは〈音程〉の意味。音速は音の速さで、音の高さがずれるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37748, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "機体は音速が超えると、大きな衝撃波が生まれる。", "corrected_sentence": "機体は音速を超えると、大きな衝撃波が生まれる。", "error_description": "「超える」の目的語には「を」が必要。「が」は誤りで、正しくは「音速を超える」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37748, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弾は音速に飛んだので、窓ガラスが割れた。", "corrected_sentence": "弾は音速で飛んだので、窓ガラスが割れた。", "error_description": "速さを表す「音速で飛ぶ」の「で」が正しい。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
