INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37749, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "音が空気や水の中を伝わる速さ。空気中では約秒速340メートル。", "primary_collocate": null, "pronunciation": "おんそく", "ipa": "onsokɯ", "syllable_count": 4, "sentences": [{"text": "空気中の音速は、約秒速340メートルだ。", "target_word": "音速", "complexity_tier": "T3", "furigana": "空気中[くうきちゅう]の音速[おんそく]は、約[やく]秒速[びょうそく]340メートルだ。", "sentence_source": "generated"}, {"text": "水中では、空気中より音速が速い。", "target_word": "音速", "complexity_tier": "T3", "furigana": "水中[すいちゅう]では、空気中[くうきちゅう]より音速[おんそく]が速[はや]い。", "sentence_source": "generated"}, {"text": "気温が高くなると、空気中の音速は少し速くなる。", "target_word": "音速", "complexity_tier": "T3", "furigana": "気温[きおん]が高[たか]くなると、空気中[くうきちゅう]の音速[おんそく]は少[すこ]し速[はや]くなる。", "sentence_source": "generated"}, {"text": "音速が分かれば、雷までの距離が計算できる。", "target_word": "音速", "complexity_tier": "T3", "furigana": "音速[おんそく]が分[わ]かれば、雷[かみなり]までの距離[きょり]が計算[けいさん]できる。", "sentence_source": "generated"}, {"text": "鉄の中の音速は、空気中の音速よりずっと速い。", "target_word": "音速", "complexity_tier": "T3", "furigana": "鉄[てつ]の中[なか]の音速[おんそく]は、空気中[くうきちゅう]の音速[おんそく]よりずっと速[はや]い。", "sentence_source": "generated"}, {"text": "音速は温度によって変わるので、実験では気温も測る。", "target_word": "音速", "complexity_tier": "T3", "furigana": "音速[おんそく]は温度[おんど]によって変[か]わるので、実験[じっけん]では気温[きおん]も測[はか]る。", "sentence_source": "generated"}, {"text": "音速には限りがあるので、やまびこは少し遅れて返ってくる。", "target_word": "音速", "complexity_tier": "T3", "furigana": "音速[おんそく]には限[かぎ]りがあるので、やまびこは少[すこ]し遅[おく]れて返[かえ]ってくる。", "sentence_source": "generated"}, {"text": "海の中の音速を使って、船は海の深さを測る。", "target_word": "音速", "complexity_tier": "T3", "furigana": "海[うみ]の中[なか]の音速[おんそく]を使[つか]って、船[ふね]は海[うみ]の深[ふか]さを測[はか]る。", "sentence_source": "generated"}, {"text": "氷の中でも音速は変わり、空気中とは違う値になる。", "target_word": "音速", "complexity_tier": "T3", "furigana": "氷[こおり]の中[なか]でも音速[おんそく]は変[か]わり、空気中[くうきちゅう]とは違[ちが]う値[あたい]になる。", "sentence_source": "generated"}, {"text": "先生は、空気中の音速が秒速約340メートルだと黒板に書いた。", "target_word": "音速", "complexity_tier": "T3", "furigana": "先生[せんせい]は、空気中[くうきちゅう]の音速[おんそく]が秒速[びょうそく]約[やく]340メートルだと黒板[こくばん]に書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "音速", "label": "基本形"}], "register": "technical", "sense_fingerprint": "音が空気や水などの中を伝わる速さ。空気中で約秒速340メートル", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37749, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音速", "is_correct": true, "explanation": "空気中の音が伝わる速さを表す語で、約秒速340メートルに合う。これが正解。"}, {"text": "気圧", "is_correct": false, "explanation": "空気が押す力のことで、速さの値ではない。秒速とは結びつかない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水蒸気の割合で、速さを表さない。"}, {"text": "重さ", "is_correct": false, "explanation": "物の重さで、秒速340メートルという速さには当てはまらない。"}], "explanations": {"音速": "空気中の音が伝わる速さを表す語で、約秒速340メートルに合う。これが正解。", "気圧": "空気が押す力のことで、速さの値ではない。秒速とは結びつかない。", "湿度": "空気中の水蒸気の割合で、速さを表さない。", "重さ": "物の重さで、秒速340メートルという速さには当てはまらない。"}, "sentence_index": 0, "correct_answer": "音速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "光の音速が分かれば、色が判別できる。", "explanation": "ここは〈光速〉の意味。光の速さは光速と言い、音速は音が伝わる速さなので光には使わない。"}, {"text": "この先生は音速の調子が悪くて、説明が聞き取れない。", "explanation": "ここは〈音声〉の意味。音速は音の速さで、話し声の調子とは関係ない。"}, {"text": "あの投手は音速が百五十キロを超える。", "explanation": "ここは〈球速〉の意味。投げた球の速さには音速は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37749, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音速", "is_correct": true, "explanation": "音には限りがあり、伝わる速さが決まっているという文脈に合う。これが正解。"}, {"text": "色", "is_correct": false, "explanation": "物の見た目を表す語で、やまびこの遅れとの因果関係が成り立たない。"}, {"text": "味", "is_correct": false, "explanation": "味覚に関する語で、「限りがあるので遅れて返る」という文脈に合わない。"}, {"text": "香り", "is_correct": false, "explanation": "においを表す語で、やまびこの話とは関係しない。"}], "explanations": {"音速": "音には限りがあり、伝わる速さが決まっているという文脈に合う。これが正解。", "色": "物の見た目を表す語で、やまびこの遅れとの因果関係が成り立たない。", "味": "味覚に関する語で、「限りがあるので遅れて返る」という文脈に合わない。", "香り": "においを表す語で、やまびこの話とは関係しない。"}, "sentence_index": 6, "correct_answer": "音速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、音速の波長を黒板に書いた。", "explanation": "ここは〈音波〉の意味。音速は速さの値で、波長を持たないので「音速の波長」とは言わない。"}, {"text": "このアンプは音速を上げると、ひずみが出やすい。", "explanation": "ここは〈音量〉の意味。音速は速さで、アンプで上げたり下げたりする音の大きさには使わない。"}, {"text": "台風の中心では音速がビルを揺らすほど強く吹いた。", "explanation": "ここは〈風速〉の意味。音速は音が伝わる速さで、風が吹く速さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37749, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この実験では、空気中の音速に毎回測り直している。", "corrected_sentence": "この実験では、空気中の音速を毎回測り直している。", "error_description": "「測り直す」の目的語には「を」が必要。「に」は誤りで、正しくは「音速を毎回測り直している」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37749, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雷までの距離は、音速が使って計算できる。", "corrected_sentence": "雷までの距離は、音速を使って計算できる。", "error_description": "「使う」の目的語には「を」が必要。「が」は誤りで、正しくは「音速を使って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37750, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "原因を表す「で」。落とした衝撃が原因で時計が止まったという文意に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「衝撃を、時計が止まった」では自動詞の「止まる」に目的語が付き、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「衝撃へ」では向かう先の意味になり、原因を述べる文に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「衝撃の、」で切れると後ろの述語に結びつかず、空所に入らない。"}], "correct_answer": "で", "explanations": {"で": "原因を表す「で」。落とした衝撃が原因で時計が止まったという文意に合う。", "を": "目的語の「を」。「衝撃を、時計が止まった」では自動詞の「止まる」に目的語が付き、文が成り立たない。", "へ": "方向の「へ」。「衝撃へ」では向かう先の意味になり、原因を述べる文に合わない。", "の": "連体修飾の「の」。「衝撃の、」で切れると後ろの述語に結びつかず、空所に入らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37750, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の「を」。「衝撃を受ける」で、受ける対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "原因・手段の「で」。「衝撃で受けて」では受ける対象が立たず、動詞に目的語が付かない。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」。「衝撃が受けて」では受ける側の主語が欠け、文の形が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の「と」。「衝撃と受けて」では並べる相手がなく、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語の「を」。「衝撃を受ける」で、受ける対象を示す。", "で": "原因・手段の「で」。「衝撃で受けて」では受ける対象が立たず、動詞に目的語が付かない。", "が": "主格の「が」。「衝撃が受けて」では受ける側の主語が欠け、文の形が崩れる。", "と": "並列・共同の「と」。「衝撃と受けて」では並べる相手がなく、意味が通らない。"}, "error_tags": {"で": "手段・原因", "が": "主格", "と": "並列・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37750, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "強い力でぶつかること。または、その力。", "primary_collocate": null, "pronunciation": "しょうげき", "ipa": "ɕoːɡeki", "syllable_count": 4, "sentences": [{"text": "車がぶつかった衝撃で、窓ガラスが割れた。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "車[くるま]がぶつかった衝撃[しょうげき]で、窓[まど]ガラスが割[わ]れた。", "sentence_source": "generated"}, {"text": "落とした衝撃で、時計が止まってしまった。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "落[お]とした衝撃[しょうげき]で、時計[とけい]が止[と]まってしまった。", "sentence_source": "generated"}, {"text": "この箱は、衝撃に強い素材でできている。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "この箱[はこ]は、衝撃[しょうげき]に強[つよ]い素材[そざい]でできている。", "sentence_source": "generated"}, {"text": "衝撃をやわらげるために、ヘルメットをかぶる。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "衝撃[しょうげき]をやわらげるために、ヘルメットをかぶる。", "sentence_source": "generated"}, {"text": "地面に落ちたとき、体に強い衝撃が走った。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "地面[じめん]に落[お]ちたとき、体[からだ]に強[つよ]い衝撃[しょうげき]が走[はし]った。", "sentence_source": "generated"}, {"text": "ボールが壁に当たる衝撃で、棚が揺れた。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "ボールが壁[かべ]に当[あ]たる衝撃[しょうげき]で、棚[たな]が揺[ゆ]れた。", "sentence_source": "generated"}, {"text": "スマホケースは、落としたときの衝撃を吸収する。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "スマホケースは、落[お]としたときの衝撃[しょうげき]を吸収[きゅうしゅう]する。", "sentence_source": "generated"}, {"text": "大きな衝撃を受けて、橋の柱にひびが入った。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "大[おお]きな衝撃[しょうげき]を受[う]けて、橋[はし]の柱[はしら]にひびが入[はい]った。", "sentence_source": "generated"}, {"text": "衝撃が強すぎて、機械の部品が外れた。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "衝撃[しょうげき]が強[つよ]すぎて、機械[きかい]の部品[ぶひん]が外[はず]れた。", "sentence_source": "generated"}, {"text": "転んだ衝撃で、メガネが飛んでいった。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "転[ころ]んだ衝撃[しょうげき]で、メガネが飛[と]んでいった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "衝撃", "label": "基本形"}], "register": "標準", "sense_fingerprint": "物がぶつかったときに加わる強い力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: やわらげる (Zipf 2.04)']::text[], 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37750, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衝撃", "is_correct": true, "explanation": "ぶつかったときの強い力を表し、「車がぶつかった〜で窓ガラスが割れた」の原因として文意が通る。"}, {"text": "天気", "is_correct": false, "explanation": "天候の意味で、車がぶつかって窓が割れる原因にはならず、空所に入ると文が成り立たない。"}, {"text": "料金", "is_correct": false, "explanation": "支払う金額の意味で、窓ガラスを割る原因として置くと意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "時期の意味で、ぶつかったことが窓を割った原因だという文脈に入らない。"}], "explanations": {"衝撃": "ぶつかったときの強い力を表し、「車がぶつかった〜で窓ガラスが割れた」の原因として文意が通る。", "天気": "天候の意味で、車がぶつかって窓が割れる原因にはならず、空所に入ると文が成り立たない。", "料金": "支払う金額の意味で、窓ガラスを割る原因として置くと意味が通らない。", "季節": "時期の意味で、ぶつかったことが窓を割った原因だという文脈に入らない。"}, "sentence_index": 0, "correct_answer": "衝撃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭に咲いた花の衝撃が、部屋の中まで漂ってきた。", "explanation": "ここは〈香り〉の意味。衝撃は強い力のぶつかりを表すので、においが空気に広がって届く様子には使わない。"}, {"text": "この部屋の衝撃は、淡い水色だ。", "explanation": "ここは〈色〉の意味。衝撃は強い力のぶつかりを表し、色の印象を表す語ではない。"}, {"text": "タイヤの衝撃を毎朝チェックする。", "explanation": "ここは〈空気の圧力〉の意味。衝撃は瞬間的な力で、空気圧のように測って管理するものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37750, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衝撃", "is_correct": true, "explanation": "落としたときに加わる強い力を指し、吸収の対象として文意が通る。"}, {"text": "色合い", "is_correct": false, "explanation": "色の印象を表す語で、落としたときの力を吸収する対象にはならない。"}, {"text": "値段", "is_correct": false, "explanation": "金額の意味で、力を吸収するという文に入ると意味が通らない。"}, {"text": "名前", "is_correct": false, "explanation": "呼び名の意味で、力を吸収する対象として成り立たない。"}], "explanations": {"衝撃": "落としたときに加わる強い力を指し、吸収の対象として文意が通る。", "色合い": "色の印象を表す語で、落としたときの力を吸収する対象にはならない。", "値段": "金額の意味で、力を吸収するという文に入ると意味が通らない。", "名前": "呼び名の意味で、力を吸収する対象として成り立たない。"}, "sentence_index": 6, "correct_answer": "衝撃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ピアノの衝撃が、ホールの隅まで広がった。", "explanation": "ここは〈音の響き〉の意味。衝撃は一度加わる強い力で、音が余韻を持って広がる様子には使わない。"}, {"text": "フライパンの衝撃で、卵がかたまった。", "explanation": "ここは〈熱〉の意味。衝撃は強い力のぶつかりで、熱が伝わって起こる変化の原因にはならない。"}, {"text": "布と布の衝撃で、静電気が起きた。", "explanation": "ここは〈摩擦〉の意味。衝撃はぶつかる力で、こすれ合って生じる現象を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37750, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボールが床に当たる衝撃を、棚が揺れた。", "corrected_sentence": "ボールが床に当たる衝撃で、棚が揺れた。", "error_description": "「衝撃」に続く助詞が誤り。原因を表す「で」が正しく、「を」にすると目的語になって「揺れた」と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37750, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "スマホケースは、角から落としたときの衝撃に吸収する。", "corrected_sentence": "スマホケースは、角から落としたときの衝撃を吸収する。", "error_description": "「吸収する」は目的語に「を」を取る。「衝撃に」は誤りで、「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37751, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」。「衝撃の波」で「波」を修飾し、空気に生まれる波の性質を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「衝撃を波が生まれる」では「生まれる」に目的語が付き、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「衝撃へ波」では向かう先の意味になり、波の性質を示さない。"}, {"text": "に", "is_correct": false, "explanation": "帰着の「に」。「衝撃に波が生まれる」では「波」を修飾できず、文が通らない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」。「衝撃の波」で「波」を修飾し、空気に生まれる波の性質を示す。", "を": "目的語の「を」。「衝撃を波が生まれる」では「生まれる」に目的語が付き、文が成り立たない。", "へ": "方向の「へ」。「衝撃へ波」では向かう先の意味になり、波の性質を示さない。", "に": "帰着の「に」。「衝撃に波が生まれる」では「波」を修飾できず、文が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "帰着"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37751, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主格の「が」。「衝撃が広がった」で、広がる主体を示す。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の「と」。「衝撃と広がった」では並べる相手がなく、主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「衝撃の広がった」では名詞の後に述語が立たず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「衝撃より広がった」では比べる対象も起点も文中にない。"}], "correct_answer": "が", "explanations": {"が": "主格の「が」。「衝撃が広がった」で、広がる主体を示す。", "と": "並列・共同の「と」。「衝撃と広がった」では並べる相手がなく、主語にならない。", "の": "連体修飾の「の」。「衝撃の広がった」では名詞の後に述語が立たず、文が成り立たない。", "より": "比較の「より」。「衝撃より広がった」では比べる対象も起点も文中にない。"}, "error_tags": {"と": "並列・共同", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37751, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体が高速で別の物体や空気などにぶつかるときに生じる、大きな力や波のこと。また、心に強い影響を与える出来事。", "primary_collocate": null, "pronunciation": "しょうげき", "ipa": "ɕoːɡeki", "syllable_count": 4, "sentences": [{"text": "爆発の衝撃は、遠くの建物の窓まで揺らした。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "爆発[ばくはつ]の衝撃[しょうげき]は、遠[とお]くの建物[たてもの]の窓[まど]まで揺[ゆ]らした。", "sentence_source": "generated"}, {"text": "飛行機が音速を超えると、空気に衝撃の波が生まれる。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が音速[おんそく]を超[こ]えると、空気[くうき]に衝撃[しょうげき]の波[なみ]が生[う]まれる。", "sentence_source": "generated"}, {"text": "その知らせは、私にとって大きな衝撃だった。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "その知[し]らせは、私[わたし]にとって大[おお]きな衝撃[しょうげき]だった。", "sentence_source": "generated"}, {"text": "友人の突然の引っ越しは、心に強い衝撃を与えた。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の突然[とつぜん]の引[ひ]っ越[こ]しは、心[こころ]に強[つよ]い衝撃[しょうげき]を与[あた]えた。", "sentence_source": "generated"}, {"text": "試合の結果を聞いて、みんな衝撃を受けた。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "試合[しあい]の結果[けっか]を聞[き]いて、みんな衝撃[しょうげき]を受[う]けた。", "sentence_source": "generated"}, {"text": "事故のニュースは、町の人々に衝撃を与えた。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "事故[じこ]のニュースは、町[まち]の人々[ひとびと]に衝撃[しょうげき]を与[あた]えた。", "sentence_source": "generated"}, {"text": "衝撃のあまり、しばらく声が出なかった。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "衝撃[しょうげき]のあまり、しばらく声[こえ]が出[で]なかった。", "sentence_source": "generated"}, {"text": "彼の発言で、会場に衝撃が広がった。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "彼[かれ]の発言[はつげん]で、会場[かいじょう]に衝撃[しょうげき]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "隕石が地面に落ちたとき、その衝撃で大きな穴ができた。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "隕石[いんせき]が地面[じめん]に落[お]ちたとき、その衝撃[しょうげき]で大[おお]きな穴[あな]ができた。", "sentence_source": "generated"}, {"text": "あの映画の結末は、今も忘れられない衝撃だった。", "target_word": "衝撃", "complexity_tier": "T3", "furigana": "あの映画[えいが]の結末[けつまつ]は、今[いま]も忘[わす]れられない衝撃[しょうげき]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "衝撃", "label": "基本形"}], "register": "標準", "sense_fingerprint": "衝突で生じる大きな力や波、また心を強く揺さぶる出来事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37751, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衝撃", "is_correct": true, "explanation": "爆発による強い力や波を指し、「爆発の〜は窓まで揺らした」の主語として文意が通る。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物の意味で、爆発の作用の主語にすると文が成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "時期の意味で、窓を揺らす力の主語にならない。"}, {"text": "手紙", "is_correct": false, "explanation": "文書の意味で、爆発の作用の主語にはならず文意が崩れる。"}], "explanations": {"衝撃": "爆発による強い力や波を指し、「爆発の〜は窓まで揺らした」の主語として文意が通る。", "料理": "食べ物の意味で、爆発の作用の主語にすると文が成り立たない。", "季節": "時期の意味で、窓を揺らす力の主語にならない。", "手紙": "文書の意味で、爆発の作用の主語にはならず文意が崩れる。"}, "sentence_index": 0, "correct_answer": "衝撃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ストーブの衝撃で、部屋がすぐに暖まった。", "explanation": "ここは〈熱〉の意味。衝撃は強い力や波の作用で、熱が伝わって起こる温度の変化には使わない。"}, {"text": "布と布の衝撃は、静電気を起こしやすい。", "explanation": "ここは〈摩擦〉の意味。衝撃はぶつかる力で、こすれ合う現象を表すときには使わない。"}, {"text": "この紅茶の衝撃は、ほのかに甘い。", "explanation": "ここは〈香り・味わい〉の意味。衝撃は力や波の作用を指し、飲み物の味を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37751, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衝撃", "is_correct": true, "explanation": "強い出来事に出会ったときの心の動揺を指し、「〜のあまり、声が出なかった」に入る。"}, {"text": "天気", "is_correct": false, "explanation": "天候の意味で、「〜のあまり」の前に置くと意味が通らない。"}, {"text": "料金", "is_correct": false, "explanation": "金額の意味で、感情の強さを表す「〜のあまり」には入らない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車券の意味で、感情の程度を表す語として成り立たない。"}], "explanations": {"衝撃": "強い出来事に出会ったときの心の動揺を指し、「〜のあまり、声が出なかった」に入る。", "天気": "天候の意味で、「〜のあまり」の前に置くと意味が通らない。", "料金": "金額の意味で、感情の強さを表す「〜のあまり」には入らない。", "切符": "乗車券の意味で、感情の程度を表す語として成り立たない。"}, "sentence_index": 6, "correct_answer": "衝撃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このシャツの衝撃は、三千円だった。", "explanation": "ここは〈値段〉の意味。衝撃は力や出来事の作用を指し、金額を表す語ではない。"}, {"text": "この家の衝撃は、築五十年だ。", "explanation": "ここは〈築年数〉の意味。衝撃は力や出来事の作用を指し、建物の年数を表す語ではない。"}, {"text": "この映画の衝撃は、落ち着いた色合いだ。", "explanation": "ここは〈色合い〉の意味。衝撃は力や出来事の作用を指し、色の印象を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37751, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ロケットが音速を超えると、空気に衝撃を波が生まれる。", "corrected_sentence": "ロケットが音速を超えると、空気に衝撃の波が生まれる。", "error_description": "「衝撃」に続く助詞が誤り。「波」を修飾する「の」が正しく、「を」にすると「生まれる」の目的語になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37751, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その衝撃にあまり、しばらく声が出なかった。", "corrected_sentence": "その衝撃のあまり、しばらく声が出なかった。", "error_description": "「〜のあまり」の形では「衝撃」に「の」が必要。「に」にすると「あまり」と結びつかず、文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37752, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "結合", "is_correct": true, "explanation": "正解。分離の対義語で、別々のものをつなぎ合わせる意味。"}, {"text": "固定", "is_correct": false, "explanation": "固定は動かないよう据えることで、分離の対義語ではない。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつけること。分離とは対になる関係にない。"}, {"text": "融解", "is_correct": false, "explanation": "融解は固体が熔けて液体になること。分離の対義語ではない。"}], "correct_answer": "結合", "explanations": {"結合": "正解。分離の対義語で、別々のものをつなぎ合わせる意味。", "固定": "固定は動かないよう据えることで、分離の対義語ではない。", "点火": "点火は火をつけること。分離とは対になる関係にない。", "融解": "融解は固体が熔けて液体になること。分離の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37752, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "結合", "is_correct": true, "explanation": "正解。分離の対義語で、離れていたものをつなぎ合わせる意味。"}, {"text": "溶解", "is_correct": false, "explanation": "溶解は固体が液体に溶けること。分離の対義語ではない。"}, {"text": "点灯", "is_correct": false, "explanation": "点灯は明かりをつけること。分離とは対になる関係にない。"}, {"text": "解凍", "is_correct": false, "explanation": "解凍は凍ったものを溶かすこと。分離の対義語ではない。"}], "correct_answer": "結合", "explanations": {"結合": "正解。分離の対義語で、離れていたものをつなぎ合わせる意味。", "溶解": "溶解は固体が液体に溶けること。分離の対義語ではない。", "点灯": "点灯は明かりをつけること。分離とは対になる関係にない。", "解凍": "解凍は凍ったものを溶かすこと。分離の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37752, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かが、くっついていたものから、はなれること。", "primary_collocate": null, "pronunciation": "ぶんり", "ipa": "bɯɴɾi", "syllable_count": 3, "sentences": [{"text": "ロケットの一段目が燃え尽きて、本体から分離した。", "target_word": "分離", "complexity_tier": "T3", "furigana": "ロケットの一段目[いちだんめ]が燃[も]え尽[つ]きて、本体[ほんたい]から分離[ぶんり]した。", "sentence_source": "generated"}, {"text": "落としたせいで、望遠鏡の筒が本体から分離してしまった。", "target_word": "分離", "complexity_tier": "T3", "furigana": "落[お]としたせいで、望遠鏡[ぼうえんきょう]の筒[つつ]が本体[ほんたい]から分離[ぶんり]してしまった。", "sentence_source": "generated"}, {"text": "接着剤が古くなって、板と板が分離した。", "target_word": "分離", "complexity_tier": "T3", "furigana": "接着剤[せっちゃくざい]が古[ふる]くなって、板[いた]と板[いた]が分離[ぶんり]した。", "sentence_source": "generated"}, {"text": "分離したカプセルは、予定どおり海に落ちた。", "target_word": "分離", "complexity_tier": "T3", "furigana": "分離[ぶんり]したカプセルは、予定[よてい]どおり海[うみ]に落[お]ちた。", "sentence_source": "generated"}, {"text": "宇宙船から分離した部品が、ゆっくり遠ざかっていく。", "target_word": "分離", "complexity_tier": "T3", "furigana": "宇宙船[うちゅうせん]から分離[ぶんり]した部品[ぶひん]が、ゆっくり遠[とお]ざかっていく。", "sentence_source": "generated"}, {"text": "氷河の端が分離して、大きな氷山になった。", "target_word": "分離", "complexity_tier": "T3", "furigana": "氷河[ひょうが]の端[はし]が分離[ぶんり]して、大[おお]きな氷山[ひょうざん]になった。", "sentence_source": "generated"}, {"text": "接合部が弱く、機体の一部が空中で分離した。", "target_word": "分離", "complexity_tier": "T3", "furigana": "接合部[せつごうぶ]が弱[よわ]く、機体[きたい]の一部[いちぶ]が空中[くうちゅう]で分離[ぶんり]した。", "sentence_source": "generated"}, {"text": "分離したあとのタンクは、海に落ちて回収された。", "target_word": "分離", "complexity_tier": "T3", "furigana": "分離[ぶんり]したあとのタンクは、海[うみ]に落[お]ちて回収[かいしゅう]された。", "sentence_source": "generated"}, {"text": "衝撃で車のバンパーが車体から分離し、道に落ちた。", "target_word": "分離", "complexity_tier": "T3", "furigana": "衝撃[しょうげき]で車[くるま]のバンパーが車体[しゃたい]から分離[ぶんり]し、道[みち]に落[お]ちた。", "sentence_source": "generated"}, {"text": "二つの船体が分離する瞬間を、みんなで見守った。", "target_word": "分離", "complexity_tier": "T3", "furigana": "二[ふた]つの船体[せんたい]が分離[ぶんり]する瞬間[しゅんかん]を、みんなで見守[みまも]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分離する", "label": "dictionary form"}, {"form": "分離した", "label": "past"}, {"form": "分離して", "label": "te-form"}, {"form": "分離しない", "label": "negative"}, {"form": "分離される", "label": "passive"}], "register": "neutral", "sense_fingerprint": "くっついていた部品や物が本体から離れる、物理的な切り離れ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e61789a-9eca-468c-8b66-53ec4aea85ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37752, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分離", "is_correct": true, "explanation": "正解。燃え尽きた一段目が本体から離れる、くっついていた部分の切り離れを表す。"}, {"text": "固定", "is_correct": false, "explanation": "固定は動かないように据えること。離れていく文脈と逆で、「本体から固定した」は意味が通らない。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつけること。部品が本体から離れる文に入れても意味が合わない。"}, {"text": "結合", "is_correct": false, "explanation": "結合は別々のものをつなぎ合わせること。離れる文脈では逆の意味になり、「本体から結合した」は成立しない。"}], "explanations": {"分離": "正解。燃え尽きた一段目が本体から離れる、くっついていた部分の切り離れを表す。", "固定": "固定は動かないように据えること。離れていく文脈と逆で、「本体から固定した」は意味が通らない。", "点火": "点火は火をつけること。部品が本体から離れる文に入れても意味が合わない。", "結合": "結合は別々のものをつなぎ合わせること。離れる文脈では逆の意味になり、「本体から結合した」は成立しない。"}, "sentence_index": 0, "correct_answer": "分離"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "実際の売上が予想から分離した。", "explanation": "ここは〈乖離〉の意味。予想と実績が食い違う場合は乖離を使い、分離は一体のものが離れる意味なので合わない。"}, {"text": "飛行機が分離して、ゆっくり空へ上がっていった。", "explanation": "ここは〈離陸〉の意味。分離は本体から部品が離れることで、機体全体が地面を離れる場合は離陸を使う。"}, {"text": "ロープを分離して、荷物を下に落とした。", "explanation": "ここは〈切断〉の意味。分離は元は一体だった部分が離れることで、刃物で断つロープには切断が合う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37752, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分離", "is_correct": true, "explanation": "正解。接合部が弱く、機体の一部が空中で離れたことを表す。"}, {"text": "着陸", "is_correct": false, "explanation": "着陸は地面に降りること。空中で機体の一部が外れる文脈と矛盾する。"}, {"text": "転倒", "is_correct": false, "explanation": "転倒は倒れること。空中で機体が倒れるという文は、部品が外れる文と合わない。"}, {"text": "解凍", "is_correct": false, "explanation": "解凍は凍ったものを溶かすこと。機体の接合部の文脈には使えない。"}], "explanations": {"分離": "正解。接合部が弱く、機体の一部が空中で離れたことを表す。", "着陸": "着陸は地面に降りること。空中で機体の一部が外れる文脈と矛盾する。", "転倒": "転倒は倒れること。空中で機体が倒れるという文は、部品が外れる文と合わない。", "解凍": "解凍は凍ったものを溶かすこと。機体の接合部の文脈には使えない。"}, "sentence_index": 6, "correct_answer": "分離"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前回の試合の結果を分離して、次の作戦を立てた。", "explanation": "ここは〈分析〉の意味。結果を細かく調べる場合は分析を使い、分離は離れる意味なので合わない。"}, {"text": "二つの町が分離して、一つの市になった。", "explanation": "ここは〈合併〉の意味。二つが一つになる場合は合併を使い、分離は離れる意味なので合わない。"}, {"text": "材料を分離して、きれいに混ぜ合わせた。", "explanation": "ここは〈混合〉の意味。材料を混ぜる場合は混合を使い、分離は離れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37752, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "衝突の後、デッキが船体に分離した。", "corrected_sentence": "衝突の後、デッキが船体から分離した。", "error_description": "「船体から」の「から」が「に」になっている。分離は離れる起点を「から」で示すので、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37752, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強風で看板が支柱から分離れた。", "corrected_sentence": "強風で看板が支柱から分離した。", "error_description": "「分離れた」が誤りで「分離した」が正しい。「分離する」はサ変動詞なので過去形は「分離した」。「分離れた」は一段動詞の活用を誤ったもの。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37753, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "統合", "is_correct": true, "explanation": "正解。分けることの対義語で、いくつかのものを一つにまとめる意味。"}, {"text": "仲介", "is_correct": false, "explanation": "仲介は間に入って取り持つこと。分離の対義語ではない。"}, {"text": "散策", "is_correct": false, "explanation": "散策は気ままに歩くこと。分離とは対になる関係にない。"}, {"text": "結晶", "is_correct": false, "explanation": "結晶は物質が規則正しく固まったもの。分離の対義語ではない。"}], "correct_answer": "統合", "explanations": {"統合": "正解。分けることの対義語で、いくつかのものを一つにまとめる意味。", "仲介": "仲介は間に入って取り持つこと。分離の対義語ではない。", "散策": "散策は気ままに歩くこと。分離とは対になる関係にない。", "結晶": "結晶は物質が規則正しく固まったもの。分離の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37753, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。映像が分けられる対象なので、「映像を分離して」となる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は行き先や結果を示すので、分けられる対象には使えない。「映像に分離して」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、分離の対象を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を表し、分離の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。映像が分けられる対象なので、「映像を分離して」となる。", "に": "「に」は行き先や結果を示すので、分けられる対象には使えない。「映像に分離して」は不自然。", "で": "「で」は手段や場所を示すので、分離の対象を表せない。", "の": "「の」は所属や修飾を表し、分離の目的語にはならない。"}, "error_tags": {"に": "行き先", "で": "手段", "の": "所属"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "統合", "is_correct": true, "explanation": "正解。分けることの対義語で、いくつかのものを一つにまとめる意味。"}, {"text": "解析", "is_correct": false, "explanation": "解析は細かく分けて調べること。分離の対義語ではない。"}, {"text": "延長", "is_correct": false, "explanation": "延長は長さや期間を伸ばすこと。分離とは対になる関係にない。"}, {"text": "点検", "is_correct": false, "explanation": "点検は状態を一つずつ調べること。分離とは対になる関係にない。"}], "correct_answer": "統合", "explanations": {"統合": "正解。分けることの対義語で、いくつかのものを一つにまとめる意味。", "解析": "解析は細かく分けて調べること。分離の対義語ではない。", "延長": "延長は長さや期間を伸ばすこと。分離とは対になる関係にない。", "点検": "点検は状態を一つずつ調べること。分離とは対になる関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37753, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "一つにまとまっていたものが、別々に分かれること。また、分けること。", "primary_collocate": null, "pronunciation": "ぶんり", "ipa": "bɯɴɾi", "syllable_count": 3, "sentences": [{"text": "遠心力を使うと、血液を成分ごとに分離できる。", "target_word": "分離", "complexity_tier": "T3", "furigana": "遠心力[えんしんりょく]を使[つか]うと、血液[けつえき]を成分[せいぶん]ごとに分離[ぶんり]できる。", "sentence_source": "generated"}, {"text": "油と水は混ざらないので、簡単に分離できる。", "target_word": "分離", "complexity_tier": "T3", "furigana": "油[あぶら]と水[みず]は混[ま]ざらないので、簡単[かんたん]に分離[ぶんり]できる。", "sentence_source": "generated"}, {"text": "目の細かい網で、砂と小石を分離した。", "target_word": "分離", "complexity_tier": "T3", "furigana": "目[め]の細[こま]かい網[あみ]で、砂[すな]と小石[こいし]を分離[ぶんり]した。", "sentence_source": "generated"}, {"text": "政治と宗教の分離は、この国の大切な原則だ。", "target_word": "分離", "complexity_tier": "T3", "furigana": "政治[せいじ]と宗教[しゅうきょう]の分離[ぶんり]は、この国[くに]の大切[たいせつ]な原則[げんそく]だ。", "sentence_source": "generated"}, {"text": "会社は、販売の部門と製造の部門を分離することにした。", "target_word": "分離", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、販売[はんばい]の部門[ぶもん]と製造[せいぞう]の部門[ぶもん]を分離[ぶんり]することにした。", "sentence_source": "generated"}, {"text": "牛乳を置いておくと、クリームが上に分離する。", "target_word": "分離", "complexity_tier": "T3", "furigana": "牛乳[ぎゅうにゅう]を置[お]いておくと、クリームが上[うえ]に分離[ぶんり]する。", "sentence_source": "generated"}, {"text": "実験では、まず混ぜた液体から塩を分離する。", "target_word": "分離", "complexity_tier": "T3", "furigana": "実験[じっけん]では、まず混[ま]ぜた液体[えきたい]から塩[しお]を分離[ぶんり]する。", "sentence_source": "generated"}, {"text": "音声と映像を分離して、別々のファイルに保存した。", "target_word": "分離", "complexity_tier": "T3", "furigana": "音声[おんせい]と映像[えいぞう]を分離[ぶんり]して、別々[べつべつ]のファイルに保存[ほぞん]した。", "sentence_source": "generated"}, {"text": "仕事と私生活の分離が難しく、休日も連絡が来る。", "target_word": "分離", "complexity_tier": "T3", "furigana": "仕事[しごと]と私生活[しせいかつ]の分離[ぶんり]が難[むずか]しく、休日[きゅうじつ]も連絡[れんらく]が来[く]る。", "sentence_source": "generated"}, {"text": "工場の排水は、汚れを分離してから川に流される。", "target_word": "分離", "complexity_tier": "T3", "furigana": "工場[こうじょう]の排水[はいすい]は、汚[よご]れを分離[ぶんり]してから川[かわ]に流[なが]される。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分離する", "label": "dictionary form"}, {"form": "分離した", "label": "past"}, {"form": "分離して", "label": "te-form"}, {"form": "分離できる", "label": "potential"}, {"form": "分離される", "label": "passive"}], "register": "neutral", "sense_fingerprint": "混ざっていたものや一体だったものを、成分や部門ごとに分けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e61789a-9eca-468c-8b66-53ec4aea85ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37753, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分離", "is_correct": true, "explanation": "正解。血液を成分ごとに分けられる、という意味を表す。"}, {"text": "解約", "is_correct": false, "explanation": "解約は契約を取り消すこと。成分を分ける文脈には合わない。"}, {"text": "施錠", "is_correct": false, "explanation": "施錠は錠をかけること。血液の成分を分ける文では意味が通らない。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲を作ること。血液の成分とは結びつかない。"}], "explanations": {"分離": "正解。血液を成分ごとに分けられる、という意味を表す。", "解約": "解約は契約を取り消すこと。成分を分ける文脈には合わない。", "施錠": "施錠は錠をかけること。血液の成分を分ける文では意味が通らない。", "作曲": "作曲は曲を作ること。血液の成分とは結びつかない。"}, "sentence_index": 0, "correct_answer": "分離"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの村が分離して、一つの町にまとまった。", "explanation": "ここは〈統合〉の意味。分離は分けることで、一つにまとまる文脈には統合を使う。"}, {"text": "二つの文化が分離して、新しい芸術が生まれた。", "explanation": "ここは〈融合〉の意味。分離は分けることで、混ざり合って新しいものが生まれる文脈には合わない。"}, {"text": "絵の具を分離して、鮮やかな緑色を作った。", "explanation": "ここは〈混色〉の意味。色を混ぜて新しい色を作る場合は混色を使い、分離は分ける意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37753, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分離", "is_correct": true, "explanation": "正解。混ぜた液体から塩を分ける、という意味を表す。"}, {"text": "購入", "is_correct": false, "explanation": "購入は代金を払って手に入れること。液体から塩を取り出す文とは合わない。"}, {"text": "登録", "is_correct": false, "explanation": "登録は名簿などに記録すること。液体から塩を取り出す文では意味が通らない。"}, {"text": "転職", "is_correct": false, "explanation": "転職は仕事を変えること。実験の文脈とはまったく合わない。"}], "explanations": {"分離": "正解。混ぜた液体から塩を分ける、という意味を表す。", "購入": "購入は代金を払って手に入れること。液体から塩を取り出す文とは合わない。", "登録": "登録は名簿などに記録すること。液体から塩を取り出す文では意味が通らない。", "転職": "転職は仕事を変えること。実験の文脈とはまったく合わない。"}, "sentence_index": 6, "correct_answer": "分離"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの会社が分離して、新しい一つの会社になった。", "explanation": "ここは〈合併〉の意味。二つが一つになる文に分離を使うと、分ける意味と矛盾する。"}, {"text": "二つの川が分離して、大きな流れになった。", "explanation": "ここは〈合流〉の意味。川が集まって一つになる場合は合流を使い、分離は使わない。"}, {"text": "二つのデータを分離して、一つの表にまとめた。", "explanation": "ここは〈連結〉の意味。データを一つにつなぐ場合は連結を使い、分離は分ける意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37753, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この装置は、牛乳から脂肪の分離できる。", "corrected_sentence": "この装置は、牛乳から脂肪を分離できる。", "error_description": "「脂肪の分離できる」の「の」が誤りで「脂肪を分離できる」が正しい。「分離できる」は目的語を「を」で示すので、「脂肪の」ではなく「脂肪を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37753, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機械は、洗濯の水から糸くずに分離する。", "corrected_sentence": "この機械は、洗濯の水から糸くずを分離する。", "error_description": "「糸くずに」の「に」が誤りで「糸くずを」が正しい。「分離する」は「〜を分離する」と目的語に「を」を取る。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37754, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。症状が表に現れていないという主語を示す「症状が顕在していない」となる。"}, {"text": "を", "is_correct": false, "explanation": "顕在は自動詞なので目的語の「を」は取らない。「症状を顕在していない」は成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、現れている主体には使えない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、症状が現れる主語には合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。症状が表に現れていないという主語を示す「症状が顕在していない」となる。", "を": "顕在は自動詞なので目的語の「を」は取らない。「症状を顕在していない」は成立しない。", "で": "「で」は手段や場所を示すので、現れている主体には使えない。", "と": "「と」は相手や並列を示すので、症状が現れる主語には合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "潜在", "is_correct": true, "explanation": "正解。顕在の対義語で、表に現れず隠れている状態を表す。"}, {"text": "不在", "is_correct": false, "explanation": "不在はそこにいないこと。顕在の対義語ではない。"}, {"text": "無効", "is_correct": false, "explanation": "無効は効力がないこと。顕在の対義語ではない。"}, {"text": "休止", "is_correct": false, "explanation": "休止は一時的に止まること。顕在の対義語ではない。"}], "correct_answer": "潜在", "explanations": {"潜在": "正解。顕在の対義語で、表に現れず隠れている状態を表す。", "不在": "不在はそこにいないこと。顕在の対義語ではない。", "無効": "無効は効力がないこと。顕在の対義語ではない。", "休止": "休止は一時的に止まること。顕在の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37754, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "潜在", "is_correct": true, "explanation": "正解。顕在の対義語で、表に現れず隠れている状態を表す。"}, {"text": "解消", "is_correct": false, "explanation": "解消は問題や状態をなくすこと。顕在の対義語ではない。"}, {"text": "沈静化", "is_correct": false, "explanation": "沈静化は騒ぎなどが静まること。顕在の対義語ではない。"}, {"text": "一掃", "is_correct": false, "explanation": "一掃は残らず取り除くこと。顕在の対義語ではない。"}], "correct_answer": "潜在", "explanations": {"潜在": "正解。顕在の対義語で、表に現れず隠れている状態を表す。", "解消": "解消は問題や状態をなくすこと。顕在の対義語ではない。", "沈静化": "沈静化は騒ぎなどが静まること。顕在の対義語ではない。", "一掃": "一掃は残らず取り除くこと。顕在の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37754, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるものが、目に見えるようになること。", "primary_collocate": null, "pronunciation": "けんざい", "ipa": "keɲzai", "syllable_count": 4, "sentences": [{"text": "隠れていた問題が、検査の結果、はっきり顕在した。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "隠[かく]れていた問題[もんだい]が、検査[けんさ]の結果[けっか]、はっきり顕在[けんざい]した。", "sentence_source": "generated"}, {"text": "症状が顕在していない段階では、病気に気づきにくい。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "症状[しょうじょう]が顕在[けんざい]していない段階[だんかい]では、病気[びょうき]に気[き]づきにくい。", "sentence_source": "generated"}, {"text": "調査が進むにつれ、これまで見えなかった不正が顕在した。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "調査[ちょうさ]が進[すす]むにつれ、これまで見[み]えなかった不正[ふせい]が顕在[けんざい]した。", "sentence_source": "generated"}, {"text": "潜在していた対立が顕在して、会議は荒れた。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "潜在[せんざい]していた対立[たいりつ]が顕在[けんざい]して、会議[かいぎ]は荒[あ]れた。", "sentence_source": "generated"}, {"text": "能力は、使われて初めて顕在する。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "能力[のうりょく]は、使[つか]われて初[はじ]めて顕在[けんざい]する。", "sentence_source": "generated"}, {"text": "地震のあと、古い建物の弱点が顕在した。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、古[ふる]い建物[たてもの]の弱点[じゃくてん]が顕在[けんざい]した。", "sentence_source": "generated"}, {"text": "顕在している危険には対策できるが、見えない危険は防ぎにくい。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "顕在[けんざい]している危険[きけん]には対策[たいさく]できるが、見[み]えない危険[きけん]は防[ふせ]ぎにくい。", "sentence_source": "generated"}, {"text": "彼の不満はすでに顕在しており、隠しようがなかった。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "彼[かれ]の不満[ふまん]はすでに顕在[けんざい]しており、隠[かく]しようがなかった。", "sentence_source": "generated"}, {"text": "顕在した課題から順に、一つずつ解決していくべきだ。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "顕在[けんざい]した課題[かだい]から順[じゅん]に、一[ひと]つずつ解決[かいけつ]していくべきだ。", "sentence_source": "generated"}, {"text": "不況の影響が顕在するのは、半年後だろう。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "不況[ふきょう]の影響[えいきょう]が顕在[けんざい]するのは、半年後[はんとしご]だろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "顕在する", "label": "dictionary form"}, {"form": "顕在した", "label": "past"}, {"form": "顕在して", "label": "te-form"}, {"form": "顕在している", "label": "progressive"}, {"form": "顕在的な", "label": "adjectival form"}], "register": "formal", "sense_fingerprint": "隠れていた問題や能力がはっきり表に現れること。潜在の対", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e61789a-9eca-468c-8b66-53ec4aea85ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37754, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顕在", "is_correct": true, "explanation": "正解。隠れていた問題が検査で表に現れた、という意味を表す。"}, {"text": "不在", "is_correct": false, "explanation": "不在はそこにいないこと。表に現れたという文とは合わない。"}, {"text": "無効", "is_correct": false, "explanation": "無効は効力がないこと。問題が表に現れる文脈には合わない。"}, {"text": "休止", "is_correct": false, "explanation": "休止は一時的に止まること。問題がはっきり現れる文とは合わない。"}], "explanations": {"顕在": "正解。隠れていた問題が検査で表に現れた、という意味を表す。", "不在": "不在はそこにいないこと。表に現れたという文とは合わない。", "無効": "無効は効力がないこと。問題が表に現れる文脈には合わない。", "休止": "休止は一時的に止まること。問題がはっきり現れる文とは合わない。"}, "sentence_index": 0, "correct_answer": "顕在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "才能が顕在して、まだ誰も気づかない。", "explanation": "ここは〈潜在〉の意味。顕在は表に現れることで、まだ気づかれていない才能には潜在が合う。"}, {"text": "ワインが顕在して、味がまろやかになった。", "explanation": "ここは〈熟成〉の意味。ワインが時間をかけて味を深める場合は熟成を使い、顕在は表に現れる意味なので合わない。"}, {"text": "病原菌が顕在して、体内でじっとしていた。", "explanation": "ここは〈潜伏〉の意味。身を隠して機会を待つ状態には潜伏を使い、顕在は表に現れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37754, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顕在", "is_correct": true, "explanation": "正解。危険が表に現れていて対策できる、という意味を表す。"}, {"text": "解除", "is_correct": false, "explanation": "解除は制限や状態を取り除くこと。「解除している危険」は文が成立しない。"}, {"text": "濃縮", "is_correct": false, "explanation": "濃縮は成分を濃くすること。危険の状態を表す文には合わない。"}, {"text": "完成", "is_correct": false, "explanation": "完成は仕上がること。危険の状態を表す文では意味が通らない。"}], "explanations": {"顕在": "正解。危険が表に現れていて対策できる、という意味を表す。", "解除": "解除は制限や状態を取り除くこと。「解除している危険」は文が成立しない。", "濃縮": "濃縮は成分を濃くすること。危険の状態を表す文には合わない。", "完成": "完成は仕上がること。危険の状態を表す文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "顕在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "交通渋滞が顕在して、道はすっかり空いた。", "explanation": "ここは〈解消〉の意味。渋滞がなくなる場合は解消を使い、顕在は表に現れる意味なので合わない。"}, {"text": "騒ぎが顕在して、町は落ち着いた。", "explanation": "ここは〈沈静化〉の意味。騒ぎが静まる場合は沈静化を使い、顕在は現れる意味なので矛盾する。"}, {"text": "汚職が顕在して、町からすっかり消えた。", "explanation": "ここは〈撲滅〉の意味。悪いものを根こそぎなくす場合は撲滅を使い、顕在は現れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37754, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "長く隠れていた欠陥を、点検で顕在した。", "corrected_sentence": "長く隠れていた欠陥が、点検で顕在した。", "error_description": "「欠陥を」の「を」が誤りで「欠陥が」が正しい。顕在は主語が現れる自動詞なので、主語に「が」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37754, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市の財政危機を、報告書で顕在した。", "corrected_sentence": "市の財政危機が、報告書で顕在した。", "error_description": "「危機を」の「を」が誤りで「危機が」が正しい。「顕在した」は自動詞で、主語の「危機」に「が」を付ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37756, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「なくなる」の主語を示す「が」が入る。「ストレスがなくなって」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「なくなる」は目的語を取らない自動詞なので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は結果や位置を示すが、「ストレスになくなって」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「ストレスへなくなって」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「なくなる」の主語を示す「が」が入る。「ストレスがなくなって」と自然に続く。", "を": "「なくなる」は目的語を取らない自動詞なので、「を」は合わない。", "に": "「に」は結果や位置を示すが、「ストレスになくなって」では文が成り立たない。", "へ": "「へ」は方向を示すので、「ストレスへなくなって」は不自然。"}, "error_tags": {"を": "対象", "に": "帰着・結果", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37756, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「感じる」の対象を示す「を」。「ストレスを感じている」と自然につながる。"}, {"text": "が", "is_correct": false, "explanation": "「が」を使うとストレスが主語になり、「感じている」の主語は人なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「強いストレスへ感じている」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「ストレスより感じている」は文として合わない。"}], "correct_answer": "を", "explanations": {"を": "「感じる」の対象を示す「を」。「ストレスを感じている」と自然につながる。", "が": "「が」を使うとストレスが主語になり、「感じている」の主語は人なので合わない。", "へ": "「へ」は方向を示すので、「強いストレスへ感じている」は不自然。", "より": "「より」は比較を示すので、「ストレスより感じている」は文として合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37756, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "しんぱいや つかれで こころや からだが くるしく なる こと。", "primary_collocate": null, "pronunciation": "すとれす", "ipa": "sɯtoɾesɯ", "syllable_count": 4, "sentences": [{"text": "仕事が忙しすぎて、最近ストレスがたまっています。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "仕事[しごと]が忙[いそが]しすぎて、最近[さいきん]ストレスがたまっています。", "sentence_source": "generated"}, {"text": "友達と話すと、ストレスがなくなって気持ちが楽になる。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "友達[ともだち]と話[はな]すと、ストレスがなくなって気持[きも]ちが楽[らく]になる。", "sentence_source": "generated"}, {"text": "ストレスが原因で、夜よく眠れなくなった。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "ストレスが原因[げんいん]で、夜[よる]よく眠[ねむ]れなくなった。", "sentence_source": "generated"}, {"text": "毎日の満員電車は、私にとって大きなストレスです。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "毎日[まいにち]の満員電車[まんいんでんしゃ]は、私[わたし]にとって大[おお]きなストレスです。", "sentence_source": "generated"}, {"text": "運動をして汗をかくと、ストレスを減らすことができる。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "運動[うんどう]をして汗[あせ]をかくと、ストレスを減[へ]らすことができる。", "sentence_source": "generated"}, {"text": "テストの前は、いつもストレスで胃が痛くなる。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "テストの前[まえ]は、いつもストレスで胃[い]が痛[いた]くなる。", "sentence_source": "generated"}, {"text": "好きな音楽を聞いて、ストレスを発散した。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "好[す]きな音楽[おんがく]を聞[き]いて、ストレスを発散[はっさん]した。", "sentence_source": "generated"}, {"text": "上司に怒られてばかりで、強いストレスを感じている。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "上司[じょうし]に怒[おこ]られてばかりで、強[つよ]いストレスを感[かん]じている。", "sentence_source": "generated"}, {"text": "旅行に行ったら、ストレスが消えて元気になった。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "旅行[りょこう]に行[い]ったら、ストレスが消[き]えて元気[げんき]になった。", "sentence_source": "generated"}, {"text": "疲れとストレスで、彼は三日間も学校を休んだ。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "疲[つか]れとストレスで、彼[かれ]は三日間[みっかかん]も学校[がっこう]を休[やす]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ストレス", "label": "基本形"}], "register": "中立", "sense_fingerprint": "心配や疲れで心身が苦しくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09538d83-9a44-4f80-ba28-79d49154d0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37756, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ストレス", "is_correct": true, "explanation": "「最近〜がたまっている」の空欄には、心身の負担による緊張を表すストレスが入る。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は響きや感動のあとに残る気配で、「たまる」とは結びつかない。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は相手に抱く気持ちで、「たまる」とは言わない。"}, {"text": "笑顔", "is_correct": false, "explanation": "笑顔は表情のことで、たまるものではない。"}], "explanations": {"ストレス": "「最近〜がたまっている」の空欄には、心身の負担による緊張を表すストレスが入る。", "余韻": "余韻は響きや感動のあとに残る気配で、「たまる」とは結びつかない。", "感謝": "感謝は相手に抱く気持ちで、「たまる」とは言わない。", "笑顔": "笑顔は表情のことで、たまるものではない。"}, "sentence_index": 0, "correct_answer": "ストレス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝る前にストレスをすると、朝に体が軽くなる。", "explanation": "ここはストレッチ（体をのばす運動）の意味。ストレスは心身の負担による緊張で、体をのばす運動の代わりには使わない。"}, {"text": "足首をひねったので、まだ強いストレスが残っている。", "explanation": "ここは〈痛み〉の意味。ストレスは心身の負担による緊張で、ケガの痛みには使わない。"}, {"text": "風邪をひいて、ストレスが38度まで上がった。", "explanation": "ここは〈体温〉の意味。ストレスは心身の負担を指し、体温のように度数で上がる数値の代わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37756, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ストレス", "is_correct": true, "explanation": "「ストレスを発散した」の空欄。心身の緊張を解く対象としてストレスが入る。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は眠くなる感覚で、発散する対象ではない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている時の呼吸音で、発散するものではない。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖は寝ている間についた髪の乱れで、発散できるものではない。"}], "explanations": {"ストレス": "「ストレスを発散した」の空欄。心身の緊張を解く対象としてストレスが入る。", "眠気": "眠気は眠くなる感覚で、発散する対象ではない。", "寝息": "寝息は眠っている時の呼吸音で、発散するものではない。", "寝癖": "寝癖は寝ている間についた髪の乱れで、発散できるものではない。"}, "sentence_index": 6, "correct_answer": "ストレス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本番の前に深呼吸して、ストレスを解いた。", "explanation": "ここは〈緊張〉の意味。緊張は解くものだが、ストレスは解消や発散をするもので、解くとは言わない。"}, {"text": "ストレスが香って、部屋中がいい匂いになった。", "explanation": "ここは〈香り〉の意味。ストレスは心身の負担を指し、香りが漂う意味では使わない。"}, {"text": "この箱は、ストレスが四角い。", "explanation": "ここは〈形〉の意味。ストレスは心身の負担を表し、物の形を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37756, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仕事でストレスが感じるので、休みが欲しい。", "corrected_sentence": "仕事でストレスを感じるので、休みが欲しい。", "error_description": "「感じる」の主語は人なので、「ストレスが感じる」は誤り。対象は「を」で示し、正しくは「ストレスを感じる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37756, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験前はストレスをたまって、体調を崩した。", "corrected_sentence": "試験前はストレスがたまって、体調を崩した。", "error_description": "「たまる」は主語に「が」を取る。「ストレスをたまって」は誤りで、正しくは「ストレスがたまって」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37757, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「受ける」の対象を示す「を」。「強いストレスを受ける」と自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」を使うとストレスが主語になり、「受ける」の主語である橋と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すので、「ストレスに受ける」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「ストレスで受ける」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「受ける」の対象を示す「を」。「強いストレスを受ける」と自然。", "が": "「が」を使うとストレスが主語になり、「受ける」の主語である橋と合わない。", "に": "「に」は位置や相手を示すので、「ストレスに受ける」は成り立たない。", "で": "「で」は手段や場所を示すので、「ストレスで受ける」は不自然。"}, "error_tags": {"が": "主語", "に": "相手・位置", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37757, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「生じる」は「が」で生じるものを示す。「内部にストレスが生じて」と自然。"}, {"text": "を", "is_correct": false, "explanation": "「生じる」は目的語を取らない自動詞なので、「ストレスを生じて」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「ストレスと生じて」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「ストレスより生じて」は文として合わない。"}], "correct_answer": "が", "explanations": {"が": "「生じる」は「が」で生じるものを示す。「内部にストレスが生じて」と自然。", "を": "「生じる」は目的語を取らない自動詞なので、「ストレスを生じて」は不自然。", "と": "「と」は並列や相手を示すので、「ストレスと生じて」は成り立たない。", "より": "「より」は比較を示すので、「ストレスより生じて」は文として合わない。"}, "error_tags": {"を": "対象", "と": "相手・並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37757, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "精神的・肉体的な負担によって起こる緊張や圧迫感。また、物体に外から加わる力。", "primary_collocate": null, "pronunciation": "すとれす", "ipa": "sɯtoɾesɯ", "syllable_count": 4, "sentences": [{"text": "長い時間パソコンを使うと、目や肩に大きなストレスがかかる。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "長[なが]い時間[じかん]パソコンを使[つか]うと、目[め]や肩[かた]に大[おお]きなストレスがかかる。", "sentence_source": "generated"}, {"text": "橋の鉄は、重い車が通るたびに強いストレスを受ける。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "橋[はし]の鉄[てつ]は、重[おも]い車[くるま]が通[とお]るたびに強[つよ]いストレスを受[う]ける。", "sentence_source": "generated"}, {"text": "この材料は、外から力を加えてストレスをかけると、少し曲がる。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "この材料[ざいりょう]は、外[そと]から力[ちから]を加[くわ]えてストレスをかけると、少[すこ]し曲[ま]がる。", "sentence_source": "generated"}, {"text": "急な環境の変化は、心と体に強いストレスを与える。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "急[きゅう]な環境[かんきょう]の変化[へんか]は、心[こころ]と体[からだ]に強[つよ]いストレスを与[あた]える。", "sentence_source": "generated"}, {"text": "長時間の立ち仕事で、足の筋肉に大きなストレスがかかった。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "長時間[ちょうじかん]の立[た]ち仕事[しごと]で、足[あし]の筋肉[きんにく]に大[おお]きなストレスがかかった。", "sentence_source": "generated"}, {"text": "ガラスは一か所にストレスが集中すると、割れやすい。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "ガラスは一[いっ]か所[しょ]にストレスが集中[しゅうちゅう]すると、割[わ]れやすい。", "sentence_source": "generated"}, {"text": "締め切りが続いて、精神的なストレスで食欲がなくなった。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "締[し]め切[き]りが続[つづ]いて、精神的[せいしんてき]なストレスで食欲[しょくよく]がなくなった。", "sentence_source": "generated"}, {"text": "金属の棒を曲げ続けると、内部にストレスが生じて折れる。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "金属[きんぞく]の棒[ぼう]を曲[ま]げ続[つづ]けると、内部[ないぶ]にストレスが生[しょう]じて折[お]れる。", "sentence_source": "generated"}, {"text": "騒音の多い職場では、体にもストレスがかかるといわれる。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "騒音[そうおん]の多[おお]い職場[しょくば]では、体[からだ]にもストレスがかかるといわれる。", "sentence_source": "generated"}, {"text": "柱にかかるストレスを計算して、建物の設計をする。", "target_word": "ストレス", "complexity_tier": "T3", "furigana": "柱[はしら]にかかるストレスを計算[けいさん]して、建物[たてもの]の設計[せっけい]をする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ストレス", "label": "基本形"}], "register": "中立", "sense_fingerprint": "心身への負担による緊張、物体に加わる力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09538d83-9a44-4f80-ba28-79d49154d0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37757, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ストレス", "is_correct": true, "explanation": "目や肩にかかる負荷を表すストレスが「大きな〜がかかる」に入る。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は響きのあとに残る気配で、体にかかるものではない。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は相手への気持ちで、体にかかるものではない。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖は髪の乱れで、目や肩にかかるものではない。"}], "explanations": {"ストレス": "目や肩にかかる負荷を表すストレスが「大きな〜がかかる」に入る。", "余韻": "余韻は響きのあとに残る気配で、体にかかるものではない。", "感謝": "感謝は相手への気持ちで、体にかかるものではない。", "寝癖": "寝癖は髪の乱れで、目や肩にかかるものではない。"}, "sentence_index": 0, "correct_answer": "ストレス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強いストレスが目に入って、まぶしくて目を開けられない。", "explanation": "ここは〈光〉の意味。ストレスは力や負担を指し、目に入る光の代わりにはならない。"}, {"text": "大きなストレスが走って、体が揺れた。", "explanation": "ここは〈衝撃〉の意味。ストレスは力の負荷を指し、一瞬走る衝撃の代わりには使わない。"}, {"text": "強いストレスが漂って、部屋中が甘い匂いになった。", "explanation": "ここは〈香り〉の意味。ストレスは力や負担で、空気に漂う匂いの代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37757, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ストレス", "is_correct": true, "explanation": "精神的な負担による緊張を表すストレスが「精神的な〜で」に入る。"}, {"text": "笑顔", "is_correct": false, "explanation": "笑顔は表情のことで、食欲をなくす原因にはならない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている間の呼吸で、食欲をなくす原因にはならない。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉はアレルギーの原因になるが、「精神的な」とは結びつかない。"}], "explanations": {"ストレス": "精神的な負担による緊張を表すストレスが「精神的な〜で」に入る。", "笑顔": "笑顔は表情のことで、食欲をなくす原因にはならない。", "寝息": "寝息は眠っている間の呼吸で、食欲をなくす原因にはならない。", "花粉": "花粉はアレルギーの原因になるが、「精神的な」とは結びつかない。"}, "sentence_index": 6, "correct_answer": "ストレス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理は、ストレスが強すぎて食べにくい。", "explanation": "ここは〈味〉の意味。ストレスは力や負担を表し、料理の味の強さは指さない。"}, {"text": "この壁は、ストレスが濃く塗られている。", "explanation": "ここは〈色〉の意味。ストレスは色の濃さを表さないので、この文では使えない。"}, {"text": "この布は、ストレスが細かく織られている。", "explanation": "ここは〈織り〉の意味。ストレスは心身の負担を表し、布の織り目の細かさを指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37757, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鉄の柱に大きなストレスをかかると、少しずつ曲がる。", "corrected_sentence": "鉄の柱に大きなストレスがかかると、少しずつ曲がる。", "error_description": "「かかる」は「が」で主語を示す。「ストレスをかかる」は誤りで、正しくは「ストレスがかかる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37757, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強い風が吹くと、看板の支柱に強いストレスを張る。", "corrected_sentence": "強い風が吹くと、看板の支柱に強いストレスがかかる。", "error_description": "ストレスに続く動詞は「かかる」。「張る」は力や負荷には使わないので、正しくは「かかる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
