INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37758, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "本当ではないけれど、本当のように見えること。", "primary_collocate": null, "pronunciation": "りある", "ipa": "ɾiaɾɯ", "syllable_count": 3, "sentences": [{"text": "このロボットは表情がリアルで、本物の人間のようだった。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "このロボットは表情[ひょうじょう]がリアルで、本物[ほんもの]の人間[にんげん]のようだった。", "sentence_source": "generated"}, {"text": "博物館の恐竜の模型はリアルで、子どもが泣き出した。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]の恐竜[きょうりゅう]の模型[もけい]はリアルで、子[こ]どもが泣[な]き出[だ]した。", "sentence_source": "generated"}, {"text": "CGの映像がリアルすぎて、実写かと思った。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "CGの映像[えいぞう]がリアルすぎて、実写[じっしゃ]かと思[おも]った。", "sentence_source": "generated"}, {"text": "この人形は髪の毛まで細かく作ってあって、とてもリアルだ。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "この人形[にんぎょう]は髪[かみ]の毛[け]まで細[こま]かく作[つく]ってあって、とてもリアルだ。", "sentence_source": "generated"}, {"text": "リアルな夢を見て、目が覚めてもしばらく現実だと思っていた。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "リアルな夢[ゆめ]を見[み]て、目[め]が覚[さ]めてもしばらく現実[げんじつ]だと思[おも]っていた。", "sentence_source": "generated"}, {"text": "VRで体験する高い場所はリアルで、本当に足がすくんだ。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "VRで体験[たいけん]する高[たか]い場所[ばしょ]はリアルで、本当[ほんとう]に足[あし]がすくんだ。", "sentence_source": "generated"}, {"text": "この料理のサンプルは、本物と見分けがつかないほどリアルだ。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "この料理[りょうり]のサンプルは、本物[ほんもの]と見分[みわ]けがつかないほどリアルだ。", "sentence_source": "generated"}, {"text": "彼女はリアルな絵を描くことで有名だ。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はリアルな絵[え]を描[か]くことで有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "映画のメイクがリアルで、けがが本物に見えた。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "映画[えいが]のメイクがリアルで、けがが本物[ほんもの]に見[み]えた。", "sentence_source": "generated"}, {"text": "このゲームは水の動きがリアルで、見ているだけで楽しい。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "このゲームは水[みず]の動[うご]きがリアルで、見[み]ているだけで楽[たの]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リアル", "label": "語幹"}, {"form": "リアルな", "label": "連体形"}, {"form": "リアルだ", "label": "終止形"}, {"form": "リアルで", "label": "連用形（て形）"}, {"form": "リアルに", "label": "連用形"}], "register": "一般的・やや口語", "sense_fingerprint": "作り物や映像が本物そっくりに見えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37758, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リアル", "is_correct": true, "explanation": "『表情がリアルで』と続き、本物そっくりに見える様子を表す。"}, {"text": "ぼうだい", "is_correct": false, "explanation": "『表情がぼうだいで』は意味が通らず、見た目の本物らしさを表さない。"}, {"text": "わずか", "is_correct": false, "explanation": "『表情がわずかで』は見た目の本物らしさを表さない。"}, {"text": "不自然", "is_correct": false, "explanation": "『表情が不自然で』は『本物の人間のようだった』と矛盾し、本物らしさを表さない。"}], "explanations": {"リアル": "『表情がリアルで』と続き、本物そっくりに見える様子を表す。", "ぼうだい": "『表情がぼうだいで』は意味が通らず、見た目の本物らしさを表さない。", "わずか": "『表情がわずかで』は見た目の本物らしさを表さない。", "不自然": "『表情が不自然で』は『本物の人間のようだった』と矛盾し、本物らしさを表さない。"}, "sentence_index": 0, "correct_answer": "リアル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の新しいメニューは、リアルな値段で評判だ。", "explanation": "ここは〈手頃な〉の意味。リアルは本物らしさを表す語で、値段の安さは表さない。"}, {"text": "この地図は、道の位置がリアルで、目的地まで迷わずに行けた。", "explanation": "ここは〈正確な〉の意味。リアルは本物らしさを表す語で、位置の正しさは表さない。"}, {"text": "遠くの景色がリアルで、輪郭がかすんでいる。", "explanation": "ここは〈ぼんやり〉の意味。リアルは細部まで鮮明に本物らしい状態で、輪郭がかすむことは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37758, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リアル", "is_correct": true, "explanation": "『本物と見分けがつかないほどリアルだ』の形で、本物そっくりを表す。"}, {"text": "いびつ", "is_correct": false, "explanation": "『本物と見分けがつかないほどいびつだ』は意味が合わない。"}, {"text": "素朴", "is_correct": false, "explanation": "『見分けがつかないほど素朴だ』は本物との比較として成り立たない。"}, {"text": "粗末", "is_correct": false, "explanation": "『見分けがつかないほど粗末だ』は意味が逆になり、成り立たない。"}], "explanations": {"リアル": "『本物と見分けがつかないほどリアルだ』の形で、本物そっくりを表す。", "いびつ": "『本物と見分けがつかないほどいびつだ』は意味が合わない。", "素朴": "『見分けがつかないほど素朴だ』は本物との比較として成り立たない。", "粗末": "『見分けがつかないほど粗末だ』は意味が逆になり、成り立たない。"}, "sentence_index": 6, "correct_answer": "リアル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議で彼は一方的に話を進め、リアルに意見を聞いてくれなかった。", "explanation": "ここは副詞の〈実際に〉の意味。リアルは本物らしさを表す語で、聞く態度や丁寧さは表さない。"}, {"text": "宿題をリアルに仕上げて、先生に提出した。", "explanation": "ここは〈急いで〉の意味。リアルは本物らしさを表し、速さは表さない。"}, {"text": "彼は約束をリアルに守る人だ。", "explanation": "ここは〈しっかり〉の意味。リアルは本物らしさの語で、約束を守る態度は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37758, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この写真は、本物と見分けがつかないほどリアルな。", "corrected_sentence": "この写真は、本物と見分けがつかないほどリアルだ。", "error_description": "文末では終止形『リアルだ』を使う。連体形『リアルな』で文を止めているのが誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "リアル", "is_correct": true, "explanation": "『リアルで、子どもが』の『で』の前にある語幹。空欄にはこの形が入る。"}, {"text": "リアルな", "is_correct": false, "explanation": "『リアルな、子どもが』となり、続きが成り立たない。"}, {"text": "リアルだ", "is_correct": false, "explanation": "『リアルだで』となり、文として続かない。"}, {"text": "リアルに", "is_correct": false, "explanation": "『リアルにで』となり、文として続かない。"}], "correct_form": "リアル", "base_form": "リアル", "form_label": "語幹", "sentence_index": 1, "explanations": {"リアル": "『リアルで、子どもが』の『で』の前にある語幹。空欄にはこの形が入る。", "リアルな": "『リアルな、子どもが』となり、続きが成り立たない。", "リアルだ": "『リアルだで』となり、文として続かない。", "リアルに": "『リアルにで』となり、文として続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37758, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "監督は映像のリアルに追求した。", "corrected_sentence": "監督は映像のリアルを追求した。", "error_description": "『追求する』は目的語に『を』を取る。『映像のリアル』に付く助詞は『を』で、『に』は不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "リアル", "is_correct": true, "explanation": "『リアルな絵』の『な』の前にある語幹。空欄にはこの形が入る。"}, {"text": "リアルで", "is_correct": false, "explanation": "『リアルで絵』とは続かない。『で』は名詞を修飾できない。"}, {"text": "リアルさ", "is_correct": false, "explanation": "『リアルさ』は名詞で、『リアルさな絵』とは続かない。"}, {"text": "リアルすぎ", "is_correct": false, "explanation": "『すぎ』は『すぎる』の形の一部で、『リアルすぎな絵』とは続かない。"}], "correct_form": "リアル", "base_form": "リアル", "form_label": "語幹", "sentence_index": 7, "explanations": {"リアル": "『リアルな絵』の『な』の前にある語幹。空欄にはこの形が入る。", "リアルで": "『リアルで絵』とは続かない。『で』は名詞を修飾できない。", "リアルさ": "『リアルさ』は名詞で、『リアルさな絵』とは続かない。", "リアルすぎ": "『すぎ』は『すぎる』の形の一部で、『リアルすぎな絵』とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
