INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37759, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "現実に存在するものや、実際の状態を指す言葉。作り物ではない、本物であること。", "primary_collocate": null, "pronunciation": "りある", "ipa": "ɾiaɾɯ", "syllable_count": 3, "sentences": [{"text": "ゲームの中では無敵だが、リアルの世界ではただの人だ。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "ゲームの中[なか]では無敵[むてき]だが、リアルの世界[せかい]ではただの人[ひと]だ。", "sentence_source": "generated"}, {"text": "ネットの情報だけでなく、リアルな現場の声を聞くことが大切だ。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "ネットの情報[じょうほう]だけでなく、リアルな現場[げんば]の声[こえ]を聞[き]くことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "オンライン授業もいいが、リアルで会って話すほうが気持ちが伝わる。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "オンライン授業[じゅぎょう]もいいが、リアルで会[あ]って話[はな]すほうが気持[きも]ちが伝[つた]わる。", "sentence_source": "generated"}, {"text": "彼は有名になっても、リアルな生活は昔と変わらず質素だ。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "彼[かれ]は有名[ゆうめい]になっても、リアルな生活[せいかつ]は昔[むかし]と変[か]わらず質素[しっそ]だ。", "sentence_source": "generated"}, {"text": "この記事には、働く人たちのリアルな悩みが書かれている。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "この記事[きじ]には、働[はたら]く人[ひと]たちのリアルな悩[なや]みが書[か]かれている。", "sentence_source": "generated"}, {"text": "ゲームの世界より、リアルの世界のほうが思いどおりにならない。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "ゲームの世界[せかい]より、リアルの世界[せかい]のほうが思[おも]いどおりにならない。", "sentence_source": "generated"}, {"text": "発表の数字は当てにならないので、リアルな経営状況は帳簿で確かめたほうがいい。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の数字は当てにならないので、リアルな経営状況は帳簿[ちょうぼ]で確かめたほうがいい。", "sentence_source": "generated"}, {"text": "留学して初めて、その国のリアルな姿を知ることができた。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "留学[りゅうがく]して初[はじ]めて、その国[くに]のリアルな姿[すがた]を知[し]ることができた。", "sentence_source": "generated"}, {"text": "バーチャルの友達も増えたが、リアルの友達は大切にしたい。", "target_word": "リアル", "complexity_tier": "T3", "furigana": "バーチャルの友達[ともだち]も増[ふ]えたが、リアルの友達[ともだち]は大切[たいせつ]にしたい。", "sentence_source": "generated"}, {"text": "監督は、リアルな体験談をもとに脚本を書いたそうだ。", "target_word": "リアル", "complexity_tier": "T4", "furigana": "監督[かんとく]は、リアルな体験談[たいけんだん]をもとに脚本[きゃくほん]を書[か]いたそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リアル", "label": "語幹"}, {"form": "リアルな", "label": "連体形"}, {"form": "リアルだ", "label": "終止形"}, {"form": "リアルで", "label": "連用形（て形）"}, {"form": "リアルに", "label": "連用形"}], "register": "一般的・やや口語", "sense_fingerprint": "作り物ではなく、現実に存在する本物の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14a57842-2a49-4cac-865e-708adcff9fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37759, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リアル", "is_correct": true, "explanation": "『リアルの世界』の形で、現実の世界を指す。空欄に入る。"}, {"text": "ケーキ", "is_correct": false, "explanation": "『ケーキの世界ではただの人だ』は意味が通らず、現実を表さない。"}, {"text": "春", "is_correct": false, "explanation": "『春の世界ではただの人だ』は意味が通らず、現実を表さない。"}, {"text": "魚", "is_correct": false, "explanation": "『魚の世界ではただの人だ』は意味が通らず、現実を表さない。"}], "explanations": {"リアル": "『リアルの世界』の形で、現実の世界を指す。空欄に入る。", "ケーキ": "『ケーキの世界ではただの人だ』は意味が通らず、現実を表さない。", "春": "『春の世界ではただの人だ』は意味が通らず、現実を表さない。", "魚": "『魚の世界ではただの人だ』は意味が通らず、現実を表さない。"}, "sentence_index": 0, "correct_answer": "リアル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスマホは、リアルな機能を次々に搭載している。", "explanation": "ここは〈最新の〉の意味。リアルは〈実際の・本物の〉という意味で、新しさは表さない。"}, {"text": "友人は心からリアルに謝ってくれた。", "explanation": "ここは副詞の〈本当に〉の意味。リアルは〈実際の・本物の〉で、謝る程度を強める副詞としては使えない。"}, {"text": "その話は全くリアルに知らなかった。", "explanation": "ここは否定を強める副詞〈全然〉の意味。リアルにはこの用法がなく、否定と組めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37759, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リアル", "is_correct": true, "explanation": "『リアルな経営状況』の形で、実際の状況を表す。空欄に入る。"}, {"text": "陽気", "is_correct": false, "explanation": "『陽気な経営状況』は意味が通らず、経営の実態を表さない。"}, {"text": "不要", "is_correct": false, "explanation": "『不要な経営状況』は文脈に合わず、経営の実態を指せない。"}, {"text": "上品", "is_correct": false, "explanation": "『上品な経営状況』は意味が合わず、経営の中身を表さない。"}], "explanations": {"リアル": "『リアルな経営状況』の形で、実際の状況を表す。空欄に入る。", "陽気": "『陽気な経営状況』は意味が通らず、経営の実態を表さない。", "不要": "『不要な経営状況』は文脈に合わず、経営の実態を指せない。", "上品": "『上品な経営状況』は意味が合わず、経営の中身を表さない。"}, "sentence_index": 6, "correct_answer": "リアル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その大会の結果は、リアルに発表された。", "explanation": "ここは〈公式に・正式に〉の意味。リアルは〈実際の〉で、発表のされ方は表さない。"}, {"text": "明日の会議には、リアルに遅れないと約束した。", "explanation": "ここは〈絶対に〉の意味。リアルは〈実際の〉で、否定を強める副詞としては使えない。"}, {"text": "その資料は、リアルに読み終えた。", "explanation": "ここは〈完全に〉の意味。リアルは〈実際の〉で、読み終えた程度を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37759, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの俳優の演技はリアルな、本当に感動した。", "corrected_sentence": "あの俳優の演技はリアルで、本当に感動した。", "error_description": "連用形『リアルで』にすべきところを、連体形『リアルな』にしている。『リアルな』は後ろに名詞が続く形で、読点の前には置けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "リアル", "is_correct": true, "explanation": "『リアルな現場』の『な』の前にある語幹。空欄にはこの形が入る。"}, {"text": "リアルで", "is_correct": false, "explanation": "『リアルで現場』とは続かない。『で』は名詞を修飾できない。"}, {"text": "リアルに", "is_correct": false, "explanation": "『リアルに現場』は副詞形で、名詞を修飾できない。"}, {"text": "リアルだ", "is_correct": false, "explanation": "『リアルだ現場』は成り立たない。終止形は名詞の前に置けない。"}], "correct_form": "リアル", "base_form": "リアル", "form_label": "語幹", "sentence_index": 1, "explanations": {"リアル": "『リアルな現場』の『な』の前にある語幹。空欄にはこの形が入る。", "リアルで": "『リアルで現場』とは続かない。『で』は名詞を修飾できない。", "リアルに": "『リアルに現場』は副詞形で、名詞を修飾できない。", "リアルだ": "『リアルだ現場』は成り立たない。終止形は名詞の前に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37759, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この記事は、現場のリアルに伝えている。", "corrected_sentence": "この記事は、現場のリアルを伝えている。", "error_description": "『伝える』は目的語に『を』を取る。『現場のリアル』に付く助詞は『を』で、『に』にすると不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "リアル", "is_correct": true, "explanation": "『リアルな姿』の『な』の前にある語幹。空欄にはこの形が入る。"}, {"text": "リアルな", "is_correct": false, "explanation": "『リアルなな姿』となり、『な』が重なって成り立たない。"}, {"text": "リアルさ", "is_correct": false, "explanation": "『リアルさ』は名詞で、『リアルさな姿』とは続かない。"}, {"text": "リアルすぎ", "is_correct": false, "explanation": "『すぎ』は『すぎる』の形の一部で、『リアルすぎな姿』とは続かない。"}], "correct_form": "リアル", "base_form": "リアル", "form_label": "語幹", "sentence_index": 7, "explanations": {"リアル": "『リアルな姿』の『な』の前にある語幹。空欄にはこの形が入る。", "リアルな": "『リアルなな姿』となり、『な』が重なって成り立たない。", "リアルさ": "『リアルさ』は名詞で、『リアルさな姿』とは続かない。", "リアルすぎ": "『すぎ』は『すぎる』の形の一部で、『リアルすぎな姿』とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '704d6ac7-8f74-4e10-9168-f8cd1f4bb10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37760, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「サーボが壊れて」の主語を示す「が」。自動詞「壊れる」の主語として自然。"}, {"text": "を", "is_correct": false, "explanation": "「壊れる」は自動詞なので「を」を取らず、「サーボを壊れて」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「サーボに壊れて」は不自然で、主語の位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「サーボへ壊れて」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「サーボが壊れて」の主語を示す「が」。自動詞「壊れる」の主語として自然。", "を": "「壊れる」は自動詞なので「を」を取らず、「サーボを壊れて」は成り立たない。", "に": "「サーボに壊れて」は不自然で、主語の位置に合わない。", "へ": "方向の「へ」。「サーボへ壊れて」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37760, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。「安いサーボは」と主題を立て、後で「力が弱い」と述べる文になる。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。「サーボと力が弱く」では主題が立たず不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「サーボから力が弱く」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「安いサーボを力が弱く」は他動詞がなく、目的語の「を」は成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。「安いサーボは」と主題を立て、後で「力が弱い」と述べる文になる。", "と": "並列の「と」。「サーボと力が弱く」では主題が立たず不自然になる。", "から": "起点の「から」。「サーボから力が弱く」は意味が通らない。", "を": "「安いサーボを力が弱く」は他動詞がなく、目的語の「を」は成り立たない。"}, "error_tags": {"と": "並列・共同", "から": "起点", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37760, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "きかいを おもった とおりに うごかす しかけ。", "primary_collocate": null, "pronunciation": "さーぼ", "ipa": "saːbo", "syllable_count": 3, "sentences": [{"text": "このロボットの腕はサーボで動いている。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "このロボットの腕[うで]はサーボで動[うご]いている。", "sentence_source": "generated"}, {"text": "サーボが壊れて、ロボットの指が動かなくなった。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "サーボが壊[こわ]れて、ロボットの指[ゆび]が動[うご]かなくなった。", "sentence_source": "generated"}, {"text": "模型の飛行機の羽は、小さなサーボで曲げる。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "模型[もけい]の飛行機[ひこうき]の羽[はね]は、小[ちい]さなサーボで曲[ま]げる。", "sentence_source": "generated"}, {"text": "サーボのおかげで、機械は思ったとおりに動く。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "サーボのおかげで、機械[きかい]は思[おも]ったとおりに動[うご]く。", "sentence_source": "generated"}, {"text": "ラジコンカーの向きは、サーボが変えている。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "ラジコンカーの向[む]きは、サーボが変[か]えている。", "sentence_source": "generated"}, {"text": "兄はロボットに四つのサーボを付けた。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "兄[あに]はロボットに四[よっ]つのサーボを付[つ]けた。", "sentence_source": "generated"}, {"text": "サーボが回ると、カメラの向きが変わる。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "サーボが回[まわ]ると、カメラの向[む]きが変[か]わる。", "sentence_source": "generated"}, {"text": "安いサーボは力が弱く、重い物は持てない。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "安[やす]いサーボは力[ちから]が弱[よわ]く、重[おも]い物[もの]は持[も]てない。", "sentence_source": "generated"}, {"text": "電池が切れると、サーボは動かなくなる。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "電池[でんち]が切[き]れると、サーボは動[うご]かなくなる。", "sentence_source": "generated"}, {"text": "部品店でロボット用のサーボを二つ買った。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "部品店[ぶひんてん]でロボット用[よう]のサーボを二[ふた]つ買[か]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サーボ", "label": "基本形"}, {"form": "サーボを", "label": "を格"}], "register": "neutral", "sense_fingerprint": "ロボットや模型を思いどおりに動かす小さな部品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba24b57-71af-43be-bb65-9109da6c8bd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37760, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サーボ", "is_correct": true, "explanation": "「〜で動いている」の手段を表す部品名。ロボットの腕を動かす仕組みとして成り立つ。ここが正解。"}, {"text": "カタログ", "is_correct": false, "explanation": "カタログは商品紹介の冊子で、「〜で動いている」の手段にはならない。"}, {"text": "ガラス", "is_correct": false, "explanation": "ガラスは材料の一つで、腕を動かす手段としては合わない。"}, {"text": "ペンキ", "is_correct": false, "explanation": "ペンキは塗料で、腕が動く仕組みを表す語ではない。"}], "explanations": {"サーボ": "「〜で動いている」の手段を表す部品名。ロボットの腕を動かす仕組みとして成り立つ。ここが正解。", "カタログ": "カタログは商品紹介の冊子で、「〜で動いている」の手段にはならない。", "ガラス": "ガラスは材料の一つで、腕を動かす手段としては合わない。", "ペンキ": "ペンキは塗料で、腕が動く仕組みを表す語ではない。"}, "sentence_index": 0, "correct_answer": "サーボ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ロボットの周りの温度をサーボで測った。", "explanation": "ここは〈センサー〉の意味。サーボは角度や位置を動かす装置で、温度を測る機器ではない。"}, {"text": "ロボットに付けたサーボから音楽が流れた。", "explanation": "ここは〈スピーカー〉の意味。音を出す装置で、サーボは角度を動かす部品なので合わない。"}, {"text": "会社の大事なデータはサーボに保存されている。", "explanation": "ここは〈サーバー〉の意味。データを保存する機械で、サーボは角度を動かす部品なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37760, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サーボ", "is_correct": true, "explanation": "回転して角度を変える部品で、「が回ると」の主語になる。ここが正解。"}, {"text": "ゼリー", "is_correct": false, "explanation": "ゼリーは菓子の一種で、回る部品にはならない。「ゼリーが回る」は文脈に合わない。"}, {"text": "ワックス", "is_correct": false, "explanation": "ワックスは塗る材料で、回る動きの主語にはならない。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "ヨーグルトは食品で、「が回ると」とは続かず、文が成り立たない。"}], "explanations": {"サーボ": "回転して角度を変える部品で、「が回ると」の主語になる。ここが正解。", "ゼリー": "ゼリーは菓子の一種で、回る部品にはならない。「ゼリーが回る」は文脈に合わない。", "ワックス": "ワックスは塗る材料で、回る動きの主語にはならない。", "ヨーグルト": "ヨーグルトは食品で、「が回ると」とは続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "サーボ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ロボットの頭脳となるサーボを組み込んだ。", "explanation": "ここは〈基板〉の意味。頭脳にあたる電子回路板で、動かす部品のサーボとは違う。"}, {"text": "パソコンとロボットをサーボでつないだ。", "explanation": "ここは〈ケーブル〉の意味。つなぐ線材で、サーボは動かす部品なので合わない。"}, {"text": "リモコンのサーボを押して、ロボットを動かした。", "explanation": "ここは〈ボタン〉の意味。押すのはボタンで、サーボは押す対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37760, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ラジコン船は、サーボに舵を左右に動かす。", "corrected_sentence": "ラジコン船は、サーボで舵を左右に動かす。", "error_description": "手段を表す「で」が正しい。「サーボに」では手段にならず、サーボを使って動かすという意味が伝わらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37760, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "模型の羽にサーボを取り組む。", "corrected_sentence": "模型の羽にサーボを取り付ける。", "error_description": "「サーボ」は「取り付ける」を使う。「取り組む」は課題や仕事に向かう意味で、部品には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37761, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「サーボが使われている」の主語を示す「が」。受け身文として自然。"}, {"text": "を", "is_correct": false, "explanation": "「サーボを使われている」は受け身の主語にならず、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「サーボへ使われている」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。「サーボと使われている」では主語が立たず不自然になる。"}], "correct_answer": "が", "explanations": {"が": "「サーボが使われている」の主語を示す「が」。受け身文として自然。", "を": "「サーボを使われている」は受け身の主語にならず、不自然になる。", "へ": "方向の「へ」。「サーボへ使われている」は文が成り立たない。", "と": "並列の「と」。「サーボと使われている」では主語が立たず不自然になる。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37761, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「サーボの調整」と名詞をつなぐ「の」。調整の対象がサーボだと示す。ここが正解。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」。「サーボで調整が悪く」は文の主語を示せず、成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所の「に」。「サーボに調整が悪く」は文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「サーボから調整が悪く」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「サーボの調整」と名詞をつなぐ「の」。調整の対象がサーボだと示す。ここが正解。", "で": "手段や場所の「で」。「サーボで調整が悪く」は文の主語を示せず、成り立たない。", "に": "相手や場所の「に」。「サーボに調整が悪く」は文が成り立たない。", "から": "起点の「から」。「サーボから調整が悪く」は意味が通らない。"}, "error_tags": {"で": "手段・場所", "に": "相手・場所", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37761, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "サーボ機構。命令どおりに位置や動きを自動で制御する装置。", "primary_collocate": null, "pronunciation": "さーぼ", "ipa": "saːbo", "syllable_count": 3, "sentences": [{"text": "サーボは指示された角度まで軸を回して止める。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "サーボは指示[しじ]された角度[かくど]まで軸[じく]を回[まわ]して止[と]める。", "sentence_source": "generated"}, {"text": "工場の機械には、位置を正確に決めるサーボが使われている。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "工場[こうじょう]の機械[きかい]には、位置[いち]を正確[せいかく]に決[き]めるサーボが使[つか]われている。", "sentence_source": "generated"}, {"text": "このサーボは、命令の信号が変わると回転角も変わる。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "このサーボは、命令[めいれい]の信号[しんごう]が変[か]わると回転角[かいてんかく]も変[か]わる。", "sentence_source": "generated"}, {"text": "サーボが動きを自動で直すので、ずれは小さい。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "サーボが動[うご]きを自動[じどう]で直[なお]すので、ずれは小[ちい]さい。", "sentence_source": "generated"}, {"text": "産業用ロボットでは、サーボの性能が精度を決める。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "産業用[さんぎょうよう]ロボットでは、サーボの性能[せいのう]が精度[せいど]を決[き]める。", "sentence_source": "generated"}, {"text": "設計者は、速さより正確さを優先してサーボを選んだ。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "設計者[せっけいしゃ]は、速[はや]さより正確[せいかく]さを優先[ゆうせん]してサーボを選[えら]んだ。", "sentence_source": "generated"}, {"text": "サーボに信号を送ると、アームが決まった位置へ動く。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "サーボに信号[しんごう]を送[おく]ると、アームが決[き]まった位置[いち]へ動[うご]く。", "sentence_source": "generated"}, {"text": "サーボの調整が悪く、機械が振動した。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "サーボの調整[ちょうせい]が悪[わる]く、機械[きかい]が振動[しんどう]した。", "sentence_source": "generated"}, {"text": "カメラの自動追尾にもサーボが使われている。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "カメラの自動[じどう]追尾[ついび]にもサーボが使[つか]われている。", "sentence_source": "generated"}, {"text": "実験では、サーボの反応の速さを測った。", "target_word": "サーボ", "complexity_tier": "T3", "furigana": "実験[じっけん]では、サーボの反応[はんのう]の速[はや]さを測[はか]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サーボ", "label": "基本形"}, {"form": "サーボの", "label": "の格"}], "register": "neutral", "sense_fingerprint": "位置や角度を自動で制御する工学上の装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba24b57-71af-43be-bb65-9109da6c8bd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37761, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サーボ", "is_correct": true, "explanation": "角度を指示して軸を回す制御装置で、「〇〇は指示された角度まで軸を回して止める」の主語になる。ここが正解。"}, {"text": "ダイオード", "is_correct": false, "explanation": "電流を一方向に流す部品で、角度を指示されて軸を回すことはない。"}, {"text": "コンデンサー", "is_correct": false, "explanation": "電気をためる部品で、軸を回す動きは持たない。文の主語として合わない。"}, {"text": "ヒューズ", "is_correct": false, "explanation": "過電流で切れる安全部品で、角度を指示されることはない。"}], "explanations": {"サーボ": "角度を指示して軸を回す制御装置で、「〇〇は指示された角度まで軸を回して止める」の主語になる。ここが正解。", "ダイオード": "電流を一方向に流す部品で、角度を指示されて軸を回すことはない。", "コンデンサー": "電気をためる部品で、軸を回す動きは持たない。文の主語として合わない。", "ヒューズ": "過電流で切れる安全部品で、角度を指示されることはない。"}, "sentence_index": 0, "correct_answer": "サーボ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "サーボを使って部屋の温度を測った。", "explanation": "ここは〈温度計〉の意味。サーボは角度や位置を制御する装置で、温度を測るのには使わない。"}, {"text": "寝坊しないように、サーボを枕元に置いた。", "explanation": "ここは〈目覚まし時計〉の意味。時刻を知らせる器具で、角度を動かすサーボとは違う。"}, {"text": "サーボを強く踏んだので、車は止まった。", "explanation": "ここは〈ブレーキ〉の意味。踏んで止めるのはブレーキで、サーボは踏む部品ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37761, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サーボ", "is_correct": true, "explanation": "信号を受けて角度を決める装置で、「に信号を送る」の相手になる。ここが正解。"}, {"text": "カーテン", "is_correct": false, "explanation": "布で光をさえぎる物で、信号を受けて動く装置ではない。"}, {"text": "ドーナツ", "is_correct": false, "explanation": "菓子の一つで、信号を受けることはない。文が成り立たない。"}, {"text": "メガネ", "is_correct": false, "explanation": "視力を補う道具で、信号の送り先にはならない。"}], "explanations": {"サーボ": "信号を受けて角度を決める装置で、「に信号を送る」の相手になる。ここが正解。", "カーテン": "布で光をさえぎる物で、信号を受けて動く装置ではない。", "ドーナツ": "菓子の一つで、信号を受けることはない。文が成り立たない。", "メガネ": "視力を補う道具で、信号の送り先にはならない。"}, "sentence_index": 6, "correct_answer": "サーボ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ロボットの電源としてサーボを積んだ。", "explanation": "ここは〈電池〉の意味。電源となる装置で、角度を制御する部品のサーボとは違う。"}, {"text": "回路を切り替えるためにサーボを入れた。", "explanation": "ここは〈スイッチ〉の意味。入れて回路を切り替える器具で、サーボは回路の切り替えに使わない。"}, {"text": "機械の頭脳となるサーボを交換した。", "explanation": "ここは〈基板〉の意味。回路を載せた板で、角度を動かすサーボとは別の部品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37761, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このアームは、サーボを角度を正確に決めている。", "corrected_sentence": "このアームは、サーボで角度を正確に決めている。", "error_description": "手段の「で」が正しい。「サーボを角度を」は目的語が二つ重なり、サーボが道具だと伝わらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37761, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "技術者は、サーボを細かく調律した。", "corrected_sentence": "技術者は、サーボを細かく調整した。", "error_description": "「サーボ」は「調整する」を使う。「調律」は楽器の音を整える意味で、機械の部品には使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37762, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。閉まる仕組みを対象として説明する「機構を説明した」となる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や対象を示すが、説明の対象を表す文では「機構を」が自然で、「機構に説明した」は成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、説明の対象は表せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、説明の対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "正解。閉まる仕組みを対象として説明する「機構を説明した」となる。", "に": "「に」は相手や対象を示すが、説明の対象を表す文では「機構を」が自然で、「機構に説明した」は成立しない。", "で": "「で」は手段や場所を示すので、説明の対象は表せない。", "と": "「と」は相手や並列を示すので、説明の対象には使えない。"}, "error_tags": {"に": "対象", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37762, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。仕組みが単純だという主語を示す「機構が単純なので」となる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、単純さの主語にはならない。「機構を単純なので」は成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象や結果を示すので、単純だと述べる主語には使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、単純だと述べる主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "正解。仕組みが単純だという主語を示す「機構が単純なので」となる。", "を": "「を」は目的語を示すが、単純さの主語にはならない。「機構を単純なので」は成立しない。", "に": "「に」は対象や結果を示すので、単純だと述べる主語には使えない。", "で": "「で」は手段や場所を示すので、単純だと述べる主語にはならない。"}, "error_tags": {"を": "目的語", "に": "対象", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37762, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "きこうは、ものをうごかすしくみのこと。", "primary_collocate": null, "pronunciation": "きこう", "ipa": "kikoː", "syllable_count": 3, "sentences": [{"text": "この時計は、歯車の機構が複雑で、修理が難しい。", "target_word": "機構", "complexity_tier": "T3", "furigana": "この時計[とけい]は、歯車[はぐるま]の機構[きこう]が複雑[ふくざつ]で、修理[しゅうり]が難[むずか]しい。", "sentence_source": "generated"}, {"text": "ドアが自動で閉まる機構を、図を見ながら説明した。", "target_word": "機構", "complexity_tier": "T3", "furigana": "ドアが自動[じどう]で閉[し]まる機構[きこう]を、図[ず]を見[み]ながら説明[せつめい]した。", "sentence_source": "generated"}, {"text": "安全のため、この機械には止める機構がついている。", "target_word": "機構", "complexity_tier": "T3", "furigana": "安全[あんぜん]のため、この機械[きかい]には止[と]める機構[きこう]がついている。", "sentence_source": "generated"}, {"text": "傘が開く機構を知りたくて、分解してみた。", "target_word": "機構", "complexity_tier": "T3", "furigana": "傘[かさ]が開[ひら]く機構[きこう]を知[し]りたくて、分解[ぶんかい]してみた。", "sentence_source": "generated"}, {"text": "おもちゃの動く機構は、ばねと歯車だけでできている。", "target_word": "機構", "complexity_tier": "T3", "furigana": "おもちゃの動[うご]く機構[きこう]は、ばねと歯車[はぐるま]だけでできている。", "sentence_source": "generated"}, {"text": "カメラのシャッターの機構は、小さな部品の組み合わせだ。", "target_word": "機構", "complexity_tier": "T3", "furigana": "カメラのシャッターの機構[きこう]は、小[ちい]さな部品[ぶひん]の組[く]み合[あ]わせだ。", "sentence_source": "generated"}, {"text": "椅子の高さを変える機構が壊れて、座面が下がってしまった。", "target_word": "機構", "complexity_tier": "T3", "furigana": "椅子[いす]の高[たか]さを変[か]える機構[きこう]が壊[こわ]れて、座面[ざめん]が下[さ]がってしまった。", "sentence_source": "generated"}, {"text": "ロックの機構が単純なので、この鍵は壊れにくい。", "target_word": "機構", "complexity_tier": "T3", "furigana": "ロックの機構[きこう]が単純[たんじゅん]なので、この鍵[かぎ]は壊[こわ]れにくい。", "sentence_source": "generated"}, {"text": "昔のからくり人形には、巧みな機構が隠されていた。", "target_word": "機構", "complexity_tier": "T3", "furigana": "昔[むかし]のからくり人形[にんぎょう]には、巧[たく]みな機構[きこう]が隠[かく]されていた。", "sentence_source": "generated"}, {"text": "自転車のブレーキの機構を学んで、自分で直した。", "target_word": "機構", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]のブレーキの機構[きこう]を学[まな]んで、自分[じぶん]で直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "機構", "label": "base form"}, {"form": "機構が", "label": "subject"}, {"form": "機構を", "label": "object"}, {"form": "機構の", "label": "attributive"}], "register": "neutral", "sense_fingerprint": "歯車やばねなどで物を動かす、機械の中の具体的な仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e61789a-9eca-468c-8b66-53ec4aea85ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37762, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "機構", "is_correct": true, "explanation": "正解。歯車の仕組みが複雑で修理が難しい、という意味を表す。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電気を蓄える装置。歯車の仕組みを指す文には合わない。"}, {"text": "味覚", "is_correct": false, "explanation": "味覚は味を感じる感覚。時計の歯車の文には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は気象の状態。時計の歯車の文では意味が通らない。"}], "explanations": {"機構": "正解。歯車の仕組みが複雑で修理が難しい、という意味を表す。", "電池": "電池は電気を蓄える装置。歯車の仕組みを指す文には合わない。", "味覚": "味覚は味を感じる感覚。時計の歯車の文には合わない。", "天気": "天気は気象の状態。時計の歯車の文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "機構"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市の機構が複雑なので、手続きの窓口が分かりにくい。", "explanation": "ここは〈組織・制度〉の意味。役所の仕組みを指すので、機械の仕組みを表す文ではない。"}, {"text": "政府の機構を見直して、無駄な部署を減らす。", "explanation": "ここは〈組織・制度〉の意味。行政の仕組みを改める文で、機械の仕組みではない。"}, {"text": "銀行の機構を改めた結果、支店の数が半分になった。", "explanation": "ここは〈組織・制度〉の意味。銀行の運営の仕組みを指し、機械の仕組みではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37762, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "機構", "is_correct": true, "explanation": "正解。椅子の高さを変える仕組みが壊れた、という意味を表す。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は敷いて座る布製品。高さを変える仕組みとは結びつかない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上面。椅子の高さを変える文とは合わない。"}, {"text": "窓ガラス", "is_correct": false, "explanation": "窓ガラスは窓の部品。椅子の高さを変える文では意味が通らない。"}], "explanations": {"機構": "正解。椅子の高さを変える仕組みが壊れた、という意味を表す。", "座布団": "座布団は敷いて座る布製品。高さを変える仕組みとは結びつかない。", "天井": "天井は部屋の上面。椅子の高さを変える文とは合わない。", "窓ガラス": "窓ガラスは窓の部品。椅子の高さを変える文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "機構"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い官僚の機構を変えない限り、改革は進まない。", "explanation": "ここは〈組織・制度〉の意味。官僚組織の仕組みを指し、機械の仕組みではない。"}, {"text": "この会社の機構では、問題が起きたら、まず担当者が上司に報告する。", "explanation": "ここは〈組織・制度〉の意味。会社の報告の仕組みを指し、機械の仕組みではない。"}, {"text": "学校の機構を整えて、先生の負担を軽くした。", "explanation": "ここは〈組織・制度〉の意味。学校の運営の仕組みを指し、機械の仕組みではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37762, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボタンを押すと、扉を閉める機構を動き出す。", "corrected_sentence": "ボタンを押すと、扉を閉める機構が動き出す。", "error_description": "「機構を」の「を」が誤りで「機構が」が正しい。「動き出す」の主語は機構なので「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37762, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このロボットの関節には、小さな機構を組み込まれている。", "corrected_sentence": "このロボットの関節には、小さな機構が組み込まれている。", "error_description": "「機構を組み込まれている」の「を」が誤りで「機構が組み込まれている」が正しい。「組み込まれている」は受け身なので、動作を受ける主語「機構」に「が」を付ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37764, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段（センサーによって）を表し、人を見つける方法として合う。"}, {"text": "を", "is_correct": false, "explanation": "「見つける」の目的語は「人」なので、「センサーを」は二重になり不自然。"}, {"text": "の", "is_correct": false, "explanation": "名詞同士をつなぐ助詞で、動詞の手段にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、見つける手段には合わない。"}], "correct_answer": "で", "explanations": {"で": "手段（センサーによって）を表し、人を見つける方法として合う。", "を": "「見つける」の目的語は「人」なので、「センサーを」は二重になり不自然。", "の": "名詞同士をつなぐ助詞で、動詞の手段にはならない。", "へ": "方向を表すが、見つける手段には合わない。"}, "error_tags": {"を": "対象の格", "の": "名詞修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
