INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37764, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものを感じたり、見つけたりする機械の部品です。", "primary_collocate": null, "pronunciation": "せんさー", "ipa": "seɴsaː", "syllable_count": 4, "sentences": [{"text": "暗くなると、センサーが反応して、ライトがつきます。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "暗[くら]くなると、センサーが反応[はんのう]して、ライトがつきます。", "sentence_source": "generated"}, {"text": "このドアはセンサーで人を見つけて、自動で開きます。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "このドアはセンサーで人[ひと]を見[み]つけて、自動[じどう]で開[あ]きます。", "sentence_source": "generated"}, {"text": "センサーがよごれていて、うまく動きません。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "センサーがよごれていて、うまく動[うご]きません。", "sentence_source": "generated"}, {"text": "車の後ろにセンサーがあって、近づくと音が鳴ります。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "車[くるま]の後[うし]ろにセンサーがあって、近[ちか]づくと音[おと]が鳴[な]ります。", "sentence_source": "generated"}, {"text": "蛇口のセンサーに手を近づけると、水が出ます。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "蛇口[じゃぐち]のセンサーに手[て]を近[ちか]づけると、水[みず]が出[で]ます。", "sentence_source": "generated"}, {"text": "電池が切れて、センサーが働かなくなりました。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "電池[でんち]が切[き]れて、センサーが働[はたら]かなくなりました。", "sentence_source": "generated"}, {"text": "部屋の温度を知るために、小さなセンサーをつけました。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "部屋[へや]の温度[おんど]を知[し]るために、小[ちい]さなセンサーをつけました。", "sentence_source": "generated"}, {"text": "犬が通ると、庭のセンサーが光ります。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "犬[いぬ]が通[とお]ると、庭[にわ]のセンサーが光[ひか]ります。", "sentence_source": "generated"}, {"text": "このカメラには、明るさを調べるセンサーが入っています。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "このカメラには、明[あか]るさを調[しら]べるセンサーが入[はい]っています。", "sentence_source": "generated"}, {"text": "センサーのおかげで、夜でも階段が安全です。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "センサーのおかげで、夜[よる]でも階段[かいだん]が安全[あんぜん]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "センサー", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "光・人・温度などを感じ取る機械の部品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37764, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "センサー", "is_correct": true, "explanation": "暗さを感じて反応する機械の部品として合う。"}, {"text": "切符", "is_correct": false, "explanation": "紙の券で、暗さに反応するものではない。"}, {"text": "季節", "is_correct": false, "explanation": "反応してライトをつける主体にはならない。"}, {"text": "階段", "is_correct": false, "explanation": "場所であり、反応する機械の部品ではない。"}], "explanations": {"センサー": "暗さを感じて反応する機械の部品として合う。", "切符": "紙の券で、暗さに反応するものではない。", "季節": "反応してライトをつける主体にはならない。", "階段": "場所であり、反応する機械の部品ではない。"}, "sentence_index": 0, "correct_answer": "センサー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町の子育てセンサーでは、毎週おもちゃを貸し出している。", "explanation": "ここは〈センター〉（施設）の意味。センサーは感知する部品なので、施設の名前としては合わない。"}, {"text": "彼女は色のセンサーがよく、服の組み合わせを考えるのが上手だ。", "explanation": "ここは〈センス〉（感覚や好み）の意味。センサーは機械の感知部品なので、人の感覚には使わない。"}, {"text": "交差点のセンサーが赤になったので、車がいっせいに止まった。", "explanation": "ここは〈信号〉の意味。センサーは感じ取る部品で、色を変えて車を止めるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37764, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "センサー", "is_correct": true, "explanation": "温度を感じ取る小さな機械の部品として、取り付けることに合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品で、温度を知るために取り付けるものではない。"}, {"text": "靴", "is_correct": false, "explanation": "身につけるもので、温度を知るために取り付けない。"}, {"text": "花びん", "is_correct": false, "explanation": "容器で、温度を知るために取り付けるものではない。"}], "explanations": {"センサー": "温度を感じ取る小さな機械の部品として、取り付けることに合う。", "砂糖": "食品で、温度を知るために取り付けるものではない。", "靴": "身につけるもので、温度を知るために取り付けない。", "花びん": "容器で、温度を知るために取り付けるものではない。"}, "sentence_index": 6, "correct_answer": "センサー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝る前に音楽を聴くため、部屋の隅にセンサーを置いた。", "explanation": "ここは〈スピーカー〉（音を出す機器）の意味。センサーは感知する部品で、音を出すものではない。"}, {"text": "毎朝、家の前のセンサーに手紙を入れて出します。", "explanation": "ここは〈ポスト〉（郵便受け）の意味。センサーは感知する部品なので、手紙を入れる箱としては合わない。"}, {"text": "毎朝、センサーを見て時間を確かめる。", "explanation": "ここは〈時計〉の意味。センサーは感知する部品で、時刻を示す器具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37764, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアのセンサーに壊れて、開きません。", "corrected_sentence": "ドアのセンサーが壊れて、開きません。", "error_description": "「壊れる」は自動詞で、主語は「が」で示す。「センサーに」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37764, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "センサーが反応しないかったので、ライトはつきませんでした。", "corrected_sentence": "センサーが反応しなかったので、ライトはつきませんでした。", "error_description": "「反応しない」の過去形は「反応しなかった」。「ないかった」は活用の誤りで、正しくは「なかった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
