INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37768, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "飛行機の翼が空気とぶつかる角度のこと。", "primary_collocate": null, "pronunciation": "むかえかく", "ipa": "mɯkaekakɯ", "syllable_count": 5, "sentences": [{"text": "翼の迎え角が大きすぎると、空気がうまく流れなくなる。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "翼[つばさ]の迎え角[むかえかく]が大[おお]きすぎると、空気[くうき]がうまく流[なが]れなくなる。", "sentence_source": "generated"}, {"text": "飛行機が上昇するときは、迎え角を少し大きくする。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が上昇[じょうしょう]するときは、迎え角[むかえかく]を少[すこ]し大[おお]きくする。", "sentence_source": "generated"}, {"text": "パイロットは迎え角を見ながら、機体の向きを調整した。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "パイロットは迎え角[むかえかく]を見[み]ながら、機体[きたい]の向[む]きを調整[ちょうせい]した。", "sentence_source": "generated"}, {"text": "迎え角が小さいので、風が翼にあまり当たらない。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "迎え角[むかえかく]が小[ちい]さいので、風[かぜ]が翼[つばさ]にあまり当[あ]たらない。", "sentence_source": "generated"}, {"text": "紙飛行機の迎え角を変えたら、飛び方がまったく違った。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "紙飛行機[かみひこうき]の迎え角[むかえかく]を変[か]えたら、飛[と]び方[かた]がまったく違[ちが]った。", "sentence_source": "generated"}, {"text": "迎え角を上げすぎて、飛行機が失速してしまった。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "迎え角[むかえかく]を上[あ]げすぎて、飛行機[ひこうき]が失速[しっそく]してしまった。", "sentence_source": "generated"}, {"text": "迎え角が適切かどうかは、飛行機の安全に関わる。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "迎え角[むかえかく]が適切[てきせつ]かどうかは、飛行機[ひこうき]の安全[あんぜん]に関[かか]わる。", "sentence_source": "generated"}, {"text": "風洞実験で、いろいろな迎え角のときの空気の流れを調べた。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "風洞[ふうどう]実験[じっけん]で、いろいろな迎え角[むかえかく]のときの空気[くうき]の流[なが]れを調[しら]べた。", "sentence_source": "generated"}, {"text": "着陸のとき、迎え角が合っていないと危ない。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "着陸[ちゃくりく]のとき、迎え角[むかえかく]が合[あ]っていないと危[あぶ]ない。", "sentence_source": "generated"}, {"text": "先生は黒板に翼の絵を描いて、迎え角を説明した。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に翼[つばさ]の絵[え]を描[か]いて、迎え角[むかえかく]を説明[せつめい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎え角", "label": "基本形"}], "register": "technical", "sense_fingerprint": "翼に空気が当たる角度（航空の専門用語）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 風洞 (Zipf 2.0)']::text[], '0e61789a-9eca-468c-8b66-53ec4aea85ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37768, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迎え角", "is_correct": true, "explanation": "翼と空気の角度を指す語。「翼の迎え角が大きすぎる」で主語の一部として文に合う。"}, {"text": "滑走路", "is_correct": false, "explanation": "「翼の滑走路が大きすぎる」は意味をなさず、空気の流れの説明にならない。"}, {"text": "燃料", "is_correct": false, "explanation": "「翼の燃料が大きすぎる」は意味をなさず、空気の流れとは関係がない。"}, {"text": "車輪", "is_correct": false, "explanation": "「翼の車輪が大きすぎる」は不自然で、空気の流れの説明にならない。"}], "explanations": {"迎え角": "翼と空気の角度を指す語。「翼の迎え角が大きすぎる」で主語の一部として文に合う。", "滑走路": "「翼の滑走路が大きすぎる」は意味をなさず、空気の流れの説明にならない。", "燃料": "「翼の燃料が大きすぎる」は意味をなさず、空気の流れとは関係がない。", "車輪": "「翼の車輪が大きすぎる」は不自然で、空気の流れの説明にならない。"}, "sentence_index": 0, "correct_answer": "迎え角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "望遠鏡で星の迎え角を測った。", "explanation": "ここは〈仰角〉の意味。空を見上げる角度は仰角で、迎え角は翼と空気の角度なので合わない。"}, {"text": "この机の迎え角を変えると、書きやすくなる。", "explanation": "ここは〈角度〉の意味。机の傾きは一般の角度で表し、迎え角は翼に当たる空気の角度を指すので合わない。"}, {"text": "屋根の迎え角が急だと、雪が落ちやすい。", "explanation": "ここは〈傾斜角〉の意味。屋根の傾きは傾斜角で、迎え角は翼に当たる空気の角度なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37768, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎え角", "is_correct": true, "explanation": "「迎え角が適切かどうかは、飛行機の安全に関わる」の主語。翼の角度として文に合う。"}, {"text": "絵葉書", "is_correct": false, "explanation": "絵葉書の適切さは飛行機の安全とは関わらず、この文の主語として意味をなさない。"}, {"text": "参考書", "is_correct": false, "explanation": "参考書の適切さは飛行機の安全に関わらず、この文では主語として成り立たない。"}, {"text": "観光地", "is_correct": false, "explanation": "観光地は飛行機の安全に関わる対象ではないので、この文には入らない。"}], "explanations": {"迎え角": "「迎え角が適切かどうかは、飛行機の安全に関わる」の主語。翼の角度として文に合う。", "絵葉書": "絵葉書の適切さは飛行機の安全とは関わらず、この文の主語として意味をなさない。", "参考書": "参考書の適切さは飛行機の安全に関わらず、この文では主語として成り立たない。", "観光地": "観光地は飛行機の安全に関わる対象ではないので、この文には入らない。"}, "sentence_index": 6, "correct_answer": "迎え角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "光が鏡に当たる迎え角と反射角は等しい。", "explanation": "ここは〈入射角〉の意味。光が当たる角度は入射角で、迎え角は翼と空気の角度なので合わない。"}, {"text": "この坂は迎え角がきつくて、自転車では上れない。", "explanation": "ここは〈勾配〉の意味。坂の傾きは勾配で、迎え角は翼に当たる空気の角度を指すので合わない。"}, {"text": "地図で目的地の迎え角を調べた。", "explanation": "ここは〈方位角〉の意味。北から見た方向は方位角で、迎え角は翼の角度なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37768, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "離陸のとき、迎え角が少しずつ上げていく。", "corrected_sentence": "離陸のとき、迎え角を少しずつ上げていく。", "error_description": "「上げる」は他動詞なので、目的語の「を」が必要。「が」では文が成り立たないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37768, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "機体は迎え角を焼いたまま、水平に飛ぶ。", "corrected_sentence": "機体は迎え角を保ったまま、水平に飛ぶ。", "error_description": "「迎え角」は保つ、調整するもの。「焼く」は加熱の動作で、迎え角とは組み合わないので誤り。正しくは「保った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
