INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37769, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "飛行機の主翼が進行方向に対してなす角度。揚力の大きさに影響する。", "primary_collocate": null, "pronunciation": "むかえかく", "ipa": "mɯkaekakɯ", "syllable_count": 5, "sentences": [{"text": "主翼の迎え角を大きくすると、揚力も大きくなる。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "主翼[しゅよく]の迎え角[むかえかく]を大[おお]きくすると、揚力[ようりょく]も大[おお]きくなる。", "sentence_source": "generated"}, {"text": "離陸の直前に、機体は迎え角を上げて空に浮かび上がった。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "離陸[りりく]の直前[ちょくぜん]に、機体[きたい]は迎え角[むかえかく]を上[あ]げて空[そら]に浮[う]かび上[あ]がった。", "sentence_source": "generated"}, {"text": "迎え角が大きすぎると、揚力が急に減ってしまう。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "迎え角[むかえかく]が大[おお]きすぎると、揚力[ようりょく]が急[きゅう]に減[へ]ってしまう。", "sentence_source": "generated"}, {"text": "旅客機は巡航中、迎え角をほとんど変えずに飛ぶ。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "旅客機[りょかくき]は巡航中[じゅんこうちゅう]、迎え角[むかえかく]をほとんど変[か]えずに飛[と]ぶ。", "sentence_source": "generated"}, {"text": "進行方向と翼の線がつくる迎え角を、図で確認した。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "進行[しんこう]方向[ほうこう]と翼[つばさ]の線[せん]がつくる迎え角[むかえかく]を、図[ず]で確認[かくにん]した。", "sentence_source": "generated"}, {"text": "鳥も迎え角を変えて、揚力の大きさを調節している。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "鳥[とり]も迎え角[むかえかく]を変[か]えて、揚力[ようりょく]の大[おお]きさを調節[ちょうせつ]している。", "sentence_source": "generated"}, {"text": "迎え角の違いで、揚力がどれだけ変わるか実験した。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "迎え角[むかえかく]の違[ちが]いで、揚力[ようりょく]がどれだけ変[か]わるか実験[じっけん]した。", "sentence_source": "generated"}, {"text": "低い速度で飛ぶときは、迎え角を大きめにして揚力を得る。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "低[ひく]い速度[そくど]で飛[と]ぶときは、迎え角[むかえかく]を大[おお]きめにして揚力[ようりょく]を得[え]る。", "sentence_source": "generated"}, {"text": "操縦席の計器には、迎え角を示す表示がある。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "操縦席[そうじゅうせき]の計器[けいき]には、迎え角[むかえかく]を示[しめ]す表示[ひょうじ]がある。", "sentence_source": "generated"}, {"text": "この模型は迎え角を調整できるので、揚力の変化を見られる。", "target_word": "迎え角", "complexity_tier": "T3", "furigana": "この模型[もけい]は迎え角[むかえかく]を調整[ちょうせい]できるので、揚力[ようりょく]の変化[へんか]を見[み]られる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎え角", "label": "基本形"}], "register": "technical", "sense_fingerprint": "主翼と進行方向のなす角度で、揚力の大きさを左右するもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 揚力 (Zipf 2.33)','sentence 2 above tier T2: contains vocabulary far above tier T2: 揚力 (Zipf 2.33)','sentence 5 above tier T2: contains vocabulary far above tier T2: 揚力 (Zipf 2.33)','sentence 6 above tier T2: contains vocabulary far above tier T2: 揚力 (Zipf 2.33)','sentence 7 above tier T2: contains vocabulary far above tier T2: 揚力 (Zipf 2.33)','sentence 9 above tier T2: contains vocabulary far above tier T2: 揚力 (Zipf 2.33)']::text[], '0e61789a-9eca-468c-8b66-53ec4aea85ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37769, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迎え角", "is_correct": true, "explanation": "主翼と進行方向のなす角度を表す語で、揚力を大きくする文の対象として入る。"}, {"text": "燃料", "is_correct": false, "explanation": "燃料は機体の燃料タンクの中身で角度ではないため、「主翼の燃料を大きくする」は成り立たない。"}, {"text": "車輪", "is_correct": false, "explanation": "車輪は離着陸の脚に付く部品で、主翼の角度を指さないので、この文では意味をなさない。"}, {"text": "機首", "is_correct": false, "explanation": "機首は機体の先端を指す語で、主翼の角度を変えるという文の対象にはならない。"}], "explanations": {"迎え角": "主翼と進行方向のなす角度を表す語で、揚力を大きくする文の対象として入る。", "燃料": "燃料は機体の燃料タンクの中身で角度ではないため、「主翼の燃料を大きくする」は成り立たない。", "車輪": "車輪は離着陸の脚に付く部品で、主翼の角度を指さないので、この文では意味をなさない。", "機首": "機首は機体の先端を指す語で、主翼の角度を変えるという文の対象にはならない。"}, "sentence_index": 0, "correct_answer": "迎え角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "次の迎え角を左に曲がると、駅が見えてくる。", "explanation": "ここは〈曲がり角〉の意味。迎え角は主翼と進行方向の角度なので、道の角は指せない。"}, {"text": "屋根の迎え角を大きくして、雨水を流れやすくした。", "explanation": "ここは〈傾斜角〉の意味。迎え角は翼と進行方向の角度で、屋根の傾きには使わない。"}, {"text": "星を見上げて、その迎え角を測った。", "explanation": "ここは〈仰角〉の意味。見上げて測る角度は仰角で、迎え角は翼の角度を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37769, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎え角", "is_correct": true, "explanation": "主翼と進行方向の角度の違いで揚力がどう変わるかを調べる文なので、この語が入る。"}, {"text": "座席", "is_correct": false, "explanation": "座席は乗客が座る場所で、角度の違いで揚力が変わるという文の対象にはならない。"}, {"text": "客室", "is_correct": false, "explanation": "客室は乗客のための空間の名称で、揚力の比較対象として「客室の違い」は成り立たない。"}, {"text": "滑走路", "is_correct": false, "explanation": "滑走路は離着陸に使う路面で、揚力の変化を比べる対象にはならない。"}], "explanations": {"迎え角": "主翼と進行方向の角度の違いで揚力がどう変わるかを調べる文なので、この語が入る。", "座席": "座席は乗客が座る場所で、角度の違いで揚力が変わるという文の対象にはならない。", "客室": "客室は乗客のための空間の名称で、揚力の比較対象として「客室の違い」は成り立たない。", "滑走路": "滑走路は離着陸に使う路面で、揚力の変化を比べる対象にはならない。"}, "sentence_index": 6, "correct_answer": "迎え角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この坂は迎え角が急で、自転車では上がれない。", "explanation": "ここは〈勾配〉の意味。坂の傾きを指す語で、迎え角は翼と進行方向の角度なので坂には使わない。"}, {"text": "空港の迎え角には、大勢の人が来ていた。", "explanation": "ここは〈出迎え〉の意味。人を迎えることを指す語で、迎え角は翼の角度を表すので合わない。"}, {"text": "鏡に当たる光の迎え角を測った。", "explanation": "ここは〈入射角〉の意味。光が面に当たる角度を指す語で、迎え角は翼の角度なので使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37769, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "機長は着陸の前に、迎え角が少し下げる指示を出した。", "corrected_sentence": "機長は着陸の前に、迎え角を少し下げる指示を出した。", "error_description": "「下げる」の目的語は「迎え角を」。「が」を使うと主語のように読まれてしまうため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37769, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "巡航中は、迎え角を小さく保ると燃費がよくなる。", "corrected_sentence": "巡航中は、迎え角を小さく保つと燃費がよくなる。", "error_description": "「保つ」の条件形は「保つと」。「保ると」は誤った活用で、正しくは「保つと」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37770, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「乗る」の乗り込む先を示す格助詞で、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語になるので、「乗る」の場所を示す形にはならない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「乗る」の場所にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「乗る」の乗り込む先にはならない。"}], "correct_answer": "に", "explanations": {"に": "「乗る」の乗り込む先を示す格助詞で、ここに入る。", "を": "「を」は目的語になるので、「乗る」の場所を示す形にはならない。", "が": "「が」は主語を示すので、「乗る」の場所にはならない。", "で": "「で」は手段や場所を示すので、「乗る」の乗り込む先にはならない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
