INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37770, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が乗る箱で、ボタンを押すと上の階や下の階に動く乗り物です。", "primary_collocate": null, "pronunciation": "えれべーたー", "ipa": "eɾebeːtaː", "syllable_count": 6, "sentences": [{"text": "ボタンを押して、エレベーターが来るのを待った。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "ボタンを押[お]して、エレベーターが来[く]るのを待[ま]った。", "sentence_source": "generated"}, {"text": "エレベーターに乗って、五階で降りた。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "エレベーターに乗[の]って、五階[ごかい]で降[お]りた。", "sentence_source": "generated"}, {"text": "階段は疲れるので、エレベーターで上がりましょう。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "階段[かいだん]は疲[つか]れるので、エレベーターで上[あ]がりましょう。", "sentence_source": "generated"}, {"text": "エレベーターの中は、朝は人が多くてせまい。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "エレベーターの中[なか]は、朝[あさ]は人[ひと]が多[おお]くてせまい。", "sentence_source": "generated"}, {"text": "子どもがエレベーターのボタンを押したがる。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "子[こ]どもがエレベーターのボタンを押[お]したがる。", "sentence_source": "generated"}, {"text": "故障中でエレベーターが使えず、階段で行った。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "故障中[こしょうちゅう]でエレベーターが使[つか]えず、階段[かいだん]で行[い]った。", "sentence_source": "generated"}, {"text": "エレベーターのドアが開いて、友達が出てきた。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "エレベーターのドアが開[ひら]いて、友達[ともだち]が出[で]てきた。", "sentence_source": "generated"}, {"text": "十階まで行くエレベーターは、右側にあります。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "十階[じっかい]まで行[い]くエレベーターは、右側[みぎがわ]にあります。", "sentence_source": "generated"}, {"text": "満員のエレベーターには、次の人は乗れない。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "満員[まんいん]のエレベーターには、次[つぎ]の人[ひと]は乗[の]れない。", "sentence_source": "generated"}, {"text": "エレベーターで知り合いに会って、あいさつした。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "エレベーターで知[し]り合[あ]いに会[あ]って、あいさつした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エレベーター", "label": "base"}], "register": "中立", "sense_fingerprint": "人が乗ってボタンで階を移動する箱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37770, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エレベーター", "is_correct": true, "explanation": "ボタンで階を移動する箱の意味で、来るのを待つ対象に合う。"}, {"text": "階段", "is_correct": false, "explanation": "歩いて上がる段で、ボタンを押して来るものではないので合わない。"}, {"text": "非常口", "is_correct": false, "explanation": "出口を指す場所で、ボタンを押して来るものではないので合わない。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の入口で、ボタンを押して来るものではないので合わない。"}], "explanations": {"エレベーター": "ボタンで階を移動する箱の意味で、来るのを待つ対象に合う。", "階段": "歩いて上がる段で、ボタンを押して来るものではないので合わない。", "非常口": "出口を指す場所で、ボタンを押して来るものではないので合わない。", "玄関": "建物の入口で、ボタンを押して来るものではないので合わない。"}, "sentence_index": 0, "correct_answer": "エレベーター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エレベーターの段は、乗るとゆっくり動き出す。", "explanation": "ここは〈エスカレーター〉の意味。段がある動く階段はエスカレーターで、箱に乗って上下する乗り物のエレベーターとは合わない。"}, {"text": "エレベーターで一段ずつ登ってから、また降りた。", "explanation": "ここは〈階段〉の意味。一段ずつ登るのは階段の話で、箱に乗って上下する乗り物のエレベーターには合わない。"}, {"text": "エレベーターの傾斜がゆるいので、車いすでも上りやすい。", "explanation": "ここは〈スロープ〉の意味。傾斜は坂道の性質を指すので、箱に乗って上下する乗り物のエレベーターには当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37770, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エレベーター", "is_correct": true, "explanation": "ドアが開いて人が出てくる箱で、人を乗せて運ぶものに合う。"}, {"text": "金庫", "is_correct": false, "explanation": "ドアはあるが、人が入る大きさではないので合わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "ドアはあるが、人が入る箱ではないので合わない。"}, {"text": "郵便ポスト", "is_correct": false, "explanation": "ドアで開くが、人が入る箱ではないので合わない。"}], "explanations": {"エレベーター": "ドアが開いて人が出てくる箱で、人を乗せて運ぶものに合う。", "金庫": "ドアはあるが、人が入る大きさではないので合わない。", "洗濯機": "ドアはあるが、人が入る箱ではないので合わない。", "郵便ポスト": "ドアで開くが、人が入る箱ではないので合わない。"}, "sentence_index": 6, "correct_answer": "エレベーター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "エレベーターの線路は、急な坂に沿って山の上まで続いている。", "explanation": "ここは〈ケーブルカー〉の意味。線路の上を坂に沿って走る乗り物で、建物の中の箱には合わない。"}, {"text": "エレベーターのアームが大きく旋回して、鉄骨を運んだ。", "explanation": "ここは〈クレーン〉の意味。アームで吊り上げて旋回する装置で、建物の中を上下に運ぶ箱のエレベーターには当てはまらない。"}, {"text": "エレベーターのベルトが切れて、工場の作業が止まった。", "explanation": "ここは〈ベルトコンベヤー〉の意味。ベルトで流れ作業をする装置で、人や荷物を乗せて上下に運ぶ箱には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37770, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "五階の会議室へ、エレベーターを行った。", "corrected_sentence": "五階の会議室へ、エレベーターで行った。", "error_description": "手段を示す「で」が正しい。「エレベーターを行った」は目的語の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37770, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いエレベーターを、もう動かない。", "corrected_sentence": "古いエレベーターは、もう動かない。", "error_description": "「動く」は主語を「が」か「は」で示す自動詞なので、「エレベーターを」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
