INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37771, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物の中で、人や荷物を上下に運ぶための機械の箱。", "primary_collocate": null, "pronunciation": "えれべーたー", "ipa": "eɾebeːtaː", "syllable_count": 6, "sentences": [{"text": "このビルの大型エレベーターは、荷物も運べる。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "このビルの大型[おおがた]エレベーターは、荷物[にもつ]も運[はこ]べる。", "sentence_source": "generated"}, {"text": "引っ越しの日は、エレベーターで家具を上の階に運んだ。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]は、エレベーターで家具[かぐ]を上[うえ]の階[かい]に運[はこ]んだ。", "sentence_source": "generated"}, {"text": "病院のエレベーターは、ベッドごと乗れる大きさだ。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "病院[びょういん]のエレベーターは、ベッドごと乗[の]れる大[おお]きさだ。", "sentence_source": "generated"}, {"text": "古い建物にエレベーターを付ける工事が始まった。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]にエレベーターを付[つ]ける工事[こうじ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "エレベーターの定員は十人までと決められている。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "エレベーターの定員[ていいん]は十人[じゅうにん]までと決[き]められている。", "sentence_source": "generated"}, {"text": "荷物用エレベーターは、お客さんは使えません。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "荷物用[にもつよう]エレベーターは、お客[きゃく]さんは使[つか]えません。", "sentence_source": "generated"}, {"text": "停電のとき、エレベーターが止まって人が閉じこめられた。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "停電[ていでん]のとき、エレベーターが止[と]まって人[ひと]が閉[と]じこめられた。", "sentence_source": "generated"}, {"text": "工場では、重い部品をエレベーターで二階に上げる。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、重[おも]い部品[ぶひん]をエレベーターで二階[にかい]に上[あ]げる。", "sentence_source": "generated"}, {"text": "毎年、エレベーターの安全検査が行われる。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "毎年[まいとし]、エレベーターの安全[あんぜん]検査[けんさ]が行[おこな]われる。", "sentence_source": "generated"}, {"text": "車いすの人のために、駅にエレベーターが作られた。", "target_word": "エレベーター", "complexity_tier": "T3", "furigana": "車[くるま]いすの人[ひと]のために、駅[えき]にエレベーターが作[つく]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エレベーター", "label": "base"}], "register": "中立", "sense_fingerprint": "建物で人や荷物を上下に運ぶ機械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37771, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エレベーター", "is_correct": true, "explanation": "建物で荷物も運ぶ機械の箱なので、「荷物も運べる」に合う。"}, {"text": "照明", "is_correct": false, "explanation": "光を出す器具で、荷物を運べないので合わない。"}, {"text": "シャッター", "is_correct": false, "explanation": "開閉する扉で、荷物を運べないので合わない。"}, {"text": "掲示板", "is_correct": false, "explanation": "情報を表示するもので、荷物を運べないので合わない。"}], "explanations": {"エレベーター": "建物で荷物も運ぶ機械の箱なので、「荷物も運べる」に合う。", "照明": "光を出す器具で、荷物を運べないので合わない。", "シャッター": "開閉する扉で、荷物を運べないので合わない。", "掲示板": "情報を表示するもので、荷物を運べないので合わない。"}, "sentence_index": 0, "correct_answer": "エレベーター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エレベーターの一段目でつまずいて、ひざを打った。", "explanation": "ここは〈階段〉の意味。一段目は階段の段を指すので、人や荷物を上下に運ぶ機械の箱には当てはまらない。"}, {"text": "エレベーターの坂は急で、車いすの人は一人では上がれない。", "explanation": "ここは〈スロープ〉の意味。坂は傾斜の道を指すので、人や荷物を上下に運ぶ機械の箱には合わない。"}, {"text": "エレベーターに乗って、雪山の頂上まで空中を渡った。", "explanation": "ここは〈ロープウェイ〉の意味。空中を索道で渡る乗り物で、建物の中で人や荷物を上下に運ぶ箱には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37771, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エレベーター", "is_correct": true, "explanation": "建物で人を運ぶ機械で、停電時に止まって人が閉じこめられる話に合う。"}, {"text": "扇風機", "is_correct": false, "explanation": "止まっても人が閉じこめられる仕組みではないので合わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "人が閉じこめられる大きさの箱ではないので合わない。"}, {"text": "水道", "is_correct": false, "explanation": "水を送る設備で、人が閉じこめられるものではないので合わない。"}], "explanations": {"エレベーター": "建物で人を運ぶ機械で、停電時に止まって人が閉じこめられる話に合う。", "扇風機": "止まっても人が閉じこめられる仕組みではないので合わない。", "洗濯機": "人が閉じこめられる大きさの箱ではないので合わない。", "水道": "水を送る設備で、人が閉じこめられるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "エレベーター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "エレベーターは、重い荷物を倉庫の床の上を転がして運ぶ。", "explanation": "ここは〈台車〉の意味。床の上を転がして運ぶ道具で、上下に動く箱のエレベーターとは合わない。"}, {"text": "エレベーターが空を飛んで、屋上へ荷物を届けた。", "explanation": "ここは〈ドローン〉の意味。空を飛んで荷物を届けるのは飛行機械で、建物の中を上下に運ぶ箱には合わない。"}, {"text": "エレベーターのフォークで、パレットを倉庫の通路まで運んだ。", "explanation": "ここは〈フォークリフト〉の意味。フォークで荷物を持ち上げて平面を運ぶ車両で、上下に動く箱のエレベーターには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37771, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "倉庫の荷物は、エレベーターを三階へ運ばれる。", "corrected_sentence": "倉庫の荷物は、エレベーターで三階へ運ばれる。", "error_description": "手段を示す「で」が正しい。「エレベーターを」は目的語の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37771, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工事のあいだ、エレベーターを止まっていた。", "corrected_sentence": "工事のあいだ、エレベーターは止まっていた。", "error_description": "「止まる」は自動詞なので、「エレベーターを」ではなく「エレベーターは」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37773, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。文の主題（エルロン）を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の助詞。受け身の文では対象が主語になるので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段の助詞。「エルロンで取り付けられている」は手段の意味になる。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示す助詞。ここでは主題を示せない。"}], "correct_answer": "は", "explanations": {"は": "正解。文の主題（エルロン）を示す。", "を": "目的語の助詞。受け身の文では対象が主語になるので合わない。", "で": "手段の助詞。「エルロンで取り付けられている」は手段の意味になる。", "に": "相手や場所を示す助詞。ここでは主題を示せない。"}, "error_tags": {"を": "目的語", "で": "手段", "に": "相手・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37773, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。並列の「と」で、エルロンとラダーを並べる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の助詞。二つ目の「を」が重なり、文が崩れる。"}, {"text": "から", "is_correct": false, "explanation": "起点の助詞。「エルロンからラダーを使う」は並列の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞。並べる意味にならない。"}], "correct_answer": "と", "explanations": {"と": "正解。並列の「と」で、エルロンとラダーを並べる。", "を": "目的語の助詞。二つ目の「を」が重なり、文が崩れる。", "から": "起点の助詞。「エルロンからラダーを使う」は並列の意味にならない。", "へ": "方向の助詞。並べる意味にならない。"}, "error_tags": {"を": "目的語", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37773, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飛行機の主翼の後縁に取り付けられた、機体を左右に傾けるための可動翼面。", "primary_collocate": null, "pronunciation": "えるろん", "ipa": "eɾɯɾoɴ", "syllable_count": 4, "sentences": [{"text": "左右のエルロンを逆に動かすと、機体が横に傾く。", "target_word": "エルロン", "complexity_tier": "T3", "furigana": "左右[さゆう]のエルロンを逆[ぎゃく]に動[うご]かすと、機体[きたい]が横[よこ]に傾[かたむ]く。", "sentence_source": "generated"}, {"text": "エルロンは主翼の後縁に取り付けられている。", "target_word": "エルロン", "complexity_tier": "T3", "furigana": "エルロンは主翼[しゅよく]の後縁[こうえん]に取[と]り付[つ]けられている。", "sentence_source": "generated"}, {"text": "操縦かんを右に倒すと、右のエルロンが上がる。", "target_word": "エルロン", "complexity_tier": "T3", "furigana": "操縦[そうじゅう]かんを右[みぎ]に倒[たお]すと、右[みぎ]のエルロンが上[あ]がる。", "sentence_source": "generated"}, {"text": "点検で、エルロンの接合部に亀裂が見つかった。", "target_word": "エルロン", "complexity_tier": "T3", "furigana": "点検[てんけん]で、エルロンの接合部[せつごうぶ]に亀裂[きれつ]が見[み]つかった。", "sentence_source": "generated"}, {"text": "エルロンの故障で、飛行機は空港に引き返した。", "target_word": "エルロン", "complexity_tier": "T3", "furigana": "エルロンの故障[こしょう]で、飛行機[ひこうき]は空港[くうこう]に引[ひ]き返[かえ]した。", "sentence_source": "generated"}, {"text": "この機体では、エルロンが電気の信号で動く。", "target_word": "エルロン", "complexity_tier": "T3", "furigana": "この機体[きたい]では、エルロンが電気[でんき]の信号[しんごう]で動[うご]く。", "sentence_source": "generated"}, {"text": "設計者は、エルロンの面積を大きくする案を出した。", "target_word": "エルロン", "complexity_tier": "T3", "furigana": "設計者[せっけいしゃ]は、エルロンの面積[めんせき]を大[おお]きくする案[あん]を出[だ]した。", "sentence_source": "generated"}, {"text": "エルロンとラダーを同時に使うと、きれいに旋回できる。", "target_word": "エルロン", "complexity_tier": "T3", "furigana": "エルロンとラダーを同時[どうじ]に使[つか]うと、きれいに旋回[せんかい]できる。", "sentence_source": "generated"}, {"text": "風洞実験で、エルロンの効きを調べた。", "target_word": "エルロン", "complexity_tier": "T3", "furigana": "風洞[ふうどう]実験[じっけん]で、エルロンの効[き]きを調[しら]べた。", "sentence_source": "generated"}, {"text": "エルロンを動かすと、機体のロール運動が起こる。", "target_word": "エルロン", "complexity_tier": "T3", "furigana": "エルロンを動[うご]かすと、機体[きたい]のロール運動[うんどう]が起[お]こる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エルロン", "label": "base"}], "register": "専門", "sense_fingerprint": "機体を横に傾ける主翼後縁の可動面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37773, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エルロン", "is_correct": true, "explanation": "正解。左右で逆に動かす、主翼後縁の可動面を指す。"}, {"text": "座席", "is_correct": false, "explanation": "人が座る場所で、機体を傾ける面ではない。"}, {"text": "伝票", "is_correct": false, "explanation": "会計に使う紙で、機体を動かす部品ではない。"}, {"text": "天井", "is_correct": false, "explanation": "室内の上面で、機体の傾きとは関係しない。"}], "explanations": {"エルロン": "正解。左右で逆に動かす、主翼後縁の可動面を指す。", "座席": "人が座る場所で、機体を傾ける面ではない。", "伝票": "会計に使う紙で、機体を動かす部品ではない。", "天井": "室内の上面で、機体の傾きとは関係しない。"}, "sentence_index": 0, "correct_answer": "エルロン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "左に曲がるため、エルロンを足で踏んだ。", "explanation": "ここは〈ラダー（方向舵）〉の働き。足で操作して機首の向きを変えるのはラダーで、エルロンは横の傾きを作る。"}, {"text": "機首を下げるため、エルロンを前に押した。", "explanation": "ここは〈エレベーター〉の働き。機首の上下を変えるのはエレベーターで、エルロンは左右の傾きを作る。"}, {"text": "操縦かんの重さを和らげるため、エルロンを小さく後ろへ折り曲げた。", "explanation": "ここは〈トリムタブ〉の働き。操縦の重さを和らげる小さな補助翼はトリムタブで、エルロンそのものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37773, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エルロン", "is_correct": true, "explanation": "正解。主翼後縁の可動面で、大きさを変える案の対象になる。"}, {"text": "食器", "is_correct": false, "explanation": "食事に使う器具で、機体の部品ではない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、面積を持たず、大きくする対象にならない。"}, {"text": "鼻歌", "is_correct": false, "explanation": "口ずさむ歌で、面積を大きくする対象にならない。"}], "explanations": {"エルロン": "正解。主翼後縁の可動面で、大きさを変える案の対象になる。", "食器": "食事に使う器具で、機体の部品ではない。", "季節": "時期を表す語で、面積を持たず、大きくする対象にならない。", "鼻歌": "口ずさむ歌で、面積を大きくする対象にならない。"}, "sentence_index": 6, "correct_answer": "エルロン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "離陸時に揚力を増やすため、エルロンを前縁から突き出した。", "explanation": "ここは〈スラット〉の働き。前縁から突き出して揚力を増やすのはスラットで、エルロンは後縁の可動面。"}, {"text": "エンジンの出力を上げるため、エルロンを開いて空気を取り込んだ。", "explanation": "ここは〈吸気口〉の働き。エンジンに空気を送るのは吸気口で、エルロンは機体を左右に傾ける可動面。"}, {"text": "機体の重さを調整するため、燃料をエルロンに移した。", "explanation": "ここは〈燃料タンク〉の働き。燃料を蓄えるのは燃料タンクで、エルロンは左右の傾きを作る可動面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37773, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "左右のエルロンに逆に動かすと、機体が横に傾きやすくなる。", "corrected_sentence": "左右のエルロンを逆に動かすと、機体が横に傾きやすくなる。", "error_description": "「動かす」の対象は「を」で示す。「に」を使うと対象が示せず、文が崩れる。正しくは「エルロンを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37773, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "設計者は、エルロンを面積を小さくする案を出した。", "corrected_sentence": "設計者は、エルロンの面積を小さくする案を出した。", "error_description": "「面積」はエルロンの所属を「の」で示す。「を」を重ねると二つ目の「を」が重なり、文が成り立たない。正しくは「エルロンの」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
