INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37774, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかのものが、ひとつにまとまったもの。", "primary_collocate": null, "pronunciation": "しゅうごう", "ipa": "ɕɯːɡoː", "syllable_count": 4, "sentences": [{"text": "数学の授業で、集合の考え方を習いました。", "target_word": "集合", "complexity_tier": "T3", "furigana": "数学[すうがく]の授業[じゅぎょう]で、集合[しゅうごう]の考[かんが]え方[かた]を習[なら]いました。", "sentence_source": "generated"}, {"text": "偶数の集合には、二や四や六が入っています。", "target_word": "集合", "complexity_tier": "T3", "furigana": "偶数[ぐうすう]の集合[しゅうごう]には、二[に]や四[よん]や六[ろく]が入[はい]っています。", "sentence_source": "generated"}, {"text": "犬と猫を合わせた集合を、図に描いてください。", "target_word": "集合", "complexity_tier": "T3", "furigana": "犬[いぬ]と猫[ねこ]を合[あ]わせた集合[しゅうごう]を、図[ず]に描[か]いてください。", "sentence_source": "generated"}, {"text": "二つの集合に共通するものを見つけます。", "target_word": "集合", "complexity_tier": "T3", "furigana": "二[ふた]つの集合[しゅうごう]に共通[きょうつう]するものを見[み]つけます。", "sentence_source": "generated"}, {"text": "この集合には、果物だけが入っています。", "target_word": "集合", "complexity_tier": "T3", "furigana": "この集合[しゅうごう]には、果物[くだもの]だけが入[はい]っています。", "sentence_source": "generated"}, {"text": "先生は黒板に丸を二つ描いて、集合を説明しました。", "target_word": "集合", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に丸[まる]を二[ふた]つ描[か]いて、集合[しゅうごう]を説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "集合に入っている一つ一つのものを、要素と呼びます。", "target_word": "集合", "complexity_tier": "T3", "furigana": "集合[しゅうごう]に入[はい]っている一[ひと]つ一[ひと]つのものを、要素[ようそ]と呼[よ]びます。", "sentence_source": "generated"}, {"text": "自然数の集合は、いくらでも続いていきます。", "target_word": "集合", "complexity_tier": "T3", "furigana": "自然数[しぜんすう]の集合[しゅうごう]は、いくらでも続[つづ]いていきます。", "sentence_source": "generated"}, {"text": "何も入っていない集合にも、名前がついています。", "target_word": "集合", "complexity_tier": "T3", "furigana": "何[なに]も入[はい]っていない集合[しゅうごう]にも、名前[なまえ]がついています。", "sentence_source": "generated"}, {"text": "赤い花の集合と白い花の集合を、別々の円で表しました。", "target_word": "集合", "complexity_tier": "T3", "furigana": "赤[あか]い花[はな]の集合[しゅうごう]と白[しろ]い花[はな]の集合[しゅうごう]を、別々[べつべつ]の円[えん]で表[あらわ]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集合", "label": "基本形"}], "register": "standard", "sense_fingerprint": "数学などで、ものの集まりをひとつのまとまりとして考えたもの(人が集まる意味ではない)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37774, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集合", "is_correct": true, "explanation": "数学の授業で習う、ものをひとつのまとまりとして考える概念。これが正解。"}, {"text": "昼寝", "is_correct": false, "explanation": "眠ることを指す語で、数学の授業の内容としては成り立たない。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗うことで、数学の考え方の対象にならない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて回ることで、数学の考え方とは結びつかない。"}], "explanations": {"集合": "数学の授業で習う、ものをひとつのまとまりとして考える概念。これが正解。", "昼寝": "眠ることを指す語で、数学の授業の内容としては成り立たない。", "洗濯": "衣類を洗うことで、数学の考え方の対象にならない。", "散歩": "歩いて回ることで、数学の考え方とは結びつかない。"}, "sentence_index": 0, "correct_answer": "集合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "集合時間に遅れないよう、校門に集合してください。", "explanation": "ここは〈人が集まる〉の意味。数学の集合とは別の語義で、ものの集まりを指さない。"}, {"text": "係の人が、先月の会費を集合した。", "explanation": "ここは〈集金〉の意味。集合にはお金を回収する意味はない。"}, {"text": "駅前に大勢の人が集合した。", "explanation": "ここは〈人が集まる〉の意味。ものをまとめて考える数学の集合ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37774, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集合", "is_correct": true, "explanation": "集合の中に入っているものを要素と呼ぶという定義に合う。これが正解。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、「天気に入っている」とは言わない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の齢で、ものが入っているという文脈に合わない。"}, {"text": "味", "is_correct": false, "explanation": "味覚の語で、「味に入っているものを要素と呼ぶ」は意味が成り立たない。"}], "explanations": {"集合": "集合の中に入っているものを要素と呼ぶという定義に合う。これが正解。", "天気": "空模様のことで、「天気に入っている」とは言わない。", "年齢": "人の齢で、ものが入っているという文脈に合わない。", "味": "味覚の語で、「味に入っているものを要素と呼ぶ」は意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "集合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "授業中は精神を集合させて、先生の話を聞いた。", "explanation": "ここは〈集中〉の意味。集合は、ものを寄せて一つにまとめる語で、注意を向ける意味はない。"}, {"text": "工場で集合回路を作っている。", "explanation": "ここは〈集積回路〉の意味。集積回路は電子部品の名前で、「集合回路」という言い方はしない。"}, {"text": "集合のチームで、勝つのは難しい。", "explanation": "ここは〈寄せ集め〉の意味。ばらばらの人が集まったチームは「寄せ集めのチーム」と言い、「集合のチーム」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37774, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奇数の集合で、一や三や五が入っています。", "corrected_sentence": "奇数の集合に、一や三や五が入っています。", "error_description": "「入っている」の場所を示すには「に」が必要。「で」は動作の場所を表すので誤り。正しくは「集合に入っている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37774, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この集合を、三つの要素からできています。", "corrected_sentence": "この集合は、三つの要素からできています。", "error_description": "「できている」は主題を「は」で示すので、「を」は誤り。正しくは「この集合は」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37776, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「平衡を失う」の「を」。失う対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「平衡に失う」とは言わない。失う対象には「を」を使う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、失う対象には使えない。"}, {"text": "と", "is_correct": false, "explanation": "「平衡と失う」は不自然。「と」は並列や相手を表す。"}], "correct_answer": "を", "explanations": {"を": "「平衡を失う」の「を」。失う対象を示す。", "に": "「平衡に失う」とは言わない。失う対象には「を」を使う。", "で": "「で」は手段や場所を示すので、失う対象には使えない。", "と": "「平衡と失う」は不自然。「と」は並列や相手を表す。"}, "error_tags": {"に": "目的語の誤り", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37776, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「平衡を失って」の「を」。失う対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「平衡が失って」は主語を示す「が」で、失う対象にはならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう方向を示すので、「平衡へ失って」は失う対象とつながらない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞なので、「平衡の失って」は動詞「失って」と続かない。"}], "correct_answer": "を", "explanations": {"を": "「平衡を失って」の「を」。失う対象を示す。", "が": "「平衡が失って」は主語を示す「が」で、失う対象にはならず文が成り立たない。", "へ": "「へ」は向かう方向を示すので、「平衡へ失って」は失う対象とつながらない。", "の": "「の」は名詞どうしをつなぐ助詞なので、「平衡の失って」は動詞「失って」と続かない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37776, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものが倒れたり動いたりしないで、同じ場所で落ち着いていること。", "primary_collocate": null, "pronunciation": "へいこう", "ipa": "heːkoː", "syllable_count": 4, "sentences": [{"text": "綱渡りの人は、長い棒を使って平衡を保っています。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "綱渡[つなわた]りの人[ひと]は、長[なが]い棒[ぼう]を使[つか]って平衡[へいこう]を保[たも]っています。", "sentence_source": "generated"}, {"text": "船が大きく揺れて、体の平衡を失いそうになりました。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "船[ふね]が大[おお]きく揺[ゆ]れて、体[からだ]の平衡[へいこう]を失[うしな]いそうになりました。", "sentence_source": "generated"}, {"text": "やじろべえは、平衡を保ったまま左右にゆれます。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "やじろべえは、平衡[へいこう]を保[たも]ったまま左右[さゆう]にゆれます。", "sentence_source": "generated"}, {"text": "積み木が崩れないのは、平衡がよく保たれているからです。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "積[つ]み木[き]が崩[くず]れないのは、平衡[へいこう]がよく保[たも]たれているからです。", "sentence_source": "generated"}, {"text": "片足で立つと、平衡を保つのが難しくなります。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "片足[かたあし]で立[た]つと、平衡[へいこう]を保[たも]つのが難[むずか]しくなります。", "sentence_source": "generated"}, {"text": "荷物が片方に寄って、自転車の平衡が崩れました。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "荷物[にもつ]が片方[かたほう]に寄[よ]って、自転車[じてんしゃ]の平衡[へいこう]が崩[くず]れました。", "sentence_source": "generated"}, {"text": "体操選手は平均台の上で、平衡を保って歩きます。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "体操[たいそう]選手[せんしゅ]は平均台[へいきんだい]の上[うえ]で、平衡[へいこう]を保[たも]って歩[ある]きます。", "sentence_source": "generated"}, {"text": "風が強くて、背の高い棚は平衡を失って倒れました。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]くて、背[せ]の高[たか]い棚[たな]は平衡[へいこう]を失[うしな]って倒[たお]れました。", "sentence_source": "generated"}, {"text": "歩き始めのころの赤ちゃんは、平衡を保つのがまだ下手です。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "歩[ある]き始[はじ]めのころの赤[あか]ちゃんは、平衡[へいこう]を保[たも]つのがまだ下手[へた]です。", "sentence_source": "generated"}, {"text": "石を高く積むときは、少しでも平衡を崩さないよう気をつけます。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "石[いし]を高[たか]く積[つ]むときは、少[すこ]しでも平衡[へいこう]を崩[くず]さないよう気[き]をつけます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "平衡", "label": "基本形"}], "register": "standard", "sense_fingerprint": "体やものが倒れずに安定していること(平衡を保つ・平衡を失う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37776, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平衡", "is_correct": true, "explanation": "ものが倒れず安定している状態を指し、棒を使って保つという文脈に合う。これが正解。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、棒を使って保つ対象にならない。"}, {"text": "掃除", "is_correct": false, "explanation": "部屋などをきれいにする行為で、「掃除を保つ」とは言わない。"}, {"text": "昼寝", "is_correct": false, "explanation": "眠ることを指す語で、綱渡りの文脈には合わない。"}], "explanations": {"平衡": "ものが倒れず安定している状態を指し、棒を使って保つという文脈に合う。これが正解。", "天気": "空模様のことで、棒を使って保つ対象にならない。", "掃除": "部屋などをきれいにする行為で、「掃除を保つ」とは言わない。", "昼寝": "眠ることを指す語で、綱渡りの文脈には合わない。"}, "sentence_index": 0, "correct_answer": "平衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法の下では、すべての人が平衡だ。", "explanation": "ここは〈平等〉の意味。平衡は物が安定して釣り合っている状態で、人の権利が同じという意味では使わない。"}, {"text": "五回の測定の平衡を出して、報告書にまとめた。", "explanation": "ここは〈平均〉の意味。平衡は釣り合いの状態で、数値の平均を出すものではない。"}, {"text": "明日の平衡を予想する。", "explanation": "ここは〈天気〉の意味。平衡は物の安定を指し、天気の予想には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37776, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平衡", "is_correct": true, "explanation": "平均台の上で体を安定させて歩くという文脈に合う。これが正解。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品の甘味料で、体を保って歩くという文脈に合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の齢で、保つ対象にならない。"}, {"text": "色", "is_correct": false, "explanation": "物の見た目を表す語で、歩き方の文脈には合わない。"}], "explanations": {"平衡": "平均台の上で体を安定させて歩くという文脈に合う。これが正解。", "砂糖": "食品の甘味料で、体を保って歩くという文脈に合わない。", "年齢": "人の齢で、保つ対象にならない。", "色": "物の見た目を表す語で、歩き方の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "平衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは平衡が濃すぎる。", "explanation": "ここは〈味〉の意味。平衡は状態を指すので、味の濃さには使わない。"}, {"text": "彼は平衡を下げて、部屋を静かにした。", "explanation": "ここは〈音量〉の意味。平衡は釣り合いの状態を指し、数値のように下げることはできない。"}, {"text": "平衡を重ねる。", "explanation": "ここは〈年齢〉の意味。平衡は年を重ねるものではなく、年齢の文脈には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37776, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "荷物を片側に寄せないよう、平衡が保って運ぶ。", "corrected_sentence": "荷物を片側に寄せないよう、平衡を保って運ぶ。", "error_description": "「保つ」の目的語には「を」が必要。「が」は誤りで、正しくは「平衡を保って」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37776, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボートの上では、体の平衡が取るため足を広げる。", "corrected_sentence": "ボートの上では、体の平衡を取るため足を広げる。", "error_description": "「取る」の目的語には「を」が必要。「が」は誤りで、正しくは「平衡を取る」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
