INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37777, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体が静止している状態、または、つり合いがとれて安定していること。", "primary_collocate": null, "pronunciation": "へいこう", "ipa": "heːkoː", "syllable_count": 4, "sentences": [{"text": "二つの力がつり合うと、物体は平衡の状態になります。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "二[ふた]つの力[ちから]がつり合[あ]うと、物体[ぶったい]は平衡[へいこう]の状態[じょうたい]になります。", "sentence_source": "generated"}, {"text": "天びんが水平で止まっているとき、左右の重さは平衡の状態です。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "天[てん]びんが水平[すいへい]で止[と]まっているとき、左右[さゆう]の重[おも]さは平衡[へいこう]の状態[じょうたい]です。", "sentence_source": "generated"}, {"text": "化学では、反応が進んでも量が変わらない状態を平衡といいます。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "化学[かがく]では、反応[はんのう]が進[すす]んでも量[りょう]が変[か]わらない状態[じょうたい]を平衡[へいこう]といいます。", "sentence_source": "generated"}, {"text": "本が机の上で動かないのは、力が平衡の状態にあるからです。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "本[ほん]が机[つくえ]の上[うえ]で動[うご]かないのは、力[ちから]が平衡[へいこう]の状態[じょうたい]にあるからです。", "sentence_source": "generated"}, {"text": "ふりこが真ん中で止まった位置を、平衡の位置といいます。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "ふりこが真[ま]ん中[なか]で止[と]まった位置[いち]を、平衡[へいこう]の位置[いち]といいます。", "sentence_source": "generated"}, {"text": "熱いお湯と冷たい水を混ぜると、やがて温度の平衡に達します。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "熱[あつ]いお湯[ゆ]と冷[つめ]たい水[みず]を混[ま]ぜると、やがて温度[おんど]の平衡[へいこう]に達[たっ]します。", "sentence_source": "generated"}, {"text": "収入と支出の平衡を保つために、予算を立てます。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]と支出[ししゅつ]の平衡[へいこう]を保[たも]つために、予算[よさん]を立[た]てます。", "sentence_source": "generated"}, {"text": "平衡の状態では、外から見て何も動いていないように見えます。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "平衡[へいこう]の状態[じょうたい]では、外[そと]から見[み]て何[なに]も動[うご]いていないように見[み]えます。", "sentence_source": "generated"}, {"text": "物理の試験で、力の平衡についての問題が出ました。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "物理[ぶつり]の試験[しけん]で、力[ちから]の平衡[へいこう]についての問題[もんだい]が出[で]ました。", "sentence_source": "generated"}, {"text": "森の生き物の数は、長い間平衡を保ってきました。", "target_word": "平衡", "complexity_tier": "T3", "furigana": "森[もり]の生[い]き物[もの]の数[かず]は、長[なが]い間[あいだ]平衡[へいこう]を保[たも]ってきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "平衡", "label": "基本形"}], "register": "standard", "sense_fingerprint": "力や量がつり合って変化しない状態(物理・化学などの平衡状態)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: つり合う (Zipf 1.13)']::text[], '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37777, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平衡", "is_correct": true, "explanation": "力がつり合って静止している状態を指すので、ここに入る。"}, {"text": "加速", "is_correct": false, "explanation": "つり合っている物体は速さを変えない。加速の状態とは逆なので合わない。"}, {"text": "回転", "is_correct": false, "explanation": "つり合いは回る力もかかっていない状態。回転の状態になるとは言えず合わない。"}, {"text": "落下", "is_correct": false, "explanation": "つり合っている物体は下に落ちていかない。落下の状態とは矛盾するので合わない。"}], "explanations": {"平衡": "力がつり合って静止している状態を指すので、ここに入る。", "加速": "つり合っている物体は速さを変えない。加速の状態とは逆なので合わない。", "回転": "つり合いは回る力もかかっていない状態。回転の状態になるとは言えず合わない。", "落下": "つり合っている物体は下に落ちていかない。落下の状態とは矛盾するので合わない。"}, "sentence_index": 0, "correct_answer": "平衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二本のレールは平衡に並んでいて、どこまで延ばしても交わらない。", "explanation": "ここは〈平行〉の意味。線や面が並んで交わらないことは平行と言い、平衡は力や量のつり合いを指すので合わない。"}, {"text": "この菓子は大きさが平衡で、どれも同じ形をしている。", "explanation": "ここは〈均一〉の意味。大きさがそろっていることは均一と言い、平衡はつり合いや静止の状態を指すので合わない。"}, {"text": "テストの点数を全部足して、クラスの平衡を出した。", "explanation": "ここは〈平均〉の意味。合計を人数で割った値は平均で、平衡は計算結果として出す言葉ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37777, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平衡", "is_correct": true, "explanation": "収入と支出のつり合いを保つという意味で、平衡がここに入る。"}, {"text": "赤字", "is_correct": false, "explanation": "赤字は支出が収入を上回る状態で、つり合いを保つ対象にはならず合わない。"}, {"text": "出費", "is_correct": false, "explanation": "出費は使うお金のことで、収入と支出のつり合いの状態を指さないので合わない。"}, {"text": "期限", "is_correct": false, "explanation": "期限は締め切りの日で、収入と支出のつり合いとは関係がないので合わない。"}], "explanations": {"平衡": "収入と支出のつり合いを保つという意味で、平衡がここに入る。", "赤字": "赤字は支出が収入を上回る状態で、つり合いを保つ対象にはならず合わない。", "出費": "出費は使うお金のことで、収入と支出のつり合いの状態を指さないので合わない。", "期限": "期限は締め切りの日で、収入と支出のつり合いとは関係がないので合わない。"}, "sentence_index": 6, "correct_answer": "平衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "森では長い間、平衡な暮らしが続いてきました。", "explanation": "ここは〈平穏〉の意味。争いがなく穏やかな暮らしは平穏と言い、平衡は力や数のつり合いを指すので合わない。"}, {"text": "森の生き物の数は、長い間平衡どおりに続いてきました。", "explanation": "ここは〈平常〉の意味。いつもと変わらない状態は平常と言い、平衡どおりとは言わないので合わない。"}, {"text": "森の生き物はすべて、平衡に扱われてきました。", "explanation": "ここは〈平等〉の意味。誰もが同じように扱われることは平等と言い、平衡は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37777, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天びんが水平で止まっているとき、左右の重さは平衡を状態になっています。", "corrected_sentence": "天びんが水平で止まっているとき、左右の重さは平衡の状態になっています。", "error_description": "「平衡」に続く助詞が誤り。「平衡の状態」と名詞を修飾するので「の」が正しく、「を」は目的語を示すため不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37777, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "収入と支出の平衡が保つために、貯金を始めました。", "corrected_sentence": "収入と支出の平衡を保つために、貯金を始めました。", "error_description": "「保つ」の目的語を示す「を」が「が」になっている。「平衡を保つ」が正しく、「が」では平衡が主語になり意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37778, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「勉強する」の対象を示す目的語の助詞で、芸術を勉強しているという意味になり正しい。"}, {"text": "が", "is_correct": false, "explanation": "「芸術が勉強している」となり、芸術が主語になって意味が通らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「芸術に勉強する」という対象の表し方は不自然で、ここでは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、勉強の対象を表すことはできないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「勉強する」の対象を示す目的語の助詞で、芸術を勉強しているという意味になり正しい。", "が": "「芸術が勉強している」となり、芸術が主語になって意味が通らないので合わない。", "に": "「芸術に勉強する」という対象の表し方は不自然で、ここでは合わない。", "へ": "方向を示す助詞で、勉強の対象を表すことはできないので合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "対象・位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37778, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「楽しむ」の対象を示す目的語の助詞で、芸術を楽しむ祭りとなり正しい。"}, {"text": "と", "is_correct": false, "explanation": "「芸術と楽しむ祭り」は共に楽しむ相手の意味になり、対象を表せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す助詞で、「芸術より楽しむ祭り」は意味が通らないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、楽しむ対象を表すことはできないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「楽しむ」の対象を示す目的語の助詞で、芸術を楽しむ祭りとなり正しい。", "と": "「芸術と楽しむ祭り」は共に楽しむ相手の意味になり、対象を表せないので合わない。", "より": "比較を表す助詞で、「芸術より楽しむ祭り」は意味が通らないので合わない。", "から": "起点を示す助詞で、楽しむ対象を表すことはできないので合わない。"}, "error_tags": {"を": "目的語", "と": "共同", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37778, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が作った美しいものや、心を動かす表現のことです。", "primary_collocate": null, "pronunciation": "げいじゅつ", "ipa": "ɡeːd͡ʑɯt͡sɯ", "syllable_count": 4, "sentences": [{"text": "美術館で、昔の芸術を見てきました。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]で、昔[むかし]の芸術[げいじゅつ]を見[み]てきました。", "sentence_source": "generated"}, {"text": "兄は大学で芸術を勉強しています。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]で芸術[げいじゅつ]を勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "音楽や絵や踊りは、どれも芸術です。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "音楽[おんがく]や絵[え]や踊[おど]りは、どれも芸術[げいじゅつ]です。", "sentence_source": "generated"}, {"text": "優れた芸術は、見る人の心を動かします。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "優[すぐ]れた芸術[げいじゅつ]は、見[み]る人[ひと]の心[こころ]を動[うご]かします。", "sentence_source": "generated"}, {"text": "この町には、芸術を学べる学校がたくさんあります。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "この町[まち]には、芸術[げいじゅつ]を学[まな]べる学校[がっこう]がたくさんあります。", "sentence_source": "generated"}, {"text": "彼女は子どものころから芸術に興味がありました。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は子[こ]どものころから芸術[げいじゅつ]に興味[きょうみ]がありました。", "sentence_source": "generated"}, {"text": "芸術と科学は別のものだと思われがちですが、似ているところもあります。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "芸術[げいじゅつ]と科学[かがく]は別[べつ]のものだと思[おも]われがちですが、似[に]ているところもあります。", "sentence_source": "generated"}, {"text": "この町では毎年、芸術を楽しむ祭りが開かれます。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "この町[まち]では毎年[まいとし]、芸術[げいじゅつ]を楽[たの]しむ祭[まつ]りが開[ひら]かれます。", "sentence_source": "generated"}, {"text": "言葉が通じなくても、芸術は人の心に届きます。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "言葉[ことば]が通[つう]じなくても、芸術[げいじゅつ]は人[ひと]の心[こころ]に届[とど]きます。", "sentence_source": "generated"}, {"text": "父は芸術がわからないと言いながら、よく絵を見に行きます。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "父[ちち]は芸術[げいじゅつ]がわからないと言[い]いながら、よく絵[え]を見[み]に行[い]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "芸術", "label": "基本形"}], "register": "standard", "sense_fingerprint": "絵・音楽・踊りなど、美しさや感動を表す人の創作活動とその作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37778, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "芸術", "is_correct": true, "explanation": "美術館で昔の作品や表現を見てきたという文脈に合い、ここに入る。"}, {"text": "税金", "is_correct": false, "explanation": "国や自治体に納めるお金で、美術館で見てきたものではないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "その日の空模様のことで、美術館で見る対象にはならないので合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙や荷物を届ける仕組みで、見てきたものとしては文の内容に合わない。"}], "explanations": {"芸術": "美術館で昔の作品や表現を見てきたという文脈に合い、ここに入る。", "税金": "国や自治体に納めるお金で、美術館で見てきたものではないので合わない。", "天気": "その日の空模様のことで、美術館で見る対象にはならないので合わない。", "郵便": "手紙や荷物を届ける仕組みで、見てきたものとしては文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "芸術"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この職人は高い芸術で、精密な部品を作る。", "explanation": "ここは〈技術〉の意味。部品を正確に作る腕前は技術と言い、芸術は感動を与える作品について使うので合わない。"}, {"text": "毎朝六時に起きることが、彼の芸術だ。", "explanation": "ここは〈習慣〉の意味。毎日決まってすることは習慣と言い、芸術は作品や表現を指すので合わない。"}, {"text": "ちょっとした芸術で、部屋が広く見える。", "explanation": "ここは〈工夫〉の意味。思いついた小さな仕掛けは工夫と言い、芸術はこの場面に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37778, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "芸術", "is_correct": true, "explanation": "芸術と科学を対比して別のものと思われる、という文脈に入る語なので正しい。"}, {"text": "玄関", "is_correct": false, "explanation": "家の入り口を表す語で、科学との関係を比べる話題にはならず合わない。"}, {"text": "寝具", "is_correct": false, "explanation": "眠るための道具で、科学と別物と思われるという比較の対象としては合わない。"}, {"text": "台所", "is_correct": false, "explanation": "料理をする場所で、学問の科学と比べて論じる対象ではないので合わない。"}], "explanations": {"芸術": "芸術と科学を対比して別のものと思われる、という文脈に入る語なので正しい。", "玄関": "家の入り口を表す語で、科学との関係を比べる話題にはならず合わない。", "寝具": "眠るための道具で、科学と別物と思われるという比較の対象としては合わない。", "台所": "料理をする場所で、学問の科学と比べて論じる対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "芸術"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は歴史の芸術が豊富で、何でも答えられる。", "explanation": "ここは〈知識〉の意味。学んで蓄えた事実は知識と言い、芸術は作品や表現を指すので合わない。"}, {"text": "この工場では、部品を組み立てる芸術を一日中続けている。", "explanation": "ここは〈作業〉の意味。決まった手順で働くことは作業と言い、芸術は美しさや感動を生む創作なので合わない。"}, {"text": "犬が輪をくぐる芸術を覚えた。", "explanation": "ここは〈芸当〉の意味。客を楽しませる技は芸当と言い、芸術は作品を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37778, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は専門学校で芸術が学んでいます。", "corrected_sentence": "姉は専門学校で芸術を学んでいます。", "error_description": "「学ぶ」の目的語には「を」が入る。「が」は主語を示すため、「芸術が学んでいる」は誤りで「芸術を学んでいる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37778, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町では、芸術が楽しむ人が増えています。", "corrected_sentence": "この町では、芸術を楽しむ人が増えています。", "error_description": "「楽しむ」の目的語を示すのは「を」。「が」にすると芸術が主語になり、楽しむ主体が合わなくなるので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
