INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37780, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "何があっても絶対にそうではないということを表す言葉。", "primary_collocate": null, "pronunciation": "けっして", "ipa": "keɕːite", "syllable_count": 4, "sentences": [{"text": "彼との約束は、決して破りません。", "target_word": "決して", "complexity_tier": "T3", "furigana": "彼[かれ]との約束[やくそく]は、決[けっ]して破[やぶ]りません。", "sentence_source": "generated"}, {"text": "私は最後まで、決してあきらめません。", "target_word": "決して", "complexity_tier": "T3", "furigana": "私[わたし]は最後[さいご]まで、決[けっ]してあきらめません。", "sentence_source": "generated"}, {"text": "彼は決して人の悪口を言いません。", "target_word": "決して", "complexity_tier": "T3", "furigana": "彼[かれ]は決[けっ]して人[ひと]の悪口[わるぐち]を言[い]いません。", "sentence_source": "generated"}, {"text": "今回の試験は、決してやさしくありませんでした。", "target_word": "決して", "complexity_tier": "T3", "furigana": "今回[こんかい]の試験[しけん]は、決[けっ]してやさしくありませんでした。", "sentence_source": "generated"}, {"text": "この仕事は決して簡単ではありません。", "target_word": "決して", "complexity_tier": "T3", "furigana": "この仕事[しごと]は決[けっ]して簡単[かんたん]ではありません。", "sentence_source": "generated"}, {"text": "危ないので、この川には決して近づかないでください。", "target_word": "決して", "complexity_tier": "T3", "furigana": "危[あぶ]ないので、この川[かわ]には決[けっ]して近[ちか]づかないでください。", "sentence_source": "generated"}, {"text": "頑張った人の努力は、決して無駄にはなりません。", "target_word": "決して", "complexity_tier": "T3", "furigana": "頑張[がんば]った人[ひと]の努力[どりょく]は、決[けっ]して無駄[むだ]にはなりません。", "sentence_source": "generated"}, {"text": "失敗しても、決して自分を責めすぎないでください。", "target_word": "決して", "complexity_tier": "T3", "furigana": "失敗[しっぱい]しても、決[けっ]して自分[じぶん]を責[せ]めすぎないでください。", "sentence_source": "generated"}, {"text": "親切にしてもらったことは、決して忘れません。", "target_word": "決して", "complexity_tier": "T3", "furigana": "親切[しんせつ]にしてもらったことは、決[けっ]して忘[わす]れません。", "sentence_source": "generated"}, {"text": "子どもたちだけで、決して夜の海に入ってはいけません。", "target_word": "決して", "complexity_tier": "T3", "furigana": "子[こ]どもたちだけで、決[けっ]して夜[よる]の海[うみ]に入[はい]ってはいけません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "決して", "label": "基本形"}], "register": "standard", "sense_fingerprint": "あとに打ち消しの言い方が続き、どんな場合でもそうではないと強く言い切る副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f72fe7-7b0c-4b04-95f6-24dbfa60262e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37780, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "決して", "is_correct": true, "explanation": "どんな場合でも破らないという強い否定を表すので、ここに入る。"}, {"text": "ようやく", "is_correct": false, "explanation": "やっとの意味で、約束を破らないという強い言い切りにはならず合わない。"}, {"text": "寝ぼけて", "is_correct": false, "explanation": "寝ぼけた状態を表す語で、約束を破らないという話の流れに合わないので合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "たまたまを表す語で、約束を守る強い意志を述べる文には合わない。"}], "explanations": {"決して": "どんな場合でも破らないという強い否定を表すので、ここに入る。", "ようやく": "やっとの意味で、約束を破らないという強い言い切りにはならず合わない。", "寝ぼけて": "寝ぼけた状態を表す語で、約束を破らないという話の流れに合わないので合わない。", "偶然": "たまたまを表す語で、約束を守る強い意志を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "決して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "いろいろ考えたが、決してやめることにした。", "explanation": "決しては「〜ない」と打ち消しの言い方と組む副詞なので、「やめることにした」と肯定で続けるのは誤り。「結局」の意味は表さない。"}, {"text": "昨日は決して雨が降った。", "explanation": "決しては打ち消しの言い方と組む副詞なので、「雨が降った」と肯定で続けるのは誤り。「確かに」の意味は表さない。"}, {"text": "工場の機械は決して動き続けている。", "explanation": "決しては打ち消しの言い方と組む副詞なので、「動き続けている」と肯定で続けるのは誤り。「絶えず」の意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37780, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "決して", "is_correct": true, "explanation": "無駄にはならないと強く言い切る副詞で、努力の価値を述べる文にここで入る。"}, {"text": "ぜひ", "is_correct": false, "explanation": "強く望む気持ちを表す語で、無駄にならないという断言とは合わない。"}, {"text": "大急ぎで", "is_correct": false, "explanation": "急ぐ様子を表す語で、努力の価値を言う文には合わない。"}, {"text": "急に", "is_correct": false, "explanation": "突然を表す語で、努力が無駄にならない理由を述べる文には合わない。"}], "explanations": {"決して": "無駄にはならないと強く言い切る副詞で、努力の価値を述べる文にここで入る。", "ぜひ": "強く望む気持ちを表す語で、無駄にならないという断言とは合わない。", "大急ぎで": "急ぐ様子を表す語で、努力の価値を言う文には合わない。", "急に": "突然を表す語で、努力が無駄にならない理由を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "決して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日は決して来てください。", "explanation": "決しては打ち消しの言い方と組む副詞なので、「来てください」と肯定の依頼に続けるのは誤り。「必ず」の意味は表さない。"}, {"text": "彼は決して成功させるつもりです。", "explanation": "決しては打ち消しの言い方と組む副詞なので、「成功させるつもりです」と肯定で続けるのは誤り。「絶対に」の意味は表さない。"}, {"text": "大雨の中、彼は決して走った。", "explanation": "決しては打ち消しの言い方と組む副詞なので、「走った」と肯定で続けるのは誤り。「必死に」の意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37780, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は決して嘘をつきます。", "corrected_sentence": "兄は決して嘘をつきません。", "error_description": "「決して」は打ち消しの文と組む副詞。「つきます」は肯定の形なので誤りで、「つきません」と打ち消しにするのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37780, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は決して泣いた。", "corrected_sentence": "彼女は決して泣かなかった。", "error_description": "「決して」は打ち消しと組む副詞。「泣いた」は肯定の形なので誤りで、「泣かなかった」と打ち消しにするのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '717eeff9-1fe1-4d2c-85ec-d8faa053cdd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
