INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37782, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "数えきれないほどたくさんあること。", "primary_collocate": null, "pronunciation": "むすう", "ipa": "mɯsɯɯ", "syllable_count": 3, "sentences": [{"text": "浜辺の砂は、無数の小さな粒からできている。", "target_word": "無数", "complexity_tier": "T2", "furigana": "浜辺[はまべ]の砂[すな]は、無数[むすう]の小[ちい]さな粒[つぶ]からできている。", "sentence_source": "generated"}, {"text": "池の中には無数の小さな魚が泳いでいる。", "target_word": "無数", "complexity_tier": "T2", "furigana": "池[いけ]の中[なか]には無数[むすう]の小[ちい]さな魚[さかな]が泳[およ]いでいる。", "sentence_source": "generated"}, {"text": "彼のノートには無数の書き込みがあって、とても読みにくい。", "target_word": "無数", "complexity_tier": "T3", "furigana": "彼[かれ]のノートには無数[むすう]の書[か]き込[こ]みがあって、とても読[よ]みにくい。", "sentence_source": "generated"}, {"text": "都会の夜景は、無数の明かりが集まってできている。", "target_word": "無数", "complexity_tier": "T3", "furigana": "都会[とかい]の夜景[やけい]は、無数[むすう]の明[あ]かりが集[あつ]まってできている。", "sentence_source": "generated"}, {"text": "古い本棚の裏には、無数のほこりがたまっていた。", "target_word": "無数", "complexity_tier": "T3", "furigana": "古[ふる]い本棚[ほんだな]の裏[うら]には、無数[むすう]のほこりがたまっていた。", "sentence_source": "generated"}, {"text": "このゲームには無数の遊び方があるので、飽きることがない。", "target_word": "無数", "complexity_tier": "T3", "furigana": "このゲームには無数[むすう]の遊[あそ]び方[かた]があるので、飽[あ]きることがない。", "sentence_source": "generated"}, {"text": "駅前の道には無数の人が行き来していて、まっすぐ歩けなかった。", "target_word": "無数", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の道[みち]には無数[むすう]の人[ひと]が行[い]き来[き]していて、まっすぐ歩[ある]けなかった。", "sentence_source": "generated"}, {"text": "地面に落ちた桜の花びらは無数にあって、道がピンク色に見えた。", "target_word": "無数", "complexity_tier": "T3", "furigana": "地面[じめん]に落[お]ちた桜[さくら]の花[はな]びらは無数[むすう]にあって、道[みち]がピンク色[いろ]に見[み]えた。", "sentence_source": "generated"}, {"text": "無数の失敗を重ねて、やっと新しい薬ができた。", "target_word": "無数", "complexity_tier": "T3", "furigana": "無数[むすう]の失敗[しっぱい]を重[かさ]ねて、やっと新[あたら]しい薬[くすり]ができた。", "sentence_source": "generated"}, {"text": "夏の夜、川の近くでは無数のホタルが光っていた。", "target_word": "無数", "complexity_tier": "T2", "furigana": "夏[なつ]の夜[よる]、川[かわ]の近[ちか]くでは無数[むすう]のホタルが光[ひか]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無数", "label": "語幹"}, {"form": "無数の", "label": "連体形"}, {"form": "無数に", "label": "連用形"}, {"form": "無数だ", "label": "終止形"}], "register": "plain", "sense_fingerprint": "数えきれないほど多くあること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b24d15-9ff0-4e3d-8f40-83d3e5a40e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37782, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無数", "is_correct": true, "explanation": "「無数の粒」は数えきれないほど多くの粒という意味で、砂が細かく多数あることを述べる文に合う。"}, {"text": "鮮やか", "is_correct": false, "explanation": "「鮮やか」は色や印象がはっきりした様子で、粒の数を述べるこの文には合わない。"}, {"text": "慎重", "is_correct": false, "explanation": "「慎重」は注意深く行動する様子で、砂の粒を形容する語としては合わない。"}, {"text": "豪華", "is_correct": false, "explanation": "「豪華」は立派で華やかな様子で、砂粒の多さを述べる文には合わない。"}], "explanations": {"無数": "「無数の粒」は数えきれないほど多くの粒という意味で、砂が細かく多数あることを述べる文に合う。", "鮮やか": "「鮮やか」は色や印象がはっきりした様子で、粒の数を述べるこの文には合わない。", "慎重": "「慎重」は注意深く行動する様子で、砂の粒を形容する語としては合わない。", "豪華": "「豪華」は立派で華やかな様子で、砂粒の多さを述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "無数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "たった無数の切符を買った。", "explanation": "ここは〈ただ一枚〉（一つだけ）の意味。無数は数えきれないほど多い意味なので、一つだけを示す文脈とは矛盾する。"}, {"text": "彼は無数に遅刻しなかった。", "explanation": "ここは〈一度も〉（一回もない）の意味。無数は数の多さを表すので、回数がゼロであることを表す文には使えない。"}, {"text": "この村には店が無数にしかない。", "explanation": "ここは〈わずかな数〉の意味。無数は多いことを表すので、わずかさを示す文脈とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37782, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無数", "is_correct": true, "explanation": "「無数の人」は数えきれないほど多くの人という意味で、人が行き来する混雑した道の様子に合う。"}, {"text": "液状", "is_correct": false, "explanation": "「液状」は液体の状態を表す語で、人の数を述べるこの文には合わない。"}, {"text": "無音", "is_correct": false, "explanation": "「無音」は音がしない状態を表し、人が行き来する様子とは合わない。"}, {"text": "海洋", "is_correct": false, "explanation": "「海洋」は海の広がりを指す語で、道を行き来する人の数を表す文には合わない。"}], "explanations": {"無数": "「無数の人」は数えきれないほど多くの人という意味で、人が行き来する混雑した道の様子に合う。", "液状": "「液状」は液体の状態を表す語で、人の数を述べるこの文には合わない。", "無音": "「無音」は音がしない状態を表し、人が行き来する様子とは合わない。", "海洋": "「海洋」は海の広がりを指す語で、道を行き来する人の数を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "無数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その日は無数に寒かった。", "explanation": "ここは〈とても〉（程度が高い）の意味。無数は数の多さを表す語で、寒さの程度を強める副詞としては使わない。"}, {"text": "彼女は無数に十個の飴を食べた。", "explanation": "ここは〈具体的な個数〉（決まった数）の意味。無数は数えきれないほど多い意味なので、個数を明示する文脈とは矛盾する。"}, {"text": "ぴったり無数だ。", "explanation": "ここは〈ちょうどの数〉の意味。無数は数えきれないほど多い意味なので、決まった数を指す使い方とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37782, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕暮れの空には無数で鳥が飛んでいた。", "corrected_sentence": "夕暮れの空には無数の鳥が飛んでいた。", "error_description": "誤: 無数で（助詞「で」）。正: 無数の（助詞「の」）。無数は後ろの名詞を修飾する語なので、手段や場所を示す「で」ではなく連体修飾の「の」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "無数", "is_correct": true, "explanation": "正解。語幹の「無数」を入れると「無数の小さな魚」となり、数えきれないほど多い魚を表す。"}, {"text": "無数の", "is_correct": false, "explanation": "「無数の」を入れると「の」が二つ続いて「無数のの小さな魚」となり、文として不自然。"}, {"text": "無数に", "is_correct": false, "explanation": "連用形の「無数に」は、後ろの名詞「魚」を直接修飾できず、ここでは成り立たない。"}, {"text": "無数だ", "is_correct": false, "explanation": "終止形の「無数だ」は述語になるため、名詞「魚」の前には置けない。"}], "correct_form": "無数", "base_form": "無数", "form_label": "語幹", "sentence_index": 1, "explanations": {"無数": "正解。語幹の「無数」を入れると「無数の小さな魚」となり、数えきれないほど多い魚を表す。", "無数の": "「無数の」を入れると「の」が二つ続いて「無数のの小さな魚」となり、文として不自然。", "無数に": "連用形の「無数に」は、後ろの名詞「魚」を直接修飾できず、ここでは成り立たない。", "無数だ": "終止形の「無数だ」は述語になるため、名詞「魚」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37782, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の草むらには無数が虫が鳴いていた。", "corrected_sentence": "夏の草むらには無数の虫が鳴いていた。", "error_description": "誤: 無数が（助詞「が」）。正: 無数の（助詞「の」）。無数は後ろの名詞を修飾する語なので、主格の「が」ではなく連体修飾の「の」を付ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "無数", "is_correct": true, "explanation": "正解。語幹の「無数」を入れると「無数の人」となり、数えきれないほど多い人を表す。"}, {"text": "無数な", "is_correct": false, "explanation": "「無数な」を入れると後ろの「の」と続いて「無数なの人」となり、文として成り立たない。"}, {"text": "無数で", "is_correct": false, "explanation": "「無数で」は断定の連用形で、名詞の前には置けず「無数での人」となり不自然。"}, {"text": "無数だった", "is_correct": false, "explanation": "過去の終止形「無数だった」は述語になるため、名詞「人」の前には置けず「無数だったの人」となり成り立たない。"}], "correct_form": "無数", "base_form": "無数", "form_label": "語幹", "sentence_index": 7, "explanations": {"無数": "正解。語幹の「無数」を入れると「無数の人」となり、数えきれないほど多い人を表す。", "無数な": "「無数な」を入れると後ろの「の」と続いて「無数なの人」となり、文として成り立たない。", "無数で": "「無数で」は断定の連用形で、名詞の前には置けず「無数での人」となり不自然。", "無数だった": "過去の終止形「無数だった」は述語になるため、名詞「人」の前には置けず「無数だったの人」となり成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37784, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「支配される」が取る「に」。「怒りに支配された」と自然。"}, {"text": "を", "is_correct": false, "explanation": "「支配される」の受け身は「〜に」を取るので、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、「怒りと支配される」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、支配の対象には使わない。"}], "correct_answer": "に", "explanations": {"に": "「支配される」が取る「に」。「怒りに支配された」と自然。", "を": "「支配される」の受け身は「〜に」を取るので、「を」は合わない。", "と": "「と」は相手や並列を示すので、「怒りと支配される」は成り立たない。", "へ": "「へ」は方向を示すので、支配の対象には使わない。"}, "error_tags": {"を": "対象", "と": "相手・並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37784, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「支配される」が取る「に」。「欲に支配された人」と自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、支配の対象にはならない。"}, {"text": "を", "is_correct": false, "explanation": "「支配される」の受け身は「〜に」を取るので、「欲を支配された」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「欲より支配された」は文として合わない。"}], "correct_answer": "に", "explanations": {"に": "「支配される」が取る「に」。「欲に支配された人」と自然。", "と": "「と」は並列や相手を示すので、支配の対象にはならない。", "を": "「支配される」の受け身は「〜に」を取るので、「欲を支配された」は成り立たない。", "より": "「より」は比較を示すので、「欲より支配された」は文として合わない。"}, "error_tags": {"と": "相手・並列", "を": "対象", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37784, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを、自分のしたいように動かすこと。", "primary_collocate": null, "pronunciation": "しはい", "ipa": "ɕihai", "syllable_count": 3, "sentences": [{"text": "恐怖に支配されて、足が動かなくなった。", "target_word": "支配", "complexity_tier": "T3", "furigana": "恐怖[きょうふ]に支配[しはい]されて、足[あし]が動[うご]かなくなった。", "sentence_source": "generated"}, {"text": "彼は怒りに支配されると、周りの声が聞こえなくなる。", "target_word": "支配", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[いか]りに支配[しはい]されると、周[まわ]りの声[こえ]が聞[き]こえなくなる。", "sentence_source": "generated"}, {"text": "母は家の中の物事をすべて自分の支配のもとに置きたがる。", "target_word": "支配", "complexity_tier": "T3", "furigana": "母[はは]は家[いえ]の中[なか]の物事[ものごと]をすべて自分[じぶん]の支配[しはい]のもとに置[お]きたがる。", "sentence_source": "generated"}, {"text": "あの会社は市場を支配しようとして、値段を大きく下げた。", "target_word": "支配", "complexity_tier": "T3", "furigana": "あの会社[かいしゃ]は市場[しじょう]を支配[しはい]しようとして、値段[ねだん]を大[おお]きく下[さ]げた。", "sentence_source": "generated"}, {"text": "一人の男が会議を支配して、ほかの人は何も言えなかった。", "target_word": "支配", "complexity_tier": "T3", "furigana": "一人[ひとり]の男[おとこ]が会議[かいぎ]を支配[しはい]して、ほかの人[ひと]は何[なに]も言[い]えなかった。", "sentence_source": "generated"}, {"text": "眠気に支配されて、授業の内容が頭に入らなかった。", "target_word": "支配", "complexity_tier": "T3", "furigana": "眠気[ねむけ]に支配[しはい]されて、授業[じゅぎょう]の内容[ないよう]が頭[あたま]に入[はい]らなかった。", "sentence_source": "generated"}, {"text": "彼女は人の気持ちを支配しようとするので、友達が離れていった。", "target_word": "支配", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は人[ひと]の気持[きも]ちを支配[しはい]しようとするので、友達[ともだち]が離[はな]れていった。", "sentence_source": "generated"}, {"text": "欲に支配された人は、正しい判断ができなくなる。", "target_word": "支配", "complexity_tier": "T3", "furigana": "欲[よく]に支配[しはい]された人[ひと]は、正[ただ]しい判断[はんだん]ができなくなる。", "sentence_source": "generated"}, {"text": "試合の後半は相手チームが流れを支配していた。", "target_word": "支配", "complexity_tier": "T3", "furigana": "試合[しあい]の後半[こうはん]は相手[あいて]チームが流[なが]れを支配[しはい]していた。", "sentence_source": "generated"}, {"text": "不安に支配されないように、深呼吸して落ち着いた。", "target_word": "支配", "complexity_tier": "T3", "furigana": "不安[ふあん]に支配[しはい]されないように、深呼吸[しんこきゅう]して落[お]ち着[つ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "支配する", "label": "辞書形"}, {"form": "支配します", "label": "丁寧形"}, {"form": "支配した", "label": "過去形"}, {"form": "支配して", "label": "て形"}, {"form": "支配しない", "label": "否定形"}, {"form": "支配される", "label": "受身形"}, {"form": "支配している", "label": "継続形"}], "register": "中立（丁寧すぎない普通の文体）", "sense_fingerprint": "感情や場の流れ、人の気持ちなどを自分の思うままに動かす・動かされること（影響力による支配）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09538d83-9a44-4f80-ba28-79d49154d0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37784, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支配", "is_correct": true, "explanation": "「〜に支配される」の形で、感情に心を動かされる意味の支配が入る。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は文章を別の言語に置き換えることで、恐怖の受け身には入らない。"}, {"text": "寄付", "is_correct": false, "explanation": "寄付は金品を贈ることで、恐怖とは結びつかない。"}, {"text": "製造", "is_correct": false, "explanation": "製造は物を作ることで、恐怖の受け身には入らない。"}], "explanations": {"支配": "「〜に支配される」の形で、感情に心を動かされる意味の支配が入る。", "翻訳": "翻訳は文章を別の言語に置き換えることで、恐怖の受け身には入らない。", "寄付": "寄付は金品を贈ることで、恐怖とは結びつかない。", "製造": "製造は物を作ることで、恐怖の受け身には入らない。"}, "sentence_index": 0, "correct_answer": "支配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "図書館の本を支配して、貸し出しの記録を付けた。", "explanation": "ここは〈管理〉の意味。支配は相手を従わせる意味で、貸し出しの記録を付けるような管理の行為には合わない。"}, {"text": "新人を支配して、仕事を教えた。", "explanation": "ここは〈指導〉の意味。支配は押さえつける意味で、仕事を教える行為には合わない。"}, {"text": "子どもを支配して、安全な場所へ移した。", "explanation": "ここは〈保護〉の意味。支配は従わせる意味で、守って避難させる行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37784, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支配", "is_correct": true, "explanation": "「〜しようとする」の形で、人の心を思いのままにする支配が入る。"}, {"text": "撮影", "is_correct": false, "explanation": "撮影は写真や映像を撮る行為で、気持ちを対象にしない。"}, {"text": "消毒", "is_correct": false, "explanation": "消毒は菌を取り除く行為で、気持ちとは結びつかない。"}, {"text": "引用", "is_correct": false, "explanation": "引用は他人の言葉を文中に示す行為で、気持ちを対象にしない。"}], "explanations": {"支配": "「〜しようとする」の形で、人の心を思いのままにする支配が入る。", "撮影": "撮影は写真や映像を撮る行為で、気持ちを対象にしない。", "消毒": "消毒は菌を取り除く行為で、気持ちとは結びつかない。", "引用": "引用は他人の言葉を文中に示す行為で、気持ちを対象にしない。"}, "sentence_index": 6, "correct_answer": "支配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お客様を出口まで支配した。", "explanation": "ここは〈案内〉の意味。支配は思い通りに従わせることで、出口へ導く行為には合わない。"}, {"text": "祖母を支配して、毎日の食事を手伝った。", "explanation": "ここは〈介護〉の意味。支配は従わせる意味で、世話をして手伝う行為には使わない。"}, {"text": "患者を支配して、薬を出した。", "explanation": "ここは〈診察〉の意味。支配は思い通りに従わせることで、患者を調べる行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37784, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は怒りを支配されて、乱暴な言葉を吐いた。", "corrected_sentence": "彼は怒りに支配されて、乱暴な言葉を吐いた。", "error_description": "「支配される」は「〜に」で支配する側を示す。「怒りを支配された」は誤りで、正しくは「怒りに支配された」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37784, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "恐怖に支配して、声が出なくなった。", "corrected_sentence": "恐怖に支配されて、声が出なくなった。", "error_description": "「支配する」は能動では「〜を」を取る。「恐怖に支配して」は誤りで、受け身の「支配されて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37785, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「受ける」の対象を示す「を」。「支配を受ける」と自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「支配が受ける」では主語が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や位置を示すので、「支配に受ける」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「支配で受ける」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「受ける」の対象を示す「を」。「支配を受ける」と自然。", "が": "「が」は主語を示すので、「支配が受ける」では主語が合わない。", "に": "「に」は相手や位置を示すので、「支配に受ける」は成り立たない。", "で": "「で」は手段や場所を示すので、「支配で受ける」は不自然。"}, "error_tags": {"が": "主語", "に": "相手・位置", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37785, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「支配する」の目的語を示す「を」。「情報を支配する」と自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、「情報と支配する」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「情報へ支配する」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「情報より支配する」は文として合わない。"}], "correct_answer": "を", "explanations": {"を": "「支配する」の目的語を示す「を」。「情報を支配する」と自然。", "と": "「と」は相手や並列を示すので、「情報と支配する」は成り立たない。", "へ": "「へ」は方向を示すので、「情報へ支配する」は不自然。", "より": "「より」は比較を示すので、「情報より支配する」は文として合わない。"}, "error_tags": {"と": "相手・並列", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37785, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事や人を自分の思い通りに統制したり、管理したりすること。", "primary_collocate": null, "pronunciation": "しはい", "ipa": "ɕihai", "syllable_count": 3, "sentences": [{"text": "その王は広い土地を支配し、人々から税を集めた。", "target_word": "支配", "complexity_tier": "T3", "furigana": "その王[おう]は広[ひろ]い土地[とち]を支配[しはい]し、人々[ひとびと]から税[ぜい]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "昔、この島は外国の支配を受けていた。", "target_word": "支配", "complexity_tier": "T3", "furigana": "昔[むかし]、この島[しま]は外国[がいこく]の支配[しはい]を受[う]けていた。", "sentence_source": "generated"}, {"text": "独裁者は言論を支配して、国民の自由を奪った。", "target_word": "支配", "complexity_tier": "T3", "furigana": "独裁者[どくさいしゃ]は言論[げんろん]を支配[しはい]して、国民[こくみん]の自由[じゆう]を奪[うば]った。", "sentence_source": "generated"}, {"text": "一つの家族が村の水と畑を支配していた。", "target_word": "支配", "complexity_tier": "T3", "furigana": "一[ひと]つの家族[かぞく]が村[むら]の水[みず]と畑[はたけ]を支配[しはい]していた。", "sentence_source": "generated"}, {"text": "大企業が業界を支配すると、小さい店は競争しにくくなる。", "target_word": "支配", "complexity_tier": "T3", "furigana": "大企業[だいきぎょう]が業界[ぎょうかい]を支配[しはい]すると、小[ちい]さい店[みせ]は競争[きょうそう]しにくくなる。", "sentence_source": "generated"}, {"text": "植民地の支配に反対して、人々は立ち上がった。", "target_word": "支配", "complexity_tier": "T3", "furigana": "植民地[しょくみんち]の支配[しはい]に反対[はんたい]して、人々[ひとびと]は立[た]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "王の支配が弱まると、各地で戦いが起こった。", "target_word": "支配", "complexity_tier": "T3", "furigana": "王[おう]の支配[しはい]が弱[よわ]まると、各地[かくち]で戦[たたか]いが起[お]こった。", "sentence_source": "generated"}, {"text": "彼は情報を支配することで、組織の中で力を持った。", "target_word": "支配", "complexity_tier": "T3", "furigana": "彼[かれ]は情報[じょうほう]を支配[しはい]することで、組織[そしき]の中[なか]で力[ちから]を持[も]った。", "sentence_source": "generated"}, {"text": "新しい領主は町を支配するため、役所を建てた。", "target_word": "支配", "complexity_tier": "T3", "furigana": "新[あたら]しい領主[りょうしゅ]は町[まち]を支配[しはい]するため、役所[やくしょ]を建[た]てた。", "sentence_source": "generated"}, {"text": "政府が放送を支配している国では、本当のニュースを知るのが難しい。", "target_word": "支配", "complexity_tier": "T3", "furigana": "政府[せいふ]が放送[ほうそう]を支配[しはい]している国[くに]では、本当[ほんとう]のニュースを知[し]るのが難[むずか]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "支配する", "label": "辞書形"}, {"form": "支配します", "label": "丁寧形"}, {"form": "支配した", "label": "過去形"}, {"form": "支配して", "label": "て形"}, {"form": "支配しない", "label": "否定形"}, {"form": "支配される", "label": "受身形"}, {"form": "支配している", "label": "継続形"}], "register": "中立（やや硬い書き言葉寄りの普通の文体）", "sense_fingerprint": "国・土地・組織・情報などを権力や力で統制し、管理下に置くこと（統治・管理としての支配）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09538d83-9a44-4f80-ba28-79d49154d0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37785, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支配", "is_correct": true, "explanation": "「土地を〜し」の形で、統治して管理下に置く支配が入る。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は言語を置き換える行為で、土地を対象にはできない。"}, {"text": "引用", "is_correct": false, "explanation": "引用は他人の言葉を示す行為で、土地を対象にはできない。"}, {"text": "解説", "is_correct": false, "explanation": "解説は説明する行為で、土地を対象にはできない。"}], "explanations": {"支配": "「土地を〜し」の形で、統治して管理下に置く支配が入る。", "翻訳": "翻訳は言語を置き換える行為で、土地を対象にはできない。", "引用": "引用は他人の言葉を示す行為で、土地を対象にはできない。", "解説": "解説は説明する行為で、土地を対象にはできない。"}, "sentence_index": 0, "correct_answer": "支配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数字を支配して、合計を出した。", "explanation": "ここは〈計算〉の意味。支配は統制の意味で、数字を足し合わせる行為には合わない。"}, {"text": "部屋を支配して、ほこりを払った。", "explanation": "ここは〈掃除〉の意味。支配は統治や統制の意味で、ほこりを払う行為には合わない。"}, {"text": "答案を支配して、点数を付けた。", "explanation": "ここは〈採点〉の意味。支配は統治の意味で、答案の点数を付ける行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37785, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支配", "is_correct": true, "explanation": "「王の〜が弱まる」の空欄に、統治としての支配が入る。"}, {"text": "製造", "is_correct": false, "explanation": "製造は物を作る行為で、王の統治には結びつかない。"}, {"text": "消毒", "is_correct": false, "explanation": "消毒は菌を取り除く行為で、王の統治の文脈では使わない。"}, {"text": "撮影", "is_correct": false, "explanation": "撮影は写真を撮る行為で、王の統治とは結びつかない。"}], "explanations": {"支配": "「王の〜が弱まる」の空欄に、統治としての支配が入る。", "製造": "製造は物を作る行為で、王の統治には結びつかない。", "消毒": "消毒は菌を取り除く行為で、王の統治の文脈では使わない。", "撮影": "撮影は写真を撮る行為で、王の統治とは結びつかない。"}, "sentence_index": 6, "correct_answer": "支配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長さを支配して、表に書いた。", "explanation": "ここは〈測定〉の意味。支配は統治の意味で、長さを量る行為には合わない。"}, {"text": "原文を支配して、本を出版した。", "explanation": "ここは〈翻訳〉の意味。支配は統治の意味で、文章を別の言語に置き換える行為には合わない。"}, {"text": "写真を支配して、展示した。", "explanation": "ここは〈撮影〉の意味。支配は統治の意味で、写真を撮る行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37785, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その帝国は長い間、島々に支配していた。", "corrected_sentence": "その帝国は長い間、島々を支配していた。", "error_description": "「支配する」は「を」で目的語を示す。「島々に支配」は誤りで、正しくは「島々を支配」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37785, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼らは島を支配で、税を取った。", "corrected_sentence": "彼らは島を支配して、税を取った。", "error_description": "「支配する」は「支配して」と連用形でつないで後続に続ける。「支配で」は形の誤りで、正しくは「支配して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37786, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "読み解く対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「意味に読み解きます」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「意味へ読み解きます」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「読み解きます」は他動詞なので、読み解く対象を「が」では示せない。"}], "correct_answer": "を", "explanations": {"を": "読み解く対象を示す。", "に": "「意味に読み解きます」は成り立たない。", "へ": "「意味へ読み解きます」は成り立たない。", "が": "「読み解きます」は他動詞なので、読み解く対象を「が」では示せない。"}, "error_tags": {"に": "target", "へ": "direction", "が": "subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37786, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "読み解かれる対象を主語として示す。"}, {"text": "の", "is_correct": false, "explanation": "「手がかりの読み解かれて」は名詞と動詞がつながらず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「手がかりへ読み解かれて」は成り立たない。"}, {"text": "や", "is_correct": false, "explanation": "「や」は名詞を並べる助詞で、後に名詞が必要。「手がかりや読み解かれて」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "読み解かれる対象を主語として示す。", "の": "「手がかりの読み解かれて」は名詞と動詞がつながらず、文が成り立たない。", "へ": "「手がかりへ読み解かれて」は成り立たない。", "や": "「や」は名詞を並べる助詞で、後に名詞が必要。「手がかりや読み解かれて」は成り立たない。"}, "error_tags": {"の": "possessive", "へ": "direction", "や": "listing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37786, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "むずかしいことを、よく考えて、わかるようにすること。", "primary_collocate": null, "pronunciation": "よみとく", "ipa": "jomitoku", "syllable_count": 4, "sentences": [{"text": "なぞを読み解く。", "target_word": "読み解く", "complexity_tier": "T1", "furigana": "なぞを読[よ]み解[と]く。", "sentence_source": "generated"}, {"text": "先生が問題の意味を読み解きます。", "target_word": "読み解きます", "complexity_tier": "T2", "furigana": "先生[せんせい]が問題[もんだい]の意味[いみ]を読[よ]み解[と]きます。", "sentence_source": "generated"}, {"text": "長い文章を読み解く練習をした。", "target_word": "読み解く", "complexity_tier": "T3", "furigana": "長[なが]い文章[ぶんしょう]を読[よ]み解[と]く練習[れんしゅう]をした。", "sentence_source": "generated"}, {"text": "地図を読み解いて、道を見つけた。", "target_word": "読み解いて", "complexity_tier": "T3", "furigana": "地図[ちず]を読[よ]み解[と]いて、道[みち]を見[み]つけた。", "sentence_source": "generated"}, {"text": "この記号はだれも読み解けなかった。", "target_word": "読み解けなかった", "complexity_tier": "T3", "furigana": "この記号[きごう]はだれも読[よ]み解[と]けなかった。", "sentence_source": "generated"}, {"text": "古い言葉を読み解く方法を学んでいる。", "target_word": "読み解く", "complexity_tier": "T3", "furigana": "古[ふる]い言葉[ことば]を読[よ]み解[と]く方法[ほうほう]を学[まな]んでいる。", "sentence_source": "generated"}, {"text": "彼女は夢の意味を読み解こうとした。", "target_word": "読み解こう", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は夢[ゆめ]の意味[いみ]を読[よ]み解[と]こうとした。", "sentence_source": "generated"}, {"text": "手がかりが読み解かれて、事件は解決した。", "target_word": "読み解かれて", "complexity_tier": "T4", "furigana": "手[て]がかりが読[よ]み解[と]かれて、事件[じけん]は解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "難しい話を読み解くには、時間がかかる。", "target_word": "読み解く", "complexity_tier": "T4", "furigana": "難[むずか]しい話[はなし]を読[よ]み解[と]くには、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "数字の裏の意味を読み解いてみよう。", "target_word": "読み解いて", "complexity_tier": "T4", "furigana": "数字[すうじ]の裏[うら]の意味[いみ]を読[よ]み解[と]いてみよう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "読み解いて", "label": "活用"}, {"form": "読み解けない", "label": "活用"}, {"form": "読み解かれる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 難しい事を考えて分かるようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37786, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "読み解く", "is_correct": true, "explanation": "なぞを考えて分かるようにする。"}, {"text": "運ぶ", "is_correct": false, "explanation": "形は合うが意味が合わない。なぞは運べない。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが意味が合わない。なぞは洗えない。"}, {"text": "売る", "is_correct": false, "explanation": "形は合うが意味が合わない。なぞは売れない。"}], "explanations": {"読み解く": "なぞを考えて分かるようにする。", "運ぶ": "形は合うが意味が合わない。なぞは運べない。", "洗う": "形は合うが意味が合わない。なぞは洗えない。", "売る": "形は合うが意味が合わない。なぞは売れない。"}, "sentence_index": 0, "correct_answer": "読み解く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バナナを読み解いて、道を見つけた。", "explanation": "バナナは考えて理解する難しい対象ではない。"}, {"text": "靴を読み解いて、道を見つけた。", "explanation": "靴は読み解く対象ではない。"}, {"text": "椅子を読み解いて、道を見つけた。", "explanation": "椅子は読み解く対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
