INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37787, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複雑な事柄や文章の意味を、一つ一つ分析しながら理解すること。", "primary_collocate": null, "pronunciation": "よみとく", "ipa": "jomitoku", "syllable_count": 4, "sentences": [{"text": "建築を単なる機能の集合体ではなく、記号が織りなすテキストとして読み解く態度が、ポスト構造主義に基づく批評の核心です。", "target_word": "読み解く", "complexity_tier": "T6", "furigana": "建築[けんちく]を単[たん]なる機能[きのう]の集合体[しゅうごうたい]ではなく、記号[きごう]が織[お]りなすテキストとして読[よ]み解[と]く態度[たいど]が、ポスト構造主義[こうぞうしゅぎ]に基[もと]づく批評[ひひょう]の核心[かくしん]です。", "sentence_source": "mined"}, {"text": "古文書を読み解く。", "target_word": "読み解く", "complexity_tier": "T1", "furigana": "古文書[こもんじょ]を読[よ]み解[と]く。", "sentence_source": "generated"}, {"text": "先生は詩の意味を読み解きました。", "target_word": "読み解きました", "complexity_tier": "T2", "furigana": "先生[せんせい]は詩[し]の意味[いみ]を読[よ]み解[と]きました。", "sentence_source": "generated"}, {"text": "この図は、データを読み解く鍵になる。", "target_word": "読み解く", "complexity_tier": "T3", "furigana": "この図[ず]は、データを読[よ]み解[と]く鍵[かぎ]になる。", "sentence_source": "generated"}, {"text": "難しい契約書を読み解いている。", "target_word": "読み解いている", "complexity_tier": "T3", "furigana": "難[むずか]しい契約書[けいやくしょ]を読[よ]み解[と]いている。", "sentence_source": "generated"}, {"text": "暗号を読み解くことができた。", "target_word": "読み解く", "complexity_tier": "T3", "furigana": "暗号[あんごう]を読[よ]み解[と]くことができた。", "sentence_source": "generated"}, {"text": "歴史の流れを読み解こうとする研究者が増えた。", "target_word": "読み解こう", "complexity_tier": "T4", "furigana": "歴史[れきし]の流[なが]れを読[よ]み解[と]こうとする研究者[けんきゅうしゃ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "彼の表情から本心を読み解くのは難しい。", "target_word": "読み解く", "complexity_tier": "T4", "furigana": "彼[かれ]の表情[ひょうじょう]から本心[ほんしん]を読[よ]み解[と]くのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "資料を読み解けば、原因が分かるはずだ。", "target_word": "読み解けば", "complexity_tier": "T4", "furigana": "資料[しりょう]を読[よ]み解[と]けば、原因[げんいん]が分[わ]かるはずだ。", "sentence_source": "generated"}, {"text": "絵に隠された意味は、専門家によって読み解かれた。", "target_word": "読み解かれた", "complexity_tier": "T4", "furigana": "絵[え]に隠[かく]された意味[いみ]は、専門家[せんもんか]によって読[よ]み解[と]かれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "読み解いた", "label": "活用"}, {"form": "読み解かれる", "label": "活用"}, {"form": "読み解ける", "label": "活用"}, {"form": "読み解き", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 複雑な内容を分析して理解する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37787, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "読み解く", "is_correct": true, "explanation": "テキストとして分析し理解する態度という意味に合う。"}, {"text": "売り払う", "is_correct": false, "explanation": "形は合うが意味が合わない。批評の態度を表さない。"}, {"text": "追い払う", "is_correct": false, "explanation": "形は合うが意味が合わない。テキストを追い払う態度は批評の核心にならない。"}, {"text": "飛び越える", "is_correct": false, "explanation": "形は合うが意味が合わない。記号を理解する態度にならない。"}], "explanations": {"読み解く": "テキストとして分析し理解する態度という意味に合う。", "売り払う": "形は合うが意味が合わない。批評の態度を表さない。", "追い払う": "形は合うが意味が合わない。テキストを追い払う態度は批評の核心にならない。", "飛び越える": "形は合うが意味が合わない。記号を理解する態度にならない。"}, "sentence_index": 0, "correct_answer": "読み解く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この図は、お茶を読み解く鍵になる。", "explanation": "お茶は分析して理解する複雑な内容ではない。"}, {"text": "この図は、靴を読み解く鍵になる。", "explanation": "靴は意味を読み取る対象ではない。"}, {"text": "この図は、机を読み解く鍵になる。", "explanation": "机は読み解く対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37787, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "読み解こう", "is_correct": true, "explanation": "「〜とする」に続く意志形で、歴史の流れを理解しようとする意味。"}, {"text": "飲もう", "is_correct": false, "explanation": "形は合うが意味が合わない。歴史の流れは飲めない。"}, {"text": "運ぼう", "is_correct": false, "explanation": "形は合うが意味が合わない。研究者の目的に合わない。"}, {"text": "洗おう", "is_correct": false, "explanation": "形は合うが意味が合わない。歴史の流れは洗えない。"}], "explanations": {"読み解こう": "「〜とする」に続く意志形で、歴史の流れを理解しようとする意味。", "飲もう": "形は合うが意味が合わない。歴史の流れは飲めない。", "運ぼう": "形は合うが意味が合わない。研究者の目的に合わない。", "洗おう": "形は合うが意味が合わない。歴史の流れは洗えない。"}, "sentence_index": 6, "correct_answer": "読み解こう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パンは、専門家によって読み解かれた。", "explanation": "パンは意味を分析して理解する対象ではない。"}, {"text": "机は、専門家によって読み解かれた。", "explanation": "机は読み解く対象ではない。"}, {"text": "雨は、専門家によって読み解かれた。", "explanation": "雨そのものは読み解く対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37787, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い手紙に読み解く。", "corrected_sentence": "古い手紙を読み解く。", "error_description": "読み解く対象は「に」ではなく「を」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "読み解く", "is_correct": true, "explanation": "文末の終止形。"}, {"text": "読み解か", "is_correct": false, "explanation": "未然形は「ない」などが続く形で、そのままでは文を終えられない。"}, {"text": "読み解き", "is_correct": false, "explanation": "連用形では文が終わらない。"}, {"text": "読み解い", "is_correct": false, "explanation": "音便の形は「て」「た」が続かないと使えない。"}], "correct_form": "読み解く", "base_form": "読み解く", "form_label": "終止形", "sentence_index": 1, "explanations": {"読み解く": "文末の終止形。", "読み解か": "未然形は「ない」などが続く形で、そのままでは文を終えられない。", "読み解き": "連用形では文が終わらない。", "読み解い": "音便の形は「て」「た」が続かないと使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37787, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の表情から本心が読み解くのは難しい。", "corrected_sentence": "彼女の表情から本心を読み解くのは難しい。", "error_description": "「読み解く」の対象は「が」ではなく「を」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "読み解く", "is_correct": true, "explanation": "「のは」の「の」に続く連体形。"}, {"text": "読み解いて", "is_correct": false, "explanation": "て形は「のは」に続かない。"}, {"text": "読み解き", "is_correct": false, "explanation": "連用形は「のは」に続かない。"}, {"text": "読み解こう", "is_correct": false, "explanation": "意志形は「のは」に続かない。"}], "correct_form": "読み解く", "base_form": "読み解く", "form_label": "連体形", "sentence_index": 7, "explanations": {"読み解く": "「のは」の「の」に続く連体形。", "読み解いて": "て形は「のは」に続かない。", "読み解き": "連用形は「のは」に続かない。", "読み解こう": "意志形は「のは」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37788, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「喧騒のせいで」の「の」で、名詞に続けて「せいで」とつながる自然な形。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」では「喧騒がせいで」となり、文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「喧騒をせいで」となり、不自然。"}, {"text": "に", "is_correct": false, "explanation": "方向・場所の「に」では「喧騒にせいで」と続かない。"}], "correct_answer": "の", "explanations": {"の": "「喧騒のせいで」の「の」で、名詞に続けて「せいで」とつながる自然な形。", "が": "主語の「が」では「喧騒がせいで」となり、文として成り立たない。", "を": "目的語の「を」では「喧騒をせいで」となり、不自然。", "に": "方向・場所の「に」では「喧騒にせいで」と続かない。"}, "error_tags": {"が": "subject", "を": "object", "に": "location"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静寂", "is_correct": true, "explanation": "音がなく静かな状態で、騒がしい喧騒の反対語として辞典に載る。"}, {"text": "旋律", "is_correct": false, "explanation": "音楽の流れを表し、騒がしさの対義語にはならない。"}, {"text": "余韻", "is_correct": false, "explanation": "音が消えた後に残る響きで、騒がしさの反対語ではない。"}, {"text": "香り", "is_correct": false, "explanation": "においを表す語で、音の対義関係には入らない。"}], "correct_answer": "静寂", "explanations": {"静寂": "音がなく静かな状態で、騒がしい喧騒の反対語として辞典に載る。", "旋律": "音楽の流れを表し、騒がしさの対義語にはならない。", "余韻": "音が消えた後に残る響きで、騒がしさの反対語ではない。", "香り": "においを表す語で、音の対義関係には入らない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37788, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。喧騒を話題にして、響いたと述べる文として自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「喧騒を遠くまで響いていた」となり、響くという自動詞の文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「喧騒へ遠くまで響いていた」と主題の位置に収まらず不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は後ろに名詞を続けるため、「喧騒の遠くまで」では文が途切れる。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。喧騒を話題にして、響いたと述べる文として自然。", "を": "目的語の「を」では「喧騒を遠くまで響いていた」となり、響くという自動詞の文に合わない。", "へ": "方向の「へ」では「喧騒へ遠くまで響いていた」と主題の位置に収まらず不自然。", "の": "連体の「の」は後ろに名詞を続けるため、「喧騒の遠くまで」では文が途切れる。"}, "error_tags": {"を": "object", "へ": "direction", "の": "modifier"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静寂", "is_correct": true, "explanation": "音がなく静かな状態で、騒がしい喧騒の反対語として辞典に載る。"}, {"text": "水面", "is_correct": false, "explanation": "水の表面を表す語で、音の大小の対義関係はない。"}, {"text": "陶器", "is_correct": false, "explanation": "焼き物を表す語で、音の反対語ではない。"}, {"text": "幸福", "is_correct": false, "explanation": "心の状態を表す語で、騒がしさの反対語ではない。"}], "correct_answer": "静寂", "explanations": {"静寂": "音がなく静かな状態で、騒がしい喧騒の反対語として辞典に載る。", "水面": "水の表面を表す語で、音の大小の対義関係はない。", "陶器": "焼き物を表す語で、音の反対語ではない。", "幸福": "心の状態を表す語で、騒がしさの反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37788, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まわりの音がうるさいこと。", "primary_collocate": null, "pronunciation": "けんそう", "ipa": "kensoː", "syllable_count": 4, "sentences": [{"text": "窓を閉めても、外の喧騒が部屋に入ってきて眠れなかった。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "窓[まど]を閉[し]めても、外[そと]の喧騒[けんそう]が部屋[へや]に入[はい]ってきて眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "工事の喧騒のせいで、電話の声が聞こえません。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "工事[こうじ]の喧騒[けんそう]のせいで、電話[でんわ]の声[こえ]が聞[き]こえません。", "sentence_source": "generated"}, {"text": "図書館に入ると、道路の喧騒がうそのように消えた。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "図書館[としょかん]に入[はい]ると、道路[どうろ]の喧騒[けんそう]がうそのように消[き]えた。", "sentence_source": "generated"}, {"text": "駅前の喧騒から離れて、静かな公園で本を読んだ。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の喧騒[けんそう]から離[はな]れて、静[しず]かな公園[こうえん]で本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "夜になると、昼間の喧騒が止んで町は静かになる。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "夜[よる]になると、昼間[ひるま]の喧騒[けんそう]が止[や]んで町[まち]は静[しず]かになる。", "sentence_source": "generated"}, {"text": "隣の部屋の喧騒が気になって、勉強に集中できない。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "隣[となり]の部屋[へや]の喧騒[けんそう]が気[き]になって、勉強[べんきょう]に集中[しゅうちゅう]できない。", "sentence_source": "generated"}, {"text": "山の宿は、都会の喧騒がまったく聞こえない場所にある。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "山[やま]の宿[やど]は、都会[とかい]の喧騒[けんそう]がまったく聞[き]こえない場所[ばしょ]にある。", "sentence_source": "generated"}, {"text": "祭りの喧騒は遠くまで響いていた。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "祭[まつ]りの喧騒[けんそう]は遠[とお]くまで響[ひび]いていた。", "sentence_source": "generated"}, {"text": "彼は喧騒の中でも、赤ちゃんのように眠れる。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "彼[かれ]は喧騒[けんそう]の中[なか]でも、赤[あか]ちゃんのように眠[ねむ]れる。", "sentence_source": "generated"}, {"text": "イヤホンをして、電車の喧騒を消した。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "イヤホンをして、電車[でんしゃ]の喧騒[けんそう]を消[け]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喧騒", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "周囲のうるさい音・騒音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37788, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喧騒", "is_correct": true, "explanation": "外からの物音を表し、部屋に入ってくるものとして自然に合う。"}, {"text": "貧困", "is_correct": false, "explanation": "社会の状態を表す語で、音のように部屋へ入ってくる文脈に合わない。"}, {"text": "親切", "is_correct": false, "explanation": "人の態度を表す語で、物音として入ってくる文脈に合わない。"}, {"text": "規則", "is_correct": false, "explanation": "決まりごとを表す語で、音として部屋に入るという意味にならない。"}], "explanations": {"喧騒": "外からの物音を表し、部屋に入ってくるものとして自然に合う。", "貧困": "社会の状態を表す語で、音のように部屋へ入ってくる文脈に合わない。", "親切": "人の態度を表す語で、物音として入ってくる文脈に合わない。", "規則": "決まりごとを表す語で、音として部屋に入るという意味にならない。"}, "sentence_index": 0, "correct_answer": "喧騒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜の図書館で、紙をめくる喧騒がそっと響いた。", "explanation": "喧騒は大きな音の騒がしさを言い、そっと鳴る紙の音には使わない。"}, {"text": "昨日、兄と喧騒になって、しばらく口をきかなかった。", "explanation": "喧騒は周囲の騒がしい音を言い、兄弟の口論には使わない。"}, {"text": "今週は予定が立て込んで、喧騒の毎日だった。", "explanation": "喧騒は音のうるささを言い、予定の忙しさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37788, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喧騒", "is_correct": true, "explanation": "都会の騒がしさを表し、聞こえないという文脈に合う。"}, {"text": "繁栄", "is_correct": false, "explanation": "栄えることを表す語で、聞こえる・聞こえないの対象にはならない。"}, {"text": "伝統", "is_correct": false, "explanation": "受け継がれる習わしで、音として聞こえるものではない。"}, {"text": "権利", "is_correct": false, "explanation": "法的な資格を表す語で、聞こえないという文脈に合わない。"}], "explanations": {"喧騒": "都会の騒がしさを表し、聞こえないという文脈に合う。", "繁栄": "栄えることを表す語で、聞こえる・聞こえないの対象にはならない。", "伝統": "受け継がれる習わしで、音として聞こえるものではない。", "権利": "法的な資格を表す語で、聞こえないという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "喧騒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "静かな会議室に、咳払いの喧騒が響いた。", "explanation": "喧騒は周囲の騒がしい音を言い、ひとつの咳払いには使わない。"}, {"text": "台所からおいしい喧騒が漂ってきた。", "explanation": "喧騒は音の騒がしさを言い、香りが漂うことには使わない。"}, {"text": "夜道で、ひとりの悲鳴の喧騒が上がった。", "explanation": "喧騒は多くの音が重なった騒がしさを言い、ひとりの悲鳴には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37788, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅前の喧騒を静まって、ほっとした。", "corrected_sentence": "駅前の喧騒が静まって、ほっとした。", "error_description": "「静まる」は自動詞なので、主語の「喧騒」には「が」を使う。「を」は他動詞につく助詞で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37788, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の宿は、都会の喧騒に遠く離れている。", "corrected_sentence": "山の宿は、都会の喧騒から遠く離れている。", "error_description": "「～から遠く離れる」は起点を示す「から」を使う。「に」では「離れる」と続かず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37789, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。喧騒を話題にして、静まったと述べる文として自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「喧騒をゆっくり静まった」となり、自動詞の文に合わない。"}, {"text": "に", "is_correct": false, "explanation": "方向の「に」では「喧騒にゆっくり静まった」が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は後ろに名詞を続けるため、「喧騒の静まった」では文が終わらない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。喧騒を話題にして、静まったと述べる文として自然。", "を": "目的語の「を」では「喧騒をゆっくり静まった」となり、自動詞の文に合わない。", "に": "方向の「に」では「喧騒にゆっくり静まった」が成り立たない。", "の": "連体の「の」は後ろに名詞を続けるため、「喧騒の静まった」では文が終わらない。"}, "error_tags": {"を": "object", "に": "direction", "の": "modifier"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37789, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「離れる」の対象を示す「を」で、都会の喧騒から離れるという文として自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では「喧騒の離れて」と続かず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "方向の「に」では「喧騒に離れて」と不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では「喧騒で離れて」と続かない。"}], "correct_answer": "を", "explanations": {"を": "「離れる」の対象を示す「を」で、都会の喧騒から離れるという文として自然。", "の": "連体の「の」では「喧騒の離れて」と続かず、文が成り立たない。", "に": "方向の「に」では「喧騒に離れて」と不自然。", "で": "手段の「で」では「喧騒で離れて」と続かない。"}, "error_tags": {"の": "modifier", "に": "direction", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37789, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "多くの人が集まって騒ぐこと。また、その騒がしいようす。", "primary_collocate": null, "pronunciation": "けんそう", "ipa": "kensoː", "syllable_count": 4, "sentences": [{"text": "年末の商店街は、買い物客でにぎわい、喧騒に包まれていた。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "年末[ねんまつ]の商店街[しょうてんがい]は、買[か]い物客[ものきゃく]でにぎわい、喧騒[けんそう]に包[つつ]まれていた。", "sentence_source": "generated"}, {"text": "試合が終わると、スタジアムの喧騒はゆっくり静まった。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "試合[しあい]が終[お]わると、スタジアムの喧騒[けんそう]はゆっくり静[しず]まった。", "sentence_source": "generated"}, {"text": "朝の市場は、売り手と客の喧騒で活気にあふれている。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "朝[あさ]の市場[いちば]は、売[う]り手[て]と客[きゃく]の喧騒[けんそう]で活気[かっき]にあふれている。", "sentence_source": "generated"}, {"text": "渋谷の人混みの喧騒が好きだという人もいる。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "渋谷[しぶや]の人混[ひとご]みの喧騒[けんそう]が好[す]きだという人[ひと]もいる。", "sentence_source": "generated"}, {"text": "休日の遊園地は、子どもたちの喧騒でいっぱいだった。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "休日[きゅうじつ]の遊園地[ゆうえんち]は、子[こ]どもたちの喧騒[けんそう]でいっぱいだった。", "sentence_source": "generated"}, {"text": "先生が入ってくると、教室の喧騒はすぐに収まった。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "先生[せんせい]が入[はい]ってくると、教室[きょうしつ]の喧騒[けんそう]はすぐに収[おさ]まった。", "sentence_source": "generated"}, {"text": "事件の後、町は報道陣の喧騒に巻き込まれた。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "事件[じけん]の後[あと]、町[まち]は報道陣[ほうどうじん]の喧騒[けんそう]に巻[ま]き込[こ]まれた。", "sentence_source": "generated"}, {"text": "彼は都会の喧騒を離れて、田舎で暮らし始めた。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "彼[かれ]は都会[とかい]の喧騒[けんそう]を離[はな]れて、田舎[いなか]で暮[く]らし始[はじ]めた。", "sentence_source": "generated"}, {"text": "花火大会の夜、川沿いは人々の喧騒に満ちていた。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "花火大会[はなびたいかい]の夜[よる]、川沿[かわぞ]いは人々[ひとびと]の喧騒[けんそう]に満[み]ちていた。", "sentence_source": "generated"}, {"text": "駅のホームは、帰宅する人たちの喧騒であふれていた。", "target_word": "喧騒", "complexity_tier": "T3", "furigana": "駅[えき]のホームは、帰宅[きたく]する人[ひと]たちの喧騒[けんそう]であふれていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喧騒", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人々が集まるにぎやかな騒ぎ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37789, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喧騒", "is_correct": true, "explanation": "買い物客のにぎやかな騒ぎを表し、商店街を包むものとして合う。"}, {"text": "規則", "is_correct": false, "explanation": "決まりごとを表す語で、人々の騒ぎに包まれる意味にならない。"}, {"text": "親切", "is_correct": false, "explanation": "人の態度を表す語で、場を包む意味にならない。"}, {"text": "郵便", "is_correct": false, "explanation": "配達の仕組みを表す語で、商店街の雰囲気を包む文脈に合わない。"}], "explanations": {"喧騒": "買い物客のにぎやかな騒ぎを表し、商店街を包むものとして合う。", "規則": "決まりごとを表す語で、人々の騒ぎに包まれる意味にならない。", "親切": "人の態度を表す語で、場を包む意味にならない。", "郵便": "配達の仕組みを表す語で、商店街の雰囲気を包む文脈に合わない。"}, "sentence_index": 0, "correct_answer": "喧騒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "隣の人の寝言の喧騒で、夜中に目が覚めた。", "explanation": "喧騒は多くの人が騒ぐことで、ひとりの寝言には使わない。"}, {"text": "改札前の喧騒は、静かに一列に並んだ行列だった。", "explanation": "喧騒は人々のにぎやかな騒ぎで、静かに整然と並んだ行列とは違う。"}, {"text": "庭先の一羽の鳥の鳴き声が、喧騒になって響いた。", "explanation": "喧騒は人々が集まる騒ぎで、一羽の鳥の声には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37789, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喧騒", "is_correct": true, "explanation": "大勢の騒ぎを表し、報道陣の騒ぎに巻き込まれるという文脈に合う。"}, {"text": "伝統", "is_correct": false, "explanation": "受け継がれる習わしで、人の騒ぎに巻き込まれる意味にならない。"}, {"text": "繁栄", "is_correct": false, "explanation": "栄えることを表す語で、巻き込まれるものではない。"}, {"text": "請求書", "is_correct": false, "explanation": "書類を表す語で、人々の騒ぎに巻き込まれる文脈に合わない。"}], "explanations": {"喧騒": "大勢の騒ぎを表し、報道陣の騒ぎに巻き込まれるという文脈に合う。", "伝統": "受け継がれる習わしで、人の騒ぎに巻き込まれる意味にならない。", "繁栄": "栄えることを表す語で、巻き込まれるものではない。", "請求書": "書類を表す語で、人々の騒ぎに巻き込まれる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "喧騒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ひとりの独り言が、部屋いっぱいの喧騒になって響いた。", "explanation": "喧騒は多くの人の騒ぎで、ひとりの独り言には当てはまらない。"}, {"text": "重いため息の喧騒が部屋に広がった。", "explanation": "喧騒は大勢の騒がしさを言い、ため息には使わない。"}, {"text": "夜の湖で、魚の跳ねる喧騒が一度だけ聞こえた。", "explanation": "喧騒は多くの人の騒ぎで、一度の水音には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37789, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅の改札前で、人々の喧騒を急に途切れた。", "corrected_sentence": "駅の改札前で、人々の喧騒が急に途切れた。", "error_description": "「途切れる」は自動詞なので、主語の「喧騒」には「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37789, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山道では、遠くの町の喧騒をまったく届かない。", "corrected_sentence": "山道では、遠くの町の喧騒がまったく届かない。", "error_description": "「届く」は自動詞なので、主語の「喧騒」には「が」を使う。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
