INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37790, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ずっとずっとまえのこと。", "primary_collocate": null, "pronunciation": "むかしむかし", "ipa": "mukaɕimukaɕi", "syllable_count": 6, "sentences": [{"text": "昔々、山の奥に小さな村がありました。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]、山[やま]の奥[おく]に小[ちい]さな村[むら]がありました。", "sentence_source": "generated"}, {"text": "昔々、この村で何があったのか、だれも本当の話を知りません。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]、この村で何があったのか、だれも本当の話を知りません。", "sentence_source": "generated"}, {"text": "祖母は昔々、この町で何があったかを、夜ごと話してくれた。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "祖母は昔々[むかしむかし]、この町で何があったかを、夜ごと話してくれた。", "sentence_source": "generated"}, {"text": "この木は昔々、この場所に植えられたそうです。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "この木は昔々[むかしむかし]、この場所に植えられたそうです。", "sentence_source": "generated"}, {"text": "昔々、人々は火を神様のものだと考えていた。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]、人々[ひとびと]は火[ひ]を神様[かみさま]のものだと考[かんが]えていた。", "sentence_source": "generated"}, {"text": "昔々あるところに、やさしい王様が住んでいました。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]あるところに、やさしい王様[おうさま]が住[す]んでいました。", "sentence_source": "generated"}, {"text": "昔々、ここで大きな戦があったが、もう記録も残っていない。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]、ここで大きな戦があったが、もう記録も残っていない。", "sentence_source": "generated"}, {"text": "博物館で見た道具は、昔々、人々が使っていたものだ。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "博物館で見た道具は、昔々[むかしむかし]、人々が使っていたものだ。", "sentence_source": "generated"}, {"text": "昔々、この町では毎年お祭りが開かれていたそうだ。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]、この町では毎年お祭りが開かれていたそうだ。", "sentence_source": "generated"}, {"text": "昔々、この川には大きな魚がたくさんいたそうだ。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]、この川[かわ]には大[おお]きな魚[さかな]がたくさんいたそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "昔々", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ずっと前の過去・昔話の語り出し", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37790, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昔々", "is_correct": true, "explanation": "遠い昔を表し、昔話の語り出しとして「ありました」と合う。"}, {"text": "明日", "is_correct": false, "explanation": "未来の日を表し、過去の話の語り出しと合わない。"}, {"text": "来年", "is_correct": false, "explanation": "未来の年を表し、過去の出来事を語る文脈に合わない。"}, {"text": "毎朝", "is_correct": false, "explanation": "毎日の繰り返しを表し、昔話の語り出しには合わない。"}], "explanations": {"昔々": "遠い昔を表し、昔話の語り出しとして「ありました」と合う。", "明日": "未来の日を表し、過去の話の語り出しと合わない。", "来年": "未来の年を表し、過去の出来事を語る文脈に合わない。", "毎朝": "毎日の繰り返しを表し、昔話の語り出しには合わない。"}, "sentence_index": 0, "correct_answer": "昔々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この木は昔々、ついさっき植えたばかりだ。", "explanation": "昔々は遠い過去を指し、ついさっきの出来事とは矛盾する。"}, {"text": "この木は昔々、来週ここに植える予定だ。", "explanation": "昔々は過去を表すので、来週の予定とは両立しない。"}, {"text": "この木は昔々、将来きっと大きく育つだろう。", "explanation": "昔々は過去を表すので、将来の話とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37790, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昔々", "is_correct": true, "explanation": "遠い昔を表し、戦があった時代の話として記録の文脈に合う。"}, {"text": "来週", "is_correct": false, "explanation": "未来の週を表し、過去の戦の話と矛盾する。"}, {"text": "来年", "is_correct": false, "explanation": "未来の年を表し、過去の戦の話と合わない。"}, {"text": "明後日", "is_correct": false, "explanation": "近い未来を表し、過去の出来事には合わない。"}], "explanations": {"昔々": "遠い昔を表し、戦があった時代の話として記録の文脈に合う。", "来週": "未来の週を表し、過去の戦の話と矛盾する。", "来年": "未来の年を表し、過去の戦の話と合わない。", "明後日": "近い未来を表し、過去の出来事には合わない。"}, "sentence_index": 6, "correct_answer": "昔々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昔々、この川で数日前に大きな魚を釣った。", "explanation": "昔々は遠い昔を指し、数日前の出来事とは両立しない。"}, {"text": "昔々、先月この川で大きな魚がたくさん捕れた。", "explanation": "昔々は遠い昔を指し、先月という近い時期とは合わない。"}, {"text": "昔々、今年この川には大きな魚がたくさんいた。", "explanation": "昔々は遠い昔を指し、今年という近い時期とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37790, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昔々を、この森で狼が遠吠えをしていたそうだ。", "corrected_sentence": "昔々は、この森で狼が遠吠えをしていたそうだ。", "error_description": "「昔々」は時を示す語で、「は」で話題にする。「を」を付けると目的語になり、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37790, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔々が町並みを、古い絵図で確かめた。", "corrected_sentence": "昔々の町並みを、古い絵図で確かめた。", "error_description": "「昔々の町並み」の「の」は名詞を修飾する助詞。「が」にすると修飾関係が崩れ、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37791, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を示す「に」。「昔々に、人の手で作られた」と時期を述べる自然な形。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「昔々を作られた」と不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では「昔々で作られた」が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列の「と」では「昔々と作られた」が不自然。"}], "correct_answer": "に", "explanations": {"に": "時点を示す「に」。「昔々に、人の手で作られた」と時期を述べる自然な形。", "を": "目的語の「を」では「昔々を作られた」と不自然。", "で": "手段の「で」では「昔々で作られた」が成り立たない。", "と": "相手・並列の「と」では「昔々と作られた」が不自然。"}, "error_tags": {"を": "object", "で": "means", "と": "with"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37791, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を示す「に」。「昔々に建てられた」と建造の時期を述べる自然な形。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」では「昔々が建てられた」と受け身の文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「昔々へ建てられた」が不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では「建てられた」の対象が立たず、文が続かない。"}], "correct_answer": "に", "explanations": {"に": "時点を示す「に」。「昔々に建てられた」と建造の時期を述べる自然な形。", "が": "主語の「が」では「昔々が建てられた」と受け身の文が成り立たない。", "へ": "方向の「へ」では「昔々へ建てられた」が不自然。", "の": "連体の「の」では「建てられた」の対象が立たず、文が続かない。"}, "error_tags": {"が": "subject", "へ": "direction", "の": "modifier"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37791, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "遠い過去のある時代。", "primary_collocate": null, "pronunciation": "むかしむかし", "ipa": "mukaɕimukaɕi", "syllable_count": 6, "sentences": [{"text": "昔々には、人々が星を見て季節を知っていた。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]には、人々が星を見て季節を知っていた。", "sentence_source": "generated"}, {"text": "この石は昔々に、人の手で作られたものだ。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "この石は昔々[むかしむかし]に、人の手で作られたものだ。", "sentence_source": "generated"}, {"text": "昔々には日本にも、今のような電気がなかった。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]には日本にも、今のような電気がなかった。", "sentence_source": "generated"}, {"text": "本で昔々を調べて、その暮らしを絵にかいた。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "本で昔々[むかしむかし]を調べて、その暮らしを絵にかいた。", "sentence_source": "generated"}, {"text": "恐竜がいた昔々には、地球の姿が今とまったく違った。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "恐竜がいた昔々[むかしむかし]には、地球の姿が今とまったく違った。", "sentence_source": "generated"}, {"text": "昔々に生まれた言い伝えが、この島には今も残っている。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]に生まれた言い伝えが、この島には今も残っている。", "sentence_source": "generated"}, {"text": "博士は昔々を研究して、その暮らしを明らかにした。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "博士は昔々[むかしむかし]を研究して、その暮らしを明らかにした。", "sentence_source": "generated"}, {"text": "この城は昔々に建てられたもので、今は草に埋もれている。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "この城は昔々[むかしむかし]に建てられたもので、今は草に埋もれている。", "sentence_source": "generated"}, {"text": "昔々には、町は今よりずっと小さかった。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]には、町は今よりずっと小さかった。", "sentence_source": "generated"}, {"text": "この歌は昔々に生まれ、歌い継がれてきた。", "target_word": "昔々", "complexity_tier": "T3", "furigana": "この歌は昔々[むかしむかし]に生まれ、歌い継がれてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "昔々", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "遠い過去の一つの時代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37791, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昔々", "is_correct": true, "explanation": "遠い過去の一時代を表し、人々の暮らしを語る文として自然。"}, {"text": "来月", "is_correct": false, "explanation": "未来の月を表し、過去の暮らしの話と合わない。"}, {"text": "今後", "is_correct": false, "explanation": "これからを表し、過去の話には合わない。"}, {"text": "来世", "is_correct": false, "explanation": "死後の世界を表し、人々の暮らしの話には合わない。"}], "explanations": {"昔々": "遠い過去の一時代を表し、人々の暮らしを語る文として自然。", "来月": "未来の月を表し、過去の暮らしの話と合わない。", "今後": "これからを表し、過去の話には合わない。", "来世": "死後の世界を表し、人々の暮らしの話には合わない。"}, "sentence_index": 0, "correct_answer": "昔々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昔々の事故は、つい先週の出来事だ。", "explanation": "昔々は遠い時代を指し、つい先週の出来事には合わない。"}, {"text": "昔々の締め切りは来週だ。", "explanation": "昔々は過去の一時代で、締め切りの日付には使わない。"}, {"text": "昔々の今年は、雨がほとんど降らなかった。", "explanation": "昔々は一つの時代を指し、今年のような一年の区切りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37791, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昔々", "is_correct": true, "explanation": "遠い過去の一時代を表し、研究の対象になる文脈に合う。"}, {"text": "今夜", "is_correct": false, "explanation": "今日の夜を表し、一つの時代を研究する文脈に合わない。"}, {"text": "明後日", "is_correct": false, "explanation": "近い未来を表し、過去の研究対象にはならない。"}, {"text": "来年", "is_correct": false, "explanation": "未来の年を表し、過去の暮らしを研究する文脈に合わない。"}], "explanations": {"昔々": "遠い過去の一時代を表し、研究の対象になる文脈に合う。", "今夜": "今日の夜を表し、一つの時代を研究する文脈に合わない。", "明後日": "近い未来を表し、過去の研究対象にはならない。", "来年": "未来の年を表し、過去の暮らしを研究する文脈に合わない。"}, "sentence_index": 6, "correct_answer": "昔々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昔々の数時間で、洗濯物がすっかり乾いた。", "explanation": "昔々は遠い時代を指し、数時間という短い時間には使わない。"}, {"text": "昔々の映画が、来週公開される。", "explanation": "昔々は過去の時代で、来週の公開予定とは両立しない。"}, {"text": "昔々、さっきまで一緒にいた友人が家を出ていった。", "explanation": "昔々は遠い時代を指し、ついさっきの出来事とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37791, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昔々を人々は、川のほとりで暮らしていた。", "corrected_sentence": "昔々の人々は、川のほとりで暮らしていた。", "error_description": "「昔々の人々」の「の」は連体修飾。「を」にすると「昔々を」が目的語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37791, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は昔々を暮らしを、よく話してくれた。", "corrected_sentence": "祖父は昔々の暮らしを、よく話してくれた。", "error_description": "「昔々の暮らし」の「の」は連体修飾。「を」にすると目的語が重なり、文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37792, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「所は」で主題を示し、生まれた場所について述べる文になる。"}, {"text": "を", "is_correct": false, "explanation": "「所を」は目的語になるが、「町です」と続かない。"}, {"text": "に", "is_correct": false, "explanation": "「所に」は位置を示すが、「町です」の文の主題にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「町です」の文とはつながらない。"}], "correct_answer": "は", "explanations": {"は": "「所は」で主題を示し、生まれた場所について述べる文になる。", "を": "「所を」は目的語になるが、「町です」と続かない。", "に": "「所に」は位置を示すが、「町です」の文の主題にならない。", "へ": "方向を示すが、「町です」の文とはつながらない。"}, "error_tags": {"を": "目的語", "に": "場所・帰着", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37792, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「所で」は動作の場所を示し、「魚をつりました」と続く。"}, {"text": "が", "is_correct": false, "explanation": "「所が」は主語を示すが、「つりました」の動作主にならない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を示すが、「所と魚をつりました」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点を示すが、ここでは動作の場所として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「所で」は動作の場所を示し、「魚をつりました」と続く。", "が": "「所が」は主語を示すが、「つりました」の動作主にならない。", "と": "並列・相手を示すが、「所と魚をつりました」は成り立たない。", "より": "比較・起点を示すが、ここでは動作の場所として成り立たない。"}, "error_tags": {"が": "主語", "と": "並列・相手", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37792, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ばしょの ことです。", "primary_collocate": null, "pronunciation": "ところ", "ipa": "tokoɾo", "syllable_count": 3, "sentences": [{"text": "ここは静かで、勉強するのにいい所だ。", "target_word": "所", "complexity_tier": "T3", "furigana": "ここは静[しず]かで、勉強[べんきょう]するのにいい所[ところ]だ。", "sentence_source": "generated"}, {"text": "私の生まれた所は、海のそばの小さな町です。", "target_word": "所", "complexity_tier": "T3", "furigana": "私[わたし]の生[う]まれた所[ところ]は、海[うみ]のそばの小[ちい]さな町[まち]です。", "sentence_source": "generated"}, {"text": "暗い所で本を読むと、目が悪くなります。", "target_word": "所", "complexity_tier": "T3", "furigana": "暗[くら]い所[ところ]で本[ほん]を読[よ]むと、目[め]が悪[わる]くなります。", "sentence_source": "generated"}, {"text": "駅から近い所に、新しいパン屋ができた。", "target_word": "所", "complexity_tier": "T3", "furigana": "駅[えき]から近[ちか]い所[ところ]に、新[あたら]しいパン屋[や]ができた。", "sentence_source": "generated"}, {"text": "荷物は、子どもの手が届かない所に置いてください。", "target_word": "所", "complexity_tier": "T3", "furigana": "荷物[にもつ]は、子[こ]どもの手[て]が届[とど]かない所[ところ]に置[お]いてください。", "sentence_source": "generated"}, {"text": "京都は、行く所がたくさんあって楽しい。", "target_word": "所", "complexity_tier": "T3", "furigana": "京都[きょうと]は、行[い]く所[ところ]がたくさんあって楽[たの]しい。", "sentence_source": "generated"}, {"text": "人の多い所は苦手なので、朝早く出かけた。", "target_word": "所", "complexity_tier": "T3", "furigana": "人[ひと]の多[おお]い所[ところ]は苦手[にがて]なので、朝早[あさはや]く出[で]かけた。", "sentence_source": "generated"}, {"text": "水がきれいな所で、魚をつりました。", "target_word": "所", "complexity_tier": "T3", "furigana": "水[みず]がきれいな所[ところ]で、魚[さかな]をつりました。", "sentence_source": "generated"}, {"text": "住む所が決まるまで、友達の家にいた。", "target_word": "所", "complexity_tier": "T3", "furigana": "住[す]む所[ところ]が決[き]まるまで、友達[ともだち]の家[いえ]にいた。", "sentence_source": "generated"}, {"text": "寒い所に住む動物は、体が大きいことが多い。", "target_word": "所", "complexity_tier": "T3", "furigana": "寒[さむ]い所[ところ]に住[す]む動物[どうぶつ]は、体[からだ]が大[おお]きいことが多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "場所・土地・住む所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37792, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所", "is_correct": true, "explanation": "「静かで、勉強するのにいい」に続き、場所を表す「所」が入る。"}, {"text": "音", "is_correct": false, "explanation": "「勉強するのにいい音」は場所を指せず、文脈に合わない。"}, {"text": "味", "is_correct": false, "explanation": "「いい味」は場所の説明にならず、文が成り立たない。"}, {"text": "数", "is_correct": false, "explanation": "「いい数」は場所を指さないので、ここでは使えない。"}], "explanations": {"所": "「静かで、勉強するのにいい」に続き、場所を表す「所」が入る。", "音": "「勉強するのにいい音」は場所を指せず、文脈に合わない。", "味": "「いい味」は場所の説明にならず、文が成り立たない。", "数": "「いい数」は場所を指さないので、ここでは使えない。"}, "sentence_index": 0, "correct_answer": "所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テストで取った所は八十点だ。", "explanation": "ここは〈得点〉の意味。点数は「点」で言い、場所の「所」では点数を表せない。"}, {"text": "会議には五所の人が参加した。", "explanation": "ここは〈人数〉の意味。人を数えるのは「人」で、「所」は場所を数える語なので使えない。"}, {"text": "彼の所は三十歳だ。", "explanation": "ここは〈年齢〉の意味。年齢は「歳」で表し、場所の「所」は年齢を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37792, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所", "is_correct": true, "explanation": "「人の多い」に続き、場所を表す「所」が入る。"}, {"text": "紙", "is_correct": false, "explanation": "「人の多い紙」は意味が通らず、苦手な対象にならない。"}, {"text": "声", "is_correct": false, "explanation": "「人の多い声」は場所の条件にならず、文脈に合わない。"}, {"text": "鍵", "is_correct": false, "explanation": "「人の多い鍵」は文が成り立たない。"}], "explanations": {"所": "「人の多い」に続き、場所を表す「所」が入る。", "紙": "「人の多い紙」は意味が通らず、苦手な対象にならない。", "声": "「人の多い声」は場所の条件にならず、文脈に合わない。", "鍵": "「人の多い鍵」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の所は、試合が中止になる決まりだ。", "explanation": "ここは〈場合・条件〉の意味。「雨の場合」と言うべきで、場所の「所」では条件を表せない。"}, {"text": "この所を生かして、英語を話す練習をしよう。", "explanation": "〈機会〉の意味。「この機会」と言うべきで、場所の「所」は機会を指さない。"}, {"text": "待ち合わせの所は、午後三時です。", "explanation": "〈時刻〉の意味。時間を指すときには「時刻」と言い、「所」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37792, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町には、人が集まる所を多い。", "corrected_sentence": "この町には、人が集まる所が多い。", "error_description": "「多い」の主語は「が」で示す（「は」でも可）。「所を」は誤った格助詞で、正しくは「所が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
