INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37793, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある場所や地点を指す言葉です。", "primary_collocate": null, "pronunciation": "ところ", "ipa": "tokoɾo", "syllable_count": 3, "sentences": [{"text": "地図の赤い印の所で待ち合わせましょう。", "target_word": "所", "complexity_tier": "T3", "furigana": "地図[ちず]の赤[あか]い印[しるし]の所[ところ]で待[ま]ち合[あ]わせましょう。", "sentence_source": "generated"}, {"text": "道が二つに分かれる所を右へ曲がってください。", "target_word": "所", "complexity_tier": "T3", "furigana": "道[みち]が二[ふた]つに分[わ]かれる所[ところ]を右[みぎ]へ曲[ま]がってください。", "sentence_source": "generated"}, {"text": "先生は、私が間違えた所を丁寧に直してくれた。", "target_word": "所", "complexity_tier": "T3", "furigana": "先生[せんせい]は、私[わたし]が間違[まちが]えた所[ところ]を丁寧[ていねい]に直[なお]してくれた。", "sentence_source": "generated"}, {"text": "橋のまん中の所から、町がよく見える。", "target_word": "所", "complexity_tier": "T3", "furigana": "橋[はし]のまん中[なか]の所[ところ]から、町[まち]がよく見[み]える。", "sentence_source": "generated"}, {"text": "ゴミは、決まった所に捨ててください。", "target_word": "所", "complexity_tier": "T3", "furigana": "ゴミは、決[き]まった所[ところ]に捨[す]ててください。", "sentence_source": "generated"}, {"text": "かぎを落とした所が、どうしてもわからない。", "target_word": "所", "complexity_tier": "T3", "furigana": "かぎを落[お]とした所[ところ]が、どうしてもわからない。", "sentence_source": "generated"}, {"text": "階段を上がった所に、小さな窓がある。", "target_word": "所", "complexity_tier": "T3", "furigana": "階段[かいだん]を上[あ]がった所[ところ]に、小[ちい]さな窓[まど]がある。", "sentence_source": "generated"}, {"text": "机の上の、ペンが置いてある所を見てください。", "target_word": "所", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の、ペンが置[お]いてある所[ところ]を見[み]てください。", "sentence_source": "generated"}, {"text": "本の線を引いた所が、試験に出ます。", "target_word": "所", "complexity_tier": "T3", "furigana": "本[ほん]の線[せん]を引[ひ]いた所[ところ]が、試験[しけん]に出[で]ます。", "sentence_source": "generated"}, {"text": "犬が穴をほった所に、古いコインがあった。", "target_word": "所", "complexity_tier": "T3", "furigana": "犬[いぬ]が穴[あな]をほった所[ところ]に、古[ふる]いコインがあった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "特定の地点・箇所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: まん中 (Zipf 2.21)']::text[], 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37793, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所", "is_correct": true, "explanation": "「地図の赤い印の」に続き、待ち合わせ場所を表す「所」が入る。"}, {"text": "歌", "is_correct": false, "explanation": "「歌で待ち合わせ」は意味が通らない。"}, {"text": "腕", "is_correct": false, "explanation": "「腕で待ち合わせ」は場所を指さず、文脈に合わない。"}, {"text": "靴", "is_correct": false, "explanation": "「靴で待ち合わせ」は成り立たない。"}], "explanations": {"所": "「地図の赤い印の」に続き、待ち合わせ場所を表す「所」が入る。", "歌": "「歌で待ち合わせ」は意味が通らない。", "腕": "「腕で待ち合わせ」は場所を指さず、文脈に合わない。", "靴": "「靴で待ち合わせ」は成り立たない。"}, "sentence_index": 0, "correct_answer": "所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "模試で取った所は七十五点だった。", "explanation": "ここは〈得点〉の意味。点数は「点」で言い、場所の「所」では点数を表せない。"}, {"text": "教室には十所の生徒がいた。", "explanation": "ここは〈人数〉の意味。生徒は「人」で数え、「所」は場所を数える語なので使えない。"}, {"text": "私の所は今年で二十歳になる。", "explanation": "ここは〈年齢〉の意味。年齢は「歳」で表し、場所の「所」では年齢を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37793, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所", "is_correct": true, "explanation": "「階段を上がった」に続き、場所を表す「所」が入る。"}, {"text": "声", "is_correct": false, "explanation": "「階段を上がった声」は場所を指さず、文脈に合わない。"}, {"text": "味", "is_correct": false, "explanation": "「階段を上がった味」は意味が通らない。"}, {"text": "数", "is_correct": false, "explanation": "「階段を上がった数」は場所にならない。"}], "explanations": {"所": "「階段を上がった」に続き、場所を表す「所」が入る。", "声": "「階段を上がった声」は場所を指さず、文脈に合わない。", "味": "「階段を上がった味」は意味が通らない。", "数": "「階段を上がった数」は場所にならない。"}, "sentence_index": 6, "correct_answer": "所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の所は、試合が中止になる決まりだ。", "explanation": "ここは〈場合・条件〉の意味。「雨の場合」と言うべきで、場所の「所」では条件を表せない。"}, {"text": "この所を生かして、資格の勉強を始めた。", "explanation": "〈機会〉の意味。「この機会」と言うべきで、場所の「所」は機会を指さない。"}, {"text": "出発の所は、朝六時です。", "explanation": "〈時刻〉の意味。時間を指すときには「時刻」と言い、「所」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37793, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ここからまっすぐ行った所を、郵便局がある。", "corrected_sentence": "ここからまっすぐ行った所に、郵便局がある。", "error_description": "存在を表す「ある」の場所には「所に」が要る。「所を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37793, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の近くの所を、古い時計がある。", "corrected_sentence": "窓の近くの所に、古い時計がある。", "error_description": "存在を表す「ある」の場所には「所に」が要る。「所を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
