INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37794, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ずっと昔のこと。", "primary_collocate": null, "pronunciation": "はるか", "ipa": "haɾɯka", "syllable_count": 3, "sentences": [{"text": "この村の祭りは、はるか昔から続いている。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "この村[むら]の祭[まつ]りは、はるか昔[むかし]から続[つづ]いている。", "sentence_source": "generated"}, {"text": "はるか昔、この丘の上には大きな城があったという。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "はるか昔[むかし]、この丘[おか]の上[うえ]には大[おお]きな城[しろ]があったという。", "sentence_source": "generated"}, {"text": "祖父は、はるか昔の戦争のことを静かに語った。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "祖父[そふ]は、はるか昔[むかし]の戦争[せんそう]のことを静[しず]かに語[かた]った。", "sentence_source": "generated"}, {"text": "恐竜が地球を歩いていたのは、はるか大昔のことだ。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "恐竜[きょうりゅう]が地球[ちきゅう]を歩[ある]いていたのは、はるか大昔[おおむかし]のことだ。", "sentence_source": "generated"}, {"text": "はるか昔に別れた友人から、突然手紙が届いた。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "はるか昔[むかし]に別[わか]れた友人[ゆうじん]から、突然[とつぜん]手紙[てがみ]が届[とど]いた。", "sentence_source": "generated"}, {"text": "この石は、はるか昔に海の底にあったものだ。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "この石[いし]は、はるか昔[むかし]に海[うみ]の底[そこ]にあったものだ。", "sentence_source": "generated"}, {"text": "はるか昔の記憶なのに、あの夏の匂いは今も鮮やかだ。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "はるか昔[むかし]の記憶[きおく]なのに、あの夏[なつ]の匂[にお]いは今[いま]も鮮[あざ]やかだ。", "sentence_source": "generated"}, {"text": "私たちの祖先は、はるか昔に海を渡ってこの島に来た。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "私[わたし]たちの祖先[そせん]は、はるか昔[むかし]に海[うみ]を渡[わた]ってこの島[しま]に来[き]た。", "sentence_source": "generated"}, {"text": "この歌は、はるか昔の人々も口ずさんでいたそうだ。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "この歌[うた]は、はるか昔[むかし]の人々[ひとびと]も口[くち]ずさんでいたそうだ。", "sentence_source": "generated"}, {"text": "古い地層から、はるか昔の生き物の化石が見つかった。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "古[ふる]い地層[ちそう]から、はるか昔[むかし]の生[い]き物[もの]の化石[かせき]が見[み]つかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "はるか", "label": "語幹"}, {"form": "はるかな", "label": "連体形"}, {"form": "はるかに", "label": "連用形"}], "register": "標準", "sense_fingerprint": "ずっと昔。はるか昔・はるか大昔の形で、過去に遠く隔たった時を表す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37794, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "はるか", "is_correct": true, "explanation": "「はるか昔」で、ずっと昔を表すため正解。"}, {"text": "穏やか", "is_correct": false, "explanation": "穏やかな様子を指し、時間の隔たりを表せないため「穏やか昔」は不適。"}, {"text": "鮮やか", "is_correct": false, "explanation": "色や印象の鮮明さを指し、「昔」を修飾できないため不適。"}, {"text": "静か", "is_correct": false, "explanation": "物音の少なさを指し、「昔」の時間の隔たりを表せないため不適。"}], "explanations": {"はるか": "「はるか昔」で、ずっと昔を表すため正解。", "穏やか": "穏やかな様子を指し、時間の隔たりを表せないため「穏やか昔」は不適。", "鮮やか": "色や印象の鮮明さを指し、「昔」を修飾できないため不適。", "静か": "物音の少なさを指し、「昔」の時間の隔たりを表せないため不適。"}, "sentence_index": 0, "correct_answer": "はるか"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "はるか足元の石が光った。", "explanation": "「はるか」はずっと昔を表すので、足元という近い場所とは矛盾し、ここでは不適。"}, {"text": "それははるか最近の出来事だ。", "explanation": "「はるか」はずっと昔を表すので、最近の出来事とは矛盾する。"}, {"text": "はるか目の前の敵に向かっていく。", "explanation": "「はるか」はずっと昔を表すので、目の前の敵とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37794, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "はるか", "is_correct": true, "explanation": "「はるか昔の記憶」で、ずっと昔を表すため正解。"}, {"text": "大らか", "is_correct": false, "explanation": "心が広くゆったりした様子を指し、「昔」の時間の隔たりを表せないため不適。"}, {"text": "厳か", "is_correct": false, "explanation": "おごそかな雰囲気を指し、「昔の記憶」を修飾できないため不適。"}, {"text": "滑らか", "is_correct": false, "explanation": "表面がなめらかな様子を指し、時間の隔たりを表せないため不適。"}], "explanations": {"はるか": "「はるか昔の記憶」で、ずっと昔を表すため正解。", "大らか": "心が広くゆったりした様子を指し、「昔」の時間の隔たりを表せないため不適。", "厳か": "おごそかな雰囲気を指し、「昔の記憶」を修飾できないため不適。", "滑らか": "表面がなめらかな様子を指し、時間の隔たりを表せないため不適。"}, "sentence_index": 6, "correct_answer": "はるか"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "はるか数分前、妹が部屋に入ってきた。", "explanation": "ずっと昔を表す「はるか」は、数分前という近い時間とは矛盾する。"}, {"text": "はるか今朝、友人から電話があった。", "explanation": "ずっと昔を表す「はるか」は、今朝という近い時間とは矛盾する。"}, {"text": "はるか隣の部屋で物音がした。", "explanation": "ずっと昔を表す「はるか」は、隣の部屋という近い場所とは時間の隔たりとして合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37794, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "はるかの昔、この地には海があった。", "corrected_sentence": "はるかな昔、この地には海があった。", "error_description": "形状詞「はるか」は名詞を修飾するとき「はるかな」となる。「はるかの」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "はるか", "is_correct": true, "explanation": "「はるか昔」で、語幹が直接名詞を修飾している形で、文中の形と一致する。"}, {"text": "はるかで", "is_correct": false, "explanation": "連用中止の形で、名詞を直接修飾しないため文中の形と合わない。"}, {"text": "はるかだった", "is_correct": false, "explanation": "過去の断定の形で、名詞を直接修飾しないため不適。"}, {"text": "はるかだ", "is_correct": false, "explanation": "断定の形で、名詞を直接修飾する形ではないため文中の形と合わない。"}], "correct_form": "はるか", "base_form": "遥か", "form_label": "語幹", "sentence_index": 1, "explanations": {"はるか": "「はるか昔」で、語幹が直接名詞を修飾している形で、文中の形と一致する。", "はるかで": "連用中止の形で、名詞を直接修飾しないため文中の形と合わない。", "はるかだった": "過去の断定の形で、名詞を直接修飾しないため不適。", "はるかだ": "断定の形で、名詞を直接修飾する形ではないため文中の形と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37794, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "はるかだった昔の人々は、火を使っていた。", "corrected_sentence": "はるかな昔の人々は、火を使っていた。", "error_description": "形状詞「はるか」は名詞を修飾するとき「はるかな」となる。「はるかだった」は断定の過去形で、名詞「昔」を修飾できないため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "はるか", "is_correct": true, "explanation": "「はるか昔に」で、語幹が直接名詞を修飾している形で、文中の形と一致する。"}, {"text": "はるかだろう", "is_correct": false, "explanation": "推量の形で、名詞を直接修飾しないため文中の形と合わない。"}, {"text": "はるかです", "is_correct": false, "explanation": "丁寧な断定の形で、名詞を直接修飾しないため不適。"}, {"text": "はるかなら", "is_correct": false, "explanation": "仮定の形で、名詞を修飾する形ではないため不適。"}], "correct_form": "はるか", "base_form": "遥か", "form_label": "語幹", "sentence_index": 7, "explanations": {"はるか": "「はるか昔に」で、語幹が直接名詞を修飾している形で、文中の形と一致する。", "はるかだろう": "推量の形で、名詞を直接修飾しないため文中の形と合わない。", "はるかです": "丁寧な断定の形で、名詞を直接修飾しないため不適。", "はるかなら": "仮定の形で、名詞を修飾する形ではないため不適。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
