INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37795, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "時間的に非常に離れていること。また、そのさま。", "primary_collocate": null, "pronunciation": "はるか", "ipa": "haɾɯka", "syllable_count": 3, "sentences": [{"text": "未知の空間たる新校舎の扉をくぐる娘の背中には、微かな緊張と、それをはるかに上回る好奇心が漲っていた。", "target_word": "はるか", "complexity_tier": "T4", "furigana": "未知[みち]の空間[くうかん]たる新校舎[しんこうしゃ]の扉[とびら]をくぐる娘[むすめ]の背中[せなか]には、微[かす]かな緊張[きんちょう]と、それをはるかに上回[うわまわ]る好奇心[こうきしん]が漲[みなぎ]っていた。", "sentence_source": "mined"}, {"text": "はるか未来の地球は、今とは全く違う姿になっているだろう。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "はるか未来[みらい]の地球[ちきゅう]は、今[いま]とは全[まった]く違[ちが]う姿[すがた]になっているだろう。", "sentence_source": "generated"}, {"text": "入学の日にはるか先だと思っていた卒業が、もう目の前に来た。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "入学[にゅうがく]の日[ひ]にはるか先[さき]だと思[おも]っていた卒業[そつぎょう]が、もう目[め]の前[まえ]に来[き]た。", "sentence_source": "generated"}, {"text": "私たちが生きているうちに実現するのは、はるか先の話だ。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "私[わたし]たちが生[い]きているうちに実現[じつげん]するのは、はるか先[さき]の話[はなし]だ。", "sentence_source": "generated"}, {"text": "宇宙の果てで出た光は、はるかな時間をかけて地球に届く。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]の果[は]てで出[で]た光[ひかり]は、はるかな時間[じかん]をかけて地球[ちきゅう]に届[とど]く。", "sentence_source": "generated"}, {"text": "完成まではるかな年月がかかると、設計者は知っていた。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "完成[かんせい]まではるかな年月[ねんげつ]がかかると、設計者[せっけいしゃ]は知[し]っていた。", "sentence_source": "generated"}, {"text": "退職する日などはるか先だと思っていたのに、もう来月だ。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "退職[たいしょく]する日[ひ]などはるか先[さき]だと思[おも]っていたのに、もう来月[らいげつ]だ。", "sentence_source": "generated"}, {"text": "はるか百年後の人々にも読まれる本を書きたい。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "はるか百年後[ひゃくねんご]の人々[ひとびと]にも読[よ]まれる本[ほん]を書[か]きたい。", "sentence_source": "generated"}, {"text": "約束の日ははるか先で、まだ何も準備していない。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "約束[やくそく]の日[ひ]ははるか先[さき]で、まだ何[なに]も準備[じゅんび]していない。", "sentence_source": "generated"}, {"text": "この木が大木になるのは、はるか先のことだ。", "target_word": "はるか", "complexity_tier": "T3", "furigana": "この木[き]が大木[たいぼく]になるのは、はるか先[さき]のことだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "はるか", "label": "語幹"}, {"form": "はるかに", "label": "連用形"}, {"form": "はるかな", "label": "連体形"}], "register": "標準（やや書き言葉寄り）", "sense_fingerprint": "時間的に非常に離れているさま。はるか先・はるかな年月など。程度が大きく上回る用法も含む。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 漲っ (Zipf 1.92)']::text[], '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37795, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "はるか", "is_correct": true, "explanation": "「はるかに上回る」で程度の大きさを表すため正解。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やかに上回る」は意味が通らないため不適。"}, {"text": "なめらか", "is_correct": false, "explanation": "表面が滑らかな様子を指し、「上回る」の程度を表せないため不適。"}, {"text": "静か", "is_correct": false, "explanation": "物音の少なさを指し、「上回る」と結びつかないため不適。"}], "explanations": {"はるか": "「はるかに上回る」で程度の大きさを表すため正解。", "穏やか": "「穏やかに上回る」は意味が通らないため不適。", "なめらか": "表面が滑らかな様子を指し、「上回る」の程度を表せないため不適。", "静か": "物音の少なさを指し、「上回る」と結びつかないため不適。"}, "sentence_index": 0, "correct_answer": "はるか"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "約束の時間まで、はるか五分しかない。", "explanation": "「はるか」は時間が非常に離れていることを表すので、五分という短さとは矛盾する。"}, {"text": "結果は、はるか数日後に届く予定だ。", "explanation": "「はるか」は時間が非常に離れていることを表すので、数日後という近い時点とは矛盾する。"}, {"text": "新しい制度は、はるか近い将来に導入される。", "explanation": "「はるか」は時間が非常に離れていることを表すので、すぐ迫った将来とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37795, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "はるか", "is_correct": true, "explanation": "「退職する日などはるか先だ」で、時間的に非常に遠いことを表すため正解。"}, {"text": "鮮やか", "is_correct": false, "explanation": "色や印象が鮮明な様子を指し、時間の隔たりを表せないため不適。"}, {"text": "大らか", "is_correct": false, "explanation": "心が広くおおらかな様子を指し、日の隔たりを表せないため不適。"}, {"text": "厳か", "is_correct": false, "explanation": "おごそかな雰囲気を指し、「先」の時間を修飾できないため不適。"}], "explanations": {"はるか": "「退職する日などはるか先だ」で、時間的に非常に遠いことを表すため正解。", "鮮やか": "色や印象が鮮明な様子を指し、時間の隔たりを表せないため不適。", "大らか": "心が広くおおらかな様子を指し、日の隔たりを表せないため不適。", "厳か": "おごそかな雰囲気を指し、「先」の時間を修飾できないため不適。"}, "sentence_index": 6, "correct_answer": "はるか"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "はるか目の前の仕事に取りかかろう。", "explanation": "「はるか」は時間的に遠いことを表すので、目の前の仕事とは矛盾する。"}, {"text": "それははるか最近の出来事だ。", "explanation": "「はるか」は時間的に遠いことを表すので、つい先ごろの出来事とは矛盾する。"}, {"text": "はるか明日の予定を確認する。", "explanation": "「はるか」は時間的に遠いことを表すので、明日の予定とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37795, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "はるかの未来、人は月に住んでいるかもしれない。", "corrected_sentence": "はるかな未来、人は月に住んでいるかもしれない。", "error_description": "形状詞「はるか」は名詞を修飾するとき「はるかな」となる。「はるかの」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "はるか", "is_correct": true, "explanation": "「はるか未来」で、語幹が直接名詞を修飾している形で、文中の形と一致する。"}, {"text": "はるかで", "is_correct": false, "explanation": "連用中止の形で、名詞を直接修飾しないため文中の形と合わない。"}, {"text": "はるかだった", "is_correct": false, "explanation": "過去の断定の形で、名詞を直接修飾しないため不適。"}, {"text": "はるかだ", "is_correct": false, "explanation": "断定の形で、名詞を直接修飾する形ではないため文中の形と合わない。"}], "correct_form": "はるか", "base_form": "遥か", "form_label": "語幹", "sentence_index": 1, "explanations": {"はるか": "「はるか未来」で、語幹が直接名詞を修飾している形で、文中の形と一致する。", "はるかで": "連用中止の形で、名詞を直接修飾しないため文中の形と合わない。", "はるかだった": "過去の断定の形で、名詞を直接修飾しないため不適。", "はるかだ": "断定の形で、名詞を直接修飾する形ではないため文中の形と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37795, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その計画が実現するのは、はるかだった先になりそうだ。", "corrected_sentence": "その計画が実現するのは、はるかな先になりそうだ。", "error_description": "形状詞「はるか」は名詞を修飾するとき「はるかな」となる。「はるかだった」は断定の過去形で、「先」を修飾できないため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "はるか", "is_correct": true, "explanation": "「はるか百年後」で、語幹が直接名詞を修飾している形で、文中の形と一致する。"}, {"text": "はるかだろう", "is_correct": false, "explanation": "推量の形で、名詞を直接修飾しないため文中の形と合わない。"}, {"text": "はるかです", "is_correct": false, "explanation": "丁寧な断定の形で、名詞を直接修飾しないため不適。"}, {"text": "はるかなら", "is_correct": false, "explanation": "仮定の形で、名詞を修飾する形ではないため不適。"}], "correct_form": "はるか", "base_form": "遥か", "form_label": "語幹", "sentence_index": 7, "explanations": {"はるか": "「はるか百年後」で、語幹が直接名詞を修飾している形で、文中の形と一致する。", "はるかだろう": "推量の形で、名詞を直接修飾しないため文中の形と合わない。", "はるかです": "丁寧な断定の形で、名詞を直接修飾しないため不適。", "はるかなら": "仮定の形で、名詞を修飾する形ではないため不適。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37796, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「話が上手」は話し方の能力の主語を示し、文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「話に上手」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「話で上手」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「話と上手」は並列にならず、文の骨組みが崩れる。"}], "correct_answer": "が", "explanations": {"が": "「話が上手」は話し方の能力の主語を示し、文が成り立つ。", "に": "「話に上手」は成り立たない。", "で": "「話で上手」は意味が通らない。", "と": "「話と上手」は並列にならず、文の骨組みが崩れる。"}, "error_tags": {"に": "対象", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37796, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「話をして」の「を」は、話すという動作の対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「話へして」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点を示すが、ここでは成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「話からして」は文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「話をして」の「を」は、話すという動作の対象を示す。", "へ": "方向を示すが、「話へして」は成り立たない。", "より": "比較・起点を示すが、ここでは成り立たない。", "から": "起点を示すが、「話からして」は文脈に合わない。"}, "error_tags": {"へ": "方向", "より": "比較・起点", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37796, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が話すことば。", "primary_collocate": null, "pronunciation": "はなし", "ipa": "hanaɕi", "syllable_count": 3, "sentences": [{"text": "先生の話が長くて、みんな眠くなった。", "target_word": "話", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]が長[なが]くて、みんな眠[ねむ]くなった。", "sentence_source": "generated"}, {"text": "あの人は話が上手で、聞いていて楽しい。", "target_word": "話", "complexity_tier": "T3", "furigana": "あの人[ひと]は話[はなし]が上手[じょうず]で、聞[き]いていて楽[たの]しい。", "sentence_source": "generated"}, {"text": "外国人の話は速すぎて、よく聞き取れなかった。", "target_word": "話", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]の話[はなし]は速[はや]すぎて、よく聞[き]き取[と]れなかった。", "sentence_source": "generated"}, {"text": "電話の声が小さくて、相手の話がわからなかった。", "target_word": "話", "complexity_tier": "T3", "furigana": "電話[でんわ]の声[こえ]が小[ちい]さくて、相手[あいて]の話[はなし]がわからなかった。", "sentence_source": "generated"}, {"text": "祖父は話がゆっくりなので、聞き取りやすい。", "target_word": "話", "complexity_tier": "T3", "furigana": "祖父[そふ]は話[はなし]がゆっくりなので、聞[き]き取[と]りやすい。", "sentence_source": "generated"}, {"text": "彼は話がはっきりしているので、意味がよく伝わる。", "target_word": "話", "complexity_tier": "T3", "furigana": "彼[かれ]は話[はなし]がはっきりしているので、意味[いみ]がよく伝[つた]わる。", "sentence_source": "generated"}, {"text": "会議では、一人ずつ話の時間が決められている。", "target_word": "話", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、一人[ひとり]ずつ話[はなし]の時間[じかん]が決[き]められている。", "sentence_source": "generated"}, {"text": "授業中に友達と話をして、先生に注意された。", "target_word": "話", "complexity_tier": "T3", "furigana": "授業中[じゅぎょうちゅう]に友達[ともだち]と話[はなし]をして、先生[せんせい]に注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "弟は話が下手で、気持ちをうまく言えない。", "target_word": "話", "complexity_tier": "T3", "furigana": "弟[おとうと]は話[はなし]が下手[へた]で、気持[きも]ちをうまく言[い]えない。", "sentence_source": "generated"}, {"text": "司会者の話が終わると、会場に拍手が起こった。", "target_word": "話", "complexity_tier": "T3", "furigana": "司会者[しかいしゃ]の話[はなし]が終[お]わると、会場[かいじょう]に拍手[はくしゅ]が起[お]こった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "話", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が口に出して話すことばや話しぶり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37796, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "話", "is_correct": true, "explanation": "「先生の」に続き、話す内容を表す「話」が入る。"}, {"text": "紙", "is_correct": false, "explanation": "「先生の紙が長くて」は意味が通らない。"}, {"text": "箱", "is_correct": false, "explanation": "「先生の箱が長くて」は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "「先生の窓が長くて」は文脈に合わない。"}], "explanations": {"話": "「先生の」に続き、話す内容を表す「話」が入る。", "紙": "「先生の紙が長くて」は意味が通らない。", "箱": "「先生の箱が長くて」は成り立たない。", "窓": "「先生の窓が長くて」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "話"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外国語の話を覚えるのは難しい。", "explanation": "ここは〈単語・ことば〉の意味。覚える対象は「言葉」で、人が話す内容の「話」とは違う。"}, {"text": "電話の話が小さくて、相手が聞こえなかった。", "explanation": "〈声の大きさ〉は「声」。「話が小さい」とは言わないので、声の代わりには使えない。"}, {"text": "夜中にドアの話が聞こえた。", "explanation": "ここは〈物音〉の意味。ドアを叩く音は「音」で、人のことばを指す「話」では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37796, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "話", "is_correct": true, "explanation": "「一人ずつ」の後に、会議で話す時間の「話」が入る。"}, {"text": "靴", "is_correct": false, "explanation": "「一人ずつ靴の時間」は成り立たない。"}, {"text": "鍵", "is_correct": false, "explanation": "「鍵の時間」は会議の文脈に合わない。"}, {"text": "雨", "is_correct": false, "explanation": "「雨の時間」は会議の話題にならない。"}], "explanations": {"話": "「一人ずつ」の後に、会議で話す時間の「話」が入る。", "靴": "「一人ずつ靴の時間」は成り立たない。", "鍵": "「鍵の時間」は会議の文脈に合わない。", "雨": "「雨の時間」は会議の話題にならない。"}, "sentence_index": 6, "correct_answer": "話"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は突然、大きな話を上げた。", "explanation": "ここは〈叫び声〉の意味。声は上げられるが、「話」は上げられないので叫び声の代わりには使えない。"}, {"text": "彼女の字は話がきれいだ。", "explanation": "ここは〈字の形〉の意味。字の美しさは「字」で表し、「話」は字の形に使えない。"}, {"text": "このスープは話が濃い。", "explanation": "ここは〈味〉の意味。スープの濃さは「味」で表し、「話」は味を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37796, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の話を、いつも面白い。", "corrected_sentence": "彼女の話は、いつも面白い。", "error_description": "形容詞「面白い」の主語は「が」か「は」で示す。「を」は目的格で、形容詞の主語にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37796, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面白く話を、みんなで笑いながら聞いた。", "corrected_sentence": "面白い話を、みんなで笑いながら聞いた。", "error_description": "「話」を修飾するのは連体形「面白い」。「面白く」は連用形で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37797, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「その話は」で主題を示し、確かめる対象を立てる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「話へ確かめたい」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「話に本当なのか」は文脈に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「話で本当なのか」は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「その話は」で主題を示し、確かめる対象を立てる。", "へ": "方向を示すが、「話へ確かめたい」は成り立たない。", "に": "「話に本当なのか」は文脈に合わない。", "で": "「話で本当なのか」は意味が通らない。"}, "error_tags": {"へ": "方向", "に": "対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37797, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「そんな話は」で主題を示し、驚いた理由となる内容を立てる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「話へ初めて聞いた」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点を示すが、ここでは主題にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「話から初めて聞いた」は文脈に合わない。"}], "correct_answer": "は", "explanations": {"は": "「そんな話は」で主題を示し、驚いた理由となる内容を立てる。", "へ": "方向を示すが、「話へ初めて聞いた」は成り立たない。", "より": "比較・起点を示すが、ここでは主題にならない。", "から": "起点を示すが、「話から初めて聞いた」は文脈に合わない。"}, "error_tags": {"へ": "方向", "より": "比較・起点", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37797, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が考えや気持ちを伝えるために、口に出して言う言葉や、その内容。", "primary_collocate": null, "pronunciation": "はなし", "ipa": "hanaɕi", "syllable_count": 3, "sentences": [{"text": "昨日、友達から面白い話を聞いた。", "target_word": "話", "complexity_tier": "T3", "furigana": "昨日[きのう]、友達[ともだち]から面白[おもしろ]い話[はなし]を聞[き]いた。", "sentence_source": "generated"}, {"text": "その話は本当なのか、確かめたい。", "target_word": "話", "complexity_tier": "T3", "furigana": "その話[はなし]は本当[ほんとう]なのか、確[たし]かめたい。", "sentence_source": "generated"}, {"text": "父は昔の話をするとき、いつも楽しそうだ。", "target_word": "話", "complexity_tier": "T3", "furigana": "父[ちち]は昔[むかし]の話[はなし]をするとき、いつも楽[たの]しそうだ。", "sentence_source": "generated"}, {"text": "悲しい話を聞いて、思わず涙が出た。", "target_word": "話", "complexity_tier": "T3", "furigana": "悲[かな]しい話[はなし]を聞[き]いて、思[おも]わず涙[なみだ]が出[で]た。", "sentence_source": "generated"}, {"text": "彼の話によると、新しい店が駅前にできるそうだ。", "target_word": "話", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]によると、新[あたら]しい店[みせ]が駅前[えきまえ]にできるそうだ。", "sentence_source": "generated"}, {"text": "この話は、まだ誰にも言っていない。", "target_word": "話", "complexity_tier": "T3", "furigana": "この話[はなし]は、まだ誰[だれ]にも言[い]っていない。", "sentence_source": "generated"}, {"text": "母に大事な話があると言われて、少し緊張した。", "target_word": "話", "complexity_tier": "T3", "furigana": "母[はは]に大事[だいじ]な話[はなし]があると言[い]われて、少[すこ]し緊張[きんちょう]した。", "sentence_source": "generated"}, {"text": "そんな話は初めて聞いたので、とても驚いた。", "target_word": "話", "complexity_tier": "T3", "furigana": "そんな話[はなし]は初[はじ]めて聞[き]いたので、とても驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "おじいさんの話は、子どもにもわかりやすい。", "target_word": "話", "complexity_tier": "T3", "furigana": "おじいさんの話[はなし]は、子[こ]どもにもわかりやすい。", "sentence_source": "generated"}, {"text": "旅行の話で盛り上がって、時間を忘れてしまった。", "target_word": "話", "complexity_tier": "T3", "furigana": "旅行[りょこう]の話[はなし]で盛[も]り上[あ]がって、時間[じかん]を忘[わす]れてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "話", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "語られる内容、話題、物語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37797, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "話", "is_correct": true, "explanation": "「面白い」を受け、語られる内容の「話」が入る。"}, {"text": "靴", "is_correct": false, "explanation": "「面白い靴を聞いた」は意味が通らない。"}, {"text": "鍋", "is_correct": false, "explanation": "「面白い鍋を聞いた」は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "「面白い窓を聞いた」は文脈に合わない。"}], "explanations": {"話": "「面白い」を受け、語られる内容の「話」が入る。", "靴": "「面白い靴を聞いた」は意味が通らない。", "鍋": "「面白い鍋を聞いた」は成り立たない。", "窓": "「面白い窓を聞いた」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "話"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その絵は話が鮮やかだ。", "explanation": "ここは〈色〉の意味。絵の鮮やかさは「色」で表し、「話」では言えない。"}, {"text": "花の話が強くて、部屋中に広がった。", "explanation": "ここは〈香り〉の意味。花の香りが強いと言うので、「香り」の代わりに「話」は使えない。"}, {"text": "荷物の話が重くて、持ち上がらない。", "explanation": "ここは〈重さ〉の意味。荷物の重さは「重さ」で表し、「話」では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37797, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "話", "is_correct": true, "explanation": "「大事な」を受け、伝えられる内容の「話」が入る。"}, {"text": "皿", "is_correct": false, "explanation": "「大事な皿があると言われて」は文脈に合わない。"}, {"text": "草", "is_correct": false, "explanation": "「大事な草がある」は場面に合わない。"}, {"text": "指", "is_correct": false, "explanation": "「大事な指がある」は成り立たない。"}], "explanations": {"話": "「大事な」を受け、伝えられる内容の「話」が入る。", "皿": "「大事な皿があると言われて」は文脈に合わない。", "草": "「大事な草がある」は場面に合わない。", "指": "「大事な指がある」は成り立たない。"}, "sentence_index": 6, "correct_answer": "話"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電話の話が小さくて、相手が聞こえなかった。", "explanation": "声の大きさは「声」。「話が小さい」とは言わないので、声の代わりには使えない。"}, {"text": "料理の話が濃くて、食べにくかった。", "explanation": "ここは〈味〉の意味。料理の濃さは「味」で表し、「話」は味の代わりにならない。"}, {"text": "部屋の話が高いので、窓を開けた。", "explanation": "ここは〈温度〉の意味。部屋の温度は「温度」で表し、「話」では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37797, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昔の話に、子どもに聞かせた。", "corrected_sentence": "昔の話を、子どもに聞かせた。", "error_description": "「聞かせる」の対象は「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37797, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "楽しく話を、みんなで笑いながら聞いた。", "corrected_sentence": "楽しい話を、みんなで笑いながら聞いた。", "error_description": "「話」を修飾するのは連体形「楽しい」。「楽しく」は連用形で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
