INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37798, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "こわいは、おばけやくらいところをみて、いやなきもちになること。", "primary_collocate": null, "pronunciation": "こわい", "ipa": "kowai", "syllable_count": 3, "sentences": [{"text": "暗い道を一人で歩くのは怖い。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "暗[くら]い道[みち]を一人[ひとり]で歩[ある]くのは怖[こわ]い。", "sentence_source": "generated"}, {"text": "おばけの映画を見たあと、夜がとても怖かった。", "target_word": "怖かった", "complexity_tier": "T3", "furigana": "おばけの映画[えいが]を見[み]たあと、夜[よる]がとても怖[こわ]かった。", "sentence_source": "generated"}, {"text": "暗い部屋に入るのが怖くて、電気をつけた。", "target_word": "怖くて", "complexity_tier": "T3", "furigana": "暗[くら]い部屋[へや]に入[はい]るのが怖[こわ]くて、電気[でんき]をつけた。", "sentence_source": "generated"}, {"text": "弟はおばけの話が怖いと言って、耳をふさいだ。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "弟[おとうと]はおばけの話[はなし]が怖[こわ]いと言[い]って、耳[みみ]をふさいだ。", "sentence_source": "generated"}, {"text": "夜の学校は静かで、ちょっと怖い。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "夜[よる]の学校[がっこう]は静[しず]かで、ちょっと怖[こわ]い。", "sentence_source": "generated"}, {"text": "暗いトンネルが怖くて、母の手をにぎった。", "target_word": "怖くて", "complexity_tier": "T3", "furigana": "暗[くら]いトンネルが怖[こわ]くて、母[はは]の手[て]をにぎった。", "sentence_source": "generated"}, {"text": "怖い夢を見て、真夜中に目が覚めた。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "怖[こわ]い夢[ゆめ]を見[み]て、真夜中[まよなか]に目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "おばけ屋敷の中は暗くて、怖かった。", "target_word": "怖かった", "complexity_tier": "T3", "furigana": "おばけ屋敷[やしき]の中[なか]は暗[くら]くて、怖[こわ]かった。", "sentence_source": "generated"}, {"text": "妹は暗い所が怖いので、ドアを少し開けて寝る。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "妹[いもうと]は暗[くら]い所[ところ]が怖[こわ]いので、ドアを少[すこ]し開[あ]けて寝[ね]る。", "sentence_source": "generated"}, {"text": "森の奥から変な音がして、怖くなった。", "target_word": "怖くなった", "complexity_tier": "T3", "furigana": "森[もり]の奥[おく]から変[へん]な音[おと]がして、怖[こわ]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "怖い", "label": "終止形・連体形"}, {"form": "怖く", "label": "連用形"}, {"form": "怖くて", "label": "テ形"}, {"form": "怖かった", "label": "過去形"}, {"form": "怖ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "おばけや暗い場所に感じるこわさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: にぎっ (Zipf 2.25)']::text[], 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37798, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怖い", "is_correct": true, "explanation": "おばけや暗い道への恐ろしさを表すので、一人で歩く場面に合う。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す形容詞で、暗い道を歩くこわさの説明にならない。"}, {"text": "遠い", "is_correct": false, "explanation": "距離を表す語で、道を歩くときの気持ちを述べる文に入らない。"}, {"text": "甘い", "is_correct": false, "explanation": "味や評価を表す語で、暗い道の様子には合わない。"}], "explanations": {"怖い": "おばけや暗い道への恐ろしさを表すので、一人で歩く場面に合う。", "眠い": "眠気を表す形容詞で、暗い道を歩くこわさの説明にならない。", "遠い": "距離を表す語で、道を歩くときの気持ちを述べる文に入らない。", "甘い": "味や評価を表す語で、暗い道の様子には合わない。"}, "sentence_index": 0, "correct_answer": "怖い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ほしかったゲームが手に入って、怖い。", "explanation": "ここは〈嬉しい〉の意味。怖いは恐れの感情を表すので、喜びの気持ちには使えない。"}, {"text": "この缶詰は臭くて、怖い。", "explanation": "ここは〈嫌だ〉の意味。怖いは恐ろしさの感覚を表すので、不快なにおいには合わない。"}, {"text": "みんなの前で転んでしまい、怖い。", "explanation": "ここは〈恥ずかしい〉の意味。怖いは恐れを表すので、恥ずかしさの気持ちには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37798, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怖い", "is_correct": true, "explanation": "夢の内容が恐ろしいことを表し、夢を修飾する形に合う。"}, {"text": "忙しい", "is_correct": false, "explanation": "忙しさを表す語で、夢の内容の説明にならない。"}, {"text": "狭い", "is_correct": false, "explanation": "空間の広さを表す語で、夢の性質を述べる文に合わない。"}, {"text": "厚い", "is_correct": false, "explanation": "物の厚みを表す語で、夢を修飾する文に入らない。"}], "explanations": {"怖い": "夢の内容が恐ろしいことを表し、夢を修飾する形に合う。", "忙しい": "忙しさを表す語で、夢の内容の説明にならない。", "狭い": "空間の広さを表す語で、夢の性質を述べる文に合わない。", "厚い": "物の厚みを表す語で、夢を修飾する文に入らない。"}, "sentence_index": 6, "correct_answer": "怖い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どものころに好きだったお菓子を食べて、怖い。", "explanation": "ここは〈懐かしい〉の意味。怖いは恐れの感情なので、思い出のなつかしさには使わない。"}, {"text": "試合で負けてしまって、怖い。", "explanation": "ここは〈悔しい〉の意味。怖いは恐ろしさの感情なので、負けた悔しさとは合わない。"}, {"text": "友達とパーティーをして、怖い。", "explanation": "ここは〈楽しい〉の意味。怖いは恐れを表すので、楽しい集まりの気分には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37798, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中に一人で留守番をするのは、やっぱり怖く。", "corrected_sentence": "夜中に一人で留守番をするのは、やっぱり怖い。", "error_description": "文末の形容詞は終止形の「怖い」が正しい。「怖く」は連用形で、そこで文を終えることができない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "怖かった", "is_correct": true, "explanation": "過去形で、映画のあとに感じた体験を表す。"}, {"text": "怖さ", "is_correct": false, "explanation": "名詞なので、文末に置くと文が成り立たない。"}, {"text": "怖くて", "is_correct": false, "explanation": "て形なので、「夜が」に続けて文を終えることができない。"}, {"text": "怖ければ", "is_correct": false, "explanation": "仮定形で、実際にあった出来事の描写にならない。"}], "correct_form": "怖かった", "base_form": "怖い", "form_label": "過去形", "sentence_index": 1, "explanations": {"怖かった": "過去形で、映画のあとに感じた体験を表す。", "怖さ": "名詞なので、文末に置くと文が成り立たない。", "怖くて": "て形なので、「夜が」に続けて文を終えることができない。", "怖ければ": "仮定形で、実際にあった出来事の描写にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37798, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "薄暗い廊下を歩くのは、少し怖いて、足が止まる。", "corrected_sentence": "薄暗い廊下を歩くのは、少し怖くて、足が止まる。", "error_description": "て形は「怖くて」が正しい。「怖いて」は活用の誤りで、「怖く」＋「て」の形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "怖かった", "is_correct": true, "explanation": "過去形で、お化け屋敷の中で感じた怖さを表す。"}, {"text": "怖く", "is_correct": false, "explanation": "連用形で、「暗くて、怖く。」と文を終えることができない。"}, {"text": "怖すぎ", "is_correct": false, "explanation": "程度を強める形で、文末に置くと文が成り立たない。"}, {"text": "怖がって", "is_correct": false, "explanation": "別の動詞「怖がる」のて形なので、文を終えることができない。"}], "correct_form": "怖かった", "base_form": "怖い", "form_label": "過去形", "sentence_index": 7, "explanations": {"怖かった": "過去形で、お化け屋敷の中で感じた怖さを表す。", "怖く": "連用形で、「暗くて、怖く。」と文を終えることができない。", "怖すぎ": "程度を強める形で、文末に置くと文が成り立たない。", "怖がって": "別の動詞「怖がる」のて形なので、文を終えることができない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
