INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37799, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "危険や不安を感じさせ、恐ろしいと思う気持ちにさせるさま。", "primary_collocate": null, "pronunciation": "こわい", "ipa": "kowai", "syllable_count": 3, "sentences": [{"text": "雪の山道で車を運転するのは怖い。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "雪[ゆき]の山道[やまみち]で車[くるま]を運転[うんてん]するのは怖[こわ]い。", "sentence_source": "generated"}, {"text": "高い所は落ちそうで怖いから、橋を渡りたくない。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "高[たか]い所[ところ]は落[お]ちそうで怖[こわ]いから、橋[はし]を渡[わた]りたくない。", "sentence_source": "generated"}, {"text": "地震が起きるたびに、また大きいのが来ないかと怖くなる。", "target_word": "怖くなる", "complexity_tier": "T3", "furigana": "地震[じしん]が起[お]きるたびに、また大[おお]きいのが来[こ]ないかと怖[こわ]くなる。", "sentence_source": "generated"}, {"text": "あの犬は大きな声でほえるので、怖い。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "あの犬[いぬ]は大[おお]きな声[こえ]でほえるので、怖[こわ]い。", "sentence_source": "generated"}, {"text": "試験に落ちたらどうしようと思うと、怖くて眠れなかった。", "target_word": "怖くて", "complexity_tier": "T3", "furigana": "試験[しけん]に落[お]ちたらどうしようと思[おも]うと、怖[こわ]くて眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "病気が見つかるのが怖くて、病院に行けずにいた。", "target_word": "怖くて", "complexity_tier": "T3", "furigana": "病気[びょうき]が見[み]つかるのが怖[こわ]くて、病院[びょういん]に行[い]けずにいた。", "sentence_source": "generated"}, {"text": "台風の夜は、風の音が家をゆらすようで怖かった。", "target_word": "怖かった", "complexity_tier": "T3", "furigana": "台風[たいふう]の夜[よる]は、風[かぜ]の音[おと]が家[いえ]をゆらすようで怖[こわ]かった。", "sentence_source": "generated"}, {"text": "彼は怒ると急に別人のようになるので、怖い人だと思う。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[おこ]ると急[きゅう]に別人[べつじん]のようになるので、怖[こわ]い人[ひと]だと思[おも]う。", "sentence_source": "generated"}, {"text": "スピードを出す車が横を通ると、ぶつかりそうで怖い。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "スピードを出[だ]す車[くるま]が横[よこ]を通[とお]ると、ぶつかりそうで怖[こわ]い。", "sentence_source": "generated"}, {"text": "失敗するのが怖いからこそ、準備をしっかりする。", "target_word": "怖い", "complexity_tier": "T3", "furigana": "失敗[しっぱい]するのが怖[こわ]いからこそ、準備[じゅんび]をしっかりする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "怖い", "label": "終止形・連体形"}, {"form": "怖く", "label": "連用形"}, {"form": "怖くて", "label": "テ形"}, {"form": "怖かった", "label": "過去形"}, {"form": "怖ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "危険や不安を感じて恐ろしいと思うさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: ほえる (Zipf 2.15)','sentence 6 above tier T1: contains vocabulary far above tier T1: ゆらす (Zipf 1.93)']::text[], 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37799, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怖い", "is_correct": true, "explanation": "雪の山道を運転する危険への不安を表すので、ここに入る。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す語で、運転の危険や不安の説明にならない。"}, {"text": "甘い", "is_correct": false, "explanation": "味や評価を表す語で、運転という行為の性質には合わない。"}, {"text": "薄い", "is_correct": false, "explanation": "厚みや濃さを表す語で、運転の不安を述べる文に合わない。"}], "explanations": {"怖い": "雪の山道を運転する危険への不安を表すので、ここに入る。", "眠い": "眠気を表す語で、運転の危険や不安の説明にならない。", "甘い": "味や評価を表す語で、運転という行為の性質には合わない。", "薄い": "厚みや濃さを表す語で、運転の不安を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "怖い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜ふかしして、怖い。", "explanation": "ここは〈眠い〉の意味。怖いは危険や不安を感じる気持ちなので、眠気の状態には合わない。"}, {"text": "試合に負けてしまい、怖い。", "explanation": "ここは〈残念〉の意味。怖いは危険や不安に対する恐れなので、結果の落胆には使わない。"}, {"text": "合格の知らせを聞いて、怖い。", "explanation": "ここは〈嬉しい〉の意味。怖いは不安や恐れを表すので、合格の喜びには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37799, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怖かった", "is_correct": true, "explanation": "過去形で、台風の夜に感じた恐ろしさを表すので、ここに入る。"}, {"text": "忙しかった", "is_correct": false, "explanation": "忙しさを表す語で、風の音への恐ろしさの説明にならない。"}, {"text": "狭かった", "is_correct": false, "explanation": "空間の狭さを表す語で、風の音の感じ方には合わない。"}, {"text": "遠かった", "is_correct": false, "explanation": "距離を表す語で、台風の夜の感覚を述べる文に入らない。"}], "explanations": {"怖かった": "過去形で、台風の夜に感じた恐ろしさを表すので、ここに入る。", "忙しかった": "忙しさを表す語で、風の音への恐ろしさの説明にならない。", "狭かった": "空間の狭さを表す語で、風の音の感じ方には合わない。", "遠かった": "距離を表す語で、台風の夜の感覚を述べる文に入らない。"}, "sentence_index": 6, "correct_answer": "怖かった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "久しぶりに会った友達と話して、怖い。", "explanation": "ここは〈懐かしい〉の意味。怖いは危険や不安を感じる気持ちなので、再会の懐かしさには使わない。"}, {"text": "転校する友達を見送って、怖い。", "explanation": "ここは〈寂しい〉の意味。怖いは恐れの感情なので、別れのさびしさには合わない。"}, {"text": "休みの日に友達と遊んで、怖い。", "explanation": "ここは〈楽しい〉の意味。怖いは不安や恐れを表すので、遊んだ楽しさには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37799, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日の夜道を車で走るのは、とても怖く。", "corrected_sentence": "雨の日の夜道を車で走るのは、とても怖い。", "error_description": "文末の形容詞は終止形の「怖い」が正しい。「怖く」は連用形で、文末には使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "怖い", "is_correct": true, "explanation": "終止形・連体形で、「から」の前に置いて理由を述べる形になる。"}, {"text": "怖く", "is_correct": false, "explanation": "連用形なので、「から」に直接続けると文法的に成り立たない。"}, {"text": "怖くて", "is_correct": false, "explanation": "て形なので、理由を表す「から」の前には置けない。"}, {"text": "怖ければ", "is_correct": false, "explanation": "仮定形なので、事実の理由を述べる「から」の文に合わない。"}], "correct_form": "怖い", "base_form": "怖い", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"怖い": "終止形・連体形で、「から」の前に置いて理由を述べる形になる。", "怖く": "連用形なので、「から」に直接続けると文法的に成り立たない。", "怖くて": "て形なので、理由を表す「から」の前には置けない。", "怖ければ": "仮定形なので、事実の理由を述べる「から」の文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37799, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の山道は、とても怖いだ。", "corrected_sentence": "夜の山道は、とても怖い。", "error_description": "形容詞の「怖い」の後に「だ」は付かない。「だ」を取って「怖い」で文を終える必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "怖い", "is_correct": true, "explanation": "終止形・連体形で、「怖い人」と人を修飾する形に合う。"}, {"text": "怖さ", "is_correct": false, "explanation": "名詞なので、「人」を修飾できず文が成り立たない。"}, {"text": "怖がって", "is_correct": false, "explanation": "動詞のて形なので、名詞「人」に続かない。"}, {"text": "怖すぎ", "is_correct": false, "explanation": "程度を強める形で、名詞「人」を直接修飾できない。"}], "correct_form": "怖い", "base_form": "怖い", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"怖い": "終止形・連体形で、「怖い人」と人を修飾する形に合う。", "怖さ": "名詞なので、「人」を修飾できず文が成り立たない。", "怖がって": "動詞のて形なので、名詞「人」に続かない。", "怖すぎ": "程度を強める形で、名詞「人」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37800, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "電話をかける相手を表す「に」で、御袋に電話するという意味になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すので、御袋を電話の対象にしてしまい意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すので、電話の相手を示す文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「御袋の電話すると」と名詞に「の」を付けても、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "電話をかける相手を表す「に」で、御袋に電話するという意味になる。", "を": "目的語を表すので、御袋を電話の対象にしてしまい意味が通らない。", "で": "手段や場所を表すので、電話の相手を示す文には合わない。", "の": "「御袋の電話すると」と名詞に「の」を付けても、文として成り立たない。"}, "error_tags": {"を": "対象", "で": "手段・場所", "の": "連体・所有"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37800, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37800, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おかあさんのこと。", "primary_collocate": null, "pronunciation": "おふくろ", "ipa": "oɸɯkɯɾo", "syllable_count": 4, "sentences": [{"text": "俺の御袋は、毎朝早く起きて弁当を作ってくれる。", "target_word": "御袋", "complexity_tier": "T3", "furigana": "俺[おれ]の御袋[おふくろ]は、毎朝[まいあさ]早[はや]く起[お]きて弁当[べんとう]を作[つく]ってくれる。", "sentence_source": "generated"}, {"text": "御袋に電話すると、いつも体の心配をされる。", "target_word": "御袋", "complexity_tier": "T3", "furigana": "御袋[おふくろ]に電話[でんわ]すると、いつも体[からだ]の心配[しんぱい]をされる。", "sentence_source": "generated"}, {"text": "週末は実家に帰って、御袋の顔を見てきた。", "target_word": "御袋", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は実家[じっか]に帰[かえ]って、御袋[おふくろ]の顔[かお]を見[み]てきた。", "sentence_source": "generated"}, {"text": "御袋は料理が上手で、友達にも評判だ。", "target_word": "御袋", "complexity_tier": "T3", "furigana": "御袋[おふくろ]は料理[りょうり]が上手[じょうず]で、友達[ともだち]にも評判[ひょうばん]だ。", "sentence_source": "generated"}, {"text": "うちの御袋は、犬が苦手で近づこうとしない。", "target_word": "御袋", "complexity_tier": "T3", "furigana": "うちの御袋[おふくろ]は、犬[いぬ]が苦手[にがて]で近[ちか]づこうとしない。", "sentence_source": "generated"}, {"text": "御袋が風邪をひいたので、今日は俺が夕飯を作った。", "target_word": "御袋", "complexity_tier": "T3", "furigana": "御袋[おふくろ]が風邪[かぜ]をひいたので、今日[きょう]は俺[おれ]が夕飯[ゆうはん]を作[つく]った。", "sentence_source": "generated"}, {"text": "卒業式には、御袋が着物を着て来てくれた。", "target_word": "御袋", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]には、御袋[おふくろ]が着物[きもの]を着[き]て来[き]てくれた。", "sentence_source": "generated"}, {"text": "御袋は毎日、庭の花に水をやっている。", "target_word": "御袋", "complexity_tier": "T3", "furigana": "御袋[おふくろ]は毎日[まいにち]、庭[にわ]の花[はな]に水[みず]をやっている。", "sentence_source": "generated"}, {"text": "御袋に誕生日のプレゼントを送ったら、とても喜んでくれた。", "target_word": "御袋", "complexity_tier": "T3", "furigana": "御袋[おふくろ]に誕生日[たんじょうび]のプレゼントを送[おく]ったら、とても喜[よろこ]んでくれた。", "sentence_source": "generated"}, {"text": "御袋の作るみそ汁を飲むと、ほっとする。", "target_word": "御袋", "complexity_tier": "T3", "furigana": "御袋[おふくろ]の作[つく]るみそ汁[しる]を飲[の]むと、ほっとする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "御袋", "label": "基本形"}], "register": "colloquial", "sense_fingerprint": "自分の母親（主に男性が使う くだけた言い方）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed1a0ad-79ac-457d-a2f9-a3b643850ea7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37800, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "御袋", "is_correct": true, "explanation": "自分の母親を指す語で、毎朝弁当を作ってくれる人の説明に合う。"}, {"text": "弁当", "is_correct": false, "explanation": "食べ物を指す名詞で、弁当を作る人の名前としては入らない。"}, {"text": "教室", "is_correct": false, "explanation": "学校の場所を指す語で、弁当を作る人の説明にならない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指す語で、人を表す位置には入らない。"}], "explanations": {"御袋": "自分の母親を指す語で、毎朝弁当を作ってくれる人の説明に合う。", "弁当": "食べ物を指す名詞で、弁当を作る人の名前としては入らない。", "教室": "学校の場所を指す語で、弁当を作る人の説明にならない。", "天気": "空模様を指す語で、人を表す位置には入らない。"}, "sentence_index": 0, "correct_answer": "御袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "俺の御袋は、来年結婚式を挙げる予定の相手だ。", "explanation": "ここは〈恋人〉の意味。御袋は自分の母親を指す語なので、恋人には使わない。"}, {"text": "俺の御袋は、もう十年前に亡くなった祖母だ。", "explanation": "ここは〈おばあさん〉の意味。御袋は自分の母親のことで、おばあさんには使わない。"}, {"text": "私の御袋は、同じクラスの友人だ。", "explanation": "ここは〈友だち〉の意味。御袋は親を指す語なので、友だちには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37800, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "御袋", "is_correct": true, "explanation": "自分の母親を指す語で、卒業式に着物を着て来てくれた人に合う。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の入り口を指す語で、着物を着て来た人の説明にならない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の部分を表す語で、人を表す位置には入らない。"}, {"text": "自転車", "is_correct": false, "explanation": "乗り物を指す語で、着物を着て来る人の説明には合わない。"}], "explanations": {"御袋": "自分の母親を指す語で、卒業式に着物を着て来てくれた人に合う。", "玄関": "建物の入り口を指す語で、着物を着て来た人の説明にならない。", "窓": "建物の部分を表す語で、人を表す位置には入らない。", "自転車": "乗り物を指す語で、着物を着て来る人の説明には合わない。"}, "sentence_index": 6, "correct_answer": "御袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の御袋が、来週の結婚式でスピーチをする。", "explanation": "ここは〈お母さま〉の意味。御袋は話し手自身の母親を指す語なので、他人の母親には使わない。"}, {"text": "おじの御袋は、毎年夏に遊びに来る。", "explanation": "ここは〈祖母〉の意味。御袋は話し手自身の母親を指す語なので、祖母には使わない。"}, {"text": "この鍋の御袋は、だいぶ古くなった。", "explanation": "御袋は人を指す語で、鍋のような物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37800, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "うちの御袋を、今も毎朝弁当を作ってくれる。", "corrected_sentence": "うちの御袋は、今も毎朝弁当を作ってくれる。", "error_description": "「御袋」は弁当を作る主語なので「は」が正しい。「を」は目的語を表すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37800, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎年、御袋に年末の大掃除を手伝ってくれる。", "corrected_sentence": "毎年、御袋が年末の大掃除を手伝ってくれる。", "error_description": "「手伝ってくれる」の主語を示すのは「が」。「に」では主語が正しく示されず、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1965d3-04c9-4dc3-8aab-78dbe877a5a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37802, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「村には店が少ない」のように、場所を示す「に」が村に付きます。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象に付くので、「村を店が少ない」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すので、店が少ないという状態の場所には使えません。"}, {"text": "が", "is_correct": false, "explanation": "「が」は後の「は」と続かず、「村がは」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「村には店が少ない」のように、場所を示す「に」が村に付きます。", "を": "「を」は動作の対象に付くので、「村を店が少ない」は文として成り立ちません。", "へ": "「へ」は移動の方向を表すので、店が少ないという状態の場所には使えません。", "が": "「が」は後の「は」と続かず、「村がは」は文として成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "が": "主格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37802, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「村の入り口」のように、村に付いて所属や場所の範囲を示す「の」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を表すので、「村を入り口に」は場所を示せず合いません。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作が行われる場所に付くので、「立っている」という存在の文には合いません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すので、村に付いて入り口を示す文脈には合いません。"}], "correct_answer": "の", "explanations": {"の": "「村の入り口」のように、村に付いて所属や場所の範囲を示す「の」が入ります。", "を": "「を」は動作の対象を表すので、「村を入り口に」は場所を示せず合いません。", "で": "「で」は動作が行われる場所に付くので、「立っている」という存在の文には合いません。", "へ": "「へ」は移動の方向を表すので、村に付いて入り口を示す文脈には合いません。"}, "error_tags": {"を": "目的語", "で": "動作の場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37802, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "むらは、人々がたくさん住んでいる、小さいまちのようなところです。", "primary_collocate": null, "pronunciation": "むら", "ipa": "mɯɾɯ", "syllable_count": 2, "sentences": [{"text": "私の祖父は山の中の村に住んでいます。", "target_word": "村", "complexity_tier": "T3", "furigana": "私[わたし]の祖父[そふ]は山[やま]の中[なか]の村[むら]に住[す]んでいます。", "sentence_source": "generated"}, {"text": "村には店が少ないので、買い物は隣の町へ行きます。", "target_word": "村", "complexity_tier": "T3", "furigana": "村[むら]には店[みせ]が少[すく]ないので、買[か]い物[もの]は隣[となり]の町[まち]へ行[い]きます。", "sentence_source": "generated"}, {"text": "この村は小さいですが、みんな仲がいいです。", "target_word": "村", "complexity_tier": "T3", "furigana": "この村[むら]は小[ちい]さいですが、みんな仲[なか]がいいです。", "sentence_source": "generated"}, {"text": "夏休みに、友だちの住む村へ遊びに行きました。", "target_word": "村", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、友[とも]だちの住[す]む村[むら]へ遊[あそ]びに行[い]きました。", "sentence_source": "generated"}, {"text": "村の子どもたちは、川で魚をとって遊びます。", "target_word": "村", "complexity_tier": "T3", "furigana": "村[むら]の子[こ]どもたちは、川[かわ]で魚[さかな]をとって遊[あそ]びます。", "sentence_source": "generated"}, {"text": "駅から遠い村なので、バスは一日に三回しか来ません。", "target_word": "村", "complexity_tier": "T3", "furigana": "駅[えき]から遠[とお]い村[むら]なので、バスは一日[いちにち]に三回[さんかい]しか来[き]ません。", "sentence_source": "generated"}, {"text": "町は人が多いですが、村は静かで空気がきれいです。", "target_word": "村", "complexity_tier": "T3", "furigana": "町[まち]は人[ひと]が多[おお]いですが、村[むら]は静[しず]かで空気[くうき]がきれいです。", "sentence_source": "generated"}, {"text": "村の入り口に大きな木が立っています。", "target_word": "村", "complexity_tier": "T3", "furigana": "村[むら]の入[い]り口[ぐち]に大[おお]きな木[き]が立[た]っています。", "sentence_source": "generated"}, {"text": "大雪で村へ行く道が通れなくなりました。", "target_word": "村", "complexity_tier": "T3", "furigana": "大雪[おおゆき]で村[むら]へ行[い]く道[みち]が通[とお]れなくなりました。", "sentence_source": "generated"}, {"text": "私が生まれた村には、学校が一つしかありませんでした。", "target_word": "村", "complexity_tier": "T3", "furigana": "私[わたし]が生[う]まれた村[むら]には、学校[がっこう]が一[ひと]つしかありませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "村", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が暮らす、町より小さい集落。住む場所としての村。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1af43bfb-eb6a-43c0-a4ea-30a6a8d66fad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37802, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村", "is_correct": true, "explanation": "「山の中の」に続き、人が住む小さな集落を指すので、「住んでいます」に合います。"}, {"text": "店", "is_correct": false, "explanation": "店は商品を売る場所で、人が住む場所ではないので「住んでいます」に合いません。"}, {"text": "駅", "is_correct": false, "explanation": "駅は乗り降りをする場所で、人が生活して住む場所にはなりません。"}, {"text": "教室", "is_correct": false, "explanation": "教室は授業をする部屋で、人が住む場所ではないので文が成り立ちません。"}], "explanations": {"村": "「山の中の」に続き、人が住む小さな集落を指すので、「住んでいます」に合います。", "店": "店は商品を売る場所で、人が住む場所ではないので「住んでいます」に合いません。", "駅": "駅は乗り降りをする場所で、人が生活して住む場所にはなりません。", "教室": "教室は授業をする部屋で、人が住む場所ではないので文が成り立ちません。"}, "sentence_index": 0, "correct_answer": "村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "わが村は島国で、四方を海に囲まれています。", "explanation": "ここは〈国〉の意味です。村は集落を指す言葉で、国家を表すときには使えないので合いません。"}, {"text": "この村は、人口が五万人を超え、大学も三つあります。", "explanation": "ここは〈町〉の意味です。村は小さな集落を指す言葉で、大学が複数ある規模には使わないので合いません。"}, {"text": "うちの村は、来年新しい社員を十人募集します。", "explanation": "ここは〈会社〉の意味です。村は人が住む地域を指すので、社員を募集する主体にはならないので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37802, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村", "is_correct": true, "explanation": "「町は人が多い」と対比して、静かで空気がきれいな小さな地域を指すので合います。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は言葉を調べる本で、「静かで空気がきれい」と様子を説明される対象にはなりません。"}, {"text": "会議", "is_correct": false, "explanation": "会議は話し合いの場で、「空気がきれい」と描写される対象にはならないので合いません。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は書く道具で、静かで空気がきれいと様子を述べる対象にはならないので合いません。"}], "explanations": {"村": "「町は人が多い」と対比して、静かで空気がきれいな小さな地域を指すので合います。", "辞書": "辞書は言葉を調べる本で、「静かで空気がきれい」と様子を説明される対象にはなりません。", "会議": "会議は話し合いの場で、「空気がきれい」と描写される対象にはならないので合いません。", "鉛筆": "鉛筆は書く道具で、静かで空気がきれいと様子を述べる対象にはならないので合いません。"}, "sentence_index": 6, "correct_answer": "村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は村に四年間通って、無事に卒業しました。", "explanation": "ここは〈大学〉の意味です。村は学校ではないので、通って卒業する場所にはならず合いません。"}, {"text": "この村は、四人が座れる狭い部屋です。", "explanation": "ここは〈部屋〉の意味です。村は地域を指す言葉で、四人が座れる狭い空間には使わないので合いません。"}, {"text": "この村は、毎朝決まった時間に出発して、乗客を駅まで運びます。", "explanation": "ここは〈バス〉の意味です。村は乗り物ではないので、乗客を運んで出発する主語には合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37802, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村を住む人は、みんな顔見知りです。", "corrected_sentence": "村に住む人は、みんな顔見知りです。", "error_description": "「村を住む」の「を」が誤りです。住む場所を表すには「に」を使い、「村に住む人」とします。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37802, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏になると、村を広場で盆踊りが開かれます。", "corrected_sentence": "夏になると、村の広場で盆踊りが開かれます。", "error_description": "「村を広場」の「を」が誤りです。村に属する広場を表すには「の」を使い、「村の広場」とします。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37803, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「村の人たち」のように、村に付いて所属を示す「の」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を表すので、「村を人たち」は所属を示せず合いません。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を表すので、「村に人たち」では人を修飾できず合いません。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所を表すので、「村で人たち」では人を修飾できず合いません。"}], "correct_answer": "の", "explanations": {"の": "「村の人たち」のように、村に付いて所属を示す「の」が入ります。", "を": "「を」は動作の対象を表すので、「村を人たち」は所属を示せず合いません。", "に": "「に」は場所や相手を表すので、「村に人たち」では人を修飾できず合いません。", "で": "「で」は動作の場所を表すので、「村で人たち」では人を修飾できず合いません。"}, "error_tags": {"を": "目的語", "に": "場所", "で": "動作の場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37803, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「村が一つの町になりました」のように、変化する主体として村に付く「が」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を表すので、「村を一つの町になる」は変化の主体を示せず合いません。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所や手段を表すので、「村で一つの町になる」は成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すので、村が町に変わるという変化の文には合いません。"}], "correct_answer": "が", "explanations": {"が": "「村が一つの町になりました」のように、変化する主体として村に付く「が」が入ります。", "を": "「を」は動作の対象を表すので、「村を一つの町になる」は変化の主体を示せず合いません。", "で": "「で」は動作の場所や手段を表すので、「村で一つの町になる」は成り立ちません。", "へ": "「へ」は移動の方向を表すので、村が町に変わるという変化の文には合いません。"}, "error_tags": {"を": "目的語", "で": "動作の場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37803, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人々が集まって住む、町よりも小さな地域。田んぼや畑が多い場所。", "primary_collocate": null, "pronunciation": "むら", "ipa": "mɯɾɯ", "syllable_count": 2, "sentences": [{"text": "村の周りには田んぼが広がっています。", "target_word": "村", "complexity_tier": "T3", "furigana": "村[むら]の周[まわ]りには田[た]んぼが広[ひろ]がっています。", "sentence_source": "generated"}, {"text": "春になると、村の人たちは畑で野菜を作ります。", "target_word": "村", "complexity_tier": "T3", "furigana": "春[はる]になると、村[むら]の人[ひと]たちは畑[はたけ]で野菜[やさい]を作[つく]ります。", "sentence_source": "generated"}, {"text": "彼女は都会を出て、のどかな村で暮らし始めました。", "target_word": "村", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は都会[とかい]を出[で]て、のどかな村[むら]で暮[く]らし始[はじ]めました。", "sentence_source": "generated"}, {"text": "この村では、秋になると米の収穫を祝う祭りがあります。", "target_word": "村", "complexity_tier": "T3", "furigana": "この村[むら]では、秋[あき]になると米[こめ]の収穫[しゅうかく]を祝[いわ]う祭[まつ]りがあります。", "sentence_source": "generated"}, {"text": "町と比べて、村は住む人の数が少ないです。", "target_word": "村", "complexity_tier": "T3", "furigana": "町[まち]と比[くら]べて、村[むら]は住[す]む人[ひと]の数[かず]が少[すく]ないです。", "sentence_source": "generated"}, {"text": "村の畑でとれたトマトを、市場に売りに行きます。", "target_word": "村", "complexity_tier": "T3", "furigana": "村[むら]の畑[はたけ]でとれたトマトを、市場[いちば]に売[う]りに行[い]きます。", "sentence_source": "generated"}, {"text": "この村は、人口が千人ほどで、ほとんどの家が米を作っています。", "target_word": "村", "complexity_tier": "T3", "furigana": "この村[むら]は、人口[じんこう]が千人[せんにん]ほどで、ほとんどの家[いえ]が米[こめ]を作[つく]っています。", "sentence_source": "generated"}, {"text": "合併して、二つの村が一つの町になりました。", "target_word": "村", "complexity_tier": "T3", "furigana": "合併[がっぺい]して、二[ふた]つの村[むら]が一[ひと]つの町[まち]になりました。", "sentence_source": "generated"}, {"text": "村の道を歩くと、田んぼのカエルの声が聞こえます。", "target_word": "村", "complexity_tier": "T3", "furigana": "村[むら]の道[みち]を歩[ある]くと、田[た]んぼのカエルの声[こえ]が聞[き]こえます。", "sentence_source": "generated"}, {"text": "山の向こうの村まで、毎朝自転車で通っています。", "target_word": "村", "complexity_tier": "T3", "furigana": "山[やま]の向[む]こうの村[むら]まで、毎朝[まいあさ]自転車[じてんしゃ]で通[かよ]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "村", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "田んぼや畑に囲まれた、農業中心の小さな地域。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1af43bfb-eb6a-43c0-a4ea-30a6a8d66fad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37803, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村", "is_correct": true, "explanation": "田んぼに囲まれた地域を指し、「村の周りには田んぼが広がっています」という文の主語に合います。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は言葉を調べる本で、周りに田んぼが広がるという文の主語にはなりません。"}, {"text": "靴", "is_correct": false, "explanation": "靴は履く物で、周りに田んぼが広がるという文の主語にはなりません。"}, {"text": "電話", "is_correct": false, "explanation": "電話は機械で、田んぼに囲まれた場所を指さないので文が成り立ちません。"}], "explanations": {"村": "田んぼに囲まれた地域を指し、「村の周りには田んぼが広がっています」という文の主語に合います。", "辞書": "辞書は言葉を調べる本で、周りに田んぼが広がるという文の主語にはなりません。", "靴": "靴は履く物で、周りに田んぼが広がるという文の主語にはなりません。", "電話": "電話は機械で、田んぼに囲まれた場所を指さないので文が成り立ちません。"}, "sentence_index": 0, "correct_answer": "村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "うちの村は、来年新しい社員を十人募集します。", "explanation": "ここは〈会社〉の意味です。村は地域を指すので、社員を募集する主体にはならず合いません。"}, {"text": "その村は、毎朝八時に東京へ向けて飛び立ちます。", "explanation": "ここは〈飛行機〉の意味です。村は地域を指す言葉で、東京へ向けて飛び立つ乗り物には使わないので合いません。"}, {"text": "その村は、全部で三百ページあり、表紙が赤いです。", "explanation": "ここは〈本〉の意味です。村は地域を指す言葉で、ページ数や表紙の色がある物には使わないので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37803, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村", "is_correct": true, "explanation": "人口が千人ほどで、家の多くが米を作る小さな地域を指すので、この文の主語に合います。"}, {"text": "会社", "is_correct": false, "explanation": "会社は組織を指し、人口や家が米を作るという説明の主語にはなりません。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文書で、人口を持たないので「人口が千人ほど」という文の主語にはなりません。"}, {"text": "公園", "is_correct": false, "explanation": "公園は人が集まる場所で、人口や家が米を作るという説明の主語にはなりません。"}], "explanations": {"村": "人口が千人ほどで、家の多くが米を作る小さな地域を指すので、この文の主語に合います。", "会社": "会社は組織を指し、人口や家が米を作るという説明の主語にはなりません。", "手紙": "手紙は文書で、人口を持たないので「人口が千人ほど」という文の主語にはなりません。", "公園": "公園は人が集まる場所で、人口や家が米を作るという説明の主語にはなりません。"}, "sentence_index": 6, "correct_answer": "村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その村は、毎朝九時に開店します。", "explanation": "ここは〈店〉の意味です。村は地域を指す言葉で、開店する施設ではないので合いません。"}, {"text": "その村は、毎朝六時に正確に鳴ります。", "explanation": "ここは〈時計〉の意味です。村は地域を指す言葉で、正確に時を知らせて鳴る物には使わないので合いません。"}, {"text": "その村は、毎朝十分おきに発車します。", "explanation": "ここは〈電車〉の意味です。村は乗り物ではないので、発車するという動作の主語には合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37803, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村を田んぼで、秋になると稲刈りをします。", "corrected_sentence": "村の田んぼで、秋になると稲刈りをします。", "error_description": "「村を田んぼ」の「を」が誤りです。村に属する田んぼを表すには「の」を使い、「村の田んぼ」とします。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37803, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村を人口が少なく、夜は星がよく見えます。", "corrected_sentence": "村は人口が少なく、夜は星がよく見えます。", "error_description": "「村を人口が」の「を」が誤りです。話題を示す「は」を使い、「村は人口が少なく」とします。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37804, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「婆の家」のように、婆に付いて所有や所属を示す「の」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を表すので、「婆を家に泊まる」では所属を示せず合いません。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所や手段を表すので、「婆で家に泊まる」は成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すので、「婆へ家に泊まる」では所属を示せず合いません。"}], "correct_answer": "の", "explanations": {"の": "「婆の家」のように、婆に付いて所有や所属を示す「の」が入ります。", "を": "「を」は動作の対象を表すので、「婆を家に泊まる」では所属を示せず合いません。", "で": "「で」は動作の場所や手段を表すので、「婆で家に泊まる」は成り立ちません。", "へ": "「へ」は移動の方向を表すので、「婆へ家に泊まる」では所属を示せず合いません。"}, "error_tags": {"を": "目的語", "で": "動作の場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37804, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「婆は昔の話をするとき」のように、話題の人として婆に付く「は」が入ります。"}, {"text": "か", "is_correct": false, "explanation": "「か」は「AかB」のように二つ以上の候補を並べる形で使うため、後ろの語がない「婆か昔の話をするとき」は文として成り立たない。"}, {"text": "やら", "is_correct": false, "explanation": "「やら」は並列の形で使うため、「婆やら昔の話をする」では成り立たず不自然になる。"}, {"text": "ね", "is_correct": false, "explanation": "「ね」は文末で相手に同意を求める終助詞なので、文中の「婆」に付けると不自然になる。"}], "correct_answer": "は", "explanations": {"は": "「婆は昔の話をするとき」のように、話題の人として婆に付く「は」が入ります。", "か": "「か」は「AかB」のように二つ以上の候補を並べる形で使うため、後ろの語がない「婆か昔の話をするとき」は文として成り立たない。", "やら": "「やら」は並列の形で使うため、「婆やら昔の話をする」では成り立たず不自然になる。", "ね": "「ね」は文末で相手に同意を求める終助詞なので、文中の「婆」に付けると不自然になる。"}, "error_tags": {"か": "選択の後半がない", "やら": "並列が成立しない", "ね": "文末の終助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37804, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おばあちゃんのこと。", "primary_collocate": null, "pronunciation": "ばあ", "ipa": "baː", "syllable_count": 2, "sentences": [{"text": "うちの婆は、毎朝庭の花に水をやります。", "target_word": "婆", "complexity_tier": "T3", "furigana": "うちの婆[ばあ]は、毎朝[まいあさ]庭[にわ]の花[はな]に水[みず]をやります。", "sentence_source": "generated"}, {"text": "夏休みは、田舎の婆の家に泊まります。", "target_word": "婆", "complexity_tier": "T3", "furigana": "夏休[なつやす]みは、田舎[いなか]の婆[ばあ]の家[いえ]に泊[と]まります。", "sentence_source": "generated"}, {"text": "爺と婆は、二人で仲よく散歩に行きました。", "target_word": "婆", "complexity_tier": "T3", "furigana": "爺[じい]と婆[ばあ]は、二人[ふたり]で仲[なか]よく散歩[さんぽ]に行[い]きました。", "sentence_source": "generated"}, {"text": "婆が作ったおにぎりは、いつもとてもおいしいです。", "target_word": "婆", "complexity_tier": "T3", "furigana": "婆[ばあ]が作[つく]ったおにぎりは、いつもとてもおいしいです。", "sentence_source": "generated"}, {"text": "婆はテレビより、ラジオを聞くのが好きです。", "target_word": "婆", "complexity_tier": "T3", "furigana": "婆[ばあ]はテレビより、ラジオを聞[き]くのが好[す]きです。", "sentence_source": "generated"}, {"text": "誕生日に、婆から手作りのセーターをもらいました。", "target_word": "婆", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]に、婆[ばあ]から手作[てづく]りのセーターをもらいました。", "sentence_source": "generated"}, {"text": "風邪をひいたとき、婆がずっとそばにいてくれました。", "target_word": "婆", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいたとき、婆[ばあ]がずっとそばにいてくれました。", "sentence_source": "generated"}, {"text": "婆は昔の話をするとき、とてもうれしそうです。", "target_word": "婆", "complexity_tier": "T3", "furigana": "婆[ばあ]は昔[むかし]の話[はなし]をするとき、とてもうれしそうです。", "sentence_source": "generated"}, {"text": "私は小さいころ、婆に絵本を読んでもらいました。", "target_word": "婆", "complexity_tier": "T3", "furigana": "私[わたし]は小[ちい]さいころ、婆[ばあ]に絵本[えほん]を読[よ]んでもらいました。", "sentence_source": "generated"}, {"text": "婆の手はしわだらけですが、とてもあたたかいです。", "target_word": "婆", "complexity_tier": "T3", "furigana": "婆[ばあ]の手[て]はしわだらけですが、とてもあたたかいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "婆", "label": "基本形"}], "register": "colloquial", "sense_fingerprint": "家族の会話で、自分や相手の祖母をくだけて呼ぶ言い方。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1af43bfb-eb6a-43c0-a4ea-30a6a8d66fad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37804, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "婆", "is_correct": true, "explanation": "家族の中で祖母を指し、庭の花に水をやる人として文の主語に合います。"}, {"text": "車", "is_correct": false, "explanation": "車は乗り物で、庭の花に水をやる主語にはならないので合いません。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は物で、庭の花に水をやるという動作の主語にはならないので合いません。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の一部で、水やりをする人の代わりにはならないので合いません。"}], "explanations": {"婆": "家族の中で祖母を指し、庭の花に水をやる人として文の主語に合います。", "車": "車は乗り物で、庭の花に水をやる主語にはならないので合いません。", "鍵": "鍵は物で、庭の花に水をやるという動作の主語にはならないので合いません。", "窓": "窓は建物の一部で、水やりをする人の代わりにはならないので合いません。"}, "sentence_index": 0, "correct_answer": "婆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "うちの婆は、毎晩ひげをそってから寝ます。", "explanation": "ここは〈爺〉の意味です。婆は女性の祖母を指すので、ひげをそる人には使わず合いません。"}, {"text": "その婆は、毎朝制服を着て高校へ通います。", "explanation": "ここは〈女子高生〉の意味です。婆は年配の祖母を指すので、制服で高校へ通う若い人には使わないので合いません。"}, {"text": "うちの婆は、朝早く窓辺で元気にさえずります。", "explanation": "ここは〈鳥〉の意味です。婆は人を指す言葉で、さえずる動物には使わないので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37804, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "婆", "is_correct": true, "explanation": "風邪のときにそばにいてくれた祖母を指すので、「そばにいてくれました」の主語に合います。"}, {"text": "薬", "is_correct": false, "explanation": "薬は飲む物で、そばにいてくれるという動作の主語にはならないので合いません。"}, {"text": "布団", "is_correct": false, "explanation": "布団は寝具で、そばにいてくれるという動作の主語にはならないので合いません。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の一部で、そばにいてくれるという人の動作の主語にはならないので合いません。"}], "explanations": {"婆": "風邪のときにそばにいてくれた祖母を指すので、「そばにいてくれました」の主語に合います。", "薬": "薬は飲む物で、そばにいてくれるという動作の主語にはならないので合いません。", "布団": "布団は寝具で、そばにいてくれるという動作の主語にはならないので合いません。", "窓": "窓は建物の一部で、そばにいてくれるという人の動作の主語にはならないので合いません。"}, "sentence_index": 6, "correct_answer": "婆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この婆は、ふわふわで甘くて、お店で一番人気です。", "explanation": "ここは〈ケーキ〉の意味です。婆は人を指す言葉で、ふわふわで甘い食べ物には使わないので合いません。"}, {"text": "この婆は、三階建てで、庭に大きな桜の木があります。", "explanation": "ここは〈家〉の意味です。婆は人を指す言葉で、三階建ての建物には使わないので合いません。"}, {"text": "この婆は、雨の日に広げて使う大きな布の傘です。", "explanation": "ここは〈傘〉の意味です。婆は人を指す言葉で、雨の日に広げて使う道具には使わないので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37804, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "婆を作ったおにぎりは、毎年おいしいです。", "corrected_sentence": "婆が作ったおにぎりは、毎年おいしいです。", "error_description": "「婆を作った」の「を」が誤りです。作る人を表すには主語の「が」を使い、「婆が作った」とします。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37804, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高熱のとき、婆をずっとそばにいてくれました。", "corrected_sentence": "高熱のとき、婆がずっとそばにいてくれました。", "error_description": "「婆をずっとそばにいてくれた」の「を」が誤りです。そばにいてくれる人を表す主語の「が」を使い、「婆がずっとそばにいてくれた」とします。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37805, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「隣の家の婆は、毎日犬と散歩しています」のように、話題の人として婆に付く「は」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を表すので、「婆を毎日犬と散歩しています」では話題の人を示せず合いません。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所や手段を表すので、「婆で毎日犬と散歩しています」は成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すので、「婆へ毎日犬と散歩しています」では話題の人を示せず合いません。"}], "correct_answer": "は", "explanations": {"は": "「隣の家の婆は、毎日犬と散歩しています」のように、話題の人として婆に付く「は」が入ります。", "を": "「を」は動作の対象を表すので、「婆を毎日犬と散歩しています」では話題の人を示せず合いません。", "で": "「で」は動作の場所や手段を表すので、「婆で毎日犬と散歩しています」は成り立ちません。", "へ": "「へ」は移動の方向を表すので、「婆へ毎日犬と散歩しています」では話題の人を示せず合いません。"}, "error_tags": {"を": "目的語", "で": "動作の場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37805, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「婆は、昔の写真を見ながら」のように、話題の人として婆に付く「は」が入ります。"}, {"text": "か", "is_correct": false, "explanation": "「か」は「AかB」のように二つ以上の候補を並べる形で使うため、後ろの語がない「婆か、昔の写真を見ながら」は文として成り立たない。"}, {"text": "やら", "is_correct": false, "explanation": "「やら」は並列の形で使うため、「婆やら、昔の写真を見ながら」では成り立たず不自然になる。"}, {"text": "ね", "is_correct": false, "explanation": "「ね」は文末で相手に同意を求める終助詞なので、文中の「婆」に付けると不自然になる。"}], "correct_answer": "は", "explanations": {"は": "「婆は、昔の写真を見ながら」のように、話題の人として婆に付く「は」が入ります。", "か": "「か」は「AかB」のように二つ以上の候補を並べる形で使うため、後ろの語がない「婆か、昔の写真を見ながら」は文として成り立たない。", "やら": "「やら」は並列の形で使うため、「婆やら、昔の写真を見ながら」では成り立たず不自然になる。", "ね": "「ね」は文末で相手に同意を求める終助詞なので、文中の「婆」に付けると不自然になる。"}, "error_tags": {"か": "選択の後半がない", "やら": "並列が成立しない", "ね": "文末の終助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37805, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "年配の女性。特に、祖母を指す。『お婆さん』の形で使われることが多い。", "primary_collocate": null, "pronunciation": "ばあ", "ipa": "baː", "syllable_count": 2, "sentences": [{"text": "バスの中で、杖をついた婆に席をゆずりました。", "target_word": "婆", "complexity_tier": "T3", "furigana": "バスの中[なか]で、杖[つえ]をついた婆[ばあ]に席[せき]をゆずりました。", "sentence_source": "generated"}, {"text": "隣の家の婆は、毎日犬と散歩しています。", "target_word": "婆", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]の婆[ばあ]は、毎日[まいにち]犬[いぬ]と散歩[さんぽ]しています。", "sentence_source": "generated"}, {"text": "うちの婆は、七十五歳ですが元気です。", "target_word": "婆", "complexity_tier": "T3", "furigana": "うちの婆[ばあ]は、七十五歳[ななじゅうごさい]ですが元気[げんき]です。", "sentence_source": "generated"}, {"text": "あの婆は、やさしくて近所の子どもに人気があります。", "target_word": "婆", "complexity_tier": "T3", "furigana": "あの婆[ばあ]は、やさしくて近所[きんじょ]の子[こ]どもに人気[にんき]があります。", "sentence_source": "generated"}, {"text": "婆が重い荷物を持っていたので、手伝いました。", "target_word": "婆", "complexity_tier": "T3", "furigana": "婆[ばあ]が重[おも]い荷物[にもつ]を持[も]っていたので、手伝[てつだ]いました。", "sentence_source": "generated"}, {"text": "日曜日に、婆の家へ家族でごはんを食べに行きます。", "target_word": "婆", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に、婆[ばあ]の家[いえ]へ家族[かぞく]でごはんを食[た]べに行[い]きます。", "sentence_source": "generated"}, {"text": "昔話には、山に住む婆がよく出てきます。", "target_word": "婆", "complexity_tier": "T3", "furigana": "昔話[むかしばなし]には、山[やま]に住[す]む婆[ばあ]がよく出[で]てきます。", "sentence_source": "generated"}, {"text": "婆は、昔の写真を見ながら思い出を話してくれました。", "target_word": "婆", "complexity_tier": "T3", "furigana": "婆[ばあ]は、昔[むかし]の写真[しゃしん]を見[み]ながら思[おも]い出[で]を話[はな]してくれました。", "sentence_source": "generated"}, {"text": "公園のベンチで、婆が鳥にえさをやっています。", "target_word": "婆", "complexity_tier": "T3", "furigana": "公園[こうえん]のベンチで、婆[ばあ]が鳥[とり]にえさをやっています。", "sentence_source": "generated"}, {"text": "婆から教えてもらった料理を、友だちに作りました。", "target_word": "婆", "complexity_tier": "T3", "furigana": "婆[ばあ]から教[おし]えてもらった料理[りょうり]を、友[とも]だちに作[つく]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "婆", "label": "基本形"}, {"form": "お婆さん", "label": "丁寧な形"}], "register": "polite", "sense_fingerprint": "『お婆さん』の形で、年配の女性や祖母を丁寧に呼ぶ言い方。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1af43bfb-eb6a-43c0-a4ea-30a6a8d66fad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37805, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "婆", "is_correct": true, "explanation": "杖をついて席を譲られる年配の人を指すので、「杖をついた___に席をゆずりました」に合います。"}, {"text": "荷物", "is_correct": false, "explanation": "荷物は物で、杖をついて席を譲られる人にはならないので合いません。"}, {"text": "箱", "is_correct": false, "explanation": "箱は物で、杖をついて席を譲られる人にはならないので合いません。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の一部で、杖をついて席を譲られる人にはならないので合いません。"}], "explanations": {"婆": "杖をついて席を譲られる年配の人を指すので、「杖をついた___に席をゆずりました」に合います。", "荷物": "荷物は物で、杖をついて席を譲られる人にはならないので合いません。", "箱": "箱は物で、杖をついて席を譲られる人にはならないので合いません。", "窓": "窓は建物の一部で、杖をついて席を譲られる人にはならないので合いません。"}, "sentence_index": 0, "correct_answer": "婆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの婆は、まだ小学生で、ランドセルを背負っています。", "explanation": "ここは〈小学生〉の意味です。婆は年配の女性を指すので、ランドセルを背負う子どもには使わないので合いません。"}, {"text": "あの婆は、ネクタイを締めて、毎朝革靴で出かけます。", "explanation": "ここは〈男性〉の意味です。婆は女性を指す言葉で、ネクタイを締めて革靴で出かける男の人には使わないので合いません。"}, {"text": "あの婆は、夜になると屋根の上で静かに眠ります。", "explanation": "ここは〈猫〉の意味です。婆は人を指す言葉で、屋根の上で眠る動物には使わないので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37805, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "婆", "is_correct": true, "explanation": "昔話に出てくる年配の女性を指すので、「山に住む___がよく出てきます」に合います。"}, {"text": "川", "is_correct": false, "explanation": "川は水の流れで、山に住むという説明の対象にはならないので合いません。"}, {"text": "石", "is_correct": false, "explanation": "石は物で、山に住むという説明の対象にはならないので合いません。"}, {"text": "電話", "is_correct": false, "explanation": "電話は機械で、山に住むという説明の対象にはならないので合いません。"}], "explanations": {"婆": "昔話に出てくる年配の女性を指すので、「山に住む___がよく出てきます」に合います。", "川": "川は水の流れで、山に住むという説明の対象にはならないので合いません。", "石": "石は物で、山に住むという説明の対象にはならないので合いません。", "電話": "電話は機械で、山に住むという説明の対象にはならないので合いません。"}, "sentence_index": 6, "correct_answer": "婆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この婆は、先月出版されたばかりで、表紙が青いです。", "explanation": "ここは〈本〉の意味です。婆は人を指す言葉で、出版されて表紙がある物には使わないので合いません。"}, {"text": "この婆は、ガソリンを入れて一日中走ります。", "explanation": "ここは〈車〉の意味です。婆は人を指す言葉で、ガソリンで走る乗り物には使わないので合いません。"}, {"text": "この婆は、冷蔵庫で冷やすとおいしく飲めます。", "explanation": "ここは〈牛乳〉の意味です。婆は人を指す言葉で、冷やして飲む飲み物には使わないので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37805, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "バスで、婆を席をゆずりました。", "corrected_sentence": "バスで、婆に席をゆずりました。", "error_description": "「婆を席を」のように「を」が二つ重なって誤りです。席を譲る相手には「に」を使い、「婆に席をゆずりました」とします。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37805, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みに、婆を家へ遊びに行きました。", "corrected_sentence": "夏休みに、婆の家へ遊びに行きました。", "error_description": "「婆を家へ」の「を」が誤りです。婆に付いて家の持ち主を示す「の」を使い、「婆の家へ」とします。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37806, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「毎晩」に続けて名詞を修飾する連体の「の」。「毎晩の宿題」となる。"}, {"text": "を", "is_correct": false, "explanation": "「毎晩を宿題が」は目的語の形にならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "時点の「に」だが、名詞の前には置けない。「毎晩に宿題」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」で、名詞を修飾できない。「毎晩で宿題」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「毎晩」に続けて名詞を修飾する連体の「の」。「毎晩の宿題」となる。", "を": "「毎晩を宿題が」は目的語の形にならず、文が成り立たない。", "に": "時点の「に」だが、名詞の前には置けない。「毎晩に宿題」は不自然。", "で": "手段や場所の「で」で、名詞を修飾できない。「毎晩で宿題」は不自然。"}, "error_tags": {"を": "object", "に": "time_point", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37806, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「毎晩」に続けて名詞を修飾する連体の「の」。「毎晩の勉強」となる。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手の「と」だが、名詞を修飾できない。「毎晩と勉強」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、修飾の働きをしない。「毎晩より勉強」は文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、名詞修飾には使えない。「毎晩へ勉強」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「毎晩」に続けて名詞を修飾する連体の「の」。「毎晩の勉強」となる。", "と": "並列や相手の「と」だが、名詞を修飾できない。「毎晩と勉強」は意味が通らない。", "より": "比較の「より」で、修飾の働きをしない。「毎晩より勉強」は文にならない。", "へ": "方向の「へ」で、名詞修飾には使えない。「毎晩へ勉強」は不自然。"}, "error_tags": {"と": "companion", "より": "comparison", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37806, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まいばんというのは、その日の夜のことをぜんぶ、その次の夜も、そのまた次の夜も、ずっと同じようにするときにつかうことばです。", "primary_collocate": null, "pronunciation": "まいばん", "ipa": "maibaɴ", "syllable_count": 4, "sentences": [{"text": "毎晩の散歩は、私の楽しみです。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]の散歩[さんぽ]は、私[わたし]の楽[たの]しみです。", "sentence_source": "generated"}, {"text": "毎晩の宿題が終わってから、寝ます。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]の宿題[しゅくだい]が終[お]わってから、寝[ね]ます。", "sentence_source": "generated"}, {"text": "父は毎晩の食事を、自分で作ります。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "父[ちち]は毎晩[まいばん]の食事[しょくじ]を、自分[じぶん]で作[つく]ります。", "sentence_source": "generated"}, {"text": "毎晩の電話で、母の声を聞きます。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]の電話[でんわ]で、母[はは]の声[こえ]を聞[き]きます。", "sentence_source": "generated"}, {"text": "毎晩のように、近くで犬が鳴きます。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]のように、近[ちか]くで犬[いぬ]が鳴[な]きます。", "sentence_source": "generated"}, {"text": "毎晩の練習のおかげで、上手になりました。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]の練習[れんしゅう]のおかげで、上手[じょうず]になりました。", "sentence_source": "generated"}, {"text": "毎晩の日記は、もう三年続いています。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]の日記[にっき]は、もう三年[さんねん]続[つづ]いています。", "sentence_source": "generated"}, {"text": "毎晩の勉強は、一時間だけです。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]の勉強[べんきょう]は、一時間[いちじかん]だけです。", "sentence_source": "generated"}, {"text": "弟は毎晩の歯みがきを忘れません。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "弟[おとうと]は毎晩[まいばん]の歯[は]みがきを忘[わす]れません。", "sentence_source": "generated"}, {"text": "毎晩のお風呂で、一日の疲れをとります。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]のお風呂[ふろ]で、一日[いちにち]の疲[つか]れをとります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "毎晩", "label": "基本形"}, {"form": "毎晩の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "毎晩の習慣を表す名詞（毎晩の〜）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1008a082-97df-4e54-bb3b-338a2360e5cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37806, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毎晩", "is_correct": true, "explanation": "「毎晩の＋名詞」の形で、毎晩くり返される散歩を表す。文の意味にも合う。"}, {"text": "すぐ", "is_correct": false, "explanation": "副詞なので「すぐの散歩」という名詞修飾の形にならない。"}, {"text": "ときどき", "is_correct": false, "explanation": "副詞なので「ときどきの散歩」とは言えない。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "副詞なので「ゆっくりの散歩」とは言えない。"}], "explanations": {"毎晩": "「毎晩の＋名詞」の形で、毎晩くり返される散歩を表す。文の意味にも合う。", "すぐ": "副詞なので「すぐの散歩」という名詞修飾の形にならない。", "ときどき": "副詞なので「ときどきの散歩」とは言えない。", "ゆっくり": "副詞なので「ゆっくりの散歩」とは言えない。"}, "sentence_index": 0, "correct_answer": "毎晩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎晩のあいさつは、『おはよう』です。", "explanation": "ここは〈毎朝〉の意味。『おはよう』は朝のあいさつなので、〈毎晩〉とは合わない。"}, {"text": "毎晩の朝刊が、玄関に届きます。", "explanation": "ここは〈毎朝〉の意味。朝刊は朝に届くものなので、〈毎晩〉とは合わない。"}, {"text": "毎晩の朝礼で、全員が体操をします。", "explanation": "ここは〈毎朝〉の意味。朝礼は朝の行事なので、〈毎晩〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37806, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毎晩", "is_correct": true, "explanation": "「毎晩の＋名詞」の形で、毎晩くり返される日記を表す。文の意味にも合う。"}, {"text": "必ず", "is_correct": false, "explanation": "副詞なので「必ずの日記」という名詞修飾の形にならない。"}, {"text": "ずっと", "is_correct": false, "explanation": "副詞なので「ずっとの日記」とは言えない。"}, {"text": "たまに", "is_correct": false, "explanation": "副詞なので「たまにの日記」とは言えない。"}], "explanations": {"毎晩": "「毎晩の＋名詞」の形で、毎晩くり返される日記を表す。文の意味にも合う。", "必ず": "副詞なので「必ずの日記」という名詞修飾の形にならない。", "ずっと": "副詞なので「ずっとの日記」とは言えない。", "たまに": "副詞なので「たまにの日記」とは言えない。"}, "sentence_index": 6, "correct_answer": "毎晩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎晩の朝市で、野菜を買います。", "explanation": "ここは〈毎朝〉の意味。朝市は朝に開かれるので、〈毎晩〉とは合わない。"}, {"text": "毎晩の朝の体操で、体を動かします。", "explanation": "ここは〈毎朝〉の意味。朝の体操は朝に行うので、〈毎晩〉とは合わない。"}, {"text": "毎晩の始業式で、先生が話をします。", "explanation": "ここは〈毎学期〉の意味。始業式は学期に一度なので、〈毎晩〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37806, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎晩に宿題を、母が確かめます。", "corrected_sentence": "毎晩の宿題を、母が確かめます。", "error_description": "「毎晩」は名詞として名詞を修飾するとき、連体の「の」で続ける。「に」は誤り。正しくは「毎晩の宿題」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
