INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37807, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「毎晩」は、「毎晩、晩ごはんを食べる」のように、夜の時間帯について、毎日くり返し行うことを表す副詞です。", "primary_collocate": null, "pronunciation": "まいばん", "ipa": "maibaɴ", "syllable_count": 4, "sentences": [{"text": "毎晩、十時に寝ます。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]、十時[じゅうじ]に寝[ね]ます。", "sentence_source": "generated"}, {"text": "姉は毎晩、日記を書いています。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "姉[あね]は毎晩[まいばん]、日記[にっき]を書[か]いています。", "sentence_source": "generated"}, {"text": "毎晩、猫が窓の外で鳴きます。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]、猫[ねこ]が窓[まど]の外[そと]で鳴[な]きます。", "sentence_source": "generated"}, {"text": "私は毎晩、友達と電話で話します。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "私[わたし]は毎晩[まいばん]、友達[ともだち]と電話[でんわ]で話[はな]します。", "sentence_source": "generated"}, {"text": "毎晩、ご飯のあとに散歩をします。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]、ご飯[はん]のあとに散歩[さんぽ]をします。", "sentence_source": "generated"}, {"text": "毎晩勉強しているので、テストは大丈夫です。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]勉強[べんきょう]しているので、テストは大丈夫[だいじょうぶ]です。", "sentence_source": "generated"}, {"text": "夏は暑いので、毎晩シャワーを浴びます。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "夏[なつ]は暑[あつ]いので、毎晩[まいばん]シャワーを浴[あ]びます。", "sentence_source": "generated"}, {"text": "弟は毎晩、ゲームをして怒られます。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "弟[おとうと]は毎晩[まいばん]、ゲームをして怒[おこ]られます。", "sentence_source": "generated"}, {"text": "毎晩、星を見に庭へ出ます。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "毎晩[まいばん]、星[ほし]を見[み]に庭[にわ]へ出[で]ます。", "sentence_source": "generated"}, {"text": "祖母は毎晩、お茶を飲んでから寝ます。", "target_word": "毎晩", "complexity_tier": "T3", "furigana": "祖母[そぼ]は毎晩[まいばん]、お茶[ちゃ]を飲[の]んでから寝[ね]ます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "毎晩", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "夜に毎日くり返す動作を修飾する副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1008a082-97df-4e54-bb3b-338a2360e5cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37807, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毎晩", "is_correct": true, "explanation": "夜ごとにくり返す就寝を表す副詞。「毎晩、十時に寝ます」で文の意味が通る。"}, {"text": "毎朝", "is_correct": false, "explanation": "朝を表すので、夜十時に寝るという文と合わない。"}, {"text": "毎週", "is_correct": false, "explanation": "週単位の頻度を表すので、毎日の就寝とは合わない。"}, {"text": "毎年", "is_correct": false, "explanation": "年単位の頻度を表すので、毎日の就寝とは合わない。"}], "explanations": {"毎晩": "夜ごとにくり返す就寝を表す副詞。「毎晩、十時に寝ます」で文の意味が通る。", "毎朝": "朝を表すので、夜十時に寝るという文と合わない。", "毎週": "週単位の頻度を表すので、毎日の就寝とは合わない。", "毎年": "年単位の頻度を表すので、毎日の就寝とは合わない。"}, "sentence_index": 0, "correct_answer": "毎晩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎晩、おはようと言って寝ます。", "explanation": "ここは〈毎朝〉の意味。『おはよう』は朝のあいさつなので、〈毎晩〉とは合わない。"}, {"text": "毎晩、起きてすぐ顔を洗います。", "explanation": "ここは〈毎朝〉の意味。起きてすぐは朝のことなので、〈毎晩〉とは合わない。"}, {"text": "毎晩、朝刊を読みます。", "explanation": "ここは〈毎朝〉の意味。朝刊は朝に読むものなので、〈毎晩〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37807, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毎晩", "is_correct": true, "explanation": "夜ごとにくり返すシャワーを表す副詞。文の意味にも合う。"}, {"text": "毎月", "is_correct": false, "explanation": "月単位の頻度なので、毎日のシャワーとは合わない。"}, {"text": "毎週", "is_correct": false, "explanation": "週単位の頻度なので、毎日のシャワーとは合わない。"}, {"text": "昨年", "is_correct": false, "explanation": "過去の一年を指すので、くり返しを表す文脈と合わない。"}], "explanations": {"毎晩": "夜ごとにくり返すシャワーを表す副詞。文の意味にも合う。", "毎月": "月単位の頻度なので、毎日のシャワーとは合わない。", "毎週": "週単位の頻度なので、毎日のシャワーとは合わない。", "昨年": "過去の一年を指すので、くり返しを表す文脈と合わない。"}, "sentence_index": 6, "correct_answer": "毎晩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は毎晩、朝のお茶を飲んでから寝ます。", "explanation": "ここは〈毎朝〉の意味。朝のお茶は朝に飲むものなので、〈毎晩〉とは合わない。"}, {"text": "祖母は毎晩、一週間に一回、お風呂を掃除します。", "explanation": "ここは〈毎週〉の意味。一週間に一回は〈毎晩〉の毎日のくり返しと矛盾するので、〈毎週〉が合う。"}, {"text": "祖母は毎晩、起きてすぐ顔を洗います。", "explanation": "ここは〈毎朝〉の意味。起きてすぐは朝のことなので、〈毎晩〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37807, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎晩の、母がお弁当を作ります。", "corrected_sentence": "毎晩、母がお弁当を作ります。", "error_description": "副詞の〈毎晩〉に連体の「の」は付かない。読点で続けて「毎晩、」とするのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37807, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎晩で、父は本を読みます。", "corrected_sentence": "毎晩、父は本を読みます。", "error_description": "副詞の〈毎晩〉に格助詞の「で」は付かない。読点で続けて「毎晩、」とするのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37808, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「店の奥にトイレがある」で、場所を示す「奥に」なので合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すため、「奥をトイレがある」では成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所を示すため、存在を表す「ある」には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すため、存在を述べる文の場所には合わない。"}], "correct_answer": "に", "explanations": {"に": "「店の奥にトイレがある」で、場所を示す「奥に」なので合う。", "を": "「を」は動作の対象を示すため、「奥をトイレがある」では成り立たない。", "で": "「で」は動作の場所を示すため、存在を表す「ある」には合わない。", "へ": "「へ」は移動の方向を示すため、存在を述べる文の場所には合わない。"}, "error_tags": {"を": "目的語の誤り", "へ": "移動の方向", "で": "動作の場所（存在の文に合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37808, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「もっと奥に詰めて座る」で、移動先の場所を示す「奥に」なので合う。"}, {"text": "が", "is_correct": false, "explanation": "「奥が詰めて」は主語になり、「座る」の動作が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「奥と詰めて」は並列になり、動作の場所を示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すため、「奥より詰めて座る」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「もっと奥に詰めて座る」で、移動先の場所を示す「奥に」なので合う。", "が": "「奥が詰めて」は主語になり、「座る」の動作が成り立たない。", "と": "「奥と詰めて」は並列になり、動作の場所を示せないので合わない。", "より": "「より」は比較の基準を示すため、「奥より詰めて座る」は意味が通らない。"}, "error_tags": {"が": "主語の誤り", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37808, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "なかの ふかい ところ。", "primary_collocate": null, "pronunciation": "おく", "ipa": "okɯ", "syllable_count": 2, "sentences": [{"text": "箱の奥にボールが入ってしまった。", "target_word": "奥", "complexity_tier": "T2", "furigana": "箱[はこ]の奥[おく]にボールが入[はい]ってしまった。", "sentence_source": "generated"}, {"text": "店の奥にトイレがあります。", "target_word": "奥", "complexity_tier": "T2", "furigana": "店[みせ]の奥[おく]にトイレがあります。", "sentence_source": "generated"}, {"text": "犬は庭の奥で寝ている。", "target_word": "奥", "complexity_tier": "T2", "furigana": "犬[いぬ]は庭[にわ]の奥[おく]で寝[ね]ている。", "sentence_source": "generated"}, {"text": "口を大きく開けて、奥まで見せてください。", "target_word": "奥", "complexity_tier": "T2", "furigana": "口[くち]を大[おお]きく開[あ]けて、奥[おく]まで見[み]せてください。", "sentence_source": "generated"}, {"text": "森の奥に、小さな家が見える。", "target_word": "奥", "complexity_tier": "T2", "furigana": "森[もり]の奥[おく]に、小[ちい]さな家[いえ]が見[み]える。", "sentence_source": "generated"}, {"text": "部屋の奥の机で、兄が勉強している。", "target_word": "奥", "complexity_tier": "T2", "furigana": "部屋[へや]の奥[おく]の机[つくえ]で、兄[あに]が勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "冷蔵庫の奥から、古いチーズが出てきた。", "target_word": "奥", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の奥[おく]から、古[ふる]いチーズが出[で]てきた。", "sentence_source": "generated"}, {"text": "もっと奥につめて座ってください。", "target_word": "奥", "complexity_tier": "T2", "furigana": "もっと奥[おく]につめて座[すわ]ってください。", "sentence_source": "generated"}, {"text": "洞窟の奥は暗くて、何も見えなかった。", "target_word": "奥", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の奥[おく]は暗[くら]くて、何[なに]も見[み]えなかった。", "sentence_source": "generated"}, {"text": "電車の奥のほうが空いているよ。", "target_word": "奥", "complexity_tier": "T2", "furigana": "電車[でんしゃ]の奥[おく]のほうが空[す]いているよ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "奥", "label": "基本形"}], "register": "中立", "sense_fingerprint": "入り口から見て、中の深いところ(箱・店・部屋・口の中など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4171fa00-9184-4481-a2ec-a876e376ecb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37808, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奥", "is_correct": true, "explanation": "箱の内側の深い所にボールが入るという意味に合う。"}, {"text": "春", "is_correct": false, "explanation": "季節は箱の中に入らないので、「箱の春にボールが入る」は成り立たない。"}, {"text": "仕事", "is_correct": false, "explanation": "仕事は箱に入るものではないので合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "「箱の手紙に」では場所として成り立たず、ボールが入る文に合わない。"}], "explanations": {"奥": "箱の内側の深い所にボールが入るという意味に合う。", "春": "季節は箱の中に入らないので、「箱の春にボールが入る」は成り立たない。", "仕事": "仕事は箱に入るものではないので合わない。", "手紙": "「箱の手紙に」では場所として成り立たず、ボールが入る文に合わない。"}, "sentence_index": 0, "correct_answer": "奥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓の奥に、ステッカーを貼った。", "explanation": "ここは〈表面〉の意味。奥は内側の深い所なので、ステッカーを貼る表面の位置には使わない。"}, {"text": "鏡の奥に、指の跡が残っている。", "explanation": "ここは〈表面〉の意味。奥は深い所なので、鏡の面に付いた跡の位置には使わない。"}, {"text": "手紙の奥に、切手を貼った。", "explanation": "ここは〈外側〉の意味。奥は内側の深い所なので、切手を貼る表面の位置には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37808, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奥", "is_correct": true, "explanation": "冷蔵庫の内側の深い所から出てくるという場所の意味に合う。"}, {"text": "ラベル", "is_correct": false, "explanation": "ラベルは貼るもので、チーズが出てくる場所ではない。"}, {"text": "脚", "is_correct": false, "explanation": "脚は支える部分で、そこからチーズが出る場所ではない。"}, {"text": "電源", "is_correct": false, "explanation": "電源はコードの接続部で、そこから食品が出てくる場所ではない。"}], "explanations": {"奥": "冷蔵庫の内側の深い所から出てくるという場所の意味に合う。", "ラベル": "ラベルは貼るもので、チーズが出てくる場所ではない。", "脚": "脚は支える部分で、そこからチーズが出る場所ではない。", "電源": "電源はコードの接続部で、そこから食品が出てくる場所ではない。"}, "sentence_index": 6, "correct_answer": "奥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "紙の奥に、名前を書いた。", "explanation": "ここは〈裏〉の意味。奥は入り口から遠い深い所なので、紙の裏側に名前を書く位置には使わない。"}, {"text": "ペンの奥を持って、字を書いた。", "explanation": "ここは〈後ろ〉の意味。奥は深い所なので、ペンの後ろの端を持つ位置には使わない。"}, {"text": "ボタンの奥を押した。", "explanation": "ここは〈表面〉の意味。奥は内側の深い所なので、ボタンの表面を押す位置には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37808, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "引き出しの奥が、古い手紙をしまってある。", "corrected_sentence": "引き出しの奥に、古い手紙をしまってある。", "error_description": "「しまってある」は場所を「に」で示す。「奥」に付いた「が」が誤りで、正しくは「奥に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37808, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店の奥を、テーブルが並んでいる。", "corrected_sentence": "店の奥に、テーブルが並んでいる。", "error_description": "「並んでいる」は場所を「に」で示す。「奥」に付いた「を」が誤りで、正しくは「奥に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d0f81d-67e4-45a7-8efe-fb24f68b76db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37810, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「言葉に元気が出る」で、言葉が元気の出るきっかけを表す「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「言葉を元気が出た」では「を」が目的語を示すことになるが、出るのは元気なので文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、言葉が元気の行き先になるわけではないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、言葉と元気が並んで出るわけではないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「言葉に元気が出る」で、言葉が元気の出るきっかけを表す「に」が正しい。", "を": "「言葉を元気が出た」では「を」が目的語を示すことになるが、出るのは元気なので文が成り立たない。", "へ": "「へ」は方向を示すが、言葉が元気の行き先になるわけではないので合わない。", "と": "「と」は並列や相手を示すが、言葉と元気が並んで出るわけではないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
