INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37810, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が話す声や、その人の言うこと。", "primary_collocate": null, "pronunciation": "ことば", "ipa": "kotoba", "syllable_count": 3, "sentences": [{"text": "外国では言葉が通じなくて、困りました。", "target_word": "言葉", "complexity_tier": "T3", "furigana": "外国[がいこく]では言葉[ことば]が通[つう]じなくて、困[こま]りました。", "sentence_source": "generated"}, {"text": "彼女のやさしい言葉に、元気が出ました。", "target_word": "言葉", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のやさしい言葉[ことば]に、元気[げんき]が出[で]ました。", "sentence_source": "generated"}, {"text": "母は、怒っても乱暴な言葉は使いません。", "target_word": "言葉", "complexity_tier": "T3", "furigana": "母[はは]は、怒[おこ]っても乱暴[らんぼう]な言葉[ことば]は使[つか]いません。", "sentence_source": "generated"}, {"text": "赤ちゃんが少しずつ言葉を覚えています。", "target_word": "言葉", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが少[すこ]しずつ言葉[ことば]を覚[おぼ]えています。", "sentence_source": "generated"}, {"text": "うれしくて、お礼の言葉が出ませんでした。", "target_word": "言葉", "complexity_tier": "T3", "furigana": "うれしくて、お礼[れい]の言葉[ことば]が出[で]ませんでした。", "sentence_source": "generated"}, {"text": "友だちの言葉を信じて、もう一度挑戦しました。", "target_word": "言葉", "complexity_tier": "T3", "furigana": "友[とも]だちの言葉[ことば]を信[しん]じて、もう一度[いちど]挑戦[ちょうせん]しました。", "sentence_source": "generated"}, {"text": "先生の言葉を、ノートに書いておきました。", "target_word": "言葉", "complexity_tier": "T3", "furigana": "先生[せんせい]の言葉[ことば]を、ノートに書[か]いておきました。", "sentence_source": "generated"}, {"text": "国が違うと、言葉も習慣も違います。", "target_word": "言葉", "complexity_tier": "T3", "furigana": "国[くに]が違[ちが]うと、言葉[ことば]も習慣[しゅうかん]も違[ちが]います。", "sentence_source": "generated"}, {"text": "別れるとき、彼は最後に感謝の言葉を残して去りました。", "target_word": "言葉", "complexity_tier": "T3", "furigana": "別[わか]れるとき、彼[かれ]は最後[さいご]に感謝[かんしゃ]の言葉[ことば]を残[のこ]して去[さ]りました。", "sentence_source": "generated"}, {"text": "人を傷つける言葉は、使わないように気をつけています。", "target_word": "言葉", "complexity_tier": "T3", "furigana": "人[ひと]を傷[きず]つける言葉[ことば]は、使[つか]わないように気[き]をつけています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "言葉", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が口にする話や、話された内容・言い方。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1af43bfb-eb6a-43c0-a4ea-30a6a8d66fad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37810, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言葉", "is_correct": true, "explanation": "「通じる」は話や言葉が相手に伝わることを表すので、「外国では言葉が通じない」で自然に成り立つ。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は通じるものではなく、読んだり送ったりするもの。「手紙が通じない」とは言わない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は見て使うもので、相手に通じるものではない。「地図が通じない」は不自然。"}, {"text": "看板", "is_correct": false, "explanation": "看板は目に入って読むもので、相手との意思疎通の対象ではない。「看板が通じない」とは言わない。"}], "explanations": {"言葉": "「通じる」は話や言葉が相手に伝わることを表すので、「外国では言葉が通じない」で自然に成り立つ。", "手紙": "手紙は通じるものではなく、読んだり送ったりするもの。「手紙が通じない」とは言わない。", "地図": "地図は見て使うもので、相手に通じるものではない。「地図が通じない」は不自然。", "看板": "看板は目に入って読むもので、相手との意思疎通の対象ではない。「看板が通じない」とは言わない。"}, "sentence_index": 0, "correct_answer": "言葉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "赤ちゃんは大きな言葉で泣いた。", "explanation": "ここは〈泣き声〉の意味。泣き声は大きく出せるが、言葉は話す内容なので、言葉で泣くとは言わないので合わない。"}, {"text": "その会議では、言葉を広げすぎて結論が出なかった。", "explanation": "言葉は広げるものではないので、この文は不自然。"}, {"text": "子どもが言葉を描いて、母に渡した。", "explanation": "ここは〈絵〉の意味。絵は描けるが、言葉を描くとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37810, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言葉", "is_correct": true, "explanation": "先生が話した内容を書き留めるので、「先生の言葉を書く」が自然。"}, {"text": "写真", "is_correct": false, "explanation": "写真は書くものではなく撮るもの。「写真を書く」とは言わない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は見たり直したりするもので、ノートに書く対象にはならない。"}, {"text": "机", "is_correct": false, "explanation": "机はノートに書く対象ではない。「机を書く」は不自然。"}], "explanations": {"言葉": "先生が話した内容を書き留めるので、「先生の言葉を書く」が自然。", "写真": "写真は書くものではなく撮るもの。「写真を書く」とは言わない。", "時計": "時計は見たり直したりするもので、ノートに書く対象にはならない。", "机": "机はノートに書く対象ではない。「机を書く」は不自然。"}, "sentence_index": 6, "correct_answer": "言葉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は言葉を浮かべて、楽しそうに笑った。", "explanation": "ここは〈表情〉の意味。表情を浮かべるとは言うが、言葉を浮かべるとは言わない。"}, {"text": "窓から言葉が差し込んで、部屋が明るくなった。", "explanation": "ここは〈光〉の意味。光が差し込むとは言うが、言葉が差し込むことはない。"}, {"text": "彼は言葉を取って、先輩に丁寧に接した。", "explanation": "ここは〈態度〉の意味。態度を取るとは言うが、言葉を取るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37810, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の言葉を、いつも私を励ましてくれる。", "corrected_sentence": "彼の言葉は、いつも私を励ましてくれる。", "error_description": "主語を示す「は」が「を」になっている。「言葉は〜励ましてくれる」の形が正しく、「を」にすると目的語になって文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37810, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の言葉を、胸が熱くなった。", "corrected_sentence": "彼女の言葉に、胸が熱くなった。", "error_description": "感動の原因を示す「に」が「を」になっている。「言葉に胸が熱くなる」が正しく、「を」にすると目的語になって文の筋が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
