INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37812, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「心が疲れた」は心を主語にした文で、「が」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「心へ疲れた」は方向を示すが、疲れるという状態の主語にはならないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「心より疲れた」は比較を示すが、比べる相手がないので文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、心と疲れる、という文にはならない。"}], "correct_answer": "が", "explanations": {"が": "「心が疲れた」は心を主語にした文で、「が」が正しい。", "へ": "「心へ疲れた」は方向を示すが、疲れるという状態の主語にはならないので合わない。", "より": "「心より疲れた」は比較を示すが、比べる相手がないので文が成り立たない。", "と": "「と」は並列や相手を示すが、心と疲れる、という文にはならない。"}, "error_tags": {"へ": "方向", "より": "比較", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37812, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "こころは、ひとのきもちのことです。", "primary_collocate": null, "pronunciation": "こころ", "ipa": "kokoɾo", "syllable_count": 3, "sentences": [{"text": "彼のやさしい言葉で、心があたたかくなりました。", "target_word": "心", "complexity_tier": "T3", "furigana": "彼[かれ]のやさしい言葉[ことば]で、心[こころ]があたたかくなりました。", "sentence_source": "generated"}, {"text": "悲しいことがあって、心が重いです。", "target_word": "心", "complexity_tier": "T3", "furigana": "悲[かな]しいことがあって、心[こころ]が重[おも]いです。", "sentence_source": "generated"}, {"text": "友だちの励ましに、心がとても軽くなりました。", "target_word": "心", "complexity_tier": "T3", "furigana": "友[とも]だちの励[はげ]ましに、心[こころ]がとても軽[かる]くなりました。", "sentence_source": "generated"}, {"text": "母は、心の広い人です。", "target_word": "心", "complexity_tier": "T3", "furigana": "母[はは]は、心[こころ]の広[ひろ]い人[ひと]です。", "sentence_source": "generated"}, {"text": "発表の前は、緊張して心が落ち着きません。", "target_word": "心", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の前[まえ]は、緊張[きんちょう]して心[こころ]が落[お]ち着[つ]きません。", "sentence_source": "generated"}, {"text": "手紙には、書いた人の心が込められています。", "target_word": "心", "complexity_tier": "T3", "furigana": "手紙[てがみ]には、書[か]いた人[ひと]の心[こころ]が込[こ]められています。", "sentence_source": "generated"}, {"text": "彼女は心を開いて、悩みを話してくれました。", "target_word": "心", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は心[こころ]を開[ひら]いて、悩[なや]みを話[はな]してくれました。", "sentence_source": "generated"}, {"text": "心が疲れたときは、海を見に行きます。", "target_word": "心", "complexity_tier": "T3", "furigana": "心[こころ]が疲[つか]れたときは、海[うみ]を見[み]に行[い]きます。", "sentence_source": "generated"}, {"text": "子どもの心は、まっすぐで美しいです。", "target_word": "心", "complexity_tier": "T3", "furigana": "子[こ]どもの心[こころ]は、まっすぐで美[うつく]しいです。", "sentence_source": "generated"}, {"text": "友だちの親切に、心を打たれました。", "target_word": "心", "complexity_tier": "T3", "furigana": "友[とも]だちの親切[しんせつ]に、心[こころ]を打[う]たれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "心", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人の中にある気持ちや感情、思いやりなどの内面。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1af43bfb-eb6a-43c0-a4ea-30a6a8d66fad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37812, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心", "is_correct": true, "explanation": "「心があたたかくなる」は、気持ちがやわらぐことを表すので自然に成り立つ。"}, {"text": "窓", "is_correct": false, "explanation": "窓は温度が変わることはあっても、あたたかくなるのは気持ちや体の感覚であり、窓が主語では不自然。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶があたたかくなるとは言わない。文の主語として意味が通じない。"}, {"text": "机", "is_correct": false, "explanation": "机があたたかくなるのは不自然で、気持ちの変化を表す文には合わない。"}], "explanations": {"心": "「心があたたかくなる」は、気持ちがやわらぐことを表すので自然に成り立つ。", "窓": "窓は温度が変わることはあっても、あたたかくなるのは気持ちや体の感覚であり、窓が主語では不自然。", "花瓶": "花瓶があたたかくなるとは言わない。文の主語として意味が通じない。", "机": "机があたたかくなるのは不自然で、気持ちの変化を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は心を握って、ボールを投げた。", "explanation": "ここは〈手〉の意味。手を握るとは言うが、心を握るとは言わないので合わない。"}, {"text": "彼女は心を速くして、階段を駆け上がった。", "explanation": "ここは〈足〉の意味。足を速くするとは言うが、心を速くするとは言わないので合わない。"}, {"text": "彼女は心を見開いて、驚いた表情を見せた。", "explanation": "ここは〈目〉の意味。目を見開くとは言うが、心を見開くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37812, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心", "is_correct": true, "explanation": "「心を開く」は、気持ちを相手にさらけ出すという慣用的な言い方で、ここで自然。"}, {"text": "約束", "is_correct": false, "explanation": "約束は開くものではない。「約束を開く」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は開けるものではない。「天気を開く」とは言わない。"}, {"text": "猫", "is_correct": false, "explanation": "猫は開くものではない。「猫を開く」は不自然。"}], "explanations": {"心": "「心を開く」は、気持ちを相手にさらけ出すという慣用的な言い方で、ここで自然。", "約束": "約束は開くものではない。「約束を開く」は成り立たない。", "天気": "天気は開けるものではない。「天気を開く」とは言わない。", "猫": "猫は開くものではない。「猫を開く」は不自然。"}, "sentence_index": 6, "correct_answer": "心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちが心を貸してくれたので、宿題が早く終わった。", "explanation": "ここは〈手〉の意味。手を貸すとは言うが、心を貸すとは言わないので合わない。"}, {"text": "彼女は心を出して、みんなの前で意見を言った。", "explanation": "ここは〈口〉の意味。口を出すとは言うが、心を出すとは言わないので合わない。"}, {"text": "ひどいことを言われ、心を立てて教室を出た。", "explanation": "ここは〈腹〉の意味。腹を立てるとは言うが、心を立てるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37812, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の一言で、心をすっと晴れた。", "corrected_sentence": "彼女の一言で、心がすっと晴れた。", "error_description": "「晴れる」は自動詞なので、主語を示す「が」が正しい。「を」にすると目的語になり、「心を晴れた」は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37812, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "深呼吸をして、心が落ち着けた。", "corrected_sentence": "深呼吸をして、心を落ち着けた。", "error_description": "「落ち着ける」は他動詞なので、目的語を示す「を」が正しい。「が」にすると、自動詞「落ち着く」の主語になり、「落ち着けた」とつながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37814, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「東に大きな公園がある」で、場所を示す「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「東を大きな公園があります」は目的語化してしまい、存在の文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「東と大きな公園があります」は並列の形になり、場所の存在を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「東へ大きな公園があります」は方向を示すが、存在の場所にはならない。"}], "correct_answer": "に", "explanations": {"に": "「東に大きな公園がある」で、場所を示す「に」が正しい。", "を": "「東を大きな公園があります」は目的語化してしまい、存在の文として成り立たない。", "と": "「東と大きな公園があります」は並列の形になり、場所の存在を表せない。", "へ": "「東へ大きな公園があります」は方向を示すが、存在の場所にはならない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "西", "is_correct": true, "explanation": "東の対義語。太陽がのぼる方角と沈む方角として対になる。"}, {"text": "北", "is_correct": false, "explanation": "北は東の反対ではない。東の反対は西。"}, {"text": "南", "is_correct": false, "explanation": "南は東と並ぶ方角だが、対義語ではない。"}, {"text": "中", "is_correct": false, "explanation": "中は方角の中心を表し、東の対義語ではない。"}], "correct_answer": "西", "explanations": {"西": "東の対義語。太陽がのぼる方角と沈む方角として対になる。", "北": "北は東の反対ではない。東の反対は西。", "南": "南は東と並ぶ方角だが、対義語ではない。", "中": "中は方角の中心を表し、東の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37814, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "西", "is_correct": true, "explanation": "東の対義語。太陽がのぼる方角と沈む方角として対になる。"}, {"text": "上", "is_correct": false, "explanation": "上は方角ではなく、東の反対ではない。"}, {"text": "下", "is_correct": false, "explanation": "下は方角ではなく、東の反対ではない。"}, {"text": "左", "is_correct": false, "explanation": "左は右の反対であり、東の対義語ではない。"}], "correct_answer": "西", "explanations": {"西": "東の対義語。太陽がのぼる方角と沈む方角として対になる。", "上": "上は方角ではなく、東の反対ではない。", "下": "下は方角ではなく、東の反対ではない。", "左": "左は右の反対であり、東の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37814, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ひがしは、たいようがのぼるところの方角です。", "primary_collocate": null, "pronunciation": "ひがし", "ipa": "çiɡaɕi", "syllable_count": 3, "sentences": [{"text": "朝、太陽は東の空からのぼります。", "target_word": "東", "complexity_tier": "T3", "furigana": "朝(あさ)、太陽(たいよう)は東(ひがし)の空(そら)からのぼります。", "sentence_source": "generated"}, {"text": "私の家の東に、大きな公園があります。", "target_word": "東", "complexity_tier": "T3", "furigana": "私(わたし)の家(いえ)の東(ひがし)に、大(おお)きな公園(こうえん)があります。", "sentence_source": "generated"}, {"text": "この道を東へまっすぐ行くと、駅があります。", "target_word": "東", "complexity_tier": "T3", "furigana": "この道(みち)を東(ひがし)へまっすぐ行(い)くと、駅(えき)があります。", "sentence_source": "generated"}, {"text": "東の窓から朝の光が入るので、部屋が明るいです。", "target_word": "東", "complexity_tier": "T3", "furigana": "東(ひがし)の窓(まど)から朝(あさ)の光(ひかり)が入(はい)るので、部屋(へや)が明(あか)るいです。", "sentence_source": "generated"}, {"text": "地図を見ると、海は町の東にあります。", "target_word": "東", "complexity_tier": "T3", "furigana": "地図(ちず)を見(み)ると、海(うみ)は町(まち)の東(ひがし)にあります。", "sentence_source": "generated"}, {"text": "東に向かって歩いたら、小さな川に出ました。", "target_word": "東", "complexity_tier": "T3", "furigana": "東(ひがし)に向(む)かって歩(ある)いたら、小(ちい)さな川(かわ)に出(で)ました。", "sentence_source": "generated"}, {"text": "太陽は東からのぼって、西にしずみます。", "target_word": "東", "complexity_tier": "T3", "furigana": "太陽(たいよう)は東(ひがし)からのぼって、西(にし)にしずみます。", "sentence_source": "generated"}, {"text": "東の山の上に、大きな月が見えました。", "target_word": "東", "complexity_tier": "T3", "furigana": "東(ひがし)の山(やま)の上(うえ)に、大(おお)きな月(つき)が見(み)えました。", "sentence_source": "generated"}, {"text": "台風は東へ進んで、夜には海に出ました。", "target_word": "東", "complexity_tier": "T3", "furigana": "台風(たいふう)は東(ひがし)へ進(すす)んで、夜(よる)には海(うみ)に出(で)ました。", "sentence_source": "generated"}, {"text": "学校の東に住んでいる友だちと、いっしょに帰ります。", "target_word": "東", "complexity_tier": "T3", "furigana": "学校(がっこう)の東(ひがし)に住(す)んでいる友(とも)だちと、いっしょに帰(かえ)ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "東", "label": "漢字表記"}, {"form": "ひがし", "label": "ひらがな表記"}], "register": "中立（です・ます体）", "sense_fingerprint": "太陽がのぼる方角。西の反対。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1af43bfb-eb6a-43c0-a4ea-30a6a8d66fad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37814, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "東", "is_correct": true, "explanation": "太陽がのぼる方角なので、「東の空からのぼる」が成り立つ。"}, {"text": "西", "is_correct": false, "explanation": "太陽がのぼるのは西ではない。西は太陽が沈む方角なので、この文脈には合わない。"}, {"text": "南", "is_correct": false, "explanation": "太陽は南からのぼらない。文脈の「のぼる」とは合わない。"}, {"text": "北", "is_correct": false, "explanation": "太陽は北からのぼらない。文脈の「のぼる」とは合わない。"}], "explanations": {"東": "太陽がのぼる方角なので、「東の空からのぼる」が成り立つ。", "西": "太陽がのぼるのは西ではない。西は太陽が沈む方角なので、この文脈には合わない。", "南": "太陽は南からのぼらない。文脈の「のぼる」とは合わない。", "北": "太陽は北からのぼらない。文脈の「のぼる」とは合わない。"}, "sentence_index": 0, "correct_answer": "東"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "東を大きく振って、友だちに合図した。", "explanation": "ここは〈旗〉の意味。旗は振るが、東は振るものではないので合わない。"}, {"text": "兄は東に合格して、家族みんなで喜んだ。", "explanation": "ここは〈東京大学〉の略。方角の意味ではないので、この文の〈東〉は定義に合わない。"}, {"text": "東をきれいに磨いて、棚に飾った。", "explanation": "ここは〈置物〉の意味。置物は磨いて飾るが、東は物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37814, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "東", "is_correct": true, "explanation": "太陽がのぼる方角なので、「東からのぼって、西にしずむ」が自然に成り立つ。"}, {"text": "左", "is_correct": false, "explanation": "左は太陽のぼる方角ではない。文の流れに合わない。"}, {"text": "右", "is_correct": false, "explanation": "右は方角ではなく、太陽がのぼる方向として使わない。"}, {"text": "夜", "is_correct": false, "explanation": "太陽は夜からのぼらない。時間の語は方角の位置に入らない。"}], "explanations": {"東": "太陽がのぼる方角なので、「東からのぼって、西にしずむ」が自然に成り立つ。", "左": "左は太陽のぼる方角ではない。文の流れに合わない。", "右": "右は方角ではなく、太陽がのぼる方向として使わない。", "夜": "太陽は夜からのぼらない。時間の語は方角の位置に入らない。"}, "sentence_index": 6, "correct_answer": "東"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "東を握りしめて、ゴールへ走った。", "explanation": "ここは〈バトン〉の意味。バトンは握るが、東は握るものではないので合わない。"}, {"text": "明日のテストに備えて、東をしっかり勉強した。", "explanation": "ここは〈東洋学〉の意味。東洋学は勉強するが、〈東〉という語を勉強するとは言わないので合わない。"}, {"text": "彼は東を着て、遠足へ出かけた。", "explanation": "ここは〈服〉の意味。服は着るが、東を着るとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37814, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を東が向けると、朝日がよく入る。", "corrected_sentence": "窓を東に向けると、朝日がよく入る。", "error_description": "「向ける」の方向を示す「に」が「が」になっている。「が」にすると東が主語になってしまい、方向を表せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37814, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海は町の東を広がっている。", "corrected_sentence": "海は町の東に広がっている。", "error_description": "場所を示す「に」が「を」になっている。「広がる」は目的語を取らない自動詞なので、「東に」が正しく、「東を」にすると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37816, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ムラには」の「に」。存在する場所を示すので正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、ここはお店が存在する場所を言う文なので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「ムラの」だけでは文が切れて合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すが、「ムラと、お店が一軒もない」は文の関係が通らない。"}], "correct_answer": "に", "explanations": {"に": "「ムラには」の「に」。存在する場所を示すので正解。", "を": "「を」は動作の対象を示すが、ここはお店が存在する場所を言う文なので合わない。", "の": "「の」は名詞をつなぐ助詞で、「ムラの」だけでは文が切れて合わない。", "と": "「と」は並列を示すが、「ムラと、お店が一軒もない」は文の関係が通らない。"}, "error_tags": {"を": "対象", "の": "所属", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37816, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「川の向こうのムラへ行く」の「へ」。行く方向を示すので正解。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所や手段を示すが、「ムラで行く」は成り立たず、行き先には使えない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる基準を示すが、「ムラより行く」は比較の文にならず、行き先を言う文には合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「ムラが行くには」ではムラが行くことになり、文の流れに合わない。"}], "correct_answer": "へ", "explanations": {"へ": "「川の向こうのムラへ行く」の「へ」。行く方向を示すので正解。", "で": "「で」は動作の場所や手段を示すが、「ムラで行く」は成り立たず、行き先には使えない。", "より": "「より」は比べる基準を示すが、「ムラより行く」は比較の文にならず、行き先を言う文には合わない。", "が": "「が」は主語を示すが、「ムラが行くには」ではムラが行くことになり、文の流れに合わない。"}, "error_tags": {"で": "場所", "より": "比較", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37816, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がたくさん住んでいる、町より小さいところ。", "primary_collocate": null, "pronunciation": "むら", "ipa": "mɯɾa", "syllable_count": 2, "sentences": [{"text": "山のふもとの小さなムラに、五十人ほどが住んでいる。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "山[やま]のふもとの小[ちい]さなムラに、五十人[ごじゅうにん]ほどが住[す]んでいる。", "sentence_source": "generated"}, {"text": "このムラには、お店が一軒もない。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "このムラには、お店[みせ]が一軒[いっけん]もない。", "sentence_source": "generated"}, {"text": "ムラの人たちは、みんな顔見知りだ。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "ムラの人[ひと]たちは、みんな顔見知[かおみし]りだ。", "sentence_source": "generated"}, {"text": "祖母は海の近くのムラで生まれ育った。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "祖母[そぼ]は海[うみ]の近[ちか]くのムラで生[う]まれ育[そだ]った。", "sentence_source": "generated"}, {"text": "ムラから町まで、バスで一時間かかる。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "ムラから町[まち]まで、バスで一時間[いちじかん]かかる。", "sentence_source": "generated"}, {"text": "雪が深いので、冬はムラの道が通れなくなる。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "雪[ゆき]が深[ふか]いので、冬[ふゆ]はムラの道[みち]が通[とお]れなくなる。", "sentence_source": "generated"}, {"text": "ムラのお祭りには、遠くからも人が集まる。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "ムラのお祭[まつ]りには、遠[とお]くからも人[ひと]が集[あつ]まる。", "sentence_source": "generated"}, {"text": "川の向こうのムラへ行くには、橋をわたる。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "川[かわ]の向[む]こうのムラへ行[い]くには、橋[はし]をわたる。", "sentence_source": "generated"}, {"text": "若い人が町へ出て、ムラは静かになった。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]が町[まち]へ出[で]て、ムラは静[しず]かになった。", "sentence_source": "generated"}, {"text": "ムラの中心にある広場で、子どもたちが遊んでいる。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "ムラの中心[ちゅうしん]にある広場[ひろば]で、子[こ]どもたちが遊[あそ]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ムラ", "label": "基本形"}], "register": "一般", "sense_fingerprint": "人が住む、町より小さな地域（村）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37816, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ムラ", "is_correct": true, "explanation": "人が五十人ほど住む小さな集落を指すので正解。"}, {"text": "川", "is_correct": false, "explanation": "川に人が住むとは言えず、「小さな川に五十人が住む」は意味が通らない。"}, {"text": "机", "is_correct": false, "explanation": "机に人が住むことはなく、文が成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓に人が住むことはなく、文が成り立たない。"}], "explanations": {"ムラ": "人が五十人ほど住む小さな集落を指すので正解。", "川": "川に人が住むとは言えず、「小さな川に五十人が住む」は意味が通らない。", "机": "机に人が住むことはなく、文が成り立たない。", "窓": "窓に人が住むことはなく、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "ムラ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このムラは人口が十万人で、市役所の前に大きな駅がある。", "explanation": "ここは〈市〉の意味。市は大きな行政単位で、小さな集落のムラとは合わない。"}, {"text": "このムラには工場が五つ並び、夜も機械の音が続く。", "explanation": "ここは〈工業地帯〉の意味。工場が集まる地域は工業地帯と言い、小さな集落のムラとは合わない。"}, {"text": "このムラには高層マンションが並び、住宅地として人気だ。", "explanation": "ここは〈住宅地〉の意味。高層マンションが並ぶ都市の住宅地は、ムラの小さな集落とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37816, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ムラ", "is_correct": true, "explanation": "村で行われるお祭りを指し、人が集まる文に合うので正解。"}, {"text": "紙", "is_correct": false, "explanation": "「紙のお祭り」とは言わず、文が成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "雨にお祭りはなく、「雨のお祭り」は意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "窓のお祭りは成り立たず、文に合わない。"}], "explanations": {"ムラ": "村で行われるお祭りを指し、人が集まる文に合うので正解。", "紙": "「紙のお祭り」とは言わず、文が成り立たない。", "雨": "雨にお祭りはなく、「雨のお祭り」は意味が通らない。", "窓": "窓のお祭りは成り立たず、文に合わない。"}, "sentence_index": 6, "correct_answer": "ムラ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このムラには高層ビルが並び、ビジネス街が広がる。", "explanation": "ここは〈都会〉の意味。ビジネス街が広がる大都市の様子で、小さな集落のムラとは合わない。"}, {"text": "このムラには学生が二百人住み、寮の食堂が三つある。", "explanation": "ここは〈寮〉の意味。学生が共同で暮らす施設で、地域の集落を表すムラとは合わない。"}, {"text": "このムラは社員が千人いて、本社が大きなビルにある。", "explanation": "ここは〈会社〉の意味。社員が働く組織を指すので、地域の集落とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37816, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この小さなムラを、若い人が多く住んでいる。", "corrected_sentence": "この小さなムラに、若い人が多く住んでいる。", "error_description": "「住む」は場所に「に」を取る。ムラの直後に「を」を使うのは誤りで、正しくは「ムラに住む」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37816, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若い人が町へ出て、ムラは寂しかになった。", "corrected_sentence": "若い人が町へ出て、ムラは寂しくなった。", "error_description": "形容詞「寂しい」の連用形は「寂しく」で、「寂しかに」は誤り。正しくは「寂しくなった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37817, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ムラの寄り合い」の「の」。ムラに属する集まりを示すので正解。"}, {"text": "を", "is_correct": false, "explanation": "「ムラを寄り合い」は動作の対象にならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ムラに寄り合い」は場所と寄り合いの関係が不自然で合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、寄り合いは行くものではないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「ムラの寄り合い」の「の」。ムラに属する集まりを示すので正解。", "を": "「ムラを寄り合い」は動作の対象にならず、文が成り立たない。", "に": "「ムラに寄り合い」は場所と寄り合いの関係が不自然で合わない。", "へ": "「へ」は方向を示すが、寄り合いは行くものではないので合わない。"}, "error_tags": {"を": "対象", "に": "場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37817, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ムラの人口」の「の」。ムラに属する人口を示すので正解。"}, {"text": "を", "is_correct": false, "explanation": "「ムラを人口は減って」は、減る（自動詞）に「を」が合わず文にならない。"}, {"text": "と", "is_correct": false, "explanation": "「ムラと人口は減って」は二つの名詞を並べるだけで、人口が減った文の主語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「ムラより人口は減って」はムラとの比較になり、ムラに属する人口という意味が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「ムラの人口」の「の」。ムラに属する人口を示すので正解。", "を": "「ムラを人口は減って」は、減る（自動詞）に「を」が合わず文にならない。", "と": "「ムラと人口は減って」は二つの名詞を並べるだけで、人口が減った文の主語にならない。", "より": "「ムラより人口は減って」はムラとの比較になり、ムラに属する人口という意味が成り立たない。"}, "error_tags": {"を": "対象", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37817, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "田舎の小さな集落。市町村より小さい地域社会。", "primary_collocate": null, "pronunciation": "むら", "ipa": "mɯɾa", "syllable_count": 2, "sentences": [{"text": "田んぼに囲まれたムラでは、昔ながらの暮らしが続いている。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "田[た]んぼに囲[かこ]まれたムラでは、昔[むかし]ながらの暮[く]らしが続[つづ]いている。", "sentence_source": "generated"}, {"text": "ムラの寄り合いで、水の使い方が決められた。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "ムラの寄[よ]り合[あ]いで、水[みず]の使[つか]い方[かた]が決[き]められた。", "sentence_source": "generated"}, {"text": "このムラは、市町村より小さな単位の地域社会だ。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "このムラは、市町村[しちょうそん]より小[ちい]さな単位[たんい]の地域社会[ちいきしゃかい]だ。", "sentence_source": "generated"}, {"text": "ムラの外から来た人は、最初は少し珍しがられた。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "ムラの外[そと]から来[き]た人[ひと]は、最初[さいしょ]は少[すこ]し珍[めずら]しがられた。", "sentence_source": "generated"}, {"text": "ムラ全体で協力して、春に田植えをする。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "ムラ全体[ぜんたい]で協力[きょうりょく]して、春[はる]に田植[たう]えをする。", "sentence_source": "generated"}, {"text": "ムラの掟を破ると、仲間に入れてもらえなくなる。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "ムラの掟[おきて]を破[やぶ]ると、仲間[なかま]に入[い]れてもらえなくなる。", "sentence_source": "generated"}, {"text": "都会から移り住んだ夫婦が、ムラの行事を手伝っている。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "都会[とかい]から移[うつ]り住[す]んだ夫婦[ふうふ]が、ムラの行事[ぎょうじ]を手伝[てつだ]っている。", "sentence_source": "generated"}, {"text": "ムラの人口は減って、学校も閉じてしまった。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "ムラの人口[じんこう]は減[へ]って、学校[がっこう]も閉[と]じてしまった。", "sentence_source": "generated"}, {"text": "昔の日本では、ムラの結びつきがとても強かった。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "昔[むかし]の日本[にほん]では、ムラの結[むす]びつきがとても強[つよ]かった。", "sentence_source": "generated"}, {"text": "畑仕事で忙しい時期は、ムラの人が互いに助け合う。", "target_word": "ムラ", "complexity_tier": "T3", "furigana": "畑仕事[はたけしごと]で忙[いそが]しい時期[じき]は、ムラの人[ひと]が互[たが]いに助[たす]け合[あ]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ムラ", "label": "基本形"}], "register": "一般", "sense_fingerprint": "田舎の小さな集落で、人々が結びついた地域社会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37817, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ムラ", "is_correct": true, "explanation": "田んぼに囲まれた地域社会を指すので正解。"}, {"text": "海", "is_correct": false, "explanation": "田んぼに囲まれた海はなく、文が成り立たない。"}, {"text": "机", "is_correct": false, "explanation": "机が田んぼに囲まれることはなく、意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "窓が田んぼに囲まれる文は成り立たず、不自然。"}], "explanations": {"ムラ": "田んぼに囲まれた地域社会を指すので正解。", "海": "田んぼに囲まれた海はなく、文が成り立たない。", "机": "机が田んぼに囲まれることはなく、意味が通らない。", "窓": "窓が田んぼに囲まれる文は成り立たず、不自然。"}, "sentence_index": 0, "correct_answer": "ムラ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社は全国に三十のムラがあり、それぞれに社員が百人ほど働いている。", "explanation": "ここは〈支店〉の意味。会社の出先は支店と言い、市町村より小さい地域社会のムラとは合わない。"}, {"text": "このムラは市の中に区が五つあり、区役所が街の中心にある。", "explanation": "ここは〈区〉の意味。市の中の行政区は区と言い、田舎の小さな集落のムラとは合わない。"}, {"text": "このムラは鉄道が三本通り、ビルが並んでいる。", "explanation": "ここは〈町〉の意味。鉄道やビルが並ぶ規模は町で、田舎のムラとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37817, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ムラ", "is_correct": true, "explanation": "都会から移った夫婦が関わる地域社会の行事を指すので正解。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋の行事は成り立たず、文の意味が通らない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は行事を手伝う主語にならず、文が成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は行事を手伝えないため、文が不自然になる。"}], "explanations": {"ムラ": "都会から移った夫婦が関わる地域社会の行事を指すので正解。", "鍋": "鍋の行事は成り立たず、文の意味が通らない。", "紙": "紙は行事を手伝う主語にならず、文が成り立たない。", "雨": "雨は行事を手伝えないため、文が不自然になる。"}, "sentence_index": 6, "correct_answer": "ムラ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このムラは人口が二十万人を超え、市役所が三つある。", "explanation": "ここは〈市〉の意味。市は大きな行政単位で、田舎の集落を表すムラとは合わない。"}, {"text": "このムラには高層ビルが並び、通勤の人で朝は混み合う。", "explanation": "ここは〈都会〉の意味。人が密集した大都市の様子で、田舎の地域社会とは合わない。"}, {"text": "このムラでは学生が二百人暮らし、食堂が三つある。", "explanation": "ここは〈寮〉の意味。学生が共同で暮らす施設で、地域社会とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37817, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ムラを人口は年々減っている。", "corrected_sentence": "ムラの人口は年々減っている。", "error_description": "「ムラ」と「人口」をつなぐのは「の」で、「を」は誤り。正しくは「ムラの人口」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37817, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このムラは山に囲んでいて、冬は雪が深い。", "corrected_sentence": "このムラは山に囲まれていて、冬は雪が深い。", "error_description": "「囲む」は能動で、「山に囲んでいて」では山がムラを囲む意味になり誤り。ムラが山に囲まれる受け身の「囲まれている」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37820, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「物語を聞かせる」の目的語を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「物語に聞かせる」は成立せず、目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「物語と聞かせる」は並列にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「物語へ聞かせる」は方向として不自然。"}], "correct_answer": "を", "explanations": {"を": "「物語を聞かせる」の目的語を示す格助詞。", "に": "「物語に聞かせる」は成立せず、目的語にならない。", "と": "「物語と聞かせる」は並列にならず、不自然。", "へ": "「物語へ聞かせる」は方向として不自然。"}, "error_tags": {"に": "相手", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
