INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37820, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が話すお話のことです。", "primary_collocate": null, "pronunciation": "ものがたり", "ipa": "monoɡatari", "syllable_count": 5, "sentences": [{"text": "おばあさんが、むかしの物語を話してくれました。", "target_word": "物語", "complexity_tier": "T3", "furigana": "おばあさんが、むかしの物語[ものがたり]を話[はな]してくれました。", "sentence_source": "generated"}, {"text": "寝る前に、父が物語を聞かせてくれる。", "target_word": "物語", "complexity_tier": "T3", "furigana": "寝[ね]る前[まえ]に、父[ちち]が物語[ものがたり]を聞[き]かせてくれる。", "sentence_source": "generated"}, {"text": "先生は、子どもたちに楽しい物語を話した。", "target_word": "物語", "complexity_tier": "T3", "furigana": "先生[せんせい]は、子[こ]どもたちに楽[たの]しい物語[ものがたり]を話[はな]した。", "sentence_source": "generated"}, {"text": "わたしは祖父から、山の物語を聞きました。", "target_word": "物語", "complexity_tier": "T3", "furigana": "わたしは祖父[そふ]から、山[やま]の物語[ものがたり]を聞[き]きました。", "sentence_source": "generated"}, {"text": "この物語は、小さなうさぎのお話です。", "target_word": "物語", "complexity_tier": "T3", "furigana": "この物語[ものがたり]は、小[ちい]さなうさぎのお話[はなし]です。", "sentence_source": "generated"}, {"text": "長い物語だったので、最後まで聞くのに時間がかかった。", "target_word": "物語", "complexity_tier": "T3", "furigana": "長[なが]い物語[ものがたり]だったので、最後[さいご]まで聞[き]くのに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "夜のキャンプで、みんなにこわい物語を話した。", "target_word": "物語", "complexity_tier": "T3", "furigana": "夜[よる]のキャンプで、みんなにこわい物語[ものがたり]を話[はな]した。", "sentence_source": "generated"}, {"text": "弟は、おもしろい物語を聞くと目をかがやかせる。", "target_word": "物語", "complexity_tier": "T3", "furigana": "弟[おとうと]は、おもしろい物語[ものがたり]を聞[き]くと目[め]をかがやかせる。", "sentence_source": "generated"}, {"text": "図書館で、読み聞かせの物語を聞いた。", "target_word": "物語", "complexity_tier": "T3", "furigana": "図書館[としょかん]で、読[よ]み聞[き]かせの物語[ものがたり]を聞[き]いた。", "sentence_source": "generated"}, {"text": "母の話す物語は、いつも終わりが楽しい。", "target_word": "物語", "complexity_tier": "T3", "furigana": "母[はは]の話[はな]す物語[ものがたり]は、いつも終[お]わりが楽[たの]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物語", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が口で話して聞かせるお話", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37820, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物語", "is_correct": true, "explanation": "名詞。「むかしの物語を話す」で、語られる話を表す。"}, {"text": "天気", "is_correct": false, "explanation": "天気は話す内容にならず、「むかしの天気を話す」は不自然。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物で、話す内容にはならない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便の道具で、話す内容にはならない。"}], "explanations": {"物語": "名詞。「むかしの物語を話す」で、語られる話を表す。", "天気": "天気は話す内容にならず、「むかしの天気を話す」は不自然。", "電車": "乗り物で、話す内容にはならない。", "切手": "郵便の道具で、話す内容にはならない。"}, "sentence_index": 0, "correct_answer": "物語"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "わたしは祖父から、山の物語を焼きました。", "explanation": "〈焼く〉の場面。物語は焼けず、焼くは食べ物などに使う動作。"}, {"text": "わたしは祖父と、大事な物語をしました。", "explanation": "〈話〉の場面。「話をする」とは言えるが、「物語をする」とは言わない。"}, {"text": "わたしは祖父と、山の物語を干しました。", "explanation": "〈干す〉の場面。物語は干せず、干すのは洗濯物などに使う動作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37820, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物語", "is_correct": true, "explanation": "名詞。「こわい物語を話す」で、話される話を表す。"}, {"text": "地図", "is_correct": false, "explanation": "地図は話す内容にならず、「こわい地図を話す」は不自然。"}, {"text": "財布", "is_correct": false, "explanation": "持ち物で、話す内容にはならない。"}, {"text": "梅干し", "is_correct": false, "explanation": "食べ物で、話す内容にはならない。"}], "explanations": {"物語": "名詞。「こわい物語を話す」で、話される話を表す。", "地図": "地図は話す内容にならず、「こわい地図を話す」は不自然。", "財布": "持ち物で、話す内容にはならない。", "梅干し": "食べ物で、話す内容にはならない。"}, "sentence_index": 6, "correct_answer": "物語"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は庭に物語を植えた。", "explanation": "〈植える〉の場面。物語は植えられず、植えるのは草木や苗が合う。"}, {"text": "母は子どもに物語を投げた。", "explanation": "〈投げる〉の場面。物語は投げられず、投げるのは物が合う。"}, {"text": "川で、大きな物語を釣った。", "explanation": "〈釣る〉の場面。釣るのは魚で、物語は釣れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37820, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は孫に、昔の物語を聞かせくれた。", "corrected_sentence": "祖母は孫に、昔の物語を聞かせてくれた。", "error_description": "「聞かせてくれた」の「て」が抜けている。「聞かせくれた」は文法的に成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37820, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "おじさんは、みんなに古い物語に語った。", "corrected_sentence": "おじさんは、みんなに古い物語を語った。", "error_description": "「語る」の目的語「物語」には「を」が必要。「に」にすると目的語が成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37821, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」で、「この物語」を主題にしている。"}, {"text": "で", "is_correct": false, "explanation": "「物語で」は手段や場所を表し、主題の文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「物語へ」は方向を表し、ここでは成立しない。"}, {"text": "から", "is_correct": false, "explanation": "「物語から」は起点を表し、「もとにしている」と合わない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」で、「この物語」を主題にしている。", "で": "「物語で」は手段や場所を表し、主題の文として不自然。", "へ": "「物語へ」は方向を表し、ここでは成立しない。", "から": "「物語から」は起点を表し、「もとにしている」と合わない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37821, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」で、「物語の舞台」と名詞を結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「物語を舞台は」は目的語にならず、文が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「物語に舞台は」は成立せず、名詞を結ぶ働きもない。"}, {"text": "へ", "is_correct": false, "explanation": "「物語へ舞台は」は方向を表し、名詞を結ぶ働きがなく成立しない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」で、「物語の舞台」と名詞を結ぶ。", "を": "「物語を舞台は」は目的語にならず、文が成立しない。", "に": "「物語に舞台は」は成立せず、名詞を結ぶ働きもない。", "へ": "「物語へ舞台は」は方向を表し、名詞を結ぶ働きがなく成立しない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37821, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "現実または想像上の出来事を順序立てて語ったもの。", "primary_collocate": null, "pronunciation": "ものがたり", "ipa": "monoɡatari", "syllable_count": 5, "sentences": [{"text": "手紙の書簡体の物語は、おもしろい小説です。", "target_word": "物語", "complexity_tier": "T3", "furigana": "手紙[てがみ]の書簡体[しょかんたい]の物語[ものがたり]は、おもしろい小説[しょうせつ]です。", "sentence_source": "mined"}, {"text": "この物語は、実際にあった戦争の出来事をもとにしている。", "target_word": "物語", "complexity_tier": "T3", "furigana": "この物語[ものがたり]は、実際[じっさい]にあった戦争[せんそう]の出来事[できごと]をもとにしている。", "sentence_source": "generated"}, {"text": "作者は、少年の成長を描いた長い物語を完成させた。", "target_word": "物語", "complexity_tier": "T3", "furigana": "作者[さくしゃ]は、少年[しょうねん]の成長[せいちょう]を描[えが]いた長[なが]い物語[ものがたり]を完成[かんせい]させた。", "sentence_source": "generated"}, {"text": "その物語は、最初に事件が起こり、最後に真相が明らかになる。", "target_word": "物語", "complexity_tier": "T3", "furigana": "その物語[ものがたり]は、最初[さいしょ]に事件[じけん]が起[お]こり、最後[さいご]に真相[しんそう]が明[あき]らかになる。", "sentence_source": "generated"}, {"text": "物語の主人公は、旅をしながら仲間を増やしていく。", "target_word": "物語", "complexity_tier": "T3", "furigana": "物語[ものがたり]の主人公[しゅじんこう]は、旅[たび]をしながら仲間[なかま]を増[ふ]やしていく。", "sentence_source": "generated"}, {"text": "映画は二時間で一つの物語をまとめなければならない。", "target_word": "物語", "complexity_tier": "T3", "furigana": "映画[えいが]は二時間[にじかん]で一[ひと]つの物語[ものがたり]をまとめなければならない。", "sentence_source": "generated"}, {"text": "彼女の人生そのものが、一つの感動的な物語だと思う。", "target_word": "物語", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の人生[じんせい]そのものが、一[ひと]つの感動的[かんどうてき]な物語[ものがたり]だと思[おも]う。", "sentence_source": "generated"}, {"text": "物語の舞台は江戸時代で、商人の家族が登場する。", "target_word": "物語", "complexity_tier": "T3", "furigana": "物語[ものがたり]の舞台[ぶたい]は江戸時代[えどじだい]で、商人[しょうにん]の家族[かぞく]が登場[とうじょう]する。", "sentence_source": "generated"}, {"text": "歴史の物語を読むと、当時の暮らしがよくわかる。", "target_word": "物語", "complexity_tier": "T3", "furigana": "歴史[れきし]の物語[ものがたり]を読[よ]むと、当時[とうじ]の暮[く]らしがよくわかる。", "sentence_source": "generated"}, {"text": "結末が悲しい物語なので、読み終えて涙が出た。", "target_word": "物語", "complexity_tier": "T3", "furigana": "結末[けつまつ]が悲[かな]しい物語[ものがたり]なので、読[よ]み終[お]えて涙[なみだ]が出[で]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物語", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "現実や想像の出来事を順序立てて語った筋のある話", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37821, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物語", "is_correct": true, "explanation": "名詞。作品の種類を表し、「書簡体の物語」として主語になる。"}, {"text": "天気", "is_correct": false, "explanation": "天気は作品を表さず、「書簡体の天気」は成立しない。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物を表す語で、作品の意味と合わない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う物で、作品を表さない。"}], "explanations": {"物語": "名詞。作品の種類を表し、「書簡体の物語」として主語になる。", "天気": "天気は作品を表さず、「書簡体の天気」は成立しない。", "電車": "乗り物を表す語で、作品の意味と合わない。", "切手": "郵便に使う物で、作品を表さない。"}, "sentence_index": 0, "correct_answer": "物語"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その物語は、明日の天気を予報している。", "explanation": "〈予報〉の場面。物語は出来事を語るもので、天気を予報することはできない。"}, {"text": "その物語は、シャツのボタンを留めた。", "explanation": "〈留める〉の場面。物語は留められず、ボタンを留めるのは服に使う動作。"}, {"text": "その物語は、答えが三になる。", "explanation": "〈計算〉の場面。物語は計算の結果を出すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37821, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物語", "is_correct": true, "explanation": "名詞。「感動的な物語」として、作品を指す。"}, {"text": "地図", "is_correct": false, "explanation": "地図は作品を表さず、「感動的な地図」は意味をなさない。"}, {"text": "梅干し", "is_correct": false, "explanation": "食べ物で、作品を表す語ではない。"}, {"text": "財布", "is_correct": false, "explanation": "持ち物で、物語の意味と合わない。"}], "explanations": {"物語": "名詞。「感動的な物語」として、作品を指す。", "地図": "地図は作品を表さず、「感動的な地図」は意味をなさない。", "梅干し": "食べ物で、作品を表す語ではない。", "財布": "持ち物で、物語の意味と合わない。"}, "sentence_index": 6, "correct_answer": "物語"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱を測ったら、物語は三十八度だった。", "explanation": "〈体温〉の場面。体温は数値で表せるが、物語は数値で表せない。"}, {"text": "答えを出すために、物語を足した。", "explanation": "〈足す〉の場面。足せるのは数や量で、物語は足せない。"}, {"text": "物語を窓ガラスにはめた。", "explanation": "〈はめる〉の場面。物語は窓ガラスにはめられず、はめるのは板やガラスなどの物に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37821, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は孫に昔の物語に語った。", "corrected_sentence": "祖父は孫に昔の物語を語った。", "error_description": "「語る」の目的語「物語」には「を」が必要。「に」にすると目的語が成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37821, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は長い物語を語り終えらた。", "corrected_sentence": "彼女は長い物語を語り終えた。", "error_description": "「語り終えた」の過去形が正しい。「語り終えらた」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37822, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「慣れる」は「〜に慣れる」と組むので、暮らしの直後に「に」を置くのが正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、ここでは「慣れる」の対象を示せず、続く「も」とも不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語に使うが、「慣れる」は「に」を取るので「を」では合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「慣れる」の対象として使うのは不自然。"}], "correct_answer": "に", "explanations": {"に": "「慣れる」は「〜に慣れる」と組むので、暮らしの直後に「に」を置くのが正しい。", "が": "「が」は主語を示すが、ここでは「慣れる」の対象を示せず、続く「も」とも不自然になる。", "を": "「を」は目的語に使うが、「慣れる」は「に」を取るので「を」では合わない。", "へ": "「へ」は方向を表すので、「慣れる」の対象として使うのは不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37822, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37822, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が毎日、家でご飯を食べたり、仕事や学校に行ったりする、ふつうの生活のことです。", "primary_collocate": null, "pronunciation": "くらし", "ipa": "kɯɾaɕi", "syllable_count": 3, "sentences": [{"text": "この町の暮らしは静かで、とても楽です。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "この町(まち)の暮(く)らしは静(しず)かで、とても楽(らく)です。", "sentence_source": "generated"}, {"text": "田舎の暮らしにも、少しずつ慣れてきました。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "田舎(いなか)の暮(く)らしにも、少(すこ)しずつ慣(な)れてきました。", "sentence_source": "generated"}, {"text": "給料が上がって、暮らしが楽になりました。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "給料(きゅうりょう)が上(あ)がって、暮(く)らしが楽(らく)になりました。", "sentence_source": "generated"}, {"text": "日本の暮らしでは、家に入るとき靴をぬぎます。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "日本(にほん)の暮(く)らしでは、家(いえ)に入(はい)るとき靴(くつ)をぬぎます。", "sentence_source": "generated"}, {"text": "毎日の暮らしの中で、料理をする時間が大切です。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "毎日(まいにち)の暮(く)らしの中(なか)で、料理(りょうり)をする時間(じかん)が大切(たいせつ)です。", "sentence_source": "generated"}, {"text": "外国での暮らしは、最初は大変でした。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "外国(がいこく)での暮(く)らしは、最初(さいしょ)は大変(たいへん)でした。", "sentence_source": "generated"}, {"text": "祖父は畑の仕事をしながら、のんびりした暮らしを送っています。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "祖父(そふ)は畑(はたけ)の仕事(しごと)をしながら、のんびりした暮(く)らしを送(おく)っています。", "sentence_source": "generated"}, {"text": "物の値段が上がると、みんなの暮らしが苦しくなります。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "物(もの)の値段(ねだん)が上(あ)がると、みんなの暮(く)らしが苦(くる)しくなります。", "sentence_source": "generated"}, {"text": "引っ越しを機に、新しい暮らしが始まりました。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "引っ越(ひっこ)しを機(き)に、新(あたら)しい暮(く)らしが始(はじ)まりました。", "sentence_source": "generated"}, {"text": "犬を飼ってから、私の暮らしは明るくなりました。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "犬(いぬ)を飼(か)ってから、私(わたし)の暮(く)らしは明(あか)るくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "暮らし", "label": "漢字表記"}, {"form": "くらし", "label": "ひらがな表記"}], "register": "中立（です・ます体）", "sense_fingerprint": "毎日のふつうの生活。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ぬぎ (Zipf 2.34)']::text[], '1af43bfb-eb6a-43c0-a4ea-30a6a8d66fad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37822, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暮らし", "is_correct": true, "explanation": "「町の暮らしは静かで、とても楽だ」は生活の様子を述べる文として自然に成り立つ。"}, {"text": "値段", "is_correct": false, "explanation": "値段は物の価格のことなので、町の値段が静かで楽だとは言えない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、町の天気を「静かで楽」と評する文は成り立たない。"}, {"text": "人口", "is_correct": false, "explanation": "人口は住民の数を表すので、町の人口を「静かで楽」と言うと意味が合わない。"}], "explanations": {"暮らし": "「町の暮らしは静かで、とても楽だ」は生活の様子を述べる文として自然に成り立つ。", "値段": "値段は物の価格のことなので、町の値段が静かで楽だとは言えない。", "天気": "天気は空模様のことで、町の天気を「静かで楽」と評する文は成り立たない。", "人口": "人口は住民の数を表すので、町の人口を「静かで楽」と言うと意味が合わない。"}, "sentence_index": 0, "correct_answer": "暮らし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅の近くに暮らしを借りた。", "explanation": "ここは〈住まい〉の意味。住まいは借りるものだが、生活の様子は借りられないので合わない。"}, {"text": "地震で工場が壊れたので、暮らしを休むことになった。", "explanation": "ここは〈仕事〉の意味。仕事は休むものだが、生活の様子は休めないので合わない。"}, {"text": "この時計は、内部の暮らしが細かく組み込まれている。", "explanation": "ここは〈機構〉の意味。時計の内部の仕組みは機構と言い、暮らしは生活の様子なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37822, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暮らし", "is_correct": true, "explanation": "「のんびりした暮らしを送っている」は生活の様子を表す自然な言い方になる。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さのことで、「のんびりした体重を送る」とは言えない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は年数のことで、「のんびりした年齢を送る」という表現にはならない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は小物なので、「のんびりした財布を送る」は意味が通らない。"}], "explanations": {"暮らし": "「のんびりした暮らしを送っている」は生活の様子を表す自然な言い方になる。", "体重": "体重は体の重さのことで、「のんびりした体重を送る」とは言えない。", "年齢": "年齢は年数のことで、「のんびりした年齢を送る」という表現にはならない。", "財布": "財布は小物なので、「のんびりした財布を送る」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "暮らし"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テレビによると、明日の暮らしは一日中晴れるそうです。", "explanation": "ここは〈天気〉の意味。暮らしは生活のことで、晴れたり雨が降ったりするものではないので合わない。"}, {"text": "店に入ると、焼きたてのパンの暮らしが漂っていた。", "explanation": "ここは〈香り〉の意味。香りは漂うものだが、暮らしは生活のことで香りを表せないので合わない。"}, {"text": "夕焼けで、空の暮らしがだんだん赤くなった。", "explanation": "ここは〈色〉の意味。暮らしは生活のことで、空や物の色を表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37822, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友達が増えて、毎日の暮らしを楽しくなった。", "corrected_sentence": "友達が増えて、毎日の暮らしが楽しくなった。", "error_description": "「楽しくなる」は「〜が楽しくなる」と使い、変化の主体を「が」で示す。「暮らしを楽しくなる」は誤りで、「暮らしが楽しくなる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37822, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は近所の農家を手伝いながら、静かな暮らしを食べている。", "corrected_sentence": "母は近所の農家を手伝いながら、静かな暮らしを送っている。", "error_description": "「暮らしを食べる」は誤り。暮らしは「送る」と組むので、動詞を「送っている」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37823, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「山村の暮らしは時間がゆっくり流れる」と主題を示す形で自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「暮らしを時間がゆっくり流れる」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「暮らしで時間がゆっくり流れる」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「暮らしへ時間がゆっくり流れる」は不自然。"}], "correct_answer": "は", "explanations": {"は": "「山村の暮らしは時間がゆっくり流れる」と主題を示す形で自然に続く。", "を": "「を」は目的語を示すが、「暮らしを時間がゆっくり流れる」は成り立たない。", "で": "「で」は手段や場所を示すが、「暮らしで時間がゆっくり流れる」では意味が通らない。", "へ": "「へ」は方向を示すので、「暮らしへ時間がゆっくり流れる」は不自然。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37823, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「の」は「暮らしのリズム」と名詞をつなぐ助詞で、ここに入るのが正しい。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の意味になり、「暮らしよりリズムが変わった」では文の意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「変わる」は目的語を取らないので「暮らしをリズムが変わった」は誤り。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や対象を示すが、「暮らしにリズムが変わった」では「リズム」と結びつかない。"}], "correct_answer": "の", "explanations": {"の": "「の」は「暮らしのリズム」と名詞をつなぐ助詞で、ここに入るのが正しい。", "より": "「より」は比較の意味になり、「暮らしよりリズムが変わった」では文の意味が通らない。", "を": "「を」は目的語を示すが、「変わる」は目的語を取らないので「暮らしをリズムが変わった」は誤り。", "に": "「に」は場所や対象を示すが、「暮らしにリズムが変わった」では「リズム」と結びつかない。"}, "error_tags": {"より": "比較", "を": "目的語", "に": "位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37823, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が日常的に行う生活の様子や、生活の仕方。", "primary_collocate": null, "pronunciation": "くらし", "ipa": "kɯɾaɕi", "syllable_count": 3, "sentences": [{"text": "彼はお金に困らない、ゆとりのある暮らしをしている。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "彼(かれ)はお金(かね)に困(こま)らない、ゆとりのある暮(く)らしをしている。", "sentence_source": "generated"}, {"text": "都会の暮らしと比べると、山村の暮らしは時間がゆっくり流れる。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "都会(とかい)の暮(く)らしと比(くら)べると、山村(さんそん)の暮(く)らしは時間(じかん)がゆっくり流(なが)れる。", "sentence_source": "generated"}, {"text": "物価が上がり、庶民の暮らしは厳しくなった。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "物価(ぶっか)が上(あ)がり、庶民(しょみん)の暮(く)らしは厳(きび)しくなった。", "sentence_source": "generated"}, {"text": "昔ながらの暮らしを守る人が、この村には多い。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "昔(むかし)ながらの暮(く)らしを守(まも)る人(ひと)が、この村(むら)には多(おお)い。", "sentence_source": "generated"}, {"text": "年金だけでは、老後の暮らしを支えられない。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "年金(ねんきん)だけでは、老後(ろうご)の暮(く)らしを支(ささ)えられない。", "sentence_source": "generated"}, {"text": "質素な暮らしを心がけたので、貯金が増えた。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "質素(しっそ)な暮(く)らしを心(こころ)がけたので、貯金(ちょきん)が増(ふ)えた。", "sentence_source": "generated"}, {"text": "この写真展は、百年前の人々の暮らしを伝えている。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "この写真展(しゃしんてん)は、百年前(ひゃくねんまえ)の人々(ひとびと)の暮(く)らしを伝(つた)えている。", "sentence_source": "generated"}, {"text": "在宅勤務になって、家族との暮らしのリズムが変わった。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "在宅勤務(ざいたくきんむ)になって、家族(かぞく)との暮(く)らしのリズムが変(か)わった。", "sentence_source": "generated"}, {"text": "環境を考えて、無駄の少ない暮らしを選ぶ人が増えている。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "環境(かんきょう)を考(かんが)えて、無駄(むだ)の少(すく)ない暮(く)らしを選(えら)ぶ人(ひと)が増(ふ)えている。", "sentence_source": "generated"}, {"text": "退職後は、海の近くで静かな暮らしを楽しみたい。", "target_word": "暮らし", "complexity_tier": "T3", "furigana": "退職後(たいしょくご)は、海(うみ)の近(ちか)くで静(しず)かな暮(く)らしを楽(たの)しみたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "暮らし", "label": "漢字表記"}, {"form": "くらし", "label": "ひらがな表記"}], "register": "中立（常体）", "sense_fingerprint": "日常の生活の様子や仕方。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1af43bfb-eb6a-43c0-a4ea-30a6a8d66fad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37823, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暮らし", "is_correct": true, "explanation": "「ゆとりのある暮らしをしている」は生活の仕方を表し、文の流れに合う。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格のことで、「ゆとりのある値段をしている」という言い方にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、お金の余裕を表す文脈と結びつかず「ゆとりのある天気をしている」は成り立たない。"}, {"text": "人口", "is_correct": false, "explanation": "人口は住民の数を表すので、「ゆとりのある人口をしている」とは言えない。"}], "explanations": {"暮らし": "「ゆとりのある暮らしをしている」は生活の仕方を表し、文の流れに合う。", "値段": "値段は価格のことで、「ゆとりのある値段をしている」という言い方にはならない。", "天気": "天気は空模様のことで、お金の余裕を表す文脈と結びつかず「ゆとりのある天気をしている」は成り立たない。", "人口": "人口は住民の数を表すので、「ゆとりのある人口をしている」とは言えない。"}, "sentence_index": 0, "correct_answer": "暮らし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昔ながらの暮らしを破る人が、この村には多い。", "explanation": "ここは〈約束〉の意味。約束は破るものだが、生活の様子は破れないので合わない。"}, {"text": "今日は暮らしが悪くて、誰とも話したくない。", "explanation": "ここは〈機嫌〉の意味。機嫌は気分のことで、生活の様子を指す暮らしでは言い表せないので合わない。"}, {"text": "この書類は、昔ながらの暮らしで書かれている。", "explanation": "ここは〈形式〉の意味。書類は決まったやり方（形式）で書くもので、暮らしを手段として書くとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37823, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暮らし", "is_correct": true, "explanation": "「人々の暮らしを伝えている」は当時の生活の様子を伝える意味になり、写真展の内容として自然。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さのことで、写真展で人々の体重を伝えるとは言えない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は年数のことで、写真展が「人々の年齢を伝える」という文脈は成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は持ち物の一つで、「人々の財布を伝えている」は写真展の意味として不自然。"}], "explanations": {"暮らし": "「人々の暮らしを伝えている」は当時の生活の様子を伝える意味になり、写真展の内容として自然。", "体重": "体重は体の重さのことで、写真展で人々の体重を伝えるとは言えない。", "年齢": "年齢は年数のことで、写真展が「人々の年齢を伝える」という文脈は成り立たない。", "財布": "財布は持ち物の一つで、「人々の財布を伝えている」は写真展の意味として不自然。"}, "sentence_index": 6, "correct_answer": "暮らし"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは、とても濃い暮らしがする。", "explanation": "ここは〈味〉の意味。暮らしは生活のことで、食べ物の味として使えないので合わない。"}, {"text": "彼女の暮らしは、とても澄んだ声で響いた。", "explanation": "ここは〈声〉の意味。暮らしは生活のことで、澄んだ声のように澄むものではないので合わない。"}, {"text": "この携帯は、暮らしの残量が少なくなってきた。", "explanation": "ここは〈電池〉の意味。電池の残量は言えるが、暮らしは生活のことで残量として減っていくものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37823, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "節約を始めてから、暮らしを楽になった。", "corrected_sentence": "節約を始めてから、暮らしが楽になった。", "error_description": "「楽になる」は「〜が楽になる」と使う。「暮らしを楽になる」は誤りで、「暮らしが」の「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37823, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は一人で静かな暮らしを飲んでいる。", "corrected_sentence": "祖母は一人で静かな暮らしを営んでいる。", "error_description": "「暮らしを飲む」は誤り。暮らしは「営む」と組むので、動詞を「営んでいる」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfdc5c78-9c3e-4715-a93e-3317b06beb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37824, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表す助詞で、「口承で子どもたちに教えた」と方法を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す助詞で、「口承を子どもたちに教えた」は二重の目的語になり不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す助詞で、「口承が子どもたちに教えた」は主語が合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す助詞で、「口承より子どもたちに教えた」は文が成立しない。"}], "correct_answer": "で", "explanations": {"で": "手段を表す助詞で、「口承で子どもたちに教えた」と方法を示す。", "を": "目的語を表す助詞で、「口承を子どもたちに教えた」は二重の目的語になり不自然。", "が": "主語を表す助詞で、「口承が子どもたちに教えた」は主語が合わない。", "より": "比較を表す助詞で、「口承より子どもたちに教えた」は文が成立しない。"}, "error_tags": {"を": "対象", "が": "主語", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37824, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「口承は」と話題の主題を示し、文の主語として自然に続く。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表す助詞で、「口承に、聞く人が覚えないと」は文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「口承へ、聞く人が覚えないと」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用の助詞で、「口承と、聞く人が覚えないと」は文が成立しない。"}], "correct_answer": "は", "explanations": {"は": "「口承は」と話題の主題を示し、文の主語として自然に続く。", "に": "位置や相手を表す助詞で、「口承に、聞く人が覚えないと」は文として不自然。", "へ": "方向を表す助詞で、「口承へ、聞く人が覚えないと」は意味が通らない。", "と": "並列や引用の助詞で、「口承と、聞く人が覚えないと」は文が成立しない。"}, "error_tags": {"に": "位置", "へ": "方向", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37824, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "口で話すことによって、次の世代に伝えること", "primary_collocate": null, "pronunciation": "こうしょう", "ipa": "koːɕoː", "syllable_count": 4, "sentences": [{"text": "この歌は、祖母から母へ、口承で伝えられてきた。", "target_word": "口承", "complexity_tier": "T3", "furigana": "この歌[うた]は、祖母[そぼ]から母[はは]へ、口承[こうしょう]で伝[つた]えられてきた。", "sentence_source": "generated"}, {"text": "昔の人は、村の決まりを口承で子どもたちに教えた。", "target_word": "口承", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、村[むら]の決[き]まりを口承[こうしょう]で子[こ]どもたちに教[おし]えた。", "sentence_source": "generated"}, {"text": "文字がなかった時代、歴史は口承によって次の世代へ残された。", "target_word": "口承", "complexity_tier": "T3", "furigana": "文字[もじ]がなかった時代[じだい]、歴史[れきし]は口承[こうしょう]によって次[つぎ]の世代[せだい]へ残[のこ]された。", "sentence_source": "generated"}, {"text": "口承なので、話す人によって、少しずつ内容が違う。", "target_word": "口承", "complexity_tier": "T3", "furigana": "口承[こうしょう]なので、話[はなし]す人[ひと]によって、少[すこ]しずつ内容[ないよう]が違[ちが]う。", "sentence_source": "generated"}, {"text": "この踊りの手順は、口承でしか伝わっていない。", "target_word": "口承", "complexity_tier": "T3", "furigana": "この踊[おど]りの手順[てじゅん]は、口承[こうしょう]でしか伝[つた]わっていない。", "sentence_source": "generated"}, {"text": "祖父は、口承の昔話を孫に聞かせるのが好きだ。", "target_word": "口承", "complexity_tier": "T3", "furigana": "祖父[そふ]は、口承[こうしょう]の昔話[むかしばなし]を孫[まご]に聞[き]かせるのが好[す]きだ。", "sentence_source": "generated"}, {"text": "書き残されていないので、村の歴史は口承に頼るしかない。", "target_word": "口承", "complexity_tier": "T3", "furigana": "書[か]き残[のこ]されていないので、村[むら]の歴史[れきし]は口承[こうしょう]に頼[たよ]るしかない。", "sentence_source": "generated"}, {"text": "口承は、聞く人が覚えないと、そこで終わってしまう。", "target_word": "口承", "complexity_tier": "T3", "furigana": "口承[こうしょう]は、聞[き]く人[ひと]が覚[おぼ]えないと、そこで終[お]わってしまう。", "sentence_source": "generated"}, {"text": "漁師の知恵は、長い間、口承で守られてきた。", "target_word": "口承", "complexity_tier": "T3", "furigana": "漁師[りょうし]の知恵[ちえ]は、長[なが]い間[あいだ]、口承[こうしょう]で守[まも]られてきた。", "sentence_source": "generated"}, {"text": "親から子へ、口承で伝わった言葉が、今も町に残っている。", "target_word": "口承", "complexity_tier": "T3", "furigana": "親[おや]から子[こ]へ、口承[こうしょう]で伝[つた]わった言葉[ことば]が、今[いま]も町[まち]に残[のこ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "口承", "label": "基本形"}, {"form": "口承で", "label": "手段"}, {"form": "口承の", "label": "連体"}], "register": "普通体（説明的）", "sense_fingerprint": "話すことで次の世代へ伝えていく伝承のしかた", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37824, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口承", "is_correct": true, "explanation": "口で話して次の世代に伝える方法を指し、「で伝えられてきた」に合う。"}, {"text": "三角", "is_correct": false, "explanation": "図形を表す語で、「三角で伝えられてきた」は手段として成り立たない。"}, {"text": "大雨", "is_correct": false, "explanation": "天候を表す語で、「大雨で伝えられてきた」は意味をなさない。"}, {"text": "漁業", "is_correct": false, "explanation": "職業を表す語で、「漁業で伝えられてきた」は伝達の手段として合わない。"}], "explanations": {"口承": "口で話して次の世代に伝える方法を指し、「で伝えられてきた」に合う。", "三角": "図形を表す語で、「三角で伝えられてきた」は手段として成り立たない。", "大雨": "天候を表す語で、「大雨で伝えられてきた」は意味をなさない。", "漁業": "職業を表す語で、「漁業で伝えられてきた」は伝達の手段として合わない。"}, "sentence_index": 0, "correct_answer": "口承"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の決定は、あとで確認できるように口承で記録する。", "explanation": "ここは〈文書〉の意味。記録は文字で残すことで、口で伝える〈口承〉では残せないので合わない。"}, {"text": "英語の口承試験で、とても緊張した。", "explanation": "ここは〈口頭〉の意味。試験は口頭試験と言い、〈口承〉は語り継ぐ伝承を指すので合わない。"}, {"text": "遠くの友人には、毎年、口承で近況を知らせている。", "explanation": "元の言い方は〈手紙〉。個人の近況を知らせる手段は手紙などで、〈口承〉は世代を超えて伝わる伝承を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37824, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口承", "is_correct": true, "explanation": "口で話して伝える伝承の方法を指し、村の歴史を支える手段として合う。"}, {"text": "夜空", "is_correct": false, "explanation": "空の様子を表す語で、「夜空に頼るしかない」は意味をなさない。"}, {"text": "風船", "is_correct": false, "explanation": "遊び道具を表す語で、「風船に頼るしかない」は成り立たない。"}, {"text": "靴下", "is_correct": false, "explanation": "衣類を表す語で、「靴下に頼るしかない」は意味をなさない。"}], "explanations": {"口承": "口で話して伝える伝承の方法を指し、村の歴史を支える手段として合う。", "夜空": "空の様子を表す語で、「夜空に頼るしかない」は意味をなさない。", "風船": "遊び道具を表す語で、「風船に頼るしかない」は成り立たない。", "靴下": "衣類を表す語で、「靴下に頼るしかない」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "口承"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国の法律は、今も口承で定められている。", "explanation": "ここは〈文書〉の意味。法律は文字で定めるもので、口で伝える〈口承〉では定めない。"}, {"text": "荷物は口承で届いた。", "explanation": "ここは〈郵便〉の意味。物を届ける手段は郵便などで、〈口承〉は伝承の方法を指すので合わない。"}, {"text": "授業の様子は口承で残した。", "explanation": "ここは〈録画〉の意味。映像を残す場合は録画で、〈口承〉は話して伝える方法なので残せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37824, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この踊りは、祖母から孫へ口承に伝えられてきた。", "corrected_sentence": "この踊りは、祖母から孫へ口承で伝えられてきた。", "error_description": "手段を表す「で」を「に」にしている。「口承で伝えられてきた」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37824, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔話は、村の年寄りから孫へ口承伝えられている。", "corrected_sentence": "昔話は、村の年寄りから孫へ口承で伝えられている。", "error_description": "手段を表す「で」が抜けている。「口承」の後に「で」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
