INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37825, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「なければ」の主語を示す。「老人たちの口承がなければ」と、口承が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「ない」は主語に「が」を取るので、「を」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「口承へなければ」とは続かず、文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「口承と」では並列や引用の意味になり、「なければ」の条件文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「なければ」の主語を示す。「老人たちの口承がなければ」と、口承が主語になる。", "を": "「ない」は主語に「が」を取るので、「を」では文が成り立たない。", "へ": "方向を表す助詞で、「口承へなければ」とは続かず、文として成り立たない。", "と": "「口承と」では並列や引用の意味になり、「なければ」の条件文には合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37825, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "書いたものを使わず、話すことによって物語や知識を伝えること", "primary_collocate": null, "pronunciation": "こうしょう", "ipa": "koːɕoː", "syllable_count": 4, "sentences": [{"text": "本を使わず、口承で物語を語る人が、村にはいた。", "target_word": "口承", "complexity_tier": "T3", "furigana": "本[ほん]を使[つか]わず、口承[こうしょう]で物語[ものがたり]を語[かた]る人[ひと]が、村[むら]にはいた。", "sentence_source": "generated"}, {"text": "その民話は、文字にされず、口承だけで広まった。", "target_word": "口承", "complexity_tier": "T3", "furigana": "その民話[みんわ]は、文字[もじ]にされず、口承[こうしょう]だけで広[ひろ]まった。", "sentence_source": "generated"}, {"text": "薬草の使い方は、口承で受けつがれた大切な知識だ。", "target_word": "口承", "complexity_tier": "T3", "furigana": "薬草[やくそう]の使[つか]い方[かた]は、口承[こうしょう]で受[う]けつがれた大切[たいせつ]な知識[ちしき]だ。", "sentence_source": "generated"}, {"text": "この島の神話は、書物ではなく口承で伝えられている。", "target_word": "口承", "complexity_tier": "T3", "furigana": "この島[しま]の神話[しんわ]は、書物[しょもつ]ではなく口承[こうしょう]で伝[つた]えられている。", "sentence_source": "generated"}, {"text": "口承の物語は、語る人の声や間で、聞こえ方が変わる。", "target_word": "口承", "complexity_tier": "T3", "furigana": "口承[こうしょう]の物語[ものがたり]は、語[かた]る人[ひと]の声[こえ]や間[ま]で、聞[き]こえ方[かた]が変[か]わる。", "sentence_source": "generated"}, {"text": "文字を持たない民族は、口承で自分たちの話を残した。", "target_word": "口承", "complexity_tier": "T3", "furigana": "文字[もじ]を持[も]たない民族[みんぞく]は、口承[こうしょう]で自分[じぶん]たちの話[はなし]を残[のこ]した。", "sentence_source": "generated"}, {"text": "先生は、紙を見ずに、口承の形で昔の話を教えてくれた。", "target_word": "口承", "complexity_tier": "T3", "furigana": "先生[せんせい]は、紙[かみ]を見[み]ずに、口承[こうしょう]の形[かたち]で昔[むかし]の話[はなし]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "老人たちの口承がなければ、この伝説は消えていただろう。", "target_word": "口承", "complexity_tier": "T3", "furigana": "老人[ろうじん]たちの口承[こうしょう]がなければ、この伝説[でんせつ]は消[き]えていただろう。", "sentence_source": "generated"}, {"text": "口承で聞いた話を、研究者が初めて本にまとめた。", "target_word": "口承", "complexity_tier": "T3", "furigana": "口承[こうしょう]で聞[き]いた話[はなし]を、研究者[けんきゅうしゃ]が初[はじ]めて本[ほん]にまとめた。", "sentence_source": "generated"}, {"text": "口承の知識は、書かれたものと違い、聞いて覚えるしかない。", "target_word": "口承", "complexity_tier": "T3", "furigana": "口承[こうしょう]の知識[ちしき]は、書[か]かれたものと違[ちが]い、聞[き]いて覚[おぼ]えるしかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "口承", "label": "基本形"}, {"form": "口承で", "label": "手段"}, {"form": "口承の", "label": "連体"}], "register": "普通体（説明的）", "sense_fingerprint": "文字に頼らず、語りによって物語や知識を伝えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37825, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口承", "is_correct": true, "explanation": "本を使わず語りで伝える、という文脈に合う。"}, {"text": "重力", "is_correct": false, "explanation": "物理の力を表す語で、物語を語る手段にはならない。"}, {"text": "毛糸", "is_correct": false, "explanation": "編み物の材料で、物語を語る手段としては成り立たない。"}, {"text": "石鹸", "is_correct": false, "explanation": "洗うための品で、物語を伝える手段にはならない。"}], "explanations": {"口承": "本を使わず語りで伝える、という文脈に合う。", "重力": "物理の力を表す語で、物語を語る手段にはならない。", "毛糸": "編み物の材料で、物語を語る手段としては成り立たない。", "石鹸": "洗うための品で、物語を伝える手段にはならない。"}, "sentence_index": 0, "correct_answer": "口承"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故の経緯を、警察で口承した。", "explanation": "ここは〈口述〉の意味。口承は語り継がれる伝承を指すので、警察での供述には合わない。"}, {"text": "注文は、店員に口承で伝えた。", "explanation": "ここは〈口頭〉の意味。口承は代々語り継ぐ伝承を指すので、その場の注文には使えない。"}, {"text": "この記事は、口承で書かれている。", "explanation": "ここは〈口語〉の意味。口承は語りによる伝承を指し、書かれた文章には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37825, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口承", "is_correct": true, "explanation": "紙を使わず語りの形で教えた、という文脈に合う。"}, {"text": "花束", "is_correct": false, "explanation": "贈り物として使う品で、教え方の形式にはならない。"}, {"text": "氷塊", "is_correct": false, "explanation": "凍った塊を表す語で、昔の話を伝える形にはならない。"}, {"text": "寒気", "is_correct": false, "explanation": "冷たい空気の感覚を表す語で、話を教える形式とは合わない。"}], "explanations": {"口承": "紙を使わず語りの形で教えた、という文脈に合う。", "花束": "贈り物として使う品で、教え方の形式にはならない。", "氷塊": "凍った塊を表す語で、昔の話を伝える形にはならない。", "寒気": "冷たい空気の感覚を表す語で、話を教える形式とは合わない。"}, "sentence_index": 6, "correct_answer": "口承"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の内容を口承で残した。", "explanation": "ここは〈録音〉の意味。口承は人が語って伝えることなので、機器で記録する場面には合わない。"}, {"text": "授業の内容を口承で記録した。", "explanation": "ここは〈筆記〉の意味。口承は語りによる伝承を指すので、書き留める行為とは結びつかない。"}, {"text": "会話を口承で書き取った。", "explanation": "ここは〈速記〉の意味。口承は語りで伝えることで、速く書き取る技法には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37825, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村の人たちは、口承に昔の話を伝えてきた。", "corrected_sentence": "村の人たちは、口承で昔の話を伝えてきた。", "error_description": "手段を表す助詞は「で」。「口承に」の「に」は誤りで、正しくは「口承で伝えてきた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37825, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "口承な伝えは、語り手が変わるたびに少しずつ形を変える。", "corrected_sentence": "口承の伝えは、語り手が変わるたびに少しずつ形を変える。", "error_description": "「口承」は名詞なので、名詞を修飾するときは「の」を使う。「な」は形容動詞に付く形で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37826, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表す「で」。「話し言葉で気軽に話す」と、話す方法を示す。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所の「に」で、話す方法を表せない。「話し言葉に気軽に話す」は不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」だが、「話す」の対象は言葉ではない。「話し言葉を気軽に話す」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、話す方法を表せない。文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "手段を表す「で」。「話し言葉で気軽に話す」と、話す方法を示す。", "に": "相手や場所の「に」で、話す方法を表せない。「話し言葉に気軽に話す」は不自然。", "を": "目的語の「を」だが、「話す」の対象は言葉ではない。「話し言葉を気軽に話す」は不自然。", "より": "比較の「より」で、話す方法を表せない。文が成り立たない。"}, "error_tags": {"に": "location_or_target", "を": "object", "より": "comparison"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "書き言葉", "is_correct": true, "explanation": "文字で書く言葉を表し、口で話す〈話し言葉〉の対義語になる。"}, {"text": "方言", "is_correct": false, "explanation": "地域ごとの言葉の種類で、話し言葉と書き言葉の対義関係にはならない。"}, {"text": "音楽", "is_correct": false, "explanation": "音を楽しむ芸術で、話し言葉の対義関係にはならない。"}, {"text": "外来語", "is_correct": false, "explanation": "外国から入った語彙の種類で、対義語にはならない。"}], "correct_answer": "書き言葉", "explanations": {"書き言葉": "文字で書く言葉を表し、口で話す〈話し言葉〉の対義語になる。", "方言": "地域ごとの言葉の種類で、話し言葉と書き言葉の対義関係にはならない。", "音楽": "音を楽しむ芸術で、話し言葉の対義関係にはならない。", "外来語": "外国から入った語彙の種類で、対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37826, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "並列の「と」。「話し言葉と書き言葉の違い」と二つを並べる。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」で、二つを並べる働きにはならない。「話し言葉で書き言葉の違い」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、二つを並べられない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」で、並べる働きにはならない。「話し言葉から書き言葉の違い」は意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "並列の「と」。「話し言葉と書き言葉の違い」と二つを並べる。", "で": "手段の「で」で、二つを並べる働きにはならない。「話し言葉で書き言葉の違い」は不自然。", "へ": "方向の「へ」で、二つを並べられない。", "から": "起点の「から」で、並べる働きにはならない。「話し言葉から書き言葉の違い」は意味が通らない。"}, "error_tags": {"で": "means", "へ": "direction", "から": "source"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "書き言葉", "is_correct": true, "explanation": "文字で書く言葉を表し、口で話す〈話し言葉〉の対義語になる。"}, {"text": "漢字", "is_correct": false, "explanation": "文字の体系で、話し言葉の対義語にはならない。"}, {"text": "手紙", "is_correct": false, "explanation": "書いて送るものを指し、対義語にはならない。"}, {"text": "作文", "is_correct": false, "explanation": "書く行為や文章を指し、対義語にはならない。"}], "correct_answer": "書き言葉", "explanations": {"書き言葉": "文字で書く言葉を表し、口で話す〈話し言葉〉の対義語になる。", "漢字": "文字の体系で、話し言葉の対義語にはならない。", "手紙": "書いて送るものを指し、対義語にはならない。", "作文": "書く行為や文章を指し、対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37826, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が口で言う言葉のこと。", "primary_collocate": null, "pronunciation": "はなしことば", "ipa": "hanaɕikotoba", "syllable_count": 6, "sentences": [{"text": "話し言葉は、書き言葉より短くなることが多いです。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "話[はな]し言葉[ことば]は、書[か]き言葉[ことば]より短[みじか]くなることが多[おお]いです。", "sentence_source": "generated"}, {"text": "友達とは、話し言葉で気軽に話します。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "友達[ともだち]とは、話[はな]し言葉[ことば]で気軽[きがる]に話[はな]します。", "sentence_source": "generated"}, {"text": "手紙は丁寧ですが、話し言葉では少しくだけます。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "手紙[てがみ]は丁寧[ていねい]ですが、話[はな]し言葉[ことば]では少[すこ]しくだけます。", "sentence_source": "generated"}, {"text": "「食べちゃった」は話し言葉です。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "「食[た]べちゃった」は話[はな]し言葉[ことば]です。", "sentence_source": "generated"}, {"text": "日本語の話し言葉は、地方によって違います。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "日本語[にほんご]の話[はな]し言葉[ことば]は、地方[ちほう]によって違[ちが]います。", "sentence_source": "generated"}, {"text": "テレビのドラマは、話し言葉が多いです。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "テレビのドラマは、話[はな]し言葉[ことば]が多[おお]いです。", "sentence_source": "generated"}, {"text": "話し言葉を勉強して、会話が上手になりました。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "話[はな]し言葉[ことば]を勉強[べんきょう]して、会話[かいわ]が上手[じょうず]になりました。", "sentence_source": "generated"}, {"text": "先生は、話し言葉と書き言葉の違いを教えました。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "先生[せんせい]は、話[はな]し言葉[ことば]と書[か]き言葉[ことば]の違[ちが]いを教[おし]えました。", "sentence_source": "generated"}, {"text": "小説の会話は、話し言葉で書かれています。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "小説[しょうせつ]の会話[かいわ]は、話[はな]し言葉[ことば]で書[か]かれています。", "sentence_source": "generated"}, {"text": "レポートに話し言葉を使うと、先生に直されます。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "レポートに話[はな]し言葉[ことば]を使[つか]うと、先生[せんせい]に直[なお]されます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "話し言葉", "label": "基本形"}, {"form": "話し言葉で", "label": "手段"}], "register": "neutral", "sense_fingerprint": "書き言葉に対する、日常の会話で使う言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1008a082-97df-4e54-bb3b-338a2360e5cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37826, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "話し言葉", "is_correct": true, "explanation": "口で話す言葉を表し、書き言葉との比較の主語として文の意味が通る。"}, {"text": "方言", "is_correct": false, "explanation": "地域ごとの言葉の種類で、書き言葉との長さの比較の主題としては話がずれる。"}, {"text": "手話", "is_correct": false, "explanation": "手の動きで伝える言語で、音声の言葉とは別のものなので文の主語として合わない。"}, {"text": "外来語", "is_correct": false, "explanation": "外国から入った語彙の種類で、文体の話し言葉・書き言葉の比較とは話の軸が違う。"}], "explanations": {"話し言葉": "口で話す言葉を表し、書き言葉との比較の主語として文の意味が通る。", "方言": "地域ごとの言葉の種類で、書き言葉との長さの比較の主題としては話がずれる。", "手話": "手の動きで伝える言語で、音声の言葉とは別のものなので文の主語として合わない。", "外来語": "外国から入った語彙の種類で、文体の話し言葉・書き言葉の比較とは話の軸が違う。"}, "sentence_index": 0, "correct_answer": "話し言葉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室では、先生が話し言葉を小さくしました。", "explanation": "声の大きさは〈話し声〉の話で、〈話し言葉〉は言葉の文体を指すので、音量の調整とは合わない。"}, {"text": "この写真は話し言葉で、古い町並みを写しています。", "explanation": "ここは〈話し方〉と混同した使い方。〈話し言葉〉は言葉の種類なので、写真を撮る手段にはならない。"}, {"text": "祖母は話し言葉の着物を着て、お茶会に行きます。", "explanation": "ここは〈服装〉と混同した使い方。〈話し言葉〉は言葉の種類なので、着物の種類とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37826, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "話し言葉", "is_correct": true, "explanation": "会話の上達に関係する言葉の種類を表し、「話し言葉を勉強して」で文が通る。"}, {"text": "漢字", "is_correct": false, "explanation": "文字の体系で、会話の上達とは結びつきにくく、「漢字を勉強して会話が上手になる」は話がずれる。"}, {"text": "手紙", "is_correct": false, "explanation": "書いて送るもので、会話の練習の対象にはならない。"}, {"text": "作文", "is_correct": false, "explanation": "書く練習の対象なので、会話が上手になる話とは合わない。"}], "explanations": {"話し言葉": "会話の上達に関係する言葉の種類を表し、「話し言葉を勉強して」で文が通る。", "漢字": "文字の体系で、会話の上達とは結びつきにくく、「漢字を勉強して会話が上手になる」は話がずれる。", "手紙": "書いて送るもので、会話の練習の対象にはならない。", "作文": "書く練習の対象なので、会話が上手になる話とは合わない。"}, "sentence_index": 6, "correct_answer": "話し言葉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は話し言葉の絵を描き、展覧会に出しました。", "explanation": "ここは〈話し言葉〉を〈絵画の題材〉と混同している。言葉の種類なので、絵の題材にはならない。"}, {"text": "話し言葉は、紙に書かれて長く残ります。", "explanation": "ここは〈書き言葉〉の意味。話し言葉は口で言う言葉なので、紙に残るものとは合わない。"}, {"text": "話し言葉の手紙は、目上の人へ送るのに向いています。", "explanation": "ここは〈書き言葉〉の意味。手紙は書き言葉で書くので、〈話し言葉〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37826, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "話し言葉を、友達との会話でよく使われます。", "corrected_sentence": "話し言葉は、友達との会話でよく使われます。", "error_description": "〈話し言葉〉は主語として使うので「は」が正しい。「を」にすると受け身の文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37826, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "話し言葉に話すと、相手と仲良くなれます。", "corrected_sentence": "話し言葉で話すと、相手と仲良くなれます。", "error_description": "〈話し言葉〉は話す方法を表すので「で」が正しい。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37827, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "書き言葉", "is_correct": true, "explanation": "文字で書いて伝える言葉を表し、文字に頼らず声で伝える〈話し言葉〉の対義語になる。"}, {"text": "文字", "is_correct": false, "explanation": "書くための記号そのものを指し、言葉の種類の対義語にはならない。"}, {"text": "手紙", "is_correct": false, "explanation": "書いて送るものを指し、対義語にはならない。"}, {"text": "点字", "is_correct": false, "explanation": "触って読む文字の体系で、対義語にはならない。"}], "correct_answer": "書き言葉", "explanations": {"書き言葉": "文字で書いて伝える言葉を表し、文字に頼らず声で伝える〈話し言葉〉の対義語になる。", "文字": "書くための記号そのものを指し、言葉の種類の対義語にはならない。", "手紙": "書いて送るものを指し、対義語にはならない。", "点字": "触って読む文字の体系で、対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37827, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表す「で」。「話し言葉で道を教える」と、伝える方法を示す。"}, {"text": "に", "is_correct": false, "explanation": "相手を表す「に」で、伝える方法を示せない。「話し言葉に道を教える」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、伝える方法を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、伝える方法を示せない。"}], "correct_answer": "で", "explanations": {"で": "手段を表す「で」。「話し言葉で道を教える」と、伝える方法を示す。", "に": "相手を表す「に」で、伝える方法を示せない。「話し言葉に道を教える」は不自然。", "へ": "方向の「へ」で、伝える方法を示せない。", "より": "比較の「より」で、伝える方法を示せない。"}, "error_tags": {"に": "dative", "へ": "direction", "より": "comparison"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "書き言葉", "is_correct": true, "explanation": "文字で書いて伝える言葉を表し、声で伝える〈話し言葉〉の対義語になる。"}, {"text": "文章", "is_correct": false, "explanation": "書かれた文のまとまりを指し、対義語にはならない。"}, {"text": "絵本", "is_correct": false, "explanation": "絵と文字で作る本を指し、対義語にはならない。"}, {"text": "暗号", "is_correct": false, "explanation": "秘密の符号を指し、対義語にはならない。"}], "correct_answer": "書き言葉", "explanations": {"書き言葉": "文字で書いて伝える言葉を表し、声で伝える〈話し言葉〉の対義語になる。", "文章": "書かれた文のまとまりを指し、対義語にはならない。", "絵本": "絵と文字で作る本を指し、対義語にはならない。", "暗号": "秘密の符号を指し、対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37827, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "文字を使わずに、口で直接伝えるための言葉。", "primary_collocate": null, "pronunciation": "はなしことば", "ipa": "hanaɕikotoba", "syllable_count": 6, "sentences": [{"text": "昔、文字がない村では、話し言葉で物語を伝えました。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "昔[むかし]、文字[もじ]がない村[むら]では、話[はな]し言葉[ことば]で物語[ものがたり]を伝[つた]えました。", "sentence_source": "generated"}, {"text": "話し言葉は、声で相手にすぐ届きます。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "話[はな]し言葉[ことば]は、声[こえ]で相手[あいて]にすぐ届[とど]きます。", "sentence_source": "generated"}, {"text": "祖父は話し言葉で、昔の話を孫に聞かせました。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "祖父[そふ]は話[はな]し言葉[ことば]で、昔[むかし]の話[はなし]を孫[まご]に聞[き]かせました。", "sentence_source": "generated"}, {"text": "字が読めない子には、話し言葉で説明します。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "字[じ]が読[よ]めない子[こ]には、話[はな]し言葉[ことば]で説明[せつめい]します。", "sentence_source": "generated"}, {"text": "電話では、話し言葉だけで用事を伝えます。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "電話[でんわ]では、話[はな]し言葉[ことば]だけで用事[ようじ]を伝[つた]えます。", "sentence_source": "generated"}, {"text": "話し言葉は、書いたものと違って、あとに残りません。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "話[はな]し言葉[ことば]は、書[か]いたものと違[ちが]って、あとに残[のこ]りません。", "sentence_source": "generated"}, {"text": "この昔話は、話し言葉で長く伝わってきました。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "この昔話[むかしばなし]は、話[はな]し言葉[ことば]で長[なが]く伝[つた]わってきました。", "sentence_source": "generated"}, {"text": "目の見えない人に、話し言葉で道を教えます。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "目[め]の見[み]えない人[ひと]に、話[はな]し言葉[ことば]で道[みち]を教[おし]えます。", "sentence_source": "generated"}, {"text": "ラジオは、話し言葉で情報を伝えます。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "ラジオは、話[はな]し言葉[ことば]で情報[じょうほう]を伝[つた]えます。", "sentence_source": "generated"}, {"text": "文字を習う前、子どもは話し言葉で気持ちを話します。", "target_word": "話し言葉", "complexity_tier": "T3", "furigana": "文字[もじ]を習[なら]う前[まえ]、子[こ]どもは話[はな]し言葉[ことば]で気持[きも]ちを話[はな]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "話し言葉", "label": "基本形"}, {"form": "話し言葉で", "label": "手段"}], "register": "neutral", "sense_fingerprint": "文字に頼らず声で直接伝える言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1008a082-97df-4e54-bb3b-338a2360e5cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37827, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "話し言葉", "is_correct": true, "explanation": "文字がない村で声によって物語を伝える、という文脈に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "書いて送るものなので、文字がない村では使えない。"}, {"text": "文字", "is_correct": false, "explanation": "文字がない村という文脈と矛盾する。"}, {"text": "書き言葉", "is_correct": false, "explanation": "文字で書く言葉なので、文字がない村の文脈と矛盾する。"}], "explanations": {"話し言葉": "文字がない村で声によって物語を伝える、という文脈に合う。", "手紙": "書いて送るものなので、文字がない村では使えない。", "文字": "文字がない村という文脈と矛盾する。", "書き言葉": "文字で書く言葉なので、文字がない村の文脈と矛盾する。"}, "sentence_index": 0, "correct_answer": "話し言葉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "字が読めない子には、話し言葉で書いたプリントを配ります。", "explanation": "ここは〈書き言葉〉の意味。書いたプリントは書き言葉なので、口で伝える〈話し言葉〉とは合わない。"}, {"text": "字が読めない子には、話し言葉で絵を描きます。", "explanation": "ここは〈絵を描く〉の意味。〈話し言葉〉は声で伝える言葉なので、絵を描く手段にはならない。"}, {"text": "字が読めない子には、話し言葉で漢字の練習をさせます。", "explanation": "ここは〈書き言葉〉の意味。漢字の練習は文字を書く活動なので、文字を使わない〈話し言葉〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37827, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "話し言葉", "is_correct": true, "explanation": "口で長く伝わってきたという昔話の性質に合う。"}, {"text": "電報", "is_correct": false, "explanation": "電報は一度送る通信文で、昔話が口で長く伝わる文脈と合わない。"}, {"text": "写真", "is_correct": false, "explanation": "写真で長く伝わるという言い方は、昔話の伝わり方として合わない。"}, {"text": "暗号", "is_correct": false, "explanation": "秘密の符号で伝わるという意味になり、昔話の文脈と合わない。"}], "explanations": {"話し言葉": "口で長く伝わってきたという昔話の性質に合う。", "電報": "電報は一度送る通信文で、昔話が口で長く伝わる文脈と合わない。", "写真": "写真で長く伝わるという言い方は、昔話の伝わり方として合わない。", "暗号": "秘密の符号で伝わるという意味になり、昔話の文脈と合わない。"}, "sentence_index": 6, "correct_answer": "話し言葉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "文字を習う前、子どもは話し言葉で、ひらがなを書きます。", "explanation": "ここは〈書き言葉〉の意味。ひらがなを書くのは文字を使うことなので、〈話し言葉〉とは合わない。"}, {"text": "文字を習う前、子どもは話し言葉で、ノートに点を打ちます。", "explanation": "ここは〈書き言葉〉の意味。ノートに書くことは文字を使うので、〈話し言葉〉とは合わない。"}, {"text": "文字を習う前、子どもは話し言葉で、教科書を読んで覚えます。", "explanation": "ここは〈書き言葉〉の意味。教科書は文字で書かれているので、文字を使わない〈話し言葉〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37827, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "話し言葉を、声で遠くの人にもすぐ届きます。", "corrected_sentence": "話し言葉は、声で遠くの人にもすぐ届きます。", "error_description": "〈話し言葉〉は主語として使うので「は」が正しい。「を」は自動詞の「届く」の目的語にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37827, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "話し言葉を、祖父は昔の遊びを教えます。", "corrected_sentence": "話し言葉で、祖父は昔の遊びを教えます。", "error_description": "〈話し言葉〉は伝える方法を表すので「で」が正しい。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37828, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「この地方の民俗」と名詞をつなぐ連体修飾の「の」で、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「この地方が民俗は」では地方が民俗を持つ形になり、文の意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「この地方を民俗は」は目的語の形になるが、文の主題「民俗は」と結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「この地方へ民俗は」は民俗が行き先にならず、文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。「この地方の民俗」と名詞をつなぐ連体修飾の「の」で、文に合う。", "が": "「この地方が民俗は」では地方が民俗を持つ形になり、文の意味が通らない。", "を": "「この地方を民俗は」は目的語の形になるが、文の主題「民俗は」と結びつかない。", "へ": "方向を表す「へ」。「この地方へ民俗は」は民俗が行き先にならず、文の意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37828, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「民俗を守る」の「を」で、守る対象を示し文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「民俗へ守る」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手や共同を表す「と」。「民俗と守る」は文脈に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「民俗より守る」は比べる文ではなく、文意が通らない。"}], "correct_answer": "を", "explanations": {"を": "正解。「民俗を守る」の「を」で、守る対象を示し文に合う。", "へ": "方向を表す「へ」。「民俗へ守る」は成り立たない。", "と": "相手や共同を表す「と」。「民俗と守る」は文脈に合わない。", "より": "比較の「より」。「民俗より守る」は比べる文ではなく、文意が通らない。"}, "error_tags": {"へ": "方向", "と": "相手・共同", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37828, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある地域の人の間で、ずっと続いている生活のしかたや行事のこと。", "primary_collocate": null, "pronunciation": "みんぞく", "ipa": "mʲinzoku", "syllable_count": 4, "sentences": [{"text": "大学で日本の民俗を学び、各地の祭りについてレポートを書きました。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "大学[だいがく]で日本[にほん]の民俗[みんぞく]を学[まな]び、各地[かくち]の祭[まつ]りについてレポートを書[か]きました。", "sentence_source": "generated"}, {"text": "この地方の民俗は、親から子へ話や行事を通して伝えられてきました。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "この地方[ちほう]の民俗[みんぞく]は、親[おや]から子[こ]へ話[はなし]や行事[ぎょうじ]を通[とお]して伝[つた]えられてきました。", "sentence_source": "generated"}, {"text": "旅行先でその土地の民俗に触れると、自分の町との違いがよく分かります。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]でその土地[とち]の民俗[みんぞく]に触[ふ]れると、自分[じぶん]の町[まち]との違[ちが]いがよく分[わ]かります。", "sentence_source": "generated"}, {"text": "祖父は村の民俗にくわしいので、お祭りの意味を何でも教えてくれます。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "祖父[そふ]は村[むら]の民俗[みんぞく]にくわしいので、お祭[まつ]りの意味[いみ]を何[なん]でも教[おし]えてくれます。", "sentence_source": "generated"}, {"text": "都会では民俗が少しずつ消えていくため、記録に残す活動が大切です。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "都会[とかい]では民俗[みんぞく]が少[すこ]しずつ消[き]えていくため、記録[きろく]に残[のこ]す活動[かつどう]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "田植えの前に神様へ祈る民俗は、今もこの谷の村で続いています。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "田植[たう]えの前[まえ]に神様[かみさま]へ祈[いの]る民俗[みんぞく]は、今[いま]もこの谷[たに]の村[むら]で続[つづ]いています。", "sentence_source": "generated"}, {"text": "先生は写真を見せながら、東北の民俗について説明してくれました。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "先生[せんせい]は写真[しゃしん]を見[み]せながら、東北[とうほく]の民俗[みんぞく]について説明[せつめい]してくれました。", "sentence_source": "generated"}, {"text": "若い人が減ったので、昔の民俗を守ることが難しくなっています。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]が減[へ]ったので、昔[むかし]の民俗[みんぞく]を守[まも]ることが難[むずか]しくなっています。", "sentence_source": "generated"}, {"text": "外国から来た友だちは、日本の民俗に強い興味を持っています。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "外国[がいこく]から来[き]た友[とも]だちは、日本[にほん]の民俗[みんぞく]に強[つよ]い興味[きょうみ]を持[も]っています。", "sentence_source": "generated"}, {"text": "民俗を知らない人にも伝わるように、博物館は昔の道具を並べています。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "民俗[みんぞく]を知[し]らない人[ひと]にも伝[つた]わるように、博物館[はくぶつかん]は昔[むかし]の道具[どうぐ]を並[なら]べています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "民俗", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "地域の人々の間で続く生活のしかたや行事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37828, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民俗", "is_correct": true, "explanation": "正解。祭りや行事を含む地域の生活文化で、レポートの題材として文に合う。"}, {"text": "印鑑", "is_correct": false, "explanation": "判子のことで、「日本の印鑑を学ぶ」は道具の話になり、祭りのレポートとつながらない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、大学で学ぶ対象として文の内容と合わない。"}, {"text": "化石", "is_correct": false, "explanation": "地層に残る生物の跡で、各地の祭りについてのレポートとは関係がない。"}], "explanations": {"民俗": "正解。祭りや行事を含む地域の生活文化で、レポートの題材として文に合う。", "印鑑": "判子のことで、「日本の印鑑を学ぶ」は道具の話になり、祭りのレポートとつながらない。", "天気": "空模様のことで、大学で学ぶ対象として文の内容と合わない。", "化石": "地層に残る生物の跡で、各地の祭りについてのレポートとは関係がない。"}, "sentence_index": 0, "correct_answer": "民俗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この国には多くの民俗が暮らしている。", "explanation": "ここは〈民族〉の意味。民俗は習慣や行事を指し、人々の集団には使わないので誤り。"}, {"text": "この店では地元の民俗を売っている。", "explanation": "ここは〈民芸〉の意味。民俗は習慣を指し、民芸品のような工芸品は指さないので、店の商品には合わない。"}, {"text": "この店は夜遅くまで民俗営業をしている。", "explanation": "ここは〈風俗〉（風俗営業）の意味。民俗は習慣や行事を指し、営業の種類を表す語には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37828, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民俗", "is_correct": true, "explanation": "正解。地域に伝わる習慣や行事の意味で、東北について説明する文に合う。"}, {"text": "時差", "is_correct": false, "explanation": "時刻のずれのことで、写真を見せながら地域の習慣を説明する文とは内容が合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "生物や物が存在する期間のことで、東北について説明する文脈に合わない。"}, {"text": "血液", "is_correct": false, "explanation": "体の中を巡る液体で、地域について説明する対象として文に合わない。"}], "explanations": {"民俗": "正解。地域に伝わる習慣や行事の意味で、東北について説明する文に合う。", "時差": "時刻のずれのことで、写真を見せながら地域の習慣を説明する文とは内容が合わない。", "寿命": "生物や物が存在する期間のことで、東北について説明する文脈に合わない。", "血液": "体の中を巡る液体で、地域について説明する対象として文に合わない。"}, "sentence_index": 6, "correct_answer": "民俗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国の民俗は、政府の方針に大きく抗議した。", "explanation": "ここは〈民衆〉の意味。民俗は習慣や行事を指し、抗議する人々の集まりは指さないので誤り。"}, {"text": "あの職人は高い民俗を持っていて、どんな仕事も確実にこなす。", "explanation": "ここは〈技術〉の意味。民俗は習慣を指し、職人の腕前や技量は表さないので誤り。"}, {"text": "その土地の民俗は米作りに向いていて、毎年よく実る。", "explanation": "ここは〈風土〉の意味。民俗は習慣や行事を指し、気候や土地の性質は表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37828, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は村の民俗に研究して、本を書きました。", "corrected_sentence": "祖母は村の民俗を研究して、本を書きました。", "error_description": "「研究する」は目的語に「を」を取る。「民俗に」は誤りで、正しくは「民俗を」。「に」と「を」の取り違え。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37828, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村では昔からの民俗に受け継いでいます。", "corrected_sentence": "村では昔からの民俗を受け継いでいます。", "error_description": "「受け継ぐ」は目的語に「を」を取る。「民俗に」は誤りで、正しくは「民俗を」。「に」と「を」の取り違え。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37829, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「民俗の調査」と名詞をつなぐ「の」で、調査の対象を示し文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「民俗が調査をする」では民俗が行う主体になり、研究者の行為と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「民俗に調査をする」は対象を示す形になっておらず、文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「民俗へ調査をする」は調査の対象にならず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "正解。「民俗の調査」と名詞をつなぐ「の」で、調査の対象を示し文に合う。", "が": "「民俗が調査をする」では民俗が行う主体になり、研究者の行為と合わない。", "に": "「民俗に調査をする」は対象を示す形になっておらず、文の意味が通らない。", "へ": "方向を表す「へ」。「民俗へ調査をする」は調査の対象にならず、文が成り立たない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37829, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「その土地の民俗」と土地と民俗をつなぐ連体修飾の「の」で、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「その土地を民俗は新鮮で」は目的語の形になり、主語「民俗は」と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「その土地へ民俗は新鮮で」は方向を表す形になり、文の意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「その土地が民俗は新鮮で」は主語の形として成り立たず、文意が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。「その土地の民俗」と土地と民俗をつなぐ連体修飾の「の」で、文に合う。", "を": "「その土地を民俗は新鮮で」は目的語の形になり、主語「民俗は」と合わない。", "へ": "「その土地へ民俗は新鮮で」は方向を表す形になり、文の意味が通らない。", "が": "「その土地が民俗は新鮮で」は主語の形として成り立たず、文意が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37829, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の地域や社会で、古くから伝えられてきた習慣や行事、生活様式のこと。", "primary_collocate": null, "pronunciation": "みんぞく", "ipa": "mʲinzoku", "syllable_count": 4, "sentences": [{"text": "旅行雑誌には、この島に伝わる民俗が写真つきで紹介されていました。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "旅行雑誌[りょこうざっし]には、この島[しま]に伝[つた]わる民俗[みんぞく]が写真[しゃしん]つきで紹介[しょうかい]されていました。", "sentence_source": "generated"}, {"text": "民俗の調査をするため、研究者は何日も村に泊まってお年寄りの話を聞きました。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "民俗[みんぞく]の調査[ちょうさ]をするため、研究者[けんきゅうしゃ]は何日[なんにち]も村[むら]に泊[と]まってお年寄[としよ]りの話[はなし]を聞[き]きました。", "sentence_source": "generated"}, {"text": "正月に餅を食べる民俗は、地域によってやり方が少しずつ違います。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "正月[しょうがつ]に餅[もち]を食[た]べる民俗[みんぞく]は、地域[ちいき]によってやり方[かた]が少[すこ]しずつ違[ちが]います。", "sentence_source": "generated"}, {"text": "昔からの民俗を大切にしているので、この町では毎年同じ日に祭りを開きます。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "昔[むかし]からの民俗[みんぞく]を大切[たいせつ]にしているので、この町[まち]では毎年[まいとし]同[おな]じ日[ひ]に祭[まつ]りを開[ひら]きます。", "sentence_source": "generated"}, {"text": "山あいの集落には、雪の季節の暮らしを映した民俗が多く残っています。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "山[やま]あいの集落[しゅうらく]には、雪[ゆき]の季節[きせつ]の暮[く]らしを映[うつ]した民俗[みんぞく]が多[おお]く残[のこ]っています。", "sentence_source": "generated"}, {"text": "結婚式の民俗は時代とともに変わり、今では簡単な形になった地域もあります。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]の民俗[みんぞく]は時代[じだい]とともに変[か]わり、今[いま]では簡単[かんたん]な形[かたち]になった地域[ちいき]もあります。", "sentence_source": "generated"}, {"text": "彼女は民俗に関する本を読んで、地元の行事の意味を初めて知りました。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は民俗[みんぞく]に関[かん]する本[ほん]を読[よ]んで、地元[じもと]の行事[ぎょうじ]の意味[いみ]を初[はじ]めて知[し]りました。", "sentence_source": "generated"}, {"text": "外から来た人にとって、その土地の民俗は新鮮で、見るものすべてがおもしろいです。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "外[そと]から来[き]た人[ひと]にとって、その土地[とち]の民俗[みんぞく]は新鮮[しんせん]で、見[み]るものすべてがおもしろいです。", "sentence_source": "generated"}, {"text": "博物館では、漁師の暮らしを伝える民俗を、道具や写真で見ることができます。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、漁師[りょうし]の暮[く]らしを伝[つた]える民俗[みんぞく]を、道具[どうぐ]や写真[しゃしん]で見[み]ることができます。", "sentence_source": "generated"}, {"text": "民俗の違いを比べると、同じ国でも暮らし方がずいぶん違うと分かります。", "target_word": "民俗", "complexity_tier": "T3", "furigana": "民俗[みんぞく]の違[ちが]いを比[くら]べると、同[おな]じ国[くに]でも暮[く]らし方[かた]がずいぶん違[ちが]うと分[わ]かります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "民俗", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "古くから伝わる習慣・行事・生活様式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37829, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民俗", "is_correct": true, "explanation": "正解。島に伝わる習慣や行事を指し、紹介される内容として文に合う。"}, {"text": "電圧", "is_correct": false, "explanation": "電気の圧力のことで、島に伝わるものとして紹介される文には合わない。"}, {"text": "電卓", "is_correct": false, "explanation": "計算に使う機械で、島に伝わるものとして紹介する文には合わない。"}, {"text": "時刻表", "is_correct": false, "explanation": "交通の時刻を示す表で、伝わるものとして写真つきで紹介する文に合わない。"}], "explanations": {"民俗": "正解。島に伝わる習慣や行事を指し、紹介される内容として文に合う。", "電圧": "電気の圧力のことで、島に伝わるものとして紹介される文には合わない。", "電卓": "計算に使う機械で、島に伝わるものとして紹介する文には合わない。", "時刻表": "交通の時刻を示す表で、伝わるものとして写真つきで紹介する文に合わない。"}, "sentence_index": 0, "correct_answer": "民俗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この国では民俗の原則に従って、代表を選ぶ。", "explanation": "ここは〈民主〉の意味。民俗は習慣や行事を指し、選挙の原則には使えないので誤り。"}, {"text": "あの子は食事中の民俗が悪い。", "explanation": "ここは〈行儀〉の意味。民俗は習慣や行事の総称で、人の振る舞いの良し悪しは言わないので誤り。"}, {"text": "今朝は民俗がいい。", "explanation": "ここは〈体調〉の意味。民俗は土地の習慣を指し、人の体の状態は表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37829, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民俗", "is_correct": true, "explanation": "正解。地元の行事の意味を知る本の話題として、文に合う。"}, {"text": "電卓", "is_correct": false, "explanation": "計算に使う機械で、行事の意味を知るための本の話題としては合わない。"}, {"text": "水道", "is_correct": false, "explanation": "水を供給する設備で、本の話題としては文に合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "衣類で、地元の行事について書かれた本の話題としては不自然。"}], "explanations": {"民俗": "正解。地元の行事の意味を知る本の話題として、文に合う。", "電卓": "計算に使う機械で、行事の意味を知るための本の話題としては合わない。", "水道": "水を供給する設備で、本の話題としては文に合わない。", "靴下": "衣類で、地元の行事について書かれた本の話題としては不自然。"}, "sentence_index": 6, "correct_answer": "民俗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その寺院は毎朝、民俗を参拝する人が絶えない。", "explanation": "ここは〈神仏〉（参拝の対象）の意味。民俗は習慣や行事を指し、参拝される存在にはならないので誤り。"}, {"text": "明日は民俗が荒れそうなので、遠足は延期します。", "explanation": "ここは〈天候〉の意味。民俗は習慣を指し、空模様の状態は表さないので誤り。"}, {"text": "この工場では毎日、民俗を作って出荷している。", "explanation": "ここは〈製品〉の意味。民俗は習慣や行事を指し、作って出荷する品物にはならないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37829, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は子どものころ、村の民俗で触れて育ったそうです。", "corrected_sentence": "祖父は子どものころ、村の民俗に触れて育ったそうです。", "error_description": "「触れる」は「に」を取る。「民俗で」は誤りで、正しくは「民俗に」。「で」と「に」の取り違え。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37829, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "博物館で昔の民俗に調べたら、正月の行事の由来が分かりました。", "corrected_sentence": "博物館で昔の民俗を調べたら、正月の行事の由来が分かりました。", "error_description": "「調べる」は目的語に「を」を取る。「民俗に」は誤りで、正しくは「民俗を」。「に」と「を」の取り違え。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37830, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「年長の人」と年長と人をつなぐ連体修飾の「の」で、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「年長が人には」は主語の形になるが、文の意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「年長を人には」は目的語の形になり、人を修飾する語として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「年長へ人には」は成り立たず、文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。「年長の人」と年長と人をつなぐ連体修飾の「の」で、文に合う。", "が": "「年長が人には」は主語の形になるが、文の意味が通らない。", "を": "「年長を人には」は目的語の形になり、人を修飾する語として不自然。", "へ": "方向を表す「へ」。「年長へ人には」は成り立たず、文の意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37830, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「年長の人が火をおこし」と年長と人をつなぐ連体修飾の「の」で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「年長に人が火をおこし」は文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「年長へ人が火をおこし」は方向を表す形になり、主語と合わない。"}, {"text": "から", "is_correct": false, "explanation": "「年長から人が火をおこし」は起点の形になり、文の主語と合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「年長の人が火をおこし」と年長と人をつなぐ連体修飾の「の」で、文に合う。", "に": "「年長に人が火をおこし」は文の意味が通らない。", "へ": "「年長へ人が火をおこし」は方向を表す形になり、主語と合わない。", "から": "「年長から人が火をおこし」は起点の形になり、文の主語と合わない。"}, "error_tags": {"に": "相手・対象", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37830, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "年齢が上の人。", "primary_collocate": null, "pronunciation": "ねんちょう", "ipa": "neɲtɕoː", "syllable_count": 4, "sentences": [{"text": "私は三人兄弟の中で年長なので、弟たちの世話をすることが多いです。", "target_word": "年長", "complexity_tier": "T3", "furigana": "私[わたし]は三人兄弟[さんにんきょうだい]の中[なか]で年長[ねんちょう]なので、弟[おとうと]たちの世話[せわ]をすることが多[おお]いです。", "sentence_source": "generated"}, {"text": "年長の人には、まず敬語で話すように母から教えられました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "年長[ねんちょう]の人[ひと]には、まず敬語[けいご]で話[はな]すように母[はは]から教[おし]えられました。", "sentence_source": "generated"}, {"text": "この旅行では、いちばん年長の山田さんがみんなの道案内をしてくれました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "この旅行[りょこう]では、いちばん年長[ねんちょう]の山田[やまだ]さんがみんなの道案内[みちあんない]をしてくれました。", "sentence_source": "generated"}, {"text": "彼は年長だから、年下の子たちが困るとすぐに助けてあげます。", "target_word": "年長", "complexity_tier": "T3", "furigana": "彼[かれ]は年長[ねんちょう]だから、年下[としした]の子[こ]たちが困[こま]るとすぐに助[たす]けてあげます。", "sentence_source": "generated"}, {"text": "年長の兄が先に家を出たので、私は一人で留守番をしました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "年長[ねんちょう]の兄[あに]が先[さき]に家[いえ]を出[で]たので、私[わたし]は一人[ひとり]で留守番[るすばん]をしました。", "sentence_source": "generated"}, {"text": "会議では年長の先生が最初に意見を言い、そのあと若い人が話しました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "会議[かいぎ]では年長[ねんちょう]の先生[せんせい]が最初[さいしょ]に意見[いけん]を言[い]い、そのあと若[わか]い人[ひと]が話[はな]しました。", "sentence_source": "generated"}, {"text": "年長の友人から、仕事で失敗したときの考え方を教えてもらいました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "年長[ねんちょう]の友人[ゆうじん]から、仕事[しごと]で失敗[しっぱい]したときの考[かんが]え方[かた]を教[おし]えてもらいました。", "sentence_source": "generated"}, {"text": "キャンプでは、年長の人が火をおこし、小さい子は薪を集めました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "キャンプでは、年長[ねんちょう]の人[ひと]が火[ひ]をおこし、小[ちい]さい子[こ]は薪[まき]を集[あつ]めました。", "sentence_source": "generated"}, {"text": "彼女は私より五つ年長ですが、いつも対等に話してくれます。", "target_word": "年長", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は私[わたし]より五[いつ]つ年長[ねんちょう]ですが、いつも対等[たいとう]に話[はな]してくれます。", "sentence_source": "generated"}, {"text": "年長のいとこが、私の宿題を見ながらやさしく説明してくれました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "年長[ねんちょう]のいとこが、私[わたし]の宿題[しゅくだい]を見[み]ながらやさしく説明[せつめい]してくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年長", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "年齢が上の人、年上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37830, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年長", "is_correct": true, "explanation": "正解。三人兄弟の中での年齢の上下を表し、文に合う。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さのことで、兄弟の中での年齢の位置を表す文には合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を示す道具で、兄弟の中での位置を表す語として合わない。"}, {"text": "方角", "is_correct": false, "explanation": "東西南北の向きのことで、兄弟の年齢の位置には使えない。"}], "explanations": {"年長": "正解。三人兄弟の中での年齢の上下を表し、文に合う。", "体重": "体の重さのことで、兄弟の中での年齢の位置を表す文には合わない。", "時計": "時刻を示す道具で、兄弟の中での位置を表す語として合わない。", "方角": "東西南北の向きのことで、兄弟の年齢の位置には使えない。"}, "sentence_index": 0, "correct_answer": "年長"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は年長の努力が実って、ついに優勝した。", "explanation": "ここは〈長年〉の意味。年長は人の年齢が上であることを指し、努力を続けた期間は表さないので誤り。"}, {"text": "この職人は年長が入っていて、仕事が丁寧だ。", "explanation": "ここは〈年季〉の意味。年長は年齢の上下を指し、仕事で積んだ経験の長さは言えないので誤り。"}, {"text": "この職人は長い年長を積んでいて、どんな仕事も確実だ。", "explanation": "ここは〈年功〉の意味。年長は人を指す語で、積み重ねた経験や功績は表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37830, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年長", "is_correct": true, "explanation": "正解。年上の友人を指し、文の主語として自然。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う小さな紙で、人の関係を表す語の位置には入らない。"}, {"text": "水量", "is_correct": false, "explanation": "水の量のことで、友人を表す語として文に合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度のことで、人を表す語の位置には入らず文に合わない。"}], "explanations": {"年長": "正解。年上の友人を指し、文の主語として自然。", "切手": "郵便に使う小さな紙で、人の関係を表す語の位置には入らない。", "水量": "水の量のことで、友人を表す語として文に合わない。", "体温": "体の温度のことで、人を表す語の位置には入らず文に合わない。"}, "sentence_index": 6, "correct_answer": "年長"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あれから年長が流れて、彼はすっかり大人になった。", "explanation": "ここは〈歳月〉の意味。年長は年上の人を指すので、時の経過には使えないので誤り。"}, {"text": "図書館で年長を借りて、統計の数字を調べた。", "explanation": "ここは〈年鑑〉の意味。年長は人について言う語で、年次の資料には使えないので誤り。"}, {"text": "彼は年長を伸ばすため、毎日練習を続けている。", "explanation": "ここは〈長所〉の意味。年長は年齢が上であることで、得意な点や強みは指さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37830, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年長な姉が、妹の宿題を手伝ってくれました。", "corrected_sentence": "年長の姉が、妹の宿題を手伝ってくれました。", "error_description": "「年長」は名詞なので、名詞を修飾するには「の」を使う。「年長な」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37830, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "親戚の集まりでは、年長にいとこが昔話を聞かせてくれました。", "corrected_sentence": "親戚の集まりでは、年長のいとこが昔話を聞かせてくれました。", "error_description": "「年長」の後は連体修飾の「の」が必要。「に」は誤りで、「年長のいとこ」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37831, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "年少", "is_correct": true, "explanation": "正解。年齢が若いことを指し、年長の対義語として辞典に示される。"}, {"text": "年上", "is_correct": false, "explanation": "年長と同じく年齢が上であることを表す類義語で、対義語ではない。"}, {"text": "老年", "is_correct": false, "explanation": "年を取った時期を指す語で、年長と対になる語ではない。"}, {"text": "中年", "is_correct": false, "explanation": "年齢の中ほどの時期を指す語で、年長の反対語にはならない。"}], "correct_answer": "年少", "explanations": {"年少": "正解。年齢が若いことを指し、年長の対義語として辞典に示される。", "年上": "年長と同じく年齢が上であることを表す類義語で、対義語ではない。", "老年": "年を取った時期を指す語で、年長と対になる語ではない。", "中年": "年齢の中ほどの時期を指す語で、年長の反対語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37831, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "年少", "is_correct": true, "explanation": "正解。年齢が若いことを指し、年長の対義語として辞典に示される。"}, {"text": "人生", "is_correct": false, "explanation": "生まれてから死ぬまでの一生を指す語で、年長と対になる語ではない。"}, {"text": "歳月", "is_correct": false, "explanation": "過ぎていく時間を指す語で、年長の反対語にはならない。"}, {"text": "高齢", "is_correct": false, "explanation": "年を重ねていることを表す類義語で、対義語ではない。"}], "correct_answer": "年少", "explanations": {"年少": "正解。年齢が若いことを指し、年長の対義語として辞典に示される。", "人生": "生まれてから死ぬまでの一生を指す語で、年長と対になる語ではない。", "歳月": "過ぎていく時間を指す語で、年長の反対語にはならない。", "高齢": "年を重ねていることを表す類義語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37831, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "年齢が上のこと。また、その人。先輩や目上の人を指す。", "primary_collocate": null, "pronunciation": "ねんちょう", "ipa": "neɲtɕoː", "syllable_count": 4, "sentences": [{"text": "会社では年長の社員に対して、言葉づかいに気をつけています。", "target_word": "年長", "complexity_tier": "T3", "furigana": "会社[かいしゃ]では年長[ねんちょう]の社員[しゃいん]に対[たい]して、言葉[ことば]づかいに気[き]をつけています。", "sentence_source": "generated"}, {"text": "年齢が違う人たちの集まりでは、年長の意見を聞く場面が多いです。", "target_word": "年長", "complexity_tier": "T3", "furigana": "年齢[ねんれい]が違[ちが]う人[ひと]たちの集[あつ]まりでは、年長[ねんちょう]の意見[いけん]を聞[き]く場面[ばめん]が多[おお]いです。", "sentence_source": "generated"}, {"text": "彼は年長ということで、サークルの代表を任されました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "彼[かれ]は年長[ねんちょう]ということで、サークルの代表[だいひょう]を任[まか]されました。", "sentence_source": "generated"}, {"text": "年長の人に失礼のないよう、席を立つときも一言あいさつをしました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "年長[ねんちょう]の人[ひと]に失礼[しつれい]のないよう、席[せき]を立[た]つときも一言[ひとこと]あいさつをしました。", "sentence_source": "generated"}, {"text": "同じクラスでも、浪人した彼は私より二つ年長です。", "target_word": "年長", "complexity_tier": "T3", "furigana": "同[おな]じクラスでも、浪人[ろうにん]した彼[かれ]は私[わたし]より二[ふた]つ年長[ねんちょう]です。", "sentence_source": "generated"}, {"text": "年長の同僚が、新人の私に仕事のコツを丁寧に教えてくれました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "年長[ねんちょう]の同僚[どうりょう]が、新人[しんじん]の私[わたし]に仕事[しごと]のコツを丁寧[ていねい]に教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "祖父母のような年長の人たちから学ぶことは、とても多いです。", "target_word": "年長", "complexity_tier": "T3", "furigana": "祖父母[そふぼ]のような年長[ねんちょう]の人[ひと]たちから学[まな]ぶことは、とても多[おお]いです。", "sentence_source": "generated"}, {"text": "親戚の集まりでは、最も年長の叔父が乾杯の音頭をとりました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "親戚[しんせき]の集[あつ]まりでは、最[もっと]も年長[ねんちょう]の叔父[おじ]が乾杯[かんぱい]の音頭[おんど]をとりました。", "sentence_source": "generated"}, {"text": "年長のメンバーが引退し、若い人たちが運営を引き継ぎました。", "target_word": "年長", "complexity_tier": "T3", "furigana": "年長[ねんちょう]のメンバーが引退[いんたい]し、若[わか]い人[ひと]たちが運営[うんえい]を引[ひ]き継[つ]ぎました。", "sentence_source": "generated"}, {"text": "彼女は年長の人にも、自分の考えをはっきり伝えます。", "target_word": "年長", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は年長[ねんちょう]の人[ひと]にも、自分[じぶん]の考[かんが]えをはっきり伝[つた]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年長", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "年齢が上であること、目上の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37831, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年長", "is_correct": true, "explanation": "正解。会社で年齢が上の社員を指し、言葉づかいに気をつける文に合う。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度のことで、社員を表す語の位置には入らず文に合わない。"}, {"text": "雨量", "is_correct": false, "explanation": "降った雨の量のことで、社員について言う語として合わない。"}, {"text": "電池", "is_correct": false, "explanation": "電気を蓄える部品で、社員の立場を表す語として合わない。"}], "explanations": {"年長": "正解。会社で年齢が上の社員を指し、言葉づかいに気をつける文に合う。", "体温": "体の温度のことで、社員を表す語の位置には入らず文に合わない。", "雨量": "降った雨の量のことで、社員について言う語として合わない。", "電池": "電気を蓄える部品で、社員の立場を表す語として合わない。"}, "sentence_index": 0, "correct_answer": "年長"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は年長をとって、少し耳が遠くなりました。", "explanation": "ここは〈歳〉の意味。「歳をとる」の歳は年数を指し、年上の人を表す年長とは言えないので誤り。"}, {"text": "この電池は年長が尽きて、使えなくなりました。", "explanation": "ここは〈寿命〉の意味。年長は人の年齢の上下を指し、物の寿命は言えないので誤り。"}, {"text": "木の年長を数えると、その木の樹齢が分かります。", "explanation": "ここは〈年輪〉の意味。年長は人について使う語で、木の層を数える言い方には合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37831, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年長", "is_correct": true, "explanation": "正解。祖父母のような年上の人たちを指し、学ぶ相手として文に合う。"}, {"text": "海水", "is_correct": false, "explanation": "海の水のことで、人の集団を表す語の位置には入らない。"}, {"text": "硬貨", "is_correct": false, "explanation": "お金の一種で、人を表す語として文に合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "学校の課題のことで、人を表す語の位置に入らず文に合わない。"}], "explanations": {"年長": "正解。祖父母のような年上の人たちを指し、学ぶ相手として文に合う。", "海水": "海の水のことで、人の集団を表す語の位置には入らない。", "硬貨": "お金の一種で、人を表す語として文に合わない。", "宿題": "学校の課題のことで、人を表す語の位置に入らず文に合わない。"}, "sentence_index": 6, "correct_answer": "年長"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この仕事は年長が長く、経験を積んだ人が多いです。", "explanation": "ここは〈年数〉の意味。年長は人の年齢の上を指し、勤務などの年数の長さは表さないので誤り。"}, {"text": "来年の年長を交渉するため、社長と話し合いました。", "explanation": "ここは〈年俸〉の意味。年長は人を指す語で、一年分の給料は表さないので誤り。"}, {"text": "歴史の出来事を年長にまとめ、一枚の紙に書きました。", "explanation": "ここは〈年表〉の意味。年長は人について言う語で、時代順の一覧は指さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37831, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社では年長を社員が、新人の教育を担当しています。", "corrected_sentence": "会社では年長の社員が、新人の教育を担当しています。", "error_description": "「年長の社員」と連体修飾するには「の」が必要。「を」は目的語を示すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37831, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父母のような年長な人たちが、地域の行事を支えてきました。", "corrected_sentence": "祖父母のような年長の人たちが、地域の行事を支えてきました。", "error_description": "「年長」は名詞なので、名詞を修飾するには「の」を使う。「年長な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37832, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昼", "is_correct": true, "explanation": "夜の対義語として辞書に載る。日中の時間帯を表す。"}, {"text": "石", "is_correct": false, "explanation": "鉱物の語で、夜の対義語ではない。"}, {"text": "風", "is_correct": false, "explanation": "気象の語で、夜の対義語ではない。"}, {"text": "駅", "is_correct": false, "explanation": "場所の語で、夜の対義語ではない。"}], "correct_answer": "昼", "explanations": {"昼": "夜の対義語として辞書に載る。日中の時間帯を表す。", "石": "鉱物の語で、夜の対義語ではない。", "風": "気象の語で、夜の対義語ではない。", "駅": "場所の語で、夜の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37832, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『病院の夜』を主題として示し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、ここでは主題の夜と合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示し、主題にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示し、静かさの主語にはならない。"}], "correct_answer": "は", "explanations": {"は": "『病院の夜』を主題として示し、文に合う。", "を": "目的語を示すが、ここでは主題の夜と合わない。", "で": "場所や手段を示し、主題にはならない。", "と": "並列や相手を示し、静かさの主語にはならない。"}, "error_tags": {"を": "目的語の格助詞", "で": "場所・手段の格助詞", "と": "並列・相手の格助詞"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昼", "is_correct": true, "explanation": "夜の対義語として辞書に載る。日中の時間帯を表す。"}, {"text": "雨", "is_correct": false, "explanation": "天候の語で、時間帯の夜の対義語ではない。"}, {"text": "春", "is_correct": false, "explanation": "季節の語で、時間帯の夜の対義語ではない。"}, {"text": "鳥", "is_correct": false, "explanation": "動物の語で、夜の対義語ではない。"}], "correct_answer": "昼", "explanations": {"昼": "夜の対義語として辞書に載る。日中の時間帯を表す。", "雨": "天候の語で、時間帯の夜の対義語ではない。", "春": "季節の語で、時間帯の夜の対義語ではない。", "鳥": "動物の語で、夜の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37832, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "太陽が沈んで暗くなった後の時間のことです。", "primary_collocate": null, "pronunciation": "よる", "ipa": "joɾɯ", "syllable_count": 2, "sentences": [{"text": "夜は仕事が終わって、家族とゆっくり食事をする時間だ。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]は仕事[しごと]が終[お]わって、家族[かぞく]とゆっくり食事[しょくじ]をする時間[じかん]だ。", "sentence_source": "generated"}, {"text": "夜、窓を開けると、涼しい風が部屋に入ってきた。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]、窓[まど]を開[あ]けると、涼[すず]しい風[かぜ]が部屋[へや]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "私は朝よりも夜のほうが集中できるので、勉強はいつも夜にする。", "target_word": "夜", "complexity_tier": "T3", "furigana": "私[わたし]は朝[あさ]よりも夜[よる]のほうが集中[しゅうちゅう]できるので、勉強[べんきょう]はいつも夜[よる]にする。", "sentence_source": "generated"}, {"text": "夜の道は暗いから、自転車にはライトをつけてください。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]の道[みち]は暗[くら]いから、自転車[じてんしゃ]にはライトをつけてください。", "sentence_source": "generated"}, {"text": "夜が来ると、街の明かりが一つずつ灯りはじめた。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]が来[く]ると、街[まち]の明[あ]かりが一[ひと]つずつ灯[とも]りはじめた。", "sentence_source": "generated"}, {"text": "ひどい雨が降った夜、私は停電の中でろうそくを使った。", "target_word": "夜", "complexity_tier": "T3", "furigana": "ひどい雨[あめ]が降[ふ]った夜[よる]、私[わたし]は停電[ていでん]の中[なか]でろうそくを使[つか]った。", "sentence_source": "generated"}, {"text": "夜は空気が冷たく、昼との温度差が大きい。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]は空気[くうき]が冷[つめ]たく、昼[ひる]との温度差[おんどさ]が大[おお]きい。", "sentence_source": "generated"}, {"text": "病院の夜は静かで、廊下に足音だけが響いた。", "target_word": "夜", "complexity_tier": "T3", "furigana": "病院[びょういん]の夜[よる]は静[しず]かで、廊下[ろうか]に足音[あしおと]だけが響[ひび]いた。", "sentence_source": "generated"}, {"text": "夜に外出するときは、家族に行き先を伝えておく。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]に外出[がいしゅつ]するときは、家族[かぞく]に行[い]き先[さき]を伝[つた]えておく。", "sentence_source": "generated"}, {"text": "長い夜を、彼は手紙を書いて過ごした。", "target_word": "夜", "complexity_tier": "T3", "furigana": "長[なが]い夜[よる]を、彼[かれ]は手紙[てがみ]を書[か]いて過[す]ごした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "夜", "label": "base"}, {"form": "夜の", "label": "genitive"}, {"form": "夜に", "label": "temporal"}], "register": "neutral", "sense_fingerprint": "night, the time after the sun has set and it is dark", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 廊下 (Zipf 3.79), 足音 (Zipf 3.35), 響い (Zipf 3.51)']::text[], '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37832, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夜", "is_correct": true, "explanation": "夜に仕事が終わり、家族と食事をする時間として自然に収まる。"}, {"text": "窓", "is_correct": false, "explanation": "窓は仕事が終わる主体にならないので文が成り立たない。"}, {"text": "駅", "is_correct": false, "explanation": "駅は食事をする時間の主題にならず不自然。"}, {"text": "雨", "is_correct": false, "explanation": "雨は家族と食事をする時間にはならない。"}], "explanations": {"夜": "夜に仕事が終わり、家族と食事をする時間として自然に収まる。", "窓": "窓は仕事が終わる主体にならないので文が成り立たない。", "駅": "駅は食事をする時間の主題にならず不自然。", "雨": "雨は家族と食事をする時間にはならない。"}, "sentence_index": 0, "correct_answer": "夜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜の五時の窓辺は、西日がまぶしく差し込んでいた。", "explanation": "ここは〈夕方〉の意味。西日が差す明るい時刻は〈夜〉の定義に合わない。"}, {"text": "夜の窓辺に、朝日が差し込んでまぶしかった。", "explanation": "ここは〈夜明け〉の意味。朝日が差す時間は〈夜〉の定義に合わない。"}, {"text": "夜の教室は、窓から差す日差しで明るかった。", "explanation": "ここは〈昼〉の意味。日差しで明るい時間は夜の定義に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37832, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夜", "is_correct": true, "explanation": "夜は空気が冷たく、昼との温度差が大きいという文脈に自然に収まる。"}, {"text": "花", "is_correct": false, "explanation": "花は空気が冷たいという主語にならず不自然。"}, {"text": "机", "is_correct": false, "explanation": "机は空気の描写の主語にならない。"}, {"text": "本", "is_correct": false, "explanation": "本は空気が冷たいという主語にならない。"}], "explanations": {"夜": "夜は空気が冷たく、昼との温度差が大きいという文脈に自然に収まる。", "花": "花は空気が冷たいという主語にならず不自然。", "机": "机は空気の描写の主語にならない。", "本": "本は空気が冷たいという主語にならない。"}, "sentence_index": 6, "correct_answer": "夜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この劇場の夜の部は、午後二時に始まった。", "explanation": "ここは〈午後〉の時間を〈夜〉で言った誤用。午後二時は〈夜〉の定義に合わない。"}, {"text": "夜の公園は、真昼の熱気に包まれていた。", "explanation": "ここは〈昼〉の意味。真昼の熱気は〈夜〉の定義に合わない。"}, {"text": "夜の食堂は、朝ごはんを求める人で混みあった。", "explanation": "ここは〈朝〉の意味。朝ごはんの時間は〈夜〉の定義に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
