INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37833, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "太陽が地平線に沈んでから、再び昇るまでの暗い時間帯。", "primary_collocate": null, "pronunciation": "よる", "ipa": "joɾɯ", "syllable_count": 2, "sentences": [{"text": "夜が明け、太陽が農場を照らし始める朝、農家の男は鶏舎へと足を運ぶ。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]け、太陽[たいよう]が農場[のうじょう]を照[て]らし始[はじ]める朝[あさ]、農家[のうか]の男[おとこ]は鶏舎[けいしゃ]へと足[あし]を運[はこ]ぶ。", "sentence_source": "mined"}, {"text": "夜は気温が下がるので、上着を持って出かけたほうがいい。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]は気温[きおん]が下[さ]がるので、上着[うわぎ]を持[も]って出[で]かけたほうがいい。", "sentence_source": "generated"}, {"text": "昨日の夜、友達から電話があって、遅くまで話した。", "target_word": "夜", "complexity_tier": "T3", "furigana": "昨日[きのう]の夜[よる]、友達[ともだち]から電話[でんわ]があって、遅[おそ]くまで話[はな]した。", "sentence_source": "generated"}, {"text": "夏の夜には、公園で虫の声がよく聞こえる。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夏[なつ]の夜[よる]には、公園[こうえん]で虫[むし]の声[こえ]がよく聞[き]こえる。", "sentence_source": "generated"}, {"text": "この町は夜になると店が閉まり、とても静かになる。", "target_word": "夜", "complexity_tier": "T3", "furigana": "この町[まち]は夜[よる]になると店[みせ]が閉[し]まり、とても静[しず]かになる。", "sentence_source": "generated"}, {"text": "夜の海は暗くて、波の音だけが聞こえていた。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]の海[うみ]は暗[くら]くて、波[なみ]の音[おと]だけが聞[き]こえていた。", "sentence_source": "generated"}, {"text": "夜が長い冬は、早く寝て本を読むのが好きだ。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]が長[なが]い冬[ふゆ]は、早[はや]く寝[ね]て本[ほん]を読[よ]むのが好[す]きだ。", "sentence_source": "generated"}, {"text": "明日は朝早く出発するので、夜のうちに荷物を準備しておく。", "target_word": "夜", "complexity_tier": "T3", "furigana": "明日[あした]は朝早[あさはや]く出発[しゅっぱつ]するので、夜[よる]のうちに荷物[にもつ]を準備[じゅんび]しておく。", "sentence_source": "generated"}, {"text": "夜に食べすぎると、次の朝おなかが重く感じる。", "target_word": "夜", "complexity_tier": "T3", "furigana": "夜[よる]に食[た]べすぎると、次[つぎ]の朝[あさ]おなかが重[おも]く感[かん]じる。", "sentence_source": "generated"}, {"text": "空に星が見えるのは、昼ではなく夜だ。", "target_word": "夜", "complexity_tier": "T3", "furigana": "空[そら]に星[ほし]が見[み]えるのは、昼[ひる]ではなく夜[よる]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "夜", "label": "base"}, {"form": "夜の", "label": "genitive"}, {"form": "夜に", "label": "temporal"}], "register": "neutral", "sense_fingerprint": "night, the dark period between sunset and sunrise", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 鶏舎 (Zipf 2.02)']::text[], '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37833, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夜", "is_correct": true, "explanation": "『夜が明け』は暗い時間帯が終わる表現として自然に収まる。"}, {"text": "昼", "is_correct": false, "explanation": "『昼が明け』は不自然で、夜明けの表現に合わない。"}, {"text": "午後", "is_correct": false, "explanation": "午後は『明ける』とは結びつかないので文が成り立たない。"}, {"text": "夕方", "is_correct": false, "explanation": "夕方は『明ける』とは結びつかないので不自然。"}], "explanations": {"夜": "『夜が明け』は暗い時間帯が終わる表現として自然に収まる。", "昼": "『昼が明け』は不自然で、夜明けの表現に合わない。", "午後": "午後は『明ける』とは結びつかないので文が成り立たない。", "夕方": "夕方は『明ける』とは結びつかないので不自然。"}, "sentence_index": 0, "correct_answer": "夜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜の五時、空はまだ明るく西日が差していた。", "explanation": "ここは〈夕方〉の意味。西日が差す明るい時刻は〈夜〉の定義に合わない。"}, {"text": "夜の食卓で、朝ごはんの味噌汁を温め直した。", "explanation": "ここは〈朝〉の意味。朝ごはんの時間は〈夜〉の定義に合わない。"}, {"text": "夜の教室は、窓から差す日差しで明るかった。", "explanation": "ここは〈昼〉の意味。日差しで明るい時間は夜の定義に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37833, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夜", "is_correct": true, "explanation": "『夜が長い冬は』という季節の文脈に自然に収まる。"}, {"text": "夏", "is_correct": false, "explanation": "『夏が長い冬』は矛盾し、文が成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は季節の長さの主語にならない。"}, {"text": "石", "is_correct": false, "explanation": "石は季節の長さの主語にならない。"}], "explanations": {"夜": "『夜が長い冬は』という季節の文脈に自然に収まる。", "夏": "『夏が長い冬』は矛盾し、文が成り立たない。", "窓": "窓は季節の長さの主語にならない。", "石": "石は季節の長さの主語にならない。"}, "sentence_index": 6, "correct_answer": "夜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この劇場の夜の部は、午後二時に始まった。", "explanation": "ここは〈午後〉の時間を〈夜〉で言った誤用。午後二時は〈夜〉の定義に合わない。"}, {"text": "夜の海が、朝日を浴びてきらきら光っていた。", "explanation": "ここは〈夜明け〉の意味。朝日を浴びる時間は〈夜〉の定義に合わない。"}, {"text": "夜の廊下は、窓から差す日差しで明るかった。", "explanation": "ここは〈昼〉の意味。日差しで明るい時間は夜の定義に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37833, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜で雨が降ったので、道がぬれていた。", "corrected_sentence": "夜に雨が降ったので、道がぬれていた。", "error_description": "『夜』は時点を表すので『に』が必要。『で』は場所や手段を示すので不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37833, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜をなると、窓の外の街灯がともる。", "corrected_sentence": "夜になると、窓の外の街灯がともる。", "error_description": "『夜になる』の『に』が『を』になっている。『なる』は『に』で変化の結果を示すので、『を』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37834, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「夢を語る」の〈を〉。話す内容（夢）を表す目的語で、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「夢が語る」は夢が話すことになり、語る主体として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「夢へ語る」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、「夢から語る」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「夢を語る」の〈を〉。話す内容（夢）を表す目的語で、ここに入る。", "が": "「夢が語る」は夢が話すことになり、語る主体として不自然。", "へ": "方向を表すが、「夢へ語る」は文として成り立たない。", "から": "起点を表すが、「夢から語る」は意味が通らない。"}, "error_tags": {"が": "「夢が語る」は夢が話すことになり、語る主体として不自然。", "へ": "方向を表すが、「夢へ語る」は文として成り立たない。", "から": "起点を表すが、「夢から語る」は意味が通らない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37834, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「苦労を語らない」の〈を〉。話す内容（苦労）を表す目的語で、ここに入る。"}, {"text": "に", "is_correct": false, "explanation": "「苦労に語らない」では、苦労を語る対象として示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「苦労へ語らない」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「苦労と語らない」では、何と一緒に語るのか不明で意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「苦労を語らない」の〈を〉。話す内容（苦労）を表す目的語で、ここに入る。", "に": "「苦労に語らない」では、苦労を語る対象として示せない。", "へ": "方向を表すが、「苦労へ語らない」は意味が通らない。", "と": "「苦労と語らない」では、何と一緒に語るのか不明で意味が通らない。"}, "error_tags": {"に": "「苦労に語らない」では、苦労を語る対象として示せない。", "へ": "方向を表すが、「苦労へ語らない」は意味が通らない。", "と": "「苦労と語らない」では、何と一緒に語るのか不明で意味が通らない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37834, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "自分の考えや話を口に出して言うこと。", "primary_collocate": null, "pronunciation": "かたる", "ipa": "kataɾɯ", "syllable_count": 3, "sentences": [{"text": "祖父は戦争のころの思い出を、ゆっくりと語ってくれました。", "target_word": "語って", "complexity_tier": "T3", "furigana": "祖父[そふ]は戦争[せんそう]のころの思[おも]い出[で]を、ゆっくりと語[かた]ってくれました。", "sentence_source": "generated"}, {"text": "彼は将来の夢を語るとき、目がいつも輝いています。", "target_word": "語る", "complexity_tier": "T3", "furigana": "彼[かれ]は将来[しょうらい]の夢[ゆめ]を語[かた]るとき、目[め]がいつも輝[かがや]いています。", "sentence_source": "generated"}, {"text": "社長は会社の目標について、社員の前で熱く語りました。", "target_word": "語りました", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は会社[かいしゃ]の目標[もくひょう]について、社員[しゃいん]の前[まえ]で熱[あつ]く語[かた]りました。", "sentence_source": "generated"}, {"text": "恥ずかしがり屋の弟は、自分の気持ちをあまり語らない子です。", "target_word": "語らない", "complexity_tier": "T3", "furigana": "恥[は]ずかしがり屋[や]の弟[おとうと]は、自分[じぶん]の気持[きも]ちをあまり語[かた]らない子[こ]です。", "sentence_source": "generated"}, {"text": "友だちと夜遅くまで、これからの人生について語りました。", "target_word": "語りました", "complexity_tier": "T3", "furigana": "友[とも]だちと夜遅[よるおそ]くまで、これからの人生[じんせい]について語[かた]りました。", "sentence_source": "generated"}, {"text": "インタビューで、その選手は優勝までの苦労を静かに語りました。", "target_word": "語りました", "complexity_tier": "T3", "furigana": "インタビューで、その選手[せんしゅ]は優勝[ゆうしょう]までの苦労[くろう]を静[しず]かに語[かた]りました。", "sentence_source": "generated"}, {"text": "老人は火のそばで、村に伝わる昔話を子どもたちに語っていました。", "target_word": "語って", "complexity_tier": "T3", "furigana": "老人[ろうじん]は火[ひ]のそばで、村[むら]に伝[つた]わる昔話[むかしばなし]を子[こ]どもたちに語[かた]っていました。", "sentence_source": "generated"}, {"text": "父は仕事の苦労をほとんど語らないので、何をしているのかよく分かりません。", "target_word": "語らない", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]の苦労[くろう]をほとんど語[かた]らないので、何[なに]をしているのかよく分[わ]かりません。", "sentence_source": "generated"}, {"text": "彼女は留学の経験を語り、会場の学生たちを引きつけました。", "target_word": "語り", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は留学[りゅうがく]の経験[けいけん]を語[かた]り、会場[かいじょう]の学生[がくせい]たちを引[ひ]きつけました。", "sentence_source": "generated"}, {"text": "思い出を語れば、あのころの友だちの顔が自然に浮かんできます。", "target_word": "語れば", "complexity_tier": "T3", "furigana": "思[おも]い出[で]を語[かた]れば、あのころの友[とも]だちの顔[かお]が自然[しぜん]に浮[う]かんできます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "語る", "label": "辞書形"}, {"form": "語ります", "label": "丁寧形"}, {"form": "語って", "label": "て形"}, {"form": "語った", "label": "た形"}, {"form": "語らない", "label": "ない形"}, {"form": "語れば", "label": "ば形"}], "register": "neutral", "sense_fingerprint": "考えや思い出などをまとまった話として口に出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37834, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "語って", "is_correct": true, "explanation": "て形で「くれました」に続き、「ゆっくりと語ってくれました」と自然につながる。"}, {"text": "語り", "is_correct": false, "explanation": "連用形は「くれました」に直接続かないので、文が成り立たない。"}, {"text": "語れ", "is_correct": false, "explanation": "命令形は「くれました」と続かず、文の形が崩れる。"}, {"text": "語った", "is_correct": false, "explanation": "た形の後に「くれました」が続くと「語ったくれました」になり、文法的に誤り。"}], "explanations": {"語って": "て形で「くれました」に続き、「ゆっくりと語ってくれました」と自然につながる。", "語り": "連用形は「くれました」に直接続かないので、文が成り立たない。", "語れ": "命令形は「くれました」と続かず、文の形が崩れる。", "語った": "た形の後に「くれました」が続くと「語ったくれました」になり、文法的に誤り。"}, "sentence_index": 0, "correct_answer": "語って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "初対面の彼は、自分の名前を大きな声で語った。", "explanation": "ここは〈名乗る〉の意味。自分の名前を告げる場面は〈名乗る〉で表し、〈語る〉は合わない。"}, {"text": "ピアノの前で、彼は夜遅くまでワルツを語った。", "explanation": "ここは〈弾く〉の意味。楽器の演奏は〈語る〉ではなく〈弾く〉で表す。"}, {"text": "彼は感謝の気持ちを、手紙に語った。", "explanation": "ここは〈書く〉の意味。手紙で伝えるときは〈書く〉を使い、〈語る〉は口に出す話に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37834, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "語って", "is_correct": true, "explanation": "て形で「ていました」に続き、「語っていました」になる。"}, {"text": "語らず", "is_correct": false, "explanation": "「ず」の形は「ていました」に続かず、「語らずていました」は成り立たない。"}, {"text": "語れる", "is_correct": false, "explanation": "可能形に「ていました」を付けると「語れるていました」になり、誤り。"}, {"text": "語りました", "is_correct": false, "explanation": "丁寧形の過去に「ていました」は続かず、「語りましたていました」は誤り。"}], "explanations": {"語って": "て形で「ていました」に続き、「語っていました」になる。", "語らず": "「ず」の形は「ていました」に続かず、「語らずていました」は成り立たない。", "語れる": "可能形に「ていました」を付けると「語れるていました」になり、誤り。", "語りました": "丁寧形の過去に「ていました」は続かず、「語りましたていました」は誤り。"}, "sentence_index": 6, "correct_answer": "語って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合のあと、選手は泥だらけの靴を丁寧に語った。", "explanation": "ここは〈磨く〉の意味。靴は語るものではなく磨くものなので〈磨く〉を使う。"}, {"text": "子どもたちは教室で、元気よく歌を語った。", "explanation": "ここは〈歌う〉の意味。歌は語るものではなく、歌うものなので合わない。"}, {"text": "面白い冗談に、彼はお腹を抱えて語った。", "explanation": "ここは〈笑う〉の意味。笑いは語るのではなく、笑うので、〈語る〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37834, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は孫に、若いころの苦労を語れてくれました。", "corrected_sentence": "祖母は孫に、若いころの苦労を語ってくれました。", "error_description": "誤りは「語れて」（可能形のて形）。正しくは「語って」（〜てくれる）。可能形は「〜てくれる」に続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "語る", "is_correct": true, "explanation": "辞書形で「とき」に続き、正しい形。"}, {"text": "語って", "is_correct": false, "explanation": "て形は「とき」に続かない。"}, {"text": "語れ", "is_correct": false, "explanation": "命令形は「とき」に続かない。"}, {"text": "語ろう", "is_correct": false, "explanation": "意志形は「とき」に続かず、文が成り立たない。"}], "correct_form": "語る", "base_form": "語る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"語る": "辞書形で「とき」に続き、正しい形。", "語って": "て形は「とき」に続かない。", "語れ": "命令形は「とき」に続かない。", "語ろう": "意志形は「とき」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37834, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は子どもたちを昔話を語った。", "corrected_sentence": "祖父は子どもたちに昔話を語った。", "error_description": "誤りは「子どもたちを」。語る相手（聞き手）には「に」を使う。「を」は話の内容（昔話）に使うので、「を」が二つ並ぶと文が成り立たない。正しくは「子どもたちに」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "語らない", "is_correct": true, "explanation": "ない形で「ので」に続き、「ほとんど語らないので」となる。"}, {"text": "語ら", "is_correct": false, "explanation": "未然形は「ので」に続かず、「語らので」は文が成り立たない。"}, {"text": "語らず", "is_correct": false, "explanation": "「ず」の形は「ので」に続かず、「語らずので」は不自然で文が成り立たない。"}, {"text": "語れば", "is_correct": false, "explanation": "仮定形の後に「ので」は続かず、文が成り立たない。"}], "correct_form": "語らない", "base_form": "語る", "form_label": "否定形", "sentence_index": 7, "explanations": {"語らない": "ない形で「ので」に続き、「ほとんど語らないので」となる。", "語ら": "未然形は「ので」に続かず、「語らので」は文が成り立たない。", "語らず": "「ず」の形は「ので」に続かず、「語らずので」は不自然で文が成り立たない。", "語れば": "仮定形の後に「ので」は続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37835, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「警察に語りました」の〈に〉。話す相手（警察）を表し、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「警察を語る」は、警察を対象として話すことにならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「警察の語りました」は文の形が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、「警察から詳しく語りました」は語る相手として不自然。"}], "correct_answer": "に", "explanations": {"に": "「警察に語りました」の〈に〉。話す相手（警察）を表し、ここに入る。", "を": "「警察を語る」は、警察を対象として話すことにならず不自然。", "の": "「警察の語りました」は文の形が成り立たない。", "から": "起点を表すが、「警察から詳しく語りました」は語る相手として不自然。"}, "error_tags": {"を": "「警察を語る」は、警察を対象として話すことにならず不自然。", "の": "「警察の語りました」は文の形が成り立たない。", "から": "起点を表すが、「警察から詳しく語りました」は語る相手として不自然。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37835, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「お客さんに語ってくれました」の〈に〉。話す相手（お客さん）を表し、ここに入る。"}, {"text": "で", "is_correct": false, "explanation": "「お客さんで語ってくれました」は、人を場所や手段として扱うことになり、文として成り立たない。"}, {"text": "や", "is_correct": false, "explanation": "並列の〈や〉は名詞同士を並べる助詞。「お客さんや語ってくれました」は、並べる相手がなく文が崩れる。"}, {"text": "にて", "is_correct": false, "explanation": "〈にて〉は文語的な形。「お客さんにて語ってくれました」は、話し言葉の文体と合わず不自然。"}], "correct_answer": "に", "explanations": {"に": "「お客さんに語ってくれました」の〈に〉。話す相手（お客さん）を表し、ここに入る。", "で": "「お客さんで語ってくれました」は、人を場所や手段として扱うことになり、文として成り立たない。", "や": "並列の〈や〉は名詞同士を並べる助詞。「お客さんや語ってくれました」は、並べる相手がなく文が崩れる。", "にて": "〈にて〉は文語的な形。「お客さんにて語ってくれました」は、話し言葉の文体と合わず不自然。"}, "error_tags": {"で": "「お客さんで語ってくれました」は、人を場所や手段として扱うことになり、文として成り立たない。", "や": "並列の〈や〉は名詞同士を並べる助詞。「お客さんや語ってくれました」は、並べる相手がなく文が崩れる。", "にて": "〈にて〉は文語的な形。「お客さんにて語ってくれました」は、話し言葉の文体と合わず不自然。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37835, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人が自分の考えや情報を、言葉を使って相手に伝えること。", "primary_collocate": null, "pronunciation": "かたる", "ipa": "kataɾɯ", "syllable_count": 3, "sentences": [{"text": "先生は自分の失敗談を語って、生徒たちに挑戦する大切さを伝えました。", "target_word": "語って", "complexity_tier": "T3", "furigana": "先生[せんせい]は自分[じぶん]の失敗談[しっぱいだん]を語[かた]って、生徒[せいと]たちに挑戦[ちょうせん]する大切[たいせつ]さを伝[つた]えました。", "sentence_source": "generated"}, {"text": "目撃者は事故の様子を、警察に詳しく語りました。", "target_word": "語りました", "complexity_tier": "T3", "furigana": "目撃者[もくげきしゃ]は事故[じこ]の様子[ようす]を、警察[けいさつ]に詳[くわ]しく語[かた]りました。", "sentence_source": "generated"}, {"text": "被害者の母親は、事件の夜の出来事を記者に語りました。", "target_word": "語りました", "complexity_tier": "T3", "furigana": "被害者[ひがいしゃ]の母親[ははおや]は、事件[じけん]の夜[よる]の出来事[できごと]を記者[きしゃ]に語[かた]りました。", "sentence_source": "generated"}, {"text": "彼は自分の意見を堂々と語り、会議の流れを変えました。", "target_word": "語り", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の意見[いけん]を堂々[どうどう]と語[かた]り、会議[かいぎ]の流[なが]れを変[か]えました。", "sentence_source": "generated"}, {"text": "旅から帰った兄は、見てきた景色を興奮して語りつづけました。", "target_word": "語りつづけました", "complexity_tier": "T3", "furigana": "旅[たび]から帰[かえ]った兄[あに]は、見[み]てきた景色[けしき]を興奮[こうふん]して語[かた]りつづけました。", "sentence_source": "generated"}, {"text": "作家は新しい小説に込めた思いを、ラジオで語りました。", "target_word": "語りました", "complexity_tier": "T3", "furigana": "作家[さっか]は新[あたら]しい小説[しょうせつ]に込[こ]めた思[おも]いを、ラジオで語[かた]りました。", "sentence_source": "generated"}, {"text": "初めて会った人にも、自分の仕事への考えを語れるようになりたいです。", "target_word": "語れる", "complexity_tier": "T3", "furigana": "初[はじ]めて会[あ]った人[ひと]にも、自分[じぶん]の仕事[しごと]への考[かんが]えを語[かた]れるようになりたいです。", "sentence_source": "generated"}, {"text": "老店主は店を始めたころの苦労を、お客さんに語ってくれました。", "target_word": "語って", "complexity_tier": "T3", "furigana": "老店主[ろうてんしゅ]は店[みせ]を始[はじ]めたころの苦労[くろう]を、お客[きゃく]さんに語[かた]ってくれました。", "sentence_source": "generated"}, {"text": "卒業生は壇上で、学校生活で学んだことを語りました。", "target_word": "語りました", "complexity_tier": "T3", "furigana": "卒業生[そつぎょうせい]は壇上[だんじょう]で、学校生活[がっこうせいかつ]で学[まな]んだことを語[かた]りました。", "sentence_source": "generated"}, {"text": "彼女はあまり多くを語りませんでしたが、表情から悲しみが伝わりました。", "target_word": "語りませんでした", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はあまり多[おお]くを語[かた]りませんでしたが、表情[ひょうじょう]から悲[かな]しみが伝[つた]わりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "語る", "label": "辞書形"}, {"form": "語ります", "label": "丁寧形"}, {"form": "語って", "label": "て形"}, {"form": "語った", "label": "た形"}, {"form": "語らない", "label": "ない形"}, {"form": "語れる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "考えや出来事を言葉で相手に伝える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 失敗談 (Zipf 2.47)']::text[], 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37835, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "語って", "is_correct": true, "explanation": "て形で、「失敗談を語って、〜伝えました」と続く。"}, {"text": "語れ", "is_correct": false, "explanation": "命令形は文の途中に来られず、「語れ、」は文法的に誤り。"}, {"text": "語ろう", "is_correct": false, "explanation": "意志形は「、」で続けられず、文が成り立たない。"}, {"text": "語れる", "is_correct": false, "explanation": "可能形は「、」で続けると文が崩れ、「語れる、生徒たち」は不自然。"}], "explanations": {"語って": "て形で、「失敗談を語って、〜伝えました」と続く。", "語れ": "命令形は文の途中に来られず、「語れ、」は文法的に誤り。", "語ろう": "意志形は「、」で続けられず、文が成り立たない。", "語れる": "可能形は「、」で続けると文が崩れ、「語れる、生徒たち」は不自然。"}, "sentence_index": 0, "correct_answer": "語って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は廊下で騒いでいた生徒を、大きな声で語った。", "explanation": "ここは〈叱る〉の意味。人を注意する場面では〈語る〉を使わず、〈叱る〉を使う。"}, {"text": "彼は別れの言葉を、メモに語った。", "explanation": "ここは〈書く〉の意味。メモに書き残す場合は〈語る〉ではなく〈書く〉を使う。"}, {"text": "彼女は窓の外の友だちを、大きな声で語った。", "explanation": "ここは〈呼ぶ〉の意味。人を大声で呼ぶ場面に〈語る〉は使わず、〈呼ぶ〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37835, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "語れる", "is_correct": true, "explanation": "可能形で「語れるようになりたい」となり、自然につながる。"}, {"text": "語れ", "is_correct": false, "explanation": "命令形は「ようになりたい」に続かず、「語れようになりたい」は誤り。"}, {"text": "語り", "is_correct": false, "explanation": "連用形は「ようになりたい」に続かず、「語りようになりたい」は誤り。"}, {"text": "語った", "is_correct": false, "explanation": "た形は「ようになりたい」に続かず、「語ったようになりたい」は誤り。"}], "explanations": {"語れる": "可能形で「語れるようになりたい」となり、自然につながる。", "語れ": "命令形は「ようになりたい」に続かず、「語れようになりたい」は誤り。", "語り": "連用形は「ようになりたい」に続かず、「語りようになりたい」は誤り。", "語った": "た形は「ようになりたい」に続かず、「語ったようになりたい」は誤り。"}, "sentence_index": 6, "correct_answer": "語れる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "怖くなった彼女は、壁を赤く語った。", "explanation": "ここは〈塗る〉の意味。壁は語るものではなく塗るものなので〈塗る〉を使う。"}, {"text": "彼は遅刻したことを、深く頭を下げて語った。", "explanation": "ここは〈謝る〉の意味。謝罪は〈語る〉ではなく〈謝る〉で表す。"}, {"text": "テレビのコントに、家族はお腹を抱えて語った。", "explanation": "ここは〈笑う〉の意味。笑いは語るものではなく、笑うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37835, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は旅の話を友だちを語りつづけました。", "corrected_sentence": "兄は旅の話を友だちに語りつづけました。", "error_description": "誤りは「友だちを」。話を聞く相手には「に」を使う。「を」は話の内容（旅の話）に使うので、「を」が二つ並ぶと文が成り立たない。正しくは「友だちに」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "語りました", "is_correct": true, "explanation": "丁寧形の過去で、文の述語として正しい。"}, {"text": "語れ", "is_correct": false, "explanation": "命令形は平叙文の述語にならず、「語れ。」と言い切れない。"}, {"text": "語らない", "is_correct": false, "explanation": "否定形で、「語った」事実と矛盾し、文の意味が合わない。"}, {"text": "語って", "is_correct": false, "explanation": "て形では述語として文が終わらず、成り立たない。"}], "correct_form": "語りました", "base_form": "語る", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"語りました": "丁寧形の過去で、文の述語として正しい。", "語れ": "命令形は平叙文の述語にならず、「語れ。」と言い切れない。", "語らない": "否定形で、「語った」事実と矛盾し、文の意味が合わない。", "語って": "て形では述語として文が終わらず、成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37835, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は夕食のあと、旅の思い出を家族に語りてくれました。", "corrected_sentence": "父は夕食のあと、旅の思い出を家族に語ってくれました。", "error_description": "誤りは「語りて」。連用形に「て」を付けた形は誤り。正しくは五段動詞のて形「語って」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "語って", "is_correct": true, "explanation": "て形で「くれました」に続き、「語ってくれました」となる。"}, {"text": "語る", "is_correct": false, "explanation": "辞書形の後に「くれました」は続かず、「語るくれました」となり誤り。"}, {"text": "語り", "is_correct": false, "explanation": "連用形の後に「くれました」は続かず、「語りくれました」は誤り。"}, {"text": "語れば", "is_correct": false, "explanation": "仮定形の後に「くれました」は続かず、文が成り立たない。"}], "correct_form": "語って", "base_form": "語る", "form_label": "て形", "sentence_index": 7, "explanations": {"語って": "て形で「くれました」に続き、「語ってくれました」となる。", "語る": "辞書形の後に「くれました」は続かず、「語るくれました」となり誤り。", "語り": "連用形の後に「くれました」は続かず、「語りくれました」は誤り。", "語れば": "仮定形の後に「くれました」は続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37836, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死ぬ", "is_correct": true, "explanation": "「生きる」の対義語で、命がなくなることを表す。"}, {"text": "眠る", "is_correct": false, "explanation": "眠ることは生きることの対義語ではない。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の動作で、生きることの対義語ではない。"}, {"text": "笑う", "is_correct": false, "explanation": "感情の表現で、生きることの対義語ではない。"}], "correct_answer": "死ぬ", "explanations": {"死ぬ": "「生きる」の対義語で、命がなくなることを表す。", "眠る": "眠ることは生きることの対義語ではない。", "歩く": "移動の動作で、生きることの対義語ではない。", "笑う": "感情の表現で、生きることの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37836, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死ぬ", "is_correct": true, "explanation": "「生きる」の対義語で、命がなくなることを表す。"}, {"text": "食べる", "is_correct": false, "explanation": "食事の動作で、生きることの対義語ではない。"}, {"text": "泣く", "is_correct": false, "explanation": "感情の表現で、生きることの対義語ではない。"}, {"text": "走る", "is_correct": false, "explanation": "移動の動作で、生きることの対義語ではない。"}], "correct_answer": "死ぬ", "explanations": {"死ぬ": "「生きる」の対義語で、命がなくなることを表す。", "食べる": "食事の動作で、生きることの対義語ではない。", "泣く": "感情の表現で、生きることの対義語ではない。", "走る": "移動の動作で、生きることの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37836, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "生物として命があり、死んでいない状態でいること。", "primary_collocate": null, "pronunciation": "いきる", "ipa": "ikiɾɯ", "syllable_count": 3, "sentences": [{"text": "この魚は水の外でも三時間ほど生きている。", "target_word": "生きている", "complexity_tier": "T3", "furigana": "この魚[さかな]は水[みず]の外[そと]でも三時間[さんじかん]ほど生[い]きている。", "sentence_source": "generated"}, {"text": "祖父は九十歳まで元気に生きた。", "target_word": "生きた", "complexity_tier": "T3", "furigana": "祖父[そふ]は九十歳[きゅうじゅっさい]まで元気[げんき]に生[い]きた。", "sentence_source": "generated"}, {"text": "砂漠でも生きる植物がある。", "target_word": "生きる", "complexity_tier": "T2", "furigana": "砂漠[さばく]でも生[い]きる植物[しょくぶつ]がある。", "sentence_source": "generated"}, {"text": "水がなければ、人は何日も生きられない。", "target_word": "生きられない", "complexity_tier": "T3", "furigana": "水[みず]がなければ、人[ひと]は何日[なんにち]も生[い]きられない。", "sentence_source": "generated"}, {"text": "事故のあと、彼が生きていると知って、家族は泣いて喜んだ。", "target_word": "生きている", "complexity_tier": "T4", "furigana": "事故[じこ]のあと、彼[かれ]が生[い]きていると知[し]って、家族[かぞく]は泣[な]いて喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "暗い海の底にも生きている魚がいる。", "target_word": "生きている", "complexity_tier": "T3", "furigana": "暗[くら]い海[うみ]の底[そこ]にも生[い]きている魚[さかな]がいる。", "sentence_source": "generated"}, {"text": "空気がないと、生きることはできない。", "target_word": "生きること", "complexity_tier": "T3", "furigana": "空気[くうき]がないと、生[い]きることはできない。", "sentence_source": "generated"}, {"text": "犬は寿命が短く、十五年ほどしか生きない。", "target_word": "生きない", "complexity_tier": "T3", "furigana": "犬[いぬ]は寿命[じゅみょう]が短[みじか]く、十五年[じゅうごねん]ほどしか生[い]きない。", "sentence_source": "generated"}, {"text": "冬の間、カエルは土の中で生きている。", "target_word": "生きている", "complexity_tier": "T3", "furigana": "冬[ふゆ]の間[あいだ]、カエルは土[つち]の中[なか]で生[い]きている。", "sentence_source": "generated"}, {"text": "見つかった子猫はまだ生きていて、病院に運ばれた。", "target_word": "生きていて", "complexity_tier": "T4", "furigana": "見[み]つかった子猫[こねこ]はまだ生[い]きていて、病院[びょういん]に運[はこ]ばれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生きる", "label": "終止形"}, {"form": "生きない", "label": "否定形"}, {"form": "生きた", "label": "過去形"}, {"form": "生きて", "label": "て形"}, {"form": "生きれば", "label": "仮定形"}, {"form": "生きよう", "label": "意志形"}, {"form": "生きられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "生物として命がある状態でいる、死んでいない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37836, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生きている", "is_correct": true, "explanation": "〜ている形で、「三時間ほど生きている」と現在の状態を表し、文が成り立つ。"}, {"text": "生きて", "is_correct": false, "explanation": "て形では文が終わらず、「三時間ほど生きて。」は文として成り立たない。"}, {"text": "生きれば", "is_correct": false, "explanation": "仮定形では文が終わらず、「生きれば。」は成り立たない。"}, {"text": "生きよう", "is_correct": false, "explanation": "意志形は「生きよう」という意思の文になり、ここの事実を述べる文とは合わない。"}], "explanations": {"生きている": "〜ている形で、「三時間ほど生きている」と現在の状態を表し、文が成り立つ。", "生きて": "て形では文が終わらず、「三時間ほど生きて。」は文として成り立たない。", "生きれば": "仮定形では文が終わらず、「生きれば。」は成り立たない。", "生きよう": "意志形は「生きよう」という意思の文になり、ここの事実を述べる文とは合わない。"}, "sentence_index": 0, "correct_answer": "生きている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休み、子どもたちは毎日、プールで生きた。", "explanation": "ここは〈泳ぐ〉の意味。水の中で体を動かす場合は〈生きる〉ではなく〈泳ぐ〉を使う。"}, {"text": "祖父は毎晩、古い手紙を生きた。", "explanation": "ここは〈読む〉の意味。手紙は読むものなので、〈生きる〉ではなく〈読む〉を使う。"}, {"text": "母は子どもを一人で生きた。", "explanation": "ここは〈育てる〉の意味。子どもを大きくする場合は〈生きる〉を使わず、〈育てる〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37836, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生きること", "is_correct": true, "explanation": "名詞化した形で「はできない」の主語になり、「生きることはできない」と成り立つ。"}, {"text": "生きる", "is_correct": false, "explanation": "辞書形では「生きるはできない」となり、文として成り立たない。"}, {"text": "生きた", "is_correct": false, "explanation": "た形では「生きたはできない」となり、文として成り立たない。"}, {"text": "生きない", "is_correct": false, "explanation": "否定形では「生きないはできない」となり、文として成り立たない。"}], "explanations": {"生きること": "名詞化した形で「はできない」の主語になり、「生きることはできない」と成り立つ。", "生きる": "辞書形では「生きるはできない」となり、文として成り立たない。", "生きた": "た形では「生きたはできない」となり、文として成り立たない。", "生きない": "否定形では「生きないはできない」となり、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "生きること"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に突然、部屋の電気が生きた。", "explanation": "ここは〈消える〉の意味。電気は命がないので、〈生きる〉ではなく〈消える〉を使う。"}, {"text": "天気がいい日、洗濯物がすぐに生きた。", "explanation": "ここは〈乾く〉の意味。洗濯物は乾くのであって、〈生きる〉は合わない。"}, {"text": "寒い夜、池の水が一晩で生きた。", "explanation": "ここは〈凍る〉の意味。水は凍るのであって、〈生きる〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
